-- CareGanga V1 baseline: catalog-derived from isolated PostgreSQL 17, after all 311 reviewed migrations.
-- Runtime initialization executes this file once, inside a single transaction.
-- Operational data is not included. Do not edit a released baseline.
SET LOCAL search_path TO public, pg_catalog;
SET LOCAL check_function_bodies TO false;

-- Extensions and sequences
CREATE EXTENSION btree_gist WITH SCHEMA public VERSION '1.7';
CREATE EXTENSION pgcrypto WITH SCHEMA public VERSION '1.3';
CREATE SEQUENCE public.cg02_branch_code_sequence AS bigint INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1 NO CYCLE;
