-- Functions 1-45
CREATE OR REPLACE FUNCTION public.cg01_community_public_role_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.normalized_name='careganga community applicant' THEN
   RAISE EXCEPTION 'Public community applicant role cannot be deleted';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.normalized_name='careganga community applicant' OR NEW.normalized_name='careganga community applicant' THEN
  RAISE EXCEPTION 'Public community applicant role cannot be edited';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg01_community_public_role_no_grant()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM role WHERE id=NEW.role_id
    AND normalized_name='careganga community applicant') THEN
  RAISE EXCEPTION 'Public community applicant accounts cannot receive staff capability grants';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg01_deny_access_audit_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'CG-01 access audit history is immutable';
END;
$function$
;
