$function$
;
CREATE OR REPLACE FUNCTION public.cg01_ensure_community_public_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.realm_key='FOUNDATION_ROOT' THEN
  INSERT INTO role(realm_id,name,normalized_name,description,is_protected,active)
  VALUES(NEW.id,'CareGanga Community Applicant','careganga community applicant',
   'Public community applicant sign-in; no Foundation staff actions',false,true)
  ON CONFLICT(realm_id,normalized_name) DO NOTHING;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg01_ensure_patient_public_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.realm_key='FOUNDATION_ROOT' THEN
  INSERT INTO role(realm_id,name,normalized_name,description,is_protected,active)
  VALUES(NEW.id,'CareGanga Patient','careganga patient',
   'Public patient sign-in; no Foundation staff actions',false,true)
  ON CONFLICT(realm_id,normalized_name) DO NOTHING;
 END IF;
 RETURN NEW;
END; $function$
;
