CREATE OR REPLACE FUNCTION public.cg02_staff_scope_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Delegated branch/area access history is immutable';
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.account_ref IS DISTINCT FROM OLD.account_ref
  OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
  OR NEW.branch_ref IS DISTINCT FROM OLD.branch_ref
  OR NEW.area_ref IS DISTINCT FROM OLD.area_ref
  OR NEW.reason IS DISTINCT FROM OLD.reason
  OR NEW.granted_by IS DISTINCT FROM OLD.granted_by
  OR NEW.granted_at IS DISTINCT FROM OLD.granted_at
  OR NEW.request_key IS DISTINCT FROM OLD.request_key
  OR NEW.request_digest IS DISTINCT FROM OLD.request_digest
  OR OLD.ended_at IS NOT NULL
  OR NEW.ended_at IS NULL OR NEW.ended_by IS NULL OR NEW.end_request_key IS NULL
  OR NEW.source_version<>2 THEN
  RAISE EXCEPTION 'Delegated branch/area access cannot be rewritten';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg02_submission_source_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.registration_id IS DISTINCT FROM OLD.registration_id
  OR NEW.submitted_revision IS DISTINCT FROM OLD.submitted_revision
  OR NEW.source_submission_key IS DISTINCT FROM OLD.source_submission_key
  OR NEW.immutable_payload IS DISTINCT FROM OLD.immutable_payload
  OR NEW.immutable_payload_digest IS DISTINCT FROM OLD.immutable_payload_digest
  OR NEW.verified_file_versions IS DISTINCT FROM OLD.verified_file_versions
  OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by
  OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
  OR (OLD.approval_case_ref IS NOT NULL
      AND NEW.approval_case_ref IS DISTINCT FROM OLD.approval_case_ref) THEN
   RAISE EXCEPTION 'Submitted branch source is immutable';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_branch_effect_identity_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.case_id IS DISTINCT FROM OLD.case_id
    OR NEW.realm_id IS DISTINCT FROM OLD.realm_id
    OR NEW.final_decision_id IS DISTINCT FROM OLD.final_decision_id
    OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Approved branch decision identity is immutable';
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_branch_identity_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.case_kind IS DISTINCT FROM OLD.case_kind
    OR NEW.branch_source_ref IS DISTINCT FROM OLD.branch_source_ref
    OR NEW.branch_source_revision IS DISTINCT FROM OLD.branch_source_revision
    OR NEW.branch_source_digest IS DISTINCT FROM OLD.branch_source_digest THEN
    RAISE EXCEPTION 'Original branch approval source cannot be changed';
  END IF;
