CREATE OR REPLACE FUNCTION public.cg03_hr_document_link_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.case_kind='HR_DOCUMENT_REVIEW' AND NOT EXISTS(
  SELECT 1 FROM cg03_case c JOIN hr_document_request h ON h.root_realm_id=c.realm_id AND h.id=c.hr_document_request_id
   AND h.case_ref=c.id AND h.source_digest=c.hr_document_source_digest AND h.revision=c.proposal_revision AND h.created_by=c.proposer_id
  WHERE c.id=NEW.id AND c.realm_id=NEW.realm_id AND (
   (c.status IN('SUBMITTED','IN_REVIEW') AND h.status='SUBMITTED')
   OR (c.status='FINAL_APPROVED' AND h.status='APPROVED')
   OR (c.status='RETURNED' AND h.status='RETURNED') OR (c.status='REJECTED' AND h.status='REJECTED')))
 THEN RAISE EXCEPTION 'Original document request and case outcome required'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_hr_document_source_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.hr_document_request_id,NEW.hr_document_source_digest) IS DISTINCT FROM (OLD.hr_document_request_id,OLD.hr_document_source_digest)
 THEN RAISE EXCEPTION 'Original document source cannot change'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_hr_employment_change_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.hr_employment_change_id,NEW.hr_employment_change_digest) IS DISTINCT FROM
  (OLD.hr_employment_change_id,OLD.hr_employment_change_digest) THEN RAISE EXCEPTION 'Original employment change proof cannot change'; END IF;
 IF OLD.case_kind IN('HR_TRANSFER_PROMOTION','HR_EXIT_REVIEW') AND NEW.status='CANCELLED' AND OLD.status NOT IN('SUBMITTED','IN_REVIEW','CANCELLED')
 THEN RAISE EXCEPTION 'Only pending employment cases may be withdrawn'; END IF;
 IF OLD.case_kind IN('HR_TRANSFER_PROMOTION','HR_EXIT_REVIEW') AND OLD.status='CANCELLED' AND NEW.status<>OLD.status
 THEN RAISE EXCEPTION 'Withdrawn employment case is terminal'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_hr_employment_owner_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.case_kind IN('HR_TRANSFER_PROMOTION','HR_EXIT_REVIEW') AND NOT EXISTS(
  SELECT 1 FROM cg03_case c JOIN hr_employment_change h
   ON h.id=c.hr_employment_change_id AND h.root_realm_id=c.realm_id AND h.source_digest=c.hr_employment_change_digest
   AND h.revision=c.proposal_revision AND h.case_ref=c.id AND h.created_by=c.proposer_id
   WHERE c.id=NEW.id AND c.realm_id=NEW.realm_id AND (
    (c.status IN('SUBMITTED','IN_REVIEW') AND h.status='SUBMITTED')
    OR (c.status='PENDING_OWNER' AND h.status='APPROVED_PENDING_EFFECT')
    OR (c.status='OWNER_COMPLETED' AND h.status='APPLIED')
    OR (c.status='RETURNED' AND h.status='RETURNED')
    OR (c.status='REJECTED' AND h.status='REJECTED')
    OR (c.status='CANCELLED' AND h.status='WITHDRAWN'))
 ) THEN RAISE EXCEPTION 'Original employment source and case outcome required'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_hr_leave_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.hr_leave_request_id,NEW.hr_leave_source_digest) IS DISTINCT FROM
    (OLD.hr_leave_request_id,OLD.hr_leave_source_digest) THEN
  RAISE EXCEPTION 'Original leave case source cannot be changed';
 END IF;
 IF OLD.case_kind='LEAVE_REQUEST' THEN
  IF OLD.status='CANCELLED' AND NEW.status<>OLD.status THEN
   RAISE EXCEPTION 'Cancelled leave case is terminal';
  END IF;
  IF NEW.status='CANCELLED' AND OLD.status<>'CANCELLED' AND
     (OLD.status NOT IN('SUBMITTED','IN_REVIEW') OR NEW.revision<>OLD.revision+1) THEN
   RAISE EXCEPTION 'Only the original pending leave case can be cancelled';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
