CREATE OR REPLACE FUNCTION public.cg03_leave_cancel_effect_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.case_kind='LEAVE_REQUEST' AND NEW.status='CANCELLED' AND NOT EXISTS(
  SELECT 1 FROM hr_leave_request r JOIN cg03_case_event ev ON ev.id=r.cancel_event_ref AND ev.case_id=r.case_ref AND ev.realm_id=r.root_realm_id
   WHERE r.root_realm_id=NEW.realm_id AND r.id=NEW.hr_leave_request_id AND r.case_ref=NEW.id
   AND r.source_digest=NEW.hr_leave_source_digest AND r.status='CANCELLED' AND ev.action='CANCELLED' AND ev.actor_id=NEW.proposer_id
 ) THEN RAISE EXCEPTION 'Original leave cancellation source effect required'; END IF;
 IF NEW.case_kind IN('HR_TRANSFER_PROMOTION','HR_EXIT_REVIEW') AND NEW.status='CANCELLED' AND NOT EXISTS(
  SELECT 1 FROM hr_employment_change r JOIN cg03_case_event ev ON ev.id=r.cancel_event_ref AND ev.case_id=r.case_ref AND ev.realm_id=r.root_realm_id
   WHERE r.root_realm_id=NEW.realm_id AND r.id=NEW.hr_employment_change_id AND r.case_ref=NEW.id
   AND r.source_digest=NEW.hr_employment_change_digest AND r.status='WITHDRAWN' AND ev.action='CANCELLED' AND ev.actor_id=NEW.proposer_id
 ) THEN RAISE EXCEPTION 'Original employment withdrawal source effect required'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_leave_cancel_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.action='CANCELLED' AND NOT EXISTS(
  SELECT 1 FROM cg03_case c WHERE c.id=NEW.case_id AND c.realm_id=NEW.realm_id
   AND c.case_kind IN('LEAVE_REQUEST','HR_TRANSFER_PROMOTION','HR_EXIT_REVIEW') AND c.status='CANCELLED' AND c.proposer_id=NEW.actor_id
 ) THEN RAISE EXCEPTION 'Original own pending HR cancellation required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_membership_case_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.membership_review_ref,NEW.membership_application_id,NEW.membership_application_version,NEW.membership_review_digest) IS DISTINCT FROM
     (OLD.membership_review_ref,OLD.membership_application_id,OLD.membership_application_version,OLD.membership_review_digest)
   THEN RAISE EXCEPTION 'Frozen membership review source cannot change'; END IF;
 ELSE
  IF NEW.case_kind='MEMBER_APPLICATION' AND NOT EXISTS(
   SELECT 1 FROM membership_review_snapshot s JOIN membership_application a ON a.root_realm_id=s.root_realm_id AND a.id=s.application_id
    JOIN cg03_membership_process_current cur ON cur.realm_id=s.root_realm_id AND cur.process_id=NEW.process_id
    JOIN cg03_process p ON p.realm_id=cur.realm_id AND p.id=cur.process_id
    WHERE s.root_realm_id=NEW.realm_id AND s.id=NEW.membership_review_ref AND s.submitted_by=NEW.proposer_id
    AND a.version=s.application_version AND a.status='SUBMITTED' AND a.submitted_digest=s.source_digest
    AND p.process_kind='MEMBER_APPLICATION' AND p.version=NEW.process_version
    AND NEW.current_step=1 AND NEW.status='SUBMITTED' AND NEW.revision=1)
   THEN RAISE EXCEPTION 'Original current membership review is required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;

-- Functions 46-90
CREATE OR REPLACE FUNCTION public.cg03_membership_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record;
BEGIN
 SELECT * INTO c FROM cg03_case WHERE realm_id=NEW.realm_id AND id=NEW.case_id;
 IF NOT FOUND OR c.case_kind<>'MEMBER_APPLICATION' THEN RETURN NEW; END IF;
 IF NEW.actor_id=c.proposer_id OR NEW.step_ordinal<>1 OR c.current_step<>1 OR NEW.fresh_password_verified_at IS NULL
   OR NEW.accepted_case_revision<>c.revision OR NEW.expected_case_revision+1<>NEW.accepted_case_revision
   OR NOT EXISTS(SELECT 1 FROM cg03_process p JOIN cg03_process_step s ON s.process_id=p.id
    WHERE p.realm_id=c.realm_id AND p.id=c.process_id AND p.process_kind='MEMBER_APPLICATION'
    AND s.ordinal=1 AND s.capability_key='approvals.review' AND s.protected_root_required)
   OR NOT EXISTS(SELECT 1 FROM account a JOIN account_role ar ON ar.account_id=a.id AND ar.realm_id=a.realm_id AND ar.revoked_at IS NULL
    JOIN role r ON r.id=ar.role_id AND r.realm_id=ar.realm_id AND r.is_protected AND r.active
    WHERE a.id=NEW.actor_id AND a.realm_id=NEW.realm_id AND a.status='ACTIVE')
   OR NOT EXISTS(SELECT 1 FROM membership_application a WHERE a.root_realm_id=c.realm_id AND a.id=c.membership_application_id
    AND a.status='SUBMITTED' AND a.version=c.membership_application_version AND a.submitted_digest=c.membership_review_digest)
   OR NOT ((NEW.action='APPROVE' AND c.status='PENDING_OWNER') OR (NEW.action='RETURN' AND c.status='RETURNED') OR (NEW.action='REJECT' AND c.status='REJECTED'))
  THEN RAISE EXCEPTION 'Invalid protected membership review decision'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_membership_previous_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE latest record;
BEGIN
 IF NEW.case_kind<>'MEMBER_APPLICATION' THEN RETURN NEW; END IF;
 SELECT id,status,membership_application_version INTO latest FROM cg03_case
 WHERE realm_id=NEW.realm_id AND case_kind='MEMBER_APPLICATION' AND membership_application_id=NEW.membership_application_id
 ORDER BY membership_application_version DESC LIMIT 1;
 IF FOUND THEN
  IF NEW.previous_case_id IS DISTINCT FROM latest.id OR latest.status<>'RETURNED' OR latest.membership_application_version>=NEW.membership_application_version
  THEN RAISE EXCEPTION 'Membership correction requires the original returned case'; END IF;
 ELSIF NEW.previous_case_id IS NOT NULL THEN RAISE EXCEPTION 'Invalid membership case predecessor'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_membership_process_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM cg03_process p WHERE p.id=NEW.process_id AND p.realm_id=NEW.realm_id AND p.process_kind='MEMBER_APPLICATION' AND p.first_reviewer_capability IS NULL
 AND (SELECT count(*) FROM cg03_process_step s WHERE s.process_id=p.id)=1
 AND EXISTS(SELECT 1 FROM cg03_process_step s WHERE s.process_id=p.id AND s.ordinal=1 AND s.capability_key='approvals.review' AND s.protected_root_required))
 THEN RAISE EXCEPTION 'Original membership review route is invalid'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_verify_finance_invoice_budget_decision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original record;
BEGIN
 SELECT c.case_kind,c.proposer_id,c.status,c.finance_invoice_id,
   c.finance_invoice_revision,c.finance_invoice_digest,c.finance_budget_id,
   c.finance_budget_revision,c.finance_budget_digest
 INTO original FROM cg03_case c
 WHERE c.id=NEW.case_id AND c.realm_id=NEW.realm_id FOR SHARE;
 IF NOT FOUND OR original.case_kind NOT IN('FINANCE_INVOICE','FINANCE_BUDGET')
 THEN RETURN NEW; END IF;
 IF original.proposer_id=NEW.actor_id OR NEW.step_ordinal<>1 OR
    NEW.fresh_password_verified_at IS NULL OR
    NEW.action NOT IN('APPROVE','RETURN','REJECT') THEN
  RAISE EXCEPTION 'Different protected finance reviewer is required' USING ERRCODE='P0928';
 END IF;
 IF (NEW.action='APPROVE' AND original.status<>'PENDING_OWNER') OR
    (NEW.action='RETURN' AND original.status<>'RETURNED') OR
    (NEW.action='REJECT' AND original.status<>'REJECTED') THEN
  RAISE EXCEPTION 'Original finance case review outcome is not current' USING ERRCODE='P0928';
 END IF;
 IF NEW.action<>'APPROVE' THEN RETURN NEW; END IF;
 IF original.case_kind='FINANCE_INVOICE' THEN
  PERFORM 1 FROM finance_invoice i
  JOIN finance_invoice_revision r
    ON r.invoice_id=i.id AND r.root_realm_id=i.root_realm_id
    AND r.version=i.version AND r.payload_digest=i.current_digest
  WHERE i.id=original.finance_invoice_id AND i.root_realm_id=NEW.realm_id
    AND i.status='SUBMITTED' AND i.version=original.finance_invoice_revision
    AND i.current_digest=original.finance_invoice_digest
    AND r.draft_payload=i.draft_payload FOR SHARE OF i,r;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Submitted original invoice snapshot changed' USING ERRCODE='P0928';
  END IF;
 ELSE
  PERFORM 1 FROM finance_budget b
  JOIN finance_budget_revision r
    ON r.budget_id=b.id AND r.root_realm_id=b.root_realm_id
    AND r.version=b.version AND r.source_digest=b.current_digest
  WHERE b.id=original.finance_budget_id AND b.root_realm_id=NEW.realm_id
    AND b.status='SUBMITTED' AND b.version=original.finance_budget_revision
    AND b.current_digest=original.finance_budget_digest
    AND r.financial_year_id=b.financial_year_id AND r.category_label=b.category_label
    AND r.branch_id IS NOT DISTINCT FROM b.branch_id
    AND r.approved_ceiling_minor=b.approved_ceiling_minor
    FOR SHARE OF b,r;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Submitted original budget ceiling or revision changed' USING ERRCODE='P0928';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_verify_finance_voucher_decision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_kind text; v_proposer uuid;
BEGIN
 SELECT case_kind,proposer_id INTO v_kind,v_proposer
 FROM cg03_case WHERE id=NEW.case_id AND realm_id=NEW.realm_id FOR SHARE;
 IF NOT FOUND OR v_kind<>'FINANCE_VOUCHER' THEN RETURN NEW; END IF;
 IF NEW.actor_id=v_proposer THEN
  RAISE EXCEPTION 'Submitter cannot approve own Finance voucher'
    USING ERRCODE='P0915';
 END IF;
 IF NEW.fresh_password_verified_at IS NULL OR NEW.step_ordinal<>1
    OR NEW.action NOT IN('APPROVE','RETURN','REJECT') THEN
  RAISE EXCEPTION 'A protected reviewer decision is required'
   USING ERRCODE='P0915';
 END IF;
 IF NEW.action='APPROVE' THEN
  PERFORM 1 FROM cg03_case c
   JOIN finance_voucher v ON v.id=c.finance_voucher_id AND v.root_realm_id=c.realm_id
   JOIN finance_voucher_draft_revision r ON r.voucher_id=v.id
     AND r.root_realm_id=v.root_realm_id AND r.version=c.finance_voucher_revision
   JOIN cg19_stored_file f ON f.id=c.finance_proof_file_id
     AND f.realm_id=c.realm_id AND f.voucher_id=v.id
     AND f.voucher_version=c.finance_voucher_revision
   JOIN cg19_upload_intent i ON i.id=f.upload_intent_id
     AND i.realm_id=f.realm_id AND i.owner_kind='CG09_VOUCHER'
   WHERE c.id=NEW.case_id AND c.realm_id=NEW.realm_id AND c.case_kind='FINANCE_VOUCHER'
     AND c.status='PENDING_OWNER'
     AND v.status='SUBMITTED' AND v.approval_case_id=c.id
     AND c.finance_voucher_revision=v.version
     AND c.finance_voucher_digest=r.payload_digest
     AND v.proof_file_id=f.id AND v.proof_file_revision=f.revision
     AND c.finance_proof_revision=f.revision
     AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
     AND i.status='VALIDATED'
   FOR SHARE OF c,v,r,f,i;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Verified voucher source or private evidence has changed'
    USING ERRCODE='P0915';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_visit_case_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE previous record; latest uuid;
BEGIN
 IF NEW.case_kind<>'FIELD_VISIT_REVIEW' THEN RETURN NEW; END IF;
 IF NEW.current_step<>1 OR NEW.status<>'SUBMITTED' OR NEW.revision<>1 OR NOT EXISTS(
  SELECT 1 FROM cg03_process p JOIN cg03_visit_review_process_current cur ON cur.process_id=p.id AND cur.realm_id=p.realm_id
  JOIN field_visit_review_snapshot snap ON snap.root_realm_id=NEW.realm_id AND snap.id=NEW.visit_review_ref
  JOIN field_visit v ON v.root_realm_id=snap.root_realm_id AND v.id=snap.visit_id
  WHERE p.id=NEW.process_id AND p.realm_id=NEW.realm_id AND p.process_kind='FIELD_VISIT_REVIEW' AND p.version=NEW.process_version
   AND snap.visit_id=NEW.visit_review_id AND snap.visit_version=NEW.visit_review_version AND snap.source_digest=NEW.visit_review_digest
   AND snap.submitted_by=NEW.proposer_id AND v.version=snap.visit_version AND v.status='PENDING_APPROVAL'
 ) THEN RAISE EXCEPTION 'Invalid original visit review source or route'; END IF;
 SELECT id INTO latest FROM cg03_case WHERE realm_id=NEW.realm_id AND case_kind='FIELD_VISIT_REVIEW'
   AND visit_review_id=NEW.visit_review_id ORDER BY visit_review_version DESC LIMIT 1;
 IF NEW.previous_case_id IS DISTINCT FROM latest THEN RAISE EXCEPTION 'Visit correction requires latest returned case'; END IF;
 IF NEW.previous_case_id IS NOT NULL THEN
  SELECT status,visit_review_version INTO previous FROM cg03_case WHERE realm_id=NEW.realm_id
   AND id=NEW.previous_case_id AND case_kind='FIELD_VISIT_REVIEW' AND visit_review_id=NEW.visit_review_id;
  IF NOT FOUND OR previous.status<>'RETURNED' OR previous.visit_review_version>=NEW.visit_review_version THEN
   RAISE EXCEPTION 'Invalid returned visit review predecessor';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_visit_decision_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record; v record; step record;
BEGIN
 SELECT * INTO c FROM cg03_case WHERE id=NEW.case_id AND realm_id=NEW.realm_id;
 IF NOT FOUND OR c.case_kind<>'FIELD_VISIT_REVIEW' THEN RETURN NEW; END IF;
 SELECT actor_account_ref,version,status INTO v FROM field_visit WHERE root_realm_id=NEW.realm_id AND id=c.visit_review_id;
 SELECT * INTO step FROM cg03_process_step WHERE process_id=c.process_id AND ordinal=NEW.step_ordinal;
 IF NOT FOUND OR v.version IS DISTINCT FROM c.visit_review_version OR v.status IS DISTINCT FROM 'PENDING_APPROVAL'
   OR NEW.actor_id=c.proposer_id OR NEW.actor_id=v.actor_account_ref
   OR NEW.accepted_case_revision<>c.revision OR NEW.expected_case_revision+1<>NEW.accepted_case_revision
   OR (step.protected_root_required AND (NEW.fresh_password_verified_at IS NULL OR NEW.action='FORWARD'))
   OR (NOT step.protected_root_required AND NEW.fresh_password_verified_at IS NOT NULL)
   OR (NEW.action='RETURN' AND c.status<>'RETURNED') OR (NEW.action='REJECT' AND c.status<>'REJECTED')
   OR (NEW.action IN('APPROVE','FORWARD') AND
       (step.protected_root_required AND c.status<>'PENDING_OWNER'
        OR NOT step.protected_root_required AND (c.status<>'IN_REVIEW' OR c.current_step<>NEW.step_ordinal+1)))
   OR (NOT (c.status='IN_REVIEW') AND c.current_step<>NEW.step_ordinal)
   OR EXISTS(SELECT 1 FROM cg03_case_decision prior WHERE prior.realm_id=NEW.realm_id AND prior.case_id=NEW.case_id
      AND prior.step_ordinal<NEW.step_ordinal AND prior.actor_id=NEW.actor_id)
   OR (NEW.step_ordinal>1 AND NOT EXISTS(SELECT 1 FROM cg03_case_decision prior WHERE prior.realm_id=NEW.realm_id
      AND prior.case_id=NEW.case_id AND prior.step_ordinal=1 AND prior.action IN('FORWARD','APPROVE'))) THEN
  RAISE EXCEPTION 'Decision does not match the original visit review step';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_visit_route_current_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM cg03_process p WHERE p.id=NEW.process_id AND p.realm_id=NEW.realm_id AND p.process_kind='FIELD_VISIT_REVIEW'
  AND ((p.first_reviewer_capability IS NULL AND EXISTS(SELECT 1 FROM cg03_process_step s WHERE s.process_id=p.id AND s.ordinal=1 AND s.capability_key='approvals.review' AND s.protected_root_required) AND (SELECT count(*) FROM cg03_process_step s WHERE s.process_id=p.id)=1)
   OR (p.first_reviewer_capability='projects.visits.manage' AND EXISTS(SELECT 1 FROM cg03_process_step s WHERE s.process_id=p.id AND s.ordinal=1 AND s.capability_key='projects.visits.manage' AND NOT s.protected_root_required) AND EXISTS(SELECT 1 FROM cg03_process_step s WHERE s.process_id=p.id AND s.ordinal=2 AND s.capability_key='approvals.review' AND s.protected_root_required) AND (SELECT count(*) FROM cg03_process_step s WHERE s.process_id=p.id)=2)))
 THEN RAISE EXCEPTION 'Incomplete field visit review route'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_visit_route_step_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM cg03_process p WHERE p.id=NEW.process_id AND p.process_kind='FIELD_VISIT_REVIEW') THEN
  IF NOT EXISTS(SELECT 1 FROM cg03_process p WHERE p.id=NEW.process_id AND
    ((p.first_reviewer_capability IS NULL AND NEW.ordinal=1 AND NEW.capability_key='approvals.review' AND NEW.protected_root_required)
    OR (p.first_reviewer_capability='projects.visits.manage' AND
       ((NEW.ordinal=1 AND NEW.capability_key='projects.visits.manage' AND NOT NEW.protected_root_required)
        OR (NEW.ordinal=2 AND NEW.capability_key='approvals.review' AND NEW.protected_root_required))))) THEN
    RAISE EXCEPTION 'Invalid field visit review route';
  END IF;
 ELSIF NEW.capability_key='projects.visits.manage' THEN
  RAISE EXCEPTION 'Visit reviewer step belongs only to field visit review';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_volunteer_case_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.volunteer_review_ref,NEW.volunteer_application_id,NEW.volunteer_application_version,NEW.volunteer_review_digest) IS DISTINCT FROM
     (OLD.volunteer_review_ref,OLD.volunteer_application_id,OLD.volunteer_application_version,OLD.volunteer_review_digest)
   THEN RAISE EXCEPTION 'Frozen volunteer review source cannot change'; END IF;
 ELSE
  IF NEW.case_kind='VOLUNTEER_APPLICATION' AND NOT EXISTS(
   SELECT 1 FROM volunteer_review_snapshot s JOIN volunteer_application a ON a.root_realm_id=s.root_realm_id AND a.id=s.application_id
    JOIN cg03_volunteer_process_current cur ON cur.realm_id=s.root_realm_id AND cur.process_id=NEW.process_id
    JOIN cg03_process p ON p.realm_id=cur.realm_id AND p.id=cur.process_id
    WHERE s.root_realm_id=NEW.realm_id AND s.id=NEW.volunteer_review_ref AND s.submitted_by=NEW.proposer_id
    AND a.version=s.application_version AND a.status='SUBMITTED' AND a.submitted_digest=s.source_digest
    AND p.process_kind='VOLUNTEER_APPLICATION' AND p.version=NEW.process_version
    AND NEW.current_step=1 AND NEW.status='SUBMITTED' AND NEW.revision=1)
   THEN RAISE EXCEPTION 'Original current volunteer review is required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_volunteer_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record;
BEGIN
 SELECT * INTO c FROM cg03_case WHERE realm_id=NEW.realm_id AND id=NEW.case_id;
 IF NOT FOUND OR c.case_kind<>'VOLUNTEER_APPLICATION' THEN RETURN NEW; END IF;
 IF NEW.actor_id=c.proposer_id OR NEW.step_ordinal<>1 OR c.current_step<>1 OR NEW.fresh_password_verified_at IS NULL
   OR NEW.accepted_case_revision<>c.revision OR NEW.expected_case_revision+1<>NEW.accepted_case_revision
   OR NOT EXISTS(SELECT 1 FROM cg03_process p JOIN cg03_process_step s ON s.process_id=p.id
    WHERE p.realm_id=c.realm_id AND p.id=c.process_id AND p.process_kind='VOLUNTEER_APPLICATION'
    AND s.ordinal=1 AND s.capability_key='approvals.review' AND s.protected_root_required)
   OR NOT EXISTS(SELECT 1 FROM account a JOIN account_role ar ON ar.account_id=a.id AND ar.realm_id=a.realm_id AND ar.revoked_at IS NULL
    JOIN role r ON r.id=ar.role_id AND r.realm_id=ar.realm_id AND r.is_protected AND r.active
    WHERE a.id=NEW.actor_id AND a.realm_id=NEW.realm_id AND a.status='ACTIVE')
   OR NOT EXISTS(SELECT 1 FROM volunteer_application a WHERE a.root_realm_id=c.realm_id AND a.id=c.volunteer_application_id
    AND a.status='SUBMITTED' AND a.version=c.volunteer_application_version AND a.submitted_digest=c.volunteer_review_digest)
   OR NOT ((NEW.action='APPROVE' AND c.status='PENDING_OWNER') OR (NEW.action='RETURN' AND c.status='RETURNED') OR (NEW.action='REJECT' AND c.status='REJECTED'))
  THEN RAISE EXCEPTION 'Invalid protected volunteer review decision'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_volunteer_previous_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE latest record;
BEGIN
 IF NEW.case_kind<>'VOLUNTEER_APPLICATION' THEN RETURN NEW; END IF;
