END; $function$
;
CREATE OR REPLACE FUNCTION public.cg03_volunteer_process_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM cg03_process p WHERE p.id=NEW.process_id AND p.realm_id=NEW.realm_id AND p.process_kind='VOLUNTEER_APPLICATION' AND p.first_reviewer_capability IS NULL
 AND (SELECT count(*) FROM cg03_process_step s WHERE s.process_id=p.id)=1
 AND EXISTS(SELECT 1 FROM cg03_process_step s WHERE s.process_id=p.id AND s.ordinal=1 AND s.capability_key='approvals.review' AND s.protected_root_required))
 THEN RAISE EXCEPTION 'Original volunteer review route is invalid'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_application_command_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM membership_application a WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.application_id AND a.applicant_account_ref=NEW.actor_ref AND a.version=NEW.result_version
 AND ((NEW.action='CREATE' AND a.version=1 AND a.status='DRAFT') OR (NEW.action='EDIT' AND a.version>1 AND a.status='DRAFT') OR (NEW.action='CANCEL' AND a.version>1 AND a.status='CANCELLED') OR (NEW.action='SUBMIT' AND a.status='SUBMITTED' AND a.version>1)))
 THEN RAISE EXCEPTION 'Application command must match original applicant and revision'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_application_command_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status='APPROVED' THEN
  IF NOT EXISTS(SELECT 1 FROM membership_application_effect e JOIN cg03_case c ON c.realm_id=e.root_realm_id AND c.id=e.case_id WHERE e.root_realm_id=NEW.root_realm_id AND e.application_id=NEW.id AND e.pinned_review_revision=NEW.version-1 AND e.source_digest=NEW.submitted_digest AND c.status='OWNER_COMPLETED')
  THEN RAISE EXCEPTION 'Membership activation requires original owner effect'; END IF;
 ELSIF NEW.status IN('RETURNED','REJECTED') THEN
  IF NOT EXISTS(SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
   WHERE c.realm_id=NEW.root_realm_id AND c.case_kind='MEMBER_APPLICATION' AND c.membership_application_id=NEW.id
   AND c.membership_application_version=NEW.version-1 AND c.membership_review_digest=NEW.submitted_digest AND d.actor_id<>NEW.applicant_account_ref
   AND d.fresh_password_verified_at IS NOT NULL AND d.accepted_case_revision=c.revision
   AND ((NEW.status='RETURNED' AND c.status='RETURNED' AND d.action='RETURN') OR (NEW.status='REJECTED' AND c.status='REJECTED' AND d.action='REJECT')))
   THEN RAISE EXCEPTION 'Application state requires original protected CG03 decision'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM membership_application_command c WHERE c.root_realm_id=NEW.root_realm_id AND c.application_id=NEW.id AND c.result_version=NEW.version AND c.actor_ref=NEW.applicant_account_ref) THEN RAISE EXCEPTION 'Original applicant command required'; END IF;
  IF NEW.status='SUBMITTED' AND NOT EXISTS(SELECT 1 FROM membership_review_snapshot s JOIN cg03_case c ON c.realm_id=s.root_realm_id AND c.membership_review_ref=s.id JOIN membership_application_command cmd ON cmd.root_realm_id=s.root_realm_id AND cmd.request_key=s.request_key
    JOIN membership_review_file f ON f.root_realm_id=s.root_realm_id AND f.snapshot_id=s.id
    JOIN cg19_membership_private_file doc ON doc.realm_id=f.root_realm_id AND doc.id=f.file_id
    WHERE s.root_realm_id=NEW.root_realm_id AND s.application_id=NEW.id AND s.application_version=NEW.version AND s.source_digest=NEW.submitted_digest AND s.submitted_by=NEW.applicant_account_ref
    AND cmd.application_id=NEW.id AND cmd.result_version=NEW.version AND cmd.action='SUBMIT' AND c.case_kind='MEMBER_APPLICATION'
    AND f.application_id=NEW.id AND f.classification='MEMBER_IDENTITY_PROOF' AND doc.classification=f.classification AND doc.sha256=f.sha256 AND doc.revision=f.file_version AND doc.revoked_at IS NULL)
    THEN RAISE EXCEPTION 'Submission requires original protected evidence and review case'; END IF;
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_application_draft_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Membership application history must be retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1 OR NEW.submitted_digest IS NOT NULL THEN RAISE EXCEPTION 'Invalid membership application start'; END IF;
 ELSE
  IF NEW.version<>OLD.version+1 OR (NEW.id,NEW.root_realm_id,NEW.application_ref,NEW.applicant_account_ref,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.application_ref,OLD.applicant_account_ref,OLD.created_at)
   OR NOT ((OLD.status IN('DRAFT','RETURNED') AND NEW.status IN('DRAFT','CANCELLED','SUBMITTED')) OR (OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED')))
   THEN RAISE EXCEPTION 'Invalid membership application revision'; END IF;
  IF NEW.status IN('SUBMITTED','RETURNED','REJECTED','CANCELLED','APPROVED')
   AND (to_jsonb(NEW)-'status'-'version'-'updated_at'-'submitted_at'-'submitted_digest') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'version'-'updated_at'-'submitted_at'-'submitted_digest')
   THEN RAISE EXCEPTION 'A review transition cannot change the accepted applicant source'; END IF;
  IF OLD.status='SUBMITTED' AND (NEW.submitted_digest,NEW.submitted_at) IS DISTINCT FROM (OLD.submitted_digest,OLD.submitted_at)
   THEN RAISE EXCEPTION 'Original submitted snapshot is immutable'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM access_realm r WHERE r.id=NEW.root_realm_id AND r.realm_key='FOUNDATION_ROOT') THEN RAISE EXCEPTION 'Invalid Foundation membership scope'; END IF;
 IF NEW.status IN('DRAFT','SUBMITTED') THEN
  IF NOT EXISTS(SELECT 1 FROM account a WHERE a.id=NEW.applicant_account_ref AND a.realm_id=NEW.root_realm_id
    AND a.status='ACTIVE' AND a.contact_phone_verified_at IS NOT NULL AND a.contact_phone=NEW.contact_mobile
    AND a.display_name=NEW.display_name AND a.normalized_email IS NOT DISTINCT FROM NEW.contact_email FOR SHARE)
   THEN RAISE EXCEPTION 'A verified original applicant contact is required'; END IF;
  IF NOT EXISTS(SELECT 1 FROM membership_tier_version v JOIN membership_tier t ON t.root_realm_id=v.root_realm_id AND t.id=v.tier_id
   WHERE v.root_realm_id=NEW.root_realm_id AND v.id=NEW.tier_version_id AND t.version=v.version_no AND t.status='ACTIVE'
    AND v.status='ACTIVE' AND v.published_at<=now() FOR SHARE OF t) AND NOT EXISTS(SELECT 1 FROM finance_membership_collection fee WHERE fee.root_realm_id=NEW.root_realm_id AND fee.application_id=NEW.id AND fee.amount_minor=NEW.accepted_fee_minor AND fee.branch_id IS NOT DISTINCT FROM NEW.branch_ref) THEN RAISE EXCEPTION 'Select a current published membership plan'; END IF;
  IF NEW.branch_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM branch b WHERE b.root_realm_id=NEW.root_realm_id AND b.id=NEW.branch_ref AND b.status='ACTIVE' FOR SHARE) THEN RAISE EXCEPTION 'Select an active branch'; END IF;
  IF NOT EXISTS(SELECT 1 FROM geography_area s JOIN geography_area d ON d.root_realm_id=s.root_realm_id AND d.parent_area_id=s.id WHERE s.root_realm_id=NEW.root_realm_id AND s.id=NEW.state_ref AND s.level='STATE' AND s.status='ACTIVE' AND d.id=NEW.district_ref AND d.level='DISTRICT' AND d.status='ACTIVE' FOR SHARE OF s,d) THEN RAISE EXCEPTION 'Select current state and district'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_current_volunteer(root uuid, volunteer_ref uuid, account_ref uuid, project_branch uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(SELECT 1 FROM volunteer v
 JOIN volunteer_application app ON app.root_realm_id=v.root_realm_id AND app.id=v.original_application_id AND app.status='APPROVED'
 JOIN volunteer_approval_effect effect ON effect.root_realm_id=v.root_realm_id AND effect.volunteer_id=v.id AND effect.application_id=app.id
 JOIN cg03_case review ON review.realm_id=effect.root_realm_id AND review.id=effect.case_id
  AND review.case_kind='VOLUNTEER_APPLICATION' AND review.status='OWNER_COMPLETED'
 JOIN account person ON person.realm_id=v.root_realm_id AND person.id=v.account_ref
  AND person.status='ACTIVE' AND person.contact_phone_verified_at IS NOT NULL
  AND person.contact_phone=app.contact_mobile AND person.normalized_email IS NOT DISTINCT FROM app.contact_email
 JOIN department d ON d.root_realm_id=v.root_realm_id AND d.id=v.department_ref AND d.active AND d.kind='DEPARTMENT'
 JOIN volunteer_affiliation_history affiliation ON affiliation.root_realm_id=v.root_realm_id
  AND affiliation.volunteer_id=v.id AND affiliation.effective_to IS NULL
  AND affiliation.branch_ref IS NOT DISTINCT FROM v.branch_ref AND affiliation.department_ref=v.department_ref
 WHERE v.root_realm_id=root AND v.id=volunteer_ref AND v.account_ref=account_ref AND v.status='ACTIVE'
  AND v.branch_ref IS NOT DISTINCT FROM project_branch
  AND (v.branch_ref IS NULL OR EXISTS(SELECT 1 FROM branch b WHERE b.root_realm_id=root AND b.id=v.branch_ref AND b.status='ACTIVE'))
  AND ((d.scope_kind='FOUNDATION' AND (v.branch_ref IS NULL OR EXISTS(
    SELECT 1 FROM branch_department_link link WHERE link.root_realm_id=root AND link.branch_id=v.branch_ref
      AND link.foundation_department_id=d.id AND link.ended_at IS NULL)))
    OR (d.scope_kind='BRANCH' AND d.branch_id=v.branch_ref))
  AND EXISTS(SELECT 1 FROM cg19_volunteer_private_file proof
    JOIN volunteer_review_file frozen ON frozen.root_realm_id=proof.realm_id AND frozen.file_id=proof.id
    JOIN cg03_case original ON original.realm_id=frozen.root_realm_id AND original.volunteer_review_ref=frozen.snapshot_id
      AND original.id=review.id
    WHERE proof.realm_id=root AND proof.application_id=app.id
      AND frozen.classification='VOLUNTEER_IDENTITY_PROOF' AND proof.scan_status='CLEAN_VERIFIED'
      AND proof.revoked_at IS NULL AND proof.revision=frozen.file_version AND proof.sha256=frozen.sha256));
 $function$
;
CREATE OR REPLACE FUNCTION public.cg04_effect_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT cg04_member_approved_source(NEW.root_realm_id,NEW.application_id)
 OR NOT EXISTS(SELECT 1 FROM membership_application a JOIN cg03_case c ON c.realm_id=a.root_realm_id AND c.membership_application_id=a.id
 JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id AND d.action='APPROVE' AND d.accepted_case_revision=c.revision
 JOIN member m ON m.root_realm_id=a.root_realm_id AND ((NEW.effect_kind='ACTIVATE' AND m.original_application_id=a.id)
 OR (NEW.effect_kind='RENEW' AND m.original_application_id<>a.id AND m.account_ref=a.applicant_account_ref
 AND m.status='ACTIVE' AND m.branch_ref IS NOT DISTINCT FROM a.branch_ref))
 JOIN membership_term t ON t.root_realm_id=m.root_realm_id AND t.member_id=m.id AND t.original_application_id=a.id
 JOIN member_branch_history b ON b.root_realm_id=m.root_realm_id AND b.member_id=m.id AND b.branch_ref IS NOT DISTINCT FROM m.branch_ref AND b.effective_to IS NULL AND b.actor_ref=a.applicant_account_ref
 WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.application_id AND c.id=NEW.case_id AND d.id=NEW.decision_id
 AND c.membership_application_version=NEW.pinned_review_revision AND c.membership_review_digest=NEW.source_digest
 AND m.id=NEW.member_id AND t.id=NEW.term_id AND NEW.actor_ref=a.applicant_account_ref
 AND ((a.accepted_fee_minor=0 AND NEW.fee_journal_id IS NULL) OR EXISTS(SELECT 1 FROM finance_membership_verified_collection v WHERE v.root_realm_id=a.root_realm_id AND v.application_id=a.id AND v.journal_id=NEW.fee_journal_id AND v.amount_minor=a.accepted_fee_minor)))
 THEN RAISE EXCEPTION 'Membership effect must match original approval, fee and term'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_expense_volunteer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.volunteer_ref,NEW.volunteer_branch_ref,NEW.volunteer_project_ref,
    NEW.volunteer_requested_method,NEW.volunteer_entered_utr)
   IS DISTINCT FROM
   (OLD.volunteer_ref,OLD.volunteer_branch_ref,OLD.volunteer_project_ref,
    OLD.volunteer_requested_method,OLD.volunteer_entered_utr)
  THEN RAISE EXCEPTION 'Original reimbursement volunteer source is immutable'; END IF;
 END IF;
 IF NEW.volunteer_ref IS NOT NULL
    AND (TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.status='DRAFT' AND NEW.status<>'DRAFT')) THEN
  IF NOT EXISTS(SELECT 1 FROM volunteer v WHERE v.root_realm_id=NEW.root_realm_id
    AND v.id=NEW.volunteer_ref AND v.branch_ref IS NOT DISTINCT FROM NEW.volunteer_branch_ref
    AND cg04_current_volunteer(NEW.root_realm_id,v.id,v.account_ref,NEW.volunteer_branch_ref))
  THEN RAISE EXCEPTION 'Original currently verified volunteer is required for reimbursement'; END IF;
  IF NEW.volunteer_project_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM project p
    WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.volunteer_project_ref
     AND p.branch_ref IS NOT DISTINCT FROM NEW.volunteer_branch_ref
     AND p.status NOT IN('COMPLETED','CANCELLED'))
  THEN RAISE EXCEPTION 'Choose a current Foundation project for volunteer reimbursement'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_initial_branch_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Original membership affiliation history is retained'; END IF;
 IF NEW.effective_to IS NOT NULL OR NOT EXISTS(SELECT 1 FROM member m WHERE m.root_realm_id=NEW.root_realm_id AND m.id=NEW.member_id AND m.branch_ref IS NOT DISTINCT FROM NEW.branch_ref)
 THEN RAISE EXCEPTION 'Initial member branch history must match its source'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_member_approved_source(realm uuid, app uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(SELECT 1 FROM membership_application a
 JOIN cg03_case c ON c.realm_id=a.root_realm_id AND c.membership_application_id=a.id
 JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
 JOIN account reviewer ON reviewer.id=d.actor_id AND reviewer.realm_id=d.realm_id AND reviewer.status='ACTIVE'
 JOIN account_role ar ON ar.account_id=reviewer.id AND ar.realm_id=reviewer.realm_id AND ar.revoked_at IS NULL
 JOIN role r ON r.id=ar.role_id AND r.realm_id=ar.realm_id AND r.active AND r.is_protected
 JOIN cg03_process p ON p.id=c.process_id AND p.realm_id=c.realm_id AND p.process_kind='MEMBER_APPLICATION'
 JOIN cg03_process_step step ON step.process_id=p.id AND step.ordinal=d.step_ordinal AND step.protected_root_required AND step.capability_key='approvals.review'
 WHERE a.root_realm_id=realm AND a.id=app AND a.status='SUBMITTED' AND c.case_kind='MEMBER_APPLICATION' AND c.status='PENDING_OWNER'
 AND c.membership_application_version=a.version AND c.membership_review_digest=a.submitted_digest
 AND d.action='APPROVE' AND d.actor_id<>a.applicant_account_ref AND d.fresh_password_verified_at IS NOT NULL AND d.step_ordinal=1 AND d.accepted_case_revision=c.revision
 AND (a.accepted_fee_minor=0 OR EXISTS(SELECT 1 FROM finance_membership_verified_collection v WHERE v.root_realm_id=a.root_realm_id AND v.application_id=a.id AND v.amount_minor=a.accepted_fee_minor))
 AND NOT EXISTS(SELECT 1 FROM finance_membership_refund_request rr WHERE rr.root_realm_id=a.root_realm_id AND rr.application_id=a.id)
 AND EXISTS(SELECT 1 FROM membership_review_file f JOIN cg19_membership_private_file doc ON doc.realm_id=f.root_realm_id AND doc.id=f.file_id
 WHERE f.root_realm_id=c.realm_id AND f.snapshot_id=c.membership_review_ref AND f.application_id=a.id AND f.classification='MEMBER_IDENTITY_PROOF' AND doc.revoked_at IS NULL AND doc.scan_status='CLEAN_VERIFIED' AND doc.revision=f.file_version AND doc.sha256=f.sha256)
 AND NOT EXISTS(SELECT 1 FROM membership_review_file f JOIN cg19_membership_private_file doc ON doc.realm_id=f.root_realm_id AND doc.id=f.file_id WHERE f.root_realm_id=c.realm_id AND f.snapshot_id=c.membership_review_ref AND (doc.revoked_at IS NOT NULL OR doc.revision<>f.file_version OR doc.sha256<>f.sha256 OR doc.scan_status<>'CLEAN_VERIFIED'))
 AND EXISTS(SELECT 1 FROM account owner WHERE owner.realm_id=a.root_realm_id AND owner.id=a.applicant_account_ref AND owner.status='ACTIVE' AND owner.contact_phone_verified_at IS NOT NULL)
 AND (a.branch_ref IS NULL OR EXISTS(SELECT 1 FROM branch b WHERE b.root_realm_id=a.root_realm_id AND b.id=a.branch_ref AND b.status='ACTIVE')));
$function$
;
CREATE OR REPLACE FUNCTION public.cg04_member_completion_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM membership_application_effect e JOIN membership_application a ON a.root_realm_id=e.root_realm_id AND a.id=e.application_id
 JOIN cg03_case c ON c.realm_id=e.root_realm_id AND c.id=e.case_id
 WHERE e.root_realm_id=NEW.root_realm_id AND e.member_id=NEW.id AND a.status='APPROVED' AND c.status='OWNER_COMPLETED')
 THEN RAISE EXCEPTION 'Original member completion required'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_member_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original member must be retained'; END IF;
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Protected member profile changes require their original review'; END IF;
 IF NEW.version<>1 OR NEW.status<>'ACTIVE' OR NOT cg04_member_approved_source(NEW.root_realm_id,NEW.original_application_id)
 OR NOT EXISTS(SELECT 1 FROM membership_application a WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.original_application_id AND a.applicant_account_ref=NEW.account_ref AND a.display_name=NEW.display_name AND a.branch_ref IS NOT DISTINCT FROM NEW.branch_ref)
 THEN RAISE EXCEPTION 'Member requires original approved verified application'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_membership_review_file_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM membership_review_snapshot s JOIN cg19_membership_private_file d ON d.realm_id=s.root_realm_id AND d.application_id=s.application_id
   WHERE s.root_realm_id=NEW.root_realm_id AND s.id=NEW.snapshot_id AND s.application_id=NEW.application_id
   AND d.id=NEW.file_id AND d.application_version=NEW.source_version AND d.revision=NEW.file_version AND d.classification=NEW.classification AND d.sha256=NEW.sha256
   AND d.scan_status='CLEAN_VERIFIED' AND d.revoked_at IS NULL AND d.application_version<s.application_version)
 THEN RAISE EXCEPTION 'Review proof must match original private verified file'; END IF; RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_membership_snapshot_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM membership_application a WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.application_id
   AND a.applicant_account_ref=NEW.submitted_by AND a.status='SUBMITTED' AND a.version=NEW.application_version AND a.submitted_digest=NEW.source_digest
   AND to_jsonb(a)-'status'-'version'-'updated_at'-'submitted_at'-'submitted_digest'=NEW.source_snapshot->'record')
 OR jsonb_typeof(NEW.source_snapshot->'files') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'Frozen membership snapshot must match original submitted applicant'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_renewal_effect_completion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.effect_kind='RENEW' AND NOT EXISTS(
  SELECT 1 FROM member m JOIN membership_term prior ON prior.root_realm_id=m.root_realm_id AND prior.member_id=m.id
  JOIN membership_term current_term ON current_term.root_realm_id=m.root_realm_id AND current_term.id=NEW.term_id
  WHERE m.root_realm_id=NEW.root_realm_id AND m.id=NEW.member_id
  AND m.original_application_id<>NEW.application_id AND m.status='ACTIVE'
  AND current_term.original_application_id=NEW.application_id
  AND prior.id<>current_term.id AND prior.expires_on IS NOT NULL
  AND prior.expires_on<=current_term.starts_on
 ) THEN RAISE EXCEPTION 'Original member and prior finite term required for renewal'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_review_completion_at_commit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.case_kind<>'MEMBER_APPLICATION' THEN RETURN NULL; END IF;
 IF NEW.status='OWNER_COMPLETED' AND NOT EXISTS(SELECT 1 FROM membership_application_effect e JOIN membership_application a ON a.root_realm_id=e.root_realm_id AND a.id=e.application_id WHERE e.root_realm_id=NEW.realm_id AND e.case_id=NEW.id AND e.application_id=NEW.membership_application_id AND a.status='APPROVED') THEN RAISE EXCEPTION 'Original membership owner effect required'; END IF;
 IF NEW.status='PENDING_OWNER' AND NOT EXISTS(SELECT 1 FROM cg03_case_decision d WHERE d.realm_id=NEW.realm_id AND d.case_id=NEW.id AND d.action='APPROVE' AND d.step_ordinal=1 AND d.fresh_password_verified_at IS NOT NULL AND d.accepted_case_revision=NEW.revision) THEN RAISE EXCEPTION 'Original protected membership decision required'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_staff_intake_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.expires_at>now() OR OLD.linked_application_id IS NOT NULL
  THEN RAISE EXCEPTION 'Unverified intake must be retained until privacy expiry or applicant linkage'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.linked_application_id IS NOT NULL OR NEW.linked_application_id IS NULL OR NEW.linked_at IS NULL
   OR (NEW.root_realm_id,NEW.id,NEW.batch_id,NEW.first_name,NEW.last_name,NEW.contact_mobile,
     NEW.city,NEW.state,NEW.expires_at,NEW.created_at)
    IS DISTINCT FROM (OLD.root_realm_id,OLD.id,OLD.batch_id,OLD.first_name,OLD.last_name,OLD.contact_mobile,
     OLD.city,OLD.state,OLD.expires_at,OLD.created_at)
  THEN RAISE EXCEPTION 'Staff intake candidate cannot be converted without real applicant self registration'; END IF;
  IF NOT EXISTS(SELECT 1 FROM volunteer_application app
    WHERE app.root_realm_id=NEW.root_realm_id AND app.id=NEW.linked_application_id AND app.contact_mobile=NEW.contact_mobile
     AND app.consent_version='VOLUNTEER_V1' AND app.consented_at IS NOT NULL)
  THEN RAISE EXCEPTION 'Verified self application and consent required before intake link'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_task_volunteer_event_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM project_task_event e
   WHERE e.root_realm_id=NEW.root_realm_id AND e.task_id=NEW.id AND e.result_version=NEW.version
   AND e.assignee_volunteer_ref IS NOT DISTINCT FROM NEW.assignee_volunteer_ref)
 THEN RAISE EXCEPTION 'Task volunteer assignment must match its immutable original event'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_task_volunteer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.assignee_volunteer_ref IS NOT NULL AND NEW.status NOT IN('CANCELLED','COMPLETED')
  AND NOT cg04_current_volunteer(NEW.root_realm_id,NEW.assignee_volunteer_ref,NEW.assignee_account_ref,NEW.assignee_branch_ref)
 THEN RAISE EXCEPTION 'Current approved volunteer affiliation required for task assignment'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_term_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE offer record;
BEGIN
 PERFORM 1 FROM member m WHERE m.root_realm_id=NEW.root_realm_id AND m.id=NEW.member_id FOR UPDATE;
 SELECT v.duration_unit,v.duration_count INTO offer FROM membership_application a JOIN membership_tier_version v ON v.root_realm_id=a.root_realm_id AND v.id=a.tier_version_id
 JOIN member m ON m.root_realm_id=a.root_realm_id AND (m.original_application_id=a.id OR (m.account_ref=a.applicant_account_ref AND m.status='ACTIVE' AND m.original_application_id<>a.id AND m.branch_ref IS NOT DISTINCT FROM a.branch_ref))
 WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.original_application_id AND m.id=NEW.member_id AND a.tier_version_id=NEW.tier_version_id AND a.accepted_fee_minor=NEW.fee_minor;
 IF NOT FOUND OR NOT cg04_member_approved_source(NEW.root_realm_id,NEW.original_application_id)
 OR NEW.starts_on<> (
 SELECT CASE WHEN count(*)=0 THEN (now() AT TIME ZONE 'Asia/Kolkata')::date
 ELSE GREATEST((now() AT TIME ZONE 'Asia/Kolkata')::date,max(t.expires_on)) END
 FROM membership_term t WHERE t.root_realm_id=NEW.root_realm_id AND t.member_id=NEW.member_id)
 OR EXISTS(SELECT 1 FROM membership_term t WHERE t.root_realm_id=NEW.root_realm_id AND t.member_id=NEW.member_id
   AND (t.expires_on IS NULL OR t.starts_on>(now() AT TIME ZONE 'Asia/Kolkata')::date))
 OR NEW.expires_on IS DISTINCT FROM (CASE offer.duration_unit WHEN 'LIFETIME' THEN NULL::date WHEN 'DAY' THEN NEW.starts_on+offer.duration_count WHEN 'MONTH' THEN (NEW.starts_on+make_interval(months=>offer.duration_count))::date ELSE (NEW.starts_on+make_interval(years=>offer.duration_count))::date END)
 OR EXISTS(SELECT 1 FROM membership_term t WHERE t.root_realm_id=NEW.root_realm_id AND t.member_id=NEW.member_id AND daterange(t.starts_on,t.expires_on,'[)')&&daterange(NEW.starts_on,NEW.expires_on,'[)'))
 THEN RAISE EXCEPTION 'Original membership term, dates or amount invalid'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_tier_history_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Membership plan history cannot be changed'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_tier_revision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Membership plan history must be retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.version<>1 OR NOT EXISTS(SELECT 1 FROM access_realm WHERE id=NEW.root_realm_id AND realm_key='FOUNDATION_ROOT') THEN RAISE EXCEPTION 'Invalid starting plan revision or Foundation scope'; END IF;
 ELSE
  IF NEW.version<>OLD.version+1 OR (NEW.id,NEW.root_realm_id,NEW.plan_code,NEW.created_by,NEW.created_at)
     IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.plan_code,OLD.created_by,OLD.created_at)
  THEN RAISE EXCEPTION 'Invalid membership plan revision'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_tier_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM membership_tier t WHERE t.root_realm_id=NEW.root_realm_id AND t.id=NEW.tier_id AND t.version=NEW.version_no AND t.status=NEW.status FOR SHARE)
  THEN RAISE EXCEPTION 'Membership plan version must match its current revision'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.benefits) b WHERE jsonb_typeof(b)<>'object' OR NOT (b ? 'title' AND b ? 'description') OR jsonb_typeof(b->'title') IS DISTINCT FROM 'string' OR jsonb_typeof(b->'description') IS DISTINCT FROM 'string' OR char_length(btrim(b->>'title')) NOT BETWEEN 1 AND 200 OR char_length(b->>'description')>500 OR b - 'title' - 'description' <> '{}'::jsonb)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.benefits) b GROUP BY lower(btrim(b->>'title')) HAVING count(*)>1)
  THEN RAISE EXCEPTION 'Invalid membership plan benefit'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_visit_volunteer_event_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM field_visit_event e WHERE e.root_realm_id=NEW.root_realm_id
   AND e.visit_id=NEW.id AND e.result_version=NEW.version
   AND e.actor_volunteer_ref IS NOT DISTINCT FROM NEW.actor_volunteer_ref)
 THEN RAISE EXCEPTION 'Visit volunteer source must match its immutable original event'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_visit_volunteer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE assigned record;
BEGIN
 IF TG_OP='UPDATE' AND OLD.started_at IS NOT NULL
   AND NEW.actor_volunteer_ref IS DISTINCT FROM OLD.actor_volunteer_ref
 THEN RAISE EXCEPTION 'Accepted field visit volunteer assignment is immutable'; END IF;
 IF NEW.actor_volunteer_ref IS NOT NULL AND NEW.status NOT IN('CANCELLED','COMPLETED','REJECTED')
  AND NOT cg04_current_volunteer(NEW.root_realm_id,NEW.actor_volunteer_ref,NEW.actor_account_ref,NEW.branch_ref)
 THEN RAISE EXCEPTION 'Current approved volunteer affiliation required for field visit'; END IF;
 IF NEW.task_id IS NOT NULL THEN
  SELECT t.assignee_volunteer_ref,t.assignee_account_ref INTO assigned
  FROM project_task t WHERE t.root_realm_id=NEW.root_realm_id
   AND t.project_id=NEW.project_id AND t.id=NEW.task_id;
  IF FOUND AND (assigned.assignee_volunteer_ref IS DISTINCT FROM NEW.actor_volunteer_ref
     OR (NEW.actor_volunteer_ref IS NOT NULL AND assigned.assignee_account_ref<>NEW.actor_account_ref))
  THEN RAISE EXCEPTION 'Visit volunteer assignment must match original task assignment'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_affiliation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original volunteer branch/department history must be retained'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.effective_to<=OLD.effective_from
   OR (NEW.root_realm_id,NEW.id,NEW.volunteer_id,NEW.branch_ref,NEW.department_ref,NEW.actor_ref,NEW.reason,NEW.effective_from)
    IS DISTINCT FROM
      (OLD.root_realm_id,OLD.id,OLD.volunteer_id,OLD.branch_ref,OLD.department_ref,OLD.actor_ref,OLD.reason,OLD.effective_from)
  THEN RAISE EXCEPTION 'Original affiliation source cannot be rewritten'; END IF;
 ELSE
  IF NEW.effective_to IS NOT NULL OR NEW.reason<>'APPROVED_VOLUNTEER'
   OR NOT EXISTS(SELECT 1 FROM volunteer v
    JOIN volunteer_application a ON a.root_realm_id=v.root_realm_id AND a.id=v.original_application_id
    WHERE v.root_realm_id=NEW.root_realm_id AND v.id=NEW.volunteer_id
     AND v.branch_ref IS NOT DISTINCT FROM NEW.branch_ref
     AND v.department_ref=NEW.department_ref AND a.applicant_account_ref=NEW.actor_ref)
  THEN RAISE EXCEPTION 'Original verified volunteer affiliation required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_approved_source(root uuid, app uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(
 SELECT 1 FROM volunteer_application a
 JOIN cg03_case c ON c.realm_id=a.root_realm_id AND c.volunteer_application_id=a.id
 JOIN volunteer_review_snapshot snap ON snap.root_realm_id=c.realm_id AND snap.id=c.volunteer_review_ref
 JOIN cg03_case_decision decision ON decision.realm_id=c.realm_id AND decision.case_id=c.id
 JOIN account reviewer ON reviewer.realm_id=decision.realm_id AND reviewer.id=decision.actor_id AND reviewer.status='ACTIVE'
 JOIN account_role ar ON ar.realm_id=reviewer.realm_id AND ar.account_id=reviewer.id AND ar.revoked_at IS NULL
 JOIN role role_current ON role_current.realm_id=ar.realm_id AND role_current.id=ar.role_id AND role_current.active AND role_current.is_protected
 JOIN cg03_process process ON process.realm_id=c.realm_id AND process.id=c.process_id AND process.process_kind='VOLUNTEER_APPLICATION'
 JOIN cg03_process_step step ON step.process_id=process.id AND step.ordinal=1
  AND step.capability_key='approvals.review' AND step.protected_root_required
 JOIN department dept ON dept.root_realm_id=a.root_realm_id AND dept.id=a.department_ref
 JOIN account applicant ON applicant.realm_id=a.root_realm_id AND applicant.id=a.applicant_account_ref
 WHERE a.root_realm_id=root AND a.id=app AND a.status='SUBMITTED'
  AND c.case_kind='VOLUNTEER_APPLICATION' AND c.status='PENDING_OWNER'
  AND c.volunteer_application_version=a.version AND c.volunteer_review_digest=a.submitted_digest
  AND snap.application_id=a.id AND snap.application_version=a.version AND snap.source_digest=a.submitted_digest
  AND decision.action='APPROVE' AND decision.actor_id<>a.applicant_account_ref
  AND decision.accepted_case_revision=c.revision AND decision.step_ordinal=1
  AND decision.fresh_password_verified_at IS NOT NULL
  AND applicant.status='ACTIVE' AND applicant.contact_phone_verified_at IS NOT NULL
  AND applicant.contact_phone=a.contact_mobile AND applicant.normalized_email IS NOT DISTINCT FROM a.contact_email
  AND dept.active AND dept.kind='DEPARTMENT'
  AND ((dept.scope_kind='FOUNDATION' AND (a.branch_ref IS NULL OR EXISTS(
    SELECT 1 FROM branch_department_link l WHERE l.root_realm_id=root AND l.branch_id=a.branch_ref
      AND l.foundation_department_id=dept.id AND l.ended_at IS NULL)))
   OR (dept.scope_kind='BRANCH' AND dept.branch_id=a.branch_ref))
  AND (a.branch_ref IS NULL OR EXISTS(SELECT 1 FROM branch b WHERE b.root_realm_id=root AND b.id=a.branch_ref AND b.status='ACTIVE'))
  AND EXISTS(SELECT 1 FROM volunteer_review_file f
   JOIN cg19_volunteer_private_file doc ON doc.realm_id=f.root_realm_id AND doc.id=f.file_id AND doc.application_id=f.application_id
   WHERE f.root_realm_id=root AND f.snapshot_id=c.volunteer_review_ref AND f.application_id=a.id
   AND f.classification='VOLUNTEER_IDENTITY_PROOF' AND doc.classification=f.classification
   AND doc.sha256=f.sha256 AND doc.revision=f.file_version AND doc.revoked_at IS NULL AND doc.scan_status='CLEAN_VERIFIED')
  AND NOT EXISTS(SELECT 1 FROM volunteer_review_file f
    JOIN cg19_volunteer_private_file doc ON doc.realm_id=f.root_realm_id AND doc.id=f.file_id AND doc.application_id=f.application_id
    WHERE f.root_realm_id=root AND f.snapshot_id=c.volunteer_review_ref AND
      (doc.revoked_at IS NOT NULL OR doc.sha256<>f.sha256 OR doc.revision<>f.file_version OR doc.scan_status<>'CLEAN_VERIFIED'))
 );
$function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_command_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM volunteer_application a WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.application_id AND a.applicant_account_ref=NEW.actor_ref AND a.version=NEW.result_version
 AND ((NEW.action='CREATE' AND a.version=1 AND a.status='DRAFT') OR (NEW.action='EDIT' AND a.version>1 AND a.status='DRAFT') OR (NEW.action='CANCEL' AND a.version>1 AND a.status='CANCELLED') OR (NEW.action='SUBMIT' AND a.status='SUBMITTED' AND a.version>1)))
 THEN RAISE EXCEPTION 'Application command must match original applicant and revision'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_command_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status='APPROVED' THEN
  IF NOT EXISTS(SELECT 1 FROM volunteer_approval_effect effect JOIN cg03_case review
   ON review.realm_id=effect.root_realm_id AND review.id=effect.case_id
   WHERE effect.root_realm_id=NEW.root_realm_id AND effect.application_id=NEW.id
    AND review.status='OWNER_COMPLETED' AND review.case_kind='VOLUNTEER_APPLICATION'
    AND review.volunteer_review_digest=NEW.submitted_digest
    AND effect.actor_ref=NEW.applicant_account_ref)
  THEN RAISE EXCEPTION 'Approved volunteer requires the actual independent effect'; END IF;
 ELSIF NEW.status IN('RETURNED','REJECTED') THEN
  IF NOT EXISTS(SELECT 1 FROM cg03_case review JOIN cg03_case_decision decision
   ON decision.realm_id=review.realm_id AND decision.case_id=review.id
   WHERE review.realm_id=NEW.root_realm_id AND review.case_kind='VOLUNTEER_APPLICATION'
   AND review.volunteer_application_id=NEW.id AND review.volunteer_application_version=NEW.version-1
   AND review.volunteer_review_digest=NEW.submitted_digest
   AND decision.actor_id<>NEW.applicant_account_ref AND decision.fresh_password_verified_at IS NOT NULL
   AND decision.accepted_case_revision=review.revision AND
     ((NEW.status='RETURNED' AND review.status='RETURNED' AND decision.action='RETURN')
      OR (NEW.status='REJECTED' AND review.status='REJECTED' AND decision.action='REJECT')))
  THEN RAISE EXCEPTION 'Volunteer return or rejection requires original protected decision'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM volunteer_application_command command
   WHERE command.root_realm_id=NEW.root_realm_id AND command.application_id=NEW.id
     AND command.result_version=NEW.version AND command.actor_ref=NEW.applicant_account_ref)
  THEN RAISE EXCEPTION 'A source-owner volunteer applicant command is required'; END IF;
  IF NEW.status='SUBMITTED' AND NOT EXISTS(SELECT 1 FROM volunteer_review_snapshot snapshot
   JOIN cg03_case review ON review.realm_id=snapshot.root_realm_id AND review.volunteer_review_ref=snapshot.id
   JOIN volunteer_application_command command ON command.root_realm_id=snapshot.root_realm_id AND command.request_key=snapshot.request_key
   JOIN volunteer_review_file proof ON proof.root_realm_id=snapshot.root_realm_id AND proof.snapshot_id=snapshot.id
   JOIN cg19_volunteer_private_file file ON file.realm_id=proof.root_realm_id AND file.id=proof.file_id
   WHERE snapshot.root_realm_id=NEW.root_realm_id AND snapshot.application_id=NEW.id
     AND snapshot.application_version=NEW.version AND snapshot.source_digest=NEW.submitted_digest
     AND command.application_id=NEW.id AND command.action='SUBMIT' AND command.result_version=NEW.version
     AND review.case_kind='VOLUNTEER_APPLICATION' AND review.volunteer_application_id=NEW.id
     AND proof.classification='VOLUNTEER_IDENTITY_PROOF'
     AND file.revision=proof.file_version AND file.sha256=proof.sha256 AND file.revoked_at IS NULL)
  THEN RAISE EXCEPTION 'Original verified volunteer identity and review case required'; END IF;
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_completed_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM volunteer_approval_effect effect
  JOIN volunteer_application app ON app.root_realm_id=effect.root_realm_id AND app.id=effect.application_id
  JOIN cg03_case review ON review.realm_id=effect.root_realm_id AND review.id=effect.case_id
  WHERE effect.root_realm_id=NEW.root_realm_id AND effect.volunteer_id=NEW.id
    AND app.status='APPROVED' AND review.status='OWNER_COMPLETED')
 THEN RAISE EXCEPTION 'Volunteer requires a completed original protected review'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_draft_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Volunteer application history must be retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1 OR NEW.submitted_digest IS NOT NULL THEN RAISE EXCEPTION 'Invalid volunteer application start'; END IF;
 ELSE
  IF NEW.version<>OLD.version+1 OR (NEW.id,NEW.root_realm_id,NEW.application_ref,NEW.applicant_account_ref,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.application_ref,OLD.applicant_account_ref,OLD.created_at)
   OR NOT ((OLD.status IN('DRAFT','RETURNED') AND NEW.status IN('DRAFT','CANCELLED','SUBMITTED')) OR (OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED')))
   THEN RAISE EXCEPTION 'Invalid volunteer application revision'; END IF;
  IF NEW.status IN('SUBMITTED','RETURNED','REJECTED','CANCELLED','APPROVED')
   AND (to_jsonb(NEW)-'status'-'version'-'updated_at'-'submitted_at'-'submitted_digest') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'version'-'updated_at'-'submitted_at'-'submitted_digest')
   THEN RAISE EXCEPTION 'A review transition cannot change the accepted applicant source'; END IF;
  IF OLD.status='SUBMITTED' AND (NEW.submitted_digest,NEW.submitted_at) IS DISTINCT FROM (OLD.submitted_digest,OLD.submitted_at)
   THEN RAISE EXCEPTION 'Original submitted snapshot is immutable'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM access_realm r WHERE r.id=NEW.root_realm_id AND r.realm_key='FOUNDATION_ROOT') THEN RAISE EXCEPTION 'Invalid Foundation volunteer scope'; END IF;
 IF NEW.status IN('DRAFT','SUBMITTED') THEN
  IF NOT EXISTS(SELECT 1 FROM access_realm r WHERE r.id=NEW.root_realm_id AND r.realm_key='FOUNDATION_ROOT') THEN
   RAISE EXCEPTION 'Wrong Foundation volunteer scope'; END IF;
  IF NOT EXISTS(SELECT 1 FROM account a WHERE a.id=NEW.applicant_account_ref AND a.realm_id=NEW.root_realm_id
   AND a.status='ACTIVE' AND a.contact_phone_verified_at IS NOT NULL AND a.contact_phone=NEW.contact_mobile
   AND a.normalized_email IS NOT DISTINCT FROM NEW.contact_email FOR SHARE)
  THEN RAISE EXCEPTION 'Verified applicant contact required'; END IF;
  IF NOT EXISTS(SELECT 1 FROM geography_area s JOIN geography_area d ON d.root_realm_id=s.root_realm_id AND d.parent_area_id=s.id
   WHERE s.root_realm_id=NEW.root_realm_id AND s.id=NEW.state_ref AND s.status='ACTIVE' AND s.level='STATE'
    AND d.id=NEW.district_ref AND d.status='ACTIVE' AND d.level='DISTRICT' FOR SHARE OF s,d)
  THEN RAISE EXCEPTION 'Choose real current state and district'; END IF;
  IF NEW.branch_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM branch b WHERE b.root_realm_id=NEW.root_realm_id
   AND b.id=NEW.branch_ref AND b.status='ACTIVE' FOR SHARE)
  THEN RAISE EXCEPTION 'Choose a current Foundation branch'; END IF;
  IF NOT EXISTS(SELECT 1 FROM department d WHERE d.id=NEW.department_ref AND d.root_realm_id=NEW.root_realm_id
   AND d.active AND d.kind='DEPARTMENT' AND
   ((d.scope_kind='FOUNDATION' AND (NEW.branch_ref IS NULL OR EXISTS(
    SELECT 1 FROM branch_department_link l WHERE l.root_realm_id=NEW.root_realm_id AND l.branch_id=NEW.branch_ref
      AND l.foundation_department_id=d.id AND l.ended_at IS NULL)))
    OR (d.scope_kind='BRANCH' AND d.branch_id=NEW.branch_ref))
   FOR SHARE)
  THEN RAISE EXCEPTION 'Choose an eligible current Foundation department'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_effect_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT cg04_volunteer_approved_source(NEW.root_realm_id,NEW.application_id)
  OR NOT EXISTS(SELECT 1 FROM volunteer_application app
    JOIN cg03_case c ON c.realm_id=app.root_realm_id AND c.volunteer_application_id=app.id
    JOIN cg03_case_decision decision ON decision.realm_id=c.realm_id AND decision.case_id=c.id
    JOIN volunteer v ON v.root_realm_id=app.root_realm_id AND v.original_application_id=app.id
    JOIN volunteer_affiliation_history affiliation ON affiliation.root_realm_id=v.root_realm_id
      AND affiliation.volunteer_id=v.id AND affiliation.effective_to IS NULL
    WHERE app.root_realm_id=NEW.root_realm_id AND app.id=NEW.application_id
      AND c.id=NEW.case_id AND decision.id=NEW.decision_id AND decision.action='APPROVE'
      AND decision.accepted_case_revision=c.revision AND c.volunteer_review_digest=NEW.source_digest
      AND v.id=NEW.volunteer_id AND NEW.actor_ref=app.applicant_account_ref
      AND affiliation.actor_ref=app.applicant_account_ref
      AND affiliation.department_ref=app.department_ref
      AND affiliation.branch_ref IS NOT DISTINCT FROM app.branch_ref)
 THEN RAISE EXCEPTION 'Volunteer activation effect requires exact original approval and affiliation'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'A completed volunteer identity must be retained'; END IF;
 IF TG_OP='UPDATE' THEN RAISE EXCEPTION 'Protected volunteer profile changes require original verified review'; END IF;
 IF NEW.version<>1 OR NEW.status<>'ACTIVE'
  OR NOT cg04_volunteer_approved_source(NEW.root_realm_id,NEW.original_application_id)
  OR NOT EXISTS(SELECT 1 FROM volunteer_application a WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.original_application_id
   AND a.applicant_account_ref=NEW.account_ref AND (a.first_name||' '||a.last_name)=NEW.display_name
   AND a.department_ref=NEW.department_ref AND a.branch_ref IS NOT DISTINCT FROM NEW.branch_ref
   AND a.availability=NEW.availability AND a.skills=NEW.skills)
 THEN RAISE EXCEPTION 'Verified independent volunteer approval is required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg04_volunteer_review_file_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM volunteer_review_snapshot s JOIN cg19_volunteer_private_file d ON d.realm_id=s.root_realm_id AND d.application_id=s.application_id
   WHERE s.root_realm_id=NEW.root_realm_id AND s.id=NEW.snapshot_id AND s.application_id=NEW.application_id
   AND d.id=NEW.file_id AND d.application_version=NEW.source_version AND d.revision=NEW.file_version AND d.classification=NEW.classification AND d.sha256=NEW.sha256
   AND d.scan_status='CLEAN_VERIFIED' AND d.revoked_at IS NULL AND d.application_version<s.application_version)
 THEN RAISE EXCEPTION 'Review proof must match original private verified file'; END IF; RETURN NEW;
END; $function$
;

-- Functions 91-135
CREATE OR REPLACE FUNCTION public.cg04_volunteer_snapshot_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM volunteer_application a WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.application_id
   AND a.applicant_account_ref=NEW.submitted_by AND a.status='SUBMITTED' AND a.version=NEW.application_version AND a.submitted_digest=NEW.source_digest
   AND to_jsonb(a)-'status'-'version'-'updated_at'-'submitted_at'-'submitted_digest'=NEW.source_snapshot->'record')
 OR jsonb_typeof(NEW.source_snapshot->'files') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'Frozen volunteer snapshot must match original submitted applicant'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg05_activity_event_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a project_activity%ROWTYPE; previous_status text;
BEGIN
 SELECT * INTO a FROM project_activity WHERE root_realm_id=NEW.root_realm_id AND id=NEW.activity_id FOR SHARE;
 IF NOT FOUND OR a.version<>NEW.result_version OR a.status<>NEW.resulting_status OR a.owner_account_ref<>NEW.owner_account_ref THEN
  RAISE EXCEPTION 'Activity event must match current operational revision';
 END IF;
 IF NEW.result_version=1 THEN
  IF NEW.action<>'CREATE' OR NEW.prior_status IS NOT NULL OR NEW.resulting_status NOT IN('DRAFT','SCHEDULED') THEN
   RAISE EXCEPTION 'Invalid initial activity event';
  END IF;
 ELSE
  SELECT resulting_status INTO previous_status FROM project_activity_event
   WHERE root_realm_id=NEW.root_realm_id AND activity_id=NEW.activity_id AND result_version=NEW.result_version-1;
  IF NOT FOUND OR NEW.prior_status IS DISTINCT FROM previous_status OR NEW.action='CREATE'
   OR (NEW.action='EDIT' AND NEW.prior_status<>NEW.resulting_status)
   OR (NEW.action='STATUS' AND NOT (
    (previous_status='DRAFT' AND NEW.resulting_status IN('SCHEDULED','CANCELLED'))
    OR (previous_status='SCHEDULED' AND NEW.resulting_status IN('ONGOING','CANCELLED'))
    OR (previous_status='ONGOING' AND NEW.resulting_status IN('COMPLETED','CANCELLED')))) THEN
    RAISE EXCEPTION 'Activity event must follow the preceding revision';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_activity_event_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM project_activity_event e WHERE e.root_realm_id=NEW.root_realm_id
  AND e.activity_id=NEW.id AND e.result_version=NEW.version AND e.resulting_status=NEW.status
  AND e.owner_account_ref=NEW.owner_account_ref) THEN
  RAISE EXCEPTION 'Activity revision requires an immutable matching event';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_activity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Activity history is immutable'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.version<>1 OR NEW.status NOT IN('DRAFT','SCHEDULED') THEN RAISE EXCEPTION 'Invalid initial activity state'; END IF;
 ELSE
  IF (NEW.id,NEW.root_realm_id,NEW.activity_code,NEW.created_by,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.activity_code,OLD.created_by,OLD.created_at)
   OR NEW.version<>OLD.version+1 OR OLD.status IN('COMPLETED','CANCELLED') THEN
   RAISE EXCEPTION 'Invalid activity revision';
  END IF;
  IF NEW.status<>OLD.status AND NOT (
   OLD.status='DRAFT' AND NEW.status IN('SCHEDULED','CANCELLED')
   OR OLD.status='SCHEDULED' AND NEW.status IN('ONGOING','CANCELLED')
   OR OLD.status='ONGOING' AND NEW.status IN('COMPLETED','CANCELLED')) THEN
   RAISE EXCEPTION 'Invalid activity transition';
  END IF;
 END IF;
 IF NEW.project_id IS NOT NULL THEN
  SELECT branch_ref,status,planned_start,planned_end INTO p FROM project
   WHERE root_realm_id=NEW.root_realm_id AND id=NEW.project_id FOR SHARE;
  IF NOT FOUND OR p.branch_ref IS DISTINCT FROM NEW.branch_ref
   OR (NEW.status NOT IN('CANCELLED') AND p.status IN('COMPLETED','CANCELLED'))
   OR (NEW.status<>'CANCELLED' AND p.planned_start IS NOT NULL AND (NEW.scheduled_start AT TIME ZONE 'Asia/Kolkata')::date<p.planned_start)
   OR (NEW.status<>'CANCELLED' AND p.planned_end IS NOT NULL AND (NEW.scheduled_end AT TIME ZONE 'Asia/Kolkata')::date>p.planned_end) THEN
    RAISE EXCEPTION 'Activity must use the current project scope and schedule';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_event_public_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.event_public_ref IS DISTINCT FROM OLD.event_public_ref OR NEW.event_public_id IS DISTINCT FROM OLD.event_public_id OR NEW.event_public_version IS DISTINCT FROM OLD.event_public_version OR NEW.event_public_digest IS DISTINCT FROM OLD.event_public_digest THEN RAISE EXCEPTION 'Frozen event eligibility cannot change'; END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_event_public_snapshot_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Public eligibility history is immutable'; END IF;
 IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR
 (to_jsonb(NEW)-ARRAY['revoked_at','revoked_by','revocation_reason']) IS DISTINCT FROM
 (to_jsonb(OLD)-ARRAY['revoked_at','revoked_by','revocation_reason']) THEN
 RAISE EXCEPTION 'Only irreversible eligibility withdrawal is permitted'; END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_export_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'CG05 export audit is append only'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg05_guard_project_branch_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Project branch history is immutable'; END IF;
 PERFORM 1 FROM project WHERE root_realm_id=NEW.root_realm_id AND id=NEW.project_id FOR UPDATE;
 IF TG_OP='UPDATE' THEN
  IF OLD.valid_to IS NOT NULL OR NEW.valid_to IS NULL OR
   (to_jsonb(NEW)-'valid_to') IS DISTINCT FROM (to_jsonb(OLD)-'valid_to') THEN
   RAISE EXCEPTION 'Only closing an open project branch interval is permitted';
  END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM project_branch_history h WHERE h.root_realm_id=NEW.root_realm_id AND h.project_id=NEW.project_id AND h.id<>NEW.id
  AND tstzrange(h.valid_from,h.valid_to,'[)') && tstzrange(NEW.valid_from,NEW.valid_to,'[)')) THEN
  RAISE EXCEPTION 'Project branch history intervals overlap';
 END IF;
 RETURN NEW;
END $function$
;
