CREATE OR REPLACE FUNCTION public.cg05_task_event_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t project_task%ROWTYPE; previous_status text;
BEGIN
 SELECT * INTO t FROM project_task WHERE root_realm_id=NEW.root_realm_id
  AND project_id=NEW.project_id AND id=NEW.task_id FOR SHARE;
 IF NOT FOUND OR t.version<>NEW.result_version OR t.status<>NEW.new_status
 OR t.assignee_kind<>NEW.assignee_kind
 OR t.assignee_account_ref IS DISTINCT FROM NEW.assignee_account_ref
 OR t.assignee_employee_ref IS DISTINCT FROM NEW.assignee_employee_ref
 OR t.assignee_branch_ref IS DISTINCT FROM NEW.assignee_branch_ref THEN
  RAISE EXCEPTION 'Task event does not match current source revision';
 END IF;
 IF NEW.result_version=1 THEN
  IF NEW.event_kind<>'CREATE' OR NEW.old_status IS NOT NULL THEN RAISE EXCEPTION 'Invalid initial task event'; END IF;
 ELSE
  SELECT new_status INTO previous_status FROM project_task_event WHERE root_realm_id=NEW.root_realm_id
   AND task_id=NEW.task_id AND result_version=NEW.result_version-1;
  IF NOT FOUND OR NEW.event_kind='CREATE' OR NEW.old_status IS DISTINCT FROM previous_status THEN
   RAISE EXCEPTION 'Task event must follow the preceding revision';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_task_event_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE ev project_task_event%ROWTYPE;
BEGIN
 SELECT * INTO ev FROM project_task_event WHERE root_realm_id=NEW.root_realm_id
 AND project_id=NEW.project_id AND task_id=NEW.id AND result_version=NEW.version;
 IF NOT FOUND OR ev.new_status IS DISTINCT FROM NEW.status
 OR ev.assignee_kind IS DISTINCT FROM NEW.assignee_kind
 OR ev.assignee_account_ref IS DISTINCT FROM NEW.assignee_account_ref
 OR ev.assignee_employee_ref IS DISTINCT FROM NEW.assignee_employee_ref
 OR ev.assignee_branch_ref IS DISTINCT FROM NEW.assignee_branch_ref THEN
  RAISE EXCEPTION 'Task revision requires matching immutable event';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_task_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Task history must remain available'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.version<>1 OR NEW.status NOT IN('DRAFT','ASSIGNED') THEN RAISE EXCEPTION 'Invalid task initial state'; END IF;
 ELSE
  IF (NEW.id,NEW.root_realm_id,NEW.project_id,NEW.task_code,NEW.created_by,NEW.created_at)
   IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.project_id,OLD.task_code,OLD.created_by,OLD.created_at)
   OR NEW.version<>OLD.version+1 OR OLD.status IN('COMPLETED','CANCELLED') THEN
   RAISE EXCEPTION 'Task identity or current revision cannot be changed';
  END IF;
  IF NEW.status<>OLD.status AND NOT (
    NEW.status='ASSIGNED' AND OLD.status IN('DRAFT','IN_PROGRESS')
    OR OLD.status='ASSIGNED' AND NEW.status IN('IN_PROGRESS','CANCELLED')
    OR OLD.status='IN_PROGRESS' AND NEW.status IN('COMPLETED','CANCELLED')) THEN
   RAISE EXCEPTION 'Invalid task status transition';
  END IF;
 END IF;
 IF NEW.assignee_kind='EMPLOYEE' AND (
  TG_OP='INSERT' OR NEW.assignee_employee_ref IS DISTINCT FROM OLD.assignee_employee_ref
  OR NEW.assignee_account_ref IS DISTINCT FROM OLD.assignee_account_ref
  OR NEW.assignee_branch_ref IS DISTINCT FROM OLD.assignee_branch_ref) THEN
  IF NOT EXISTS(SELECT 1 FROM hr_employee e WHERE e.root_realm_id=NEW.root_realm_id
   AND e.id=NEW.assignee_employee_ref AND e.account_ref=NEW.assignee_account_ref FOR SHARE) THEN
   RAISE EXCEPTION 'Task employee must match original account';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_visit_capture_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v field_visit%ROWTYPE; first_capture visit_checkin_event%ROWTYPE;
BEGIN
 SELECT * INTO v FROM field_visit WHERE root_realm_id=NEW.root_realm_id AND id=NEW.visit_id FOR SHARE;
 IF NOT FOUND OR v.version<>NEW.result_version OR v.actor_account_ref<>NEW.actor_account_ref THEN
  RAISE EXCEPTION 'Visit capture must match current assigned revision';
 END IF;
 IF NEW.kind='CHECK_IN' THEN
  IF v.status<>'IN_PROGRESS' OR v.started_at IS DISTINCT FROM NEW.recorded_at THEN RAISE EXCEPTION 'Invalid check-in'; END IF;
 ELSE
  SELECT * INTO first_capture FROM visit_checkin_event WHERE root_realm_id=NEW.root_realm_id AND visit_id=NEW.visit_id AND kind='CHECK_IN';
  IF NOT FOUND OR v.status<>'PENDING_PROOF' OR v.completed_at IS DISTINCT FROM NEW.recorded_at
    OR NEW.recorded_at<first_capture.recorded_at OR NEW.actor_account_ref<>first_capture.actor_account_ref
    OR (NEW.device_recorded_at IS NOT NULL AND first_capture.device_recorded_at IS NOT NULL AND NEW.device_recorded_at<first_capture.device_recorded_at) THEN
   RAISE EXCEPTION 'Check out requires original check in and chronological timestamps';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_visit_event_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v field_visit%ROWTYPE; previous_status text;
BEGIN
 SELECT * INTO v FROM field_visit WHERE root_realm_id=NEW.root_realm_id AND id=NEW.visit_id FOR SHARE;
 IF NOT FOUND OR v.version<>NEW.result_version OR v.status<>NEW.resulting_status THEN
  RAISE EXCEPTION 'Visit event must match current revision';
 END IF;
 IF NEW.result_version=1 THEN
  IF NEW.event_kind<>'CREATE' OR NEW.prior_status IS NOT NULL THEN RAISE EXCEPTION 'Invalid initial visit event'; END IF;
 ELSE
  SELECT resulting_status INTO previous_status FROM field_visit_event
   WHERE root_realm_id=NEW.root_realm_id AND visit_id=NEW.visit_id AND result_version=NEW.result_version-1;
  IF NOT FOUND OR NEW.event_kind='CREATE' OR NEW.prior_status IS DISTINCT FROM previous_status THEN
   RAISE EXCEPTION 'Visit event must follow preceding revision';
  END IF;
 END IF;
 IF NEW.event_kind IN('CHECK_IN','CHECK_OUT') AND NEW.actor_account_ref<>v.actor_account_ref THEN
   RAISE EXCEPTION 'Only assigned actor may record visit capture';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_visit_event_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM field_visit_event e WHERE e.root_realm_id=NEW.root_realm_id AND e.visit_id=NEW.id AND e.result_version=NEW.version AND e.resulting_status=NEW.status) THEN
   RAISE EXCEPTION 'Visit revision requires matching immutable event';
 END IF;
 IF NEW.started_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM visit_checkin_event e WHERE e.root_realm_id=NEW.root_realm_id AND e.visit_id=NEW.id AND e.kind='CHECK_IN' AND e.recorded_at=NEW.started_at) THEN
   RAISE EXCEPTION 'Visit start requires accepted check-in event';
 END IF;
 IF NEW.completed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM visit_checkin_event e WHERE e.root_realm_id=NEW.root_realm_id AND e.visit_id=NEW.id AND e.kind='CHECK_OUT' AND e.recorded_at=NEW.completed_at) THEN
   RAISE EXCEPTION 'Visit completion requires accepted check-out event';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_visit_review_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.visit_review_ref,NEW.visit_review_id,NEW.visit_review_version,NEW.visit_review_digest) IS DISTINCT FROM
    (OLD.visit_review_ref,OLD.visit_review_id,OLD.visit_review_version,OLD.visit_review_digest) THEN
  RAISE EXCEPTION 'Frozen visit review cannot change'; END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_visit_review_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.event_kind='SUBMIT_REVIEW' THEN
  IF NEW.resulting_status<>'PENDING_APPROVAL' OR NOT EXISTS(
   SELECT 1 FROM field_visit_review_snapshot s JOIN cg03_case c ON c.realm_id=s.root_realm_id AND c.visit_review_ref=s.id
   WHERE s.root_realm_id=NEW.root_realm_id AND s.visit_id=NEW.visit_id AND s.visit_version=NEW.result_version
     AND s.request_key=NEW.event_key AND s.source_digest=NEW.payload_digest AND s.submitted_by=NEW.actor_account_ref
     AND c.case_kind='FIELD_VISIT_REVIEW') THEN RAISE EXCEPTION 'Visit submission requires original review case'; END IF;
 ELSIF NEW.event_kind='REVIEW_DECISION' THEN
  IF NOT EXISTS(SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
   JOIN cg03_process_step step ON step.process_id=c.process_id AND step.ordinal=d.step_ordinal
   JOIN field_visit v ON v.root_realm_id=c.realm_id AND v.id=c.visit_review_id
   WHERE c.realm_id=NEW.root_realm_id AND c.case_kind='FIELD_VISIT_REVIEW' AND c.visit_review_id=NEW.visit_id
    AND d.step_ordinal=c.current_step AND d.actor_id<>c.proposer_id AND d.actor_id<>v.actor_account_ref
    AND (NOT step.protected_root_required OR d.fresh_password_verified_at IS NOT NULL)
    AND NOT EXISTS(SELECT 1 FROM cg03_case_decision earlier WHERE earlier.realm_id=c.realm_id AND earlier.case_id=c.id AND earlier.step_ordinal<d.step_ordinal AND earlier.actor_id=d.actor_id)
    AND (d.step_ordinal=1 OR EXISTS(SELECT 1 FROM cg03_case_decision earlier WHERE earlier.realm_id=c.realm_id AND earlier.case_id=c.id AND earlier.step_ordinal=1 AND earlier.action IN('APPROVE','FORWARD')))
    AND c.visit_review_version=NEW.result_version-1 AND d.request_key=NEW.event_key AND d.actor_id=NEW.actor_account_ref
    AND d.request_digest=NEW.payload_digest
    AND ((d.action='APPROVE' AND step.protected_root_required AND step.capability_key='approvals.review' AND NEW.resulting_status='COMPLETED' AND c.status='OWNER_COMPLETED')
      OR(d.action='RETURN' AND NEW.resulting_status='RETURNED' AND c.status='RETURNED')
      OR(d.action='REJECT' AND NEW.resulting_status='REJECTED' AND c.status='REJECTED'))) THEN
    RAISE EXCEPTION 'Visit approval requires matching original CG03 decision'; END IF;
 ELSIF NEW.resulting_status IN('PENDING_APPROVAL','COMPLETED','RETURNED','REJECTED') AND NEW.prior_status IS DISTINCT FROM NEW.resulting_status THEN
  RAISE EXCEPTION 'Visit review transition requires original review event';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg05_visit_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; t record;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Visit history must remain available'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.version<>1 OR NEW.status NOT IN('DRAFT','PLANNED') THEN RAISE EXCEPTION 'Invalid initial visit state'; END IF;
 ELSE
  IF (NEW.id,NEW.root_realm_id,NEW.project_id,NEW.visit_code,NEW.created_by,NEW.created_at)
     IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.project_id,OLD.visit_code,OLD.created_by,OLD.created_at)
     OR NEW.version<>OLD.version+1 OR OLD.status IN('COMPLETED','REJECTED','CANCELLED') THEN
    RAISE EXCEPTION 'Invalid visit revision';
  END IF;
  IF OLD.started_at IS NOT NULL AND
     (NEW.started_at,NEW.actor_account_ref,NEW.actor_employee_ref,NEW.actor_branch_ref,NEW.task_id,NEW.branch_ref,NEW.state_ref,NEW.district_ref,NEW.visit_kind,NEW.location_label_private,NEW.planned_at,NEW.purpose)
     IS DISTINCT FROM
     (OLD.started_at,OLD.actor_account_ref,OLD.actor_employee_ref,OLD.actor_branch_ref,OLD.task_id,OLD.branch_ref,OLD.state_ref,OLD.district_ref,OLD.visit_kind,OLD.location_label_private,OLD.planned_at,OLD.purpose) THEN
    RAISE EXCEPTION 'Accepted check-in and visit assignment are immutable';
  END IF;
  IF OLD.status='PENDING_APPROVAL' AND NEW.report_text IS DISTINCT FROM OLD.report_text THEN
   RAISE EXCEPTION 'Submitted report is frozen until returned for correction';
  END IF;
  IF OLD.completed_at IS NOT NULL AND NEW.completed_at IS DISTINCT FROM OLD.completed_at THEN
    RAISE EXCEPTION 'Accepted checkout is immutable';
  END IF;
  IF NEW.status<>OLD.status AND NOT (
    (OLD.status='DRAFT' AND NEW.status IN('PLANNED','IN_PROGRESS','CANCELLED'))
    OR (OLD.status='PLANNED' AND NEW.status IN('IN_PROGRESS','CANCELLED'))
    OR (OLD.status='IN_PROGRESS' AND NEW.status IN('PENDING_PROOF','CANCELLED'))
    OR (OLD.status IN('PENDING_PROOF','RETURNED') AND NEW.status IN('PENDING_APPROVAL','CANCELLED'))
    OR (OLD.status='PENDING_APPROVAL' AND NEW.status IN('RETURNED','REJECTED','COMPLETED','PENDING_PROOF'))) THEN
    RAISE EXCEPTION 'Invalid visit transition';
  END IF;
 END IF;
 SELECT branch_ref,status,planned_start,planned_end INTO p FROM project WHERE root_realm_id=NEW.root_realm_id AND id=NEW.project_id FOR SHARE;
 IF NOT FOUND OR (NEW.status<>'CANCELLED' AND (p.branch_ref IS DISTINCT FROM NEW.branch_ref OR p.status IN('COMPLETED','CANCELLED'))) THEN
   RAISE EXCEPTION 'Visit requires current project scope';
 END IF;
 IF NEW.status<>'CANCELLED' AND ((p.planned_start IS NOT NULL AND (NEW.planned_at AT TIME ZONE 'Asia/Kolkata')::date<p.planned_start)
  OR (p.planned_end IS NOT NULL AND (NEW.planned_at AT TIME ZONE 'Asia/Kolkata')::date>p.planned_end)) THEN
   RAISE EXCEPTION 'Visit outside current project dates';
 END IF;
 IF NEW.actor_employee_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM hr_employee e WHERE e.root_realm_id=NEW.root_realm_id AND e.id=NEW.actor_employee_ref AND e.account_ref=NEW.actor_account_ref FOR SHARE) THEN
   RAISE EXCEPTION 'Visit employee must match original account';
 END IF;
 IF NEW.task_id IS NOT NULL AND NEW.status NOT IN('CANCELLED','COMPLETED','REJECTED','RETURNED','PENDING_APPROVAL') THEN
  SELECT assignee_account_ref,status INTO t FROM project_task WHERE root_realm_id=NEW.root_realm_id AND project_id=NEW.project_id AND id=NEW.task_id FOR SHARE;
  IF NOT FOUND OR t.assignee_account_ref IS DISTINCT FROM NEW.actor_account_ref OR (t.status NOT IN('ASSIGNED','IN_PROGRESS') AND NOT (NEW.completed_at IS NOT NULL AND t.status='COMPLETED')) THEN
   RAISE EXCEPTION 'Visit requires current original task assignment';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg06_aid_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a assistance_case%ROWTYPE; total numeric; source stock_operation_draft%ROWTYPE; v finance_voucher%ROWTYPE;
BEGIN
 SELECT * INTO a FROM assistance_case WHERE root_realm_id=NEW.root_realm_id AND id=NEW.assistance_id FOR UPDATE;
 IF NOT FOUND OR a.state<>'APPROVED' OR NOT EXISTS(SELECT 1 FROM cg03_case c WHERE c.realm_id=a.root_realm_id AND c.id=a.approval_case_ref AND c.case_kind='ASSISTANCE_REVIEW' AND c.assistance_review_ref=a.id AND c.assistance_source_digest=a.source_digest AND c.status='OWNER_COMPLETED') THEN RAISE EXCEPTION 'Original assistance release is not approved' USING ERRCODE='23514'; END IF;
 IF NEW.action IN('ISSUE','RETURN') THEN
  SELECT * INTO source FROM stock_operation_draft WHERE root_realm_id=NEW.root_realm_id AND id=NEW.stock_operation_ref;
  IF a.kind<>'MATERIAL' OR NOT FOUND OR source.status<>'DRAFT' OR source.request_key<>NEW.request_key OR (source.kind,source.item_id,source.location_id,source.unit_code,source.qty_scale,source.quantity,source.actor_ref) IS DISTINCT FROM (NEW.action,a.item_ref,a.location_ref,a.unit_code,a.qty_scale,NEW.quantity,NEW.actor_ref) THEN RAISE EXCEPTION 'Stock allocation differs from original aid' USING ERRCODE='23514'; END IF;
  IF NEW.action='ISSUE' THEN
   SELECT COALESCE(sum(quantity),0) INTO total FROM assistance_fulfillment WHERE root_realm_id=NEW.root_realm_id AND assistance_id=NEW.assistance_id AND action='ISSUE';
   IF total+NEW.quantity>a.requested_qty THEN RAISE EXCEPTION 'Aid quantity exceeds approval' USING ERRCODE='23514'; END IF;
  ELSE
   SELECT COALESCE(sum(quantity),0) INTO total FROM assistance_fulfillment WHERE root_realm_id=NEW.root_realm_id AND return_of_ref=NEW.return_of_ref AND action='RETURN';
   IF NOT EXISTS(SELECT 1 FROM assistance_fulfillment original JOIN assistance_delivery_event d ON d.root_realm_id=original.root_realm_id AND d.fulfillment_id=original.id AND d.action='DELIVERED' JOIN stock_movement m ON m.root_realm_id=d.root_realm_id AND m.stock_event_id=d.stock_event_ref WHERE original.root_realm_id=NEW.root_realm_id AND original.id=NEW.return_of_ref AND original.assistance_id=NEW.assistance_id AND original.action='ISSUE' AND m.id=source.original_movement_id AND original.quantity>=total+NEW.quantity) THEN RAISE EXCEPTION 'Return exceeds original delivered stock' USING ERRCODE='23514'; END IF;
  END IF;
 ELSE
  SELECT * INTO v FROM finance_voucher WHERE root_realm_id=NEW.root_realm_id AND id=NEW.voucher_ref;
  IF a.kind<>'FINANCIAL' OR NOT FOUND OR v.voucher_type<>'PAYMENT' OR v.status<>'DRAFT' OR v.version<>NEW.voucher_revision OR v.total_minor<>NEW.amount_minor OR v.branch_id IS DISTINCT FROM a.branch_ref OR v.created_by<>NEW.actor_ref THEN RAISE EXCEPTION 'Payment allocation differs from original aid' USING ERRCODE='23514'; END IF;
  SELECT COALESCE(sum(f.amount_minor),0) INTO total FROM assistance_fulfillment f JOIN finance_voucher prior ON prior.root_realm_id=f.root_realm_id AND prior.id=f.voucher_ref WHERE f.root_realm_id=NEW.root_realm_id AND f.assistance_id=NEW.assistance_id AND f.action='PAYMENT' AND prior.status NOT IN('RETURNED','REJECTED');
  IF total+NEW.amount_minor>a.requested_minor THEN RAISE EXCEPTION 'Aid amount exceeds approval' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_aid_delivery_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a assistance_case%ROWTYPE; f assistance_fulfillment%ROWTYPE;
BEGIN
 SELECT * INTO a FROM assistance_case WHERE root_realm_id=NEW.root_realm_id AND id=NEW.assistance_id FOR SHARE;
 SELECT * INTO f FROM assistance_fulfillment WHERE root_realm_id=NEW.root_realm_id AND id=NEW.fulfillment_id AND assistance_id=a.id FOR SHARE;
 IF NOT FOUND OR a.state<>'APPROVED' OR a.beneficiary_id<>NEW.beneficiary_id THEN RAISE EXCEPTION 'Original aid allocation required' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM beneficiary b JOIN cg19_stored_file p ON p.realm_id=b.root_realm_id AND p.beneficiary_id=b.id JOIN cg19_upload_intent u ON u.realm_id=p.realm_id AND u.id=p.upload_intent_id
 WHERE b.root_realm_id=NEW.root_realm_id AND b.id=a.beneficiary_id AND b.consent_revoked_at IS NULL AND b.lifecycle_state='ACTIVE' AND b.verification_state='VERIFIED' AND b.branch_scope_id IS NOT DISTINCT FROM a.branch_ref
 AND p.id=NEW.proof_ref AND p.revision=NEW.proof_revision AND p.proposal_revision=NEW.proof_source_revision AND p.proposal_revision=b.profile_revision AND p.revoked_at IS NULL AND p.scan_status='CLEAN_VERIFIED' AND u.status='VALIDATED' AND p.created_at>=f.created_at) THEN RAISE EXCEPTION 'Current clean handover proof required' USING ERRCODE='23514'; END IF;
 IF NEW.action IN('DELIVERED','RETURNED') THEN
  IF f.action<>(CASE WHEN NEW.action='DELIVERED' THEN 'ISSUE' ELSE 'RETURN' END) OR NOT EXISTS(SELECT 1 FROM stock_operation_draft o JOIN stock_event e ON e.root_realm_id=o.root_realm_id AND e.operation_id=o.id JOIN stock_movement m ON m.root_realm_id=e.root_realm_id AND m.stock_event_id=e.id WHERE o.root_realm_id=NEW.root_realm_id AND o.id=f.stock_operation_ref AND o.status='CONFIRMED' AND e.id=NEW.stock_event_ref AND e.event_kind=f.action AND m.event_kind=f.action AND m.item_id=a.item_ref AND m.location_id=a.location_ref AND m.signed_qty=CASE WHEN f.action='ISSUE' THEN -f.quantity ELSE f.quantity END) THEN RAISE EXCEPTION 'Exact stock movement required' USING ERRCODE='23514'; END IF;
 ELSIF NEW.action='PAID' THEN
  IF f.action<>'PAYMENT' OR NOT EXISTS(SELECT 1 FROM finance_voucher v JOIN finance_voucher_posting p ON p.root_realm_id=v.root_realm_id AND p.voucher_id=v.id AND p.voucher_revision=v.version JOIN journal j ON j.root_realm_id=p.root_realm_id AND j.id=p.journal_id JOIN finance_voucher_payment_verification pay ON pay.root_realm_id=v.root_realm_id AND pay.voucher_id=v.id AND pay.voucher_revision=v.version WHERE v.root_realm_id=NEW.root_realm_id AND v.id=f.voucher_ref AND v.version=f.voucher_revision AND v.status='POSTED' AND v.total_minor=f.amount_minor AND j.id=NEW.journal_ref AND j.status='POSTED' AND j.posting_kind='VOUCHER' AND pay.status='VERIFIED' AND pay.amount_minor=f.amount_minor) THEN RAISE EXCEPTION 'Exact posted verified payment required' USING ERRCODE='23514'; END IF;
 ELSIF NEW.action='REVERSED' THEN
  IF f.action<>'PAYMENT' OR cg06_recovery_journal(NEW.root_realm_id,f.id) IS DISTINCT FROM NEW.journal_ref OR NOT EXISTS(SELECT 1 FROM assistance_delivery_event d JOIN assistance_recovery r ON r.root_realm_id=d.root_realm_id AND r.fulfillment_id=d.fulfillment_id JOIN finance_voucher_posting rp ON rp.root_realm_id=r.root_realm_id AND rp.voucher_id=r.voucher_ref AND rp.journal_id=NEW.journal_ref JOIN cg19_stored_file p ON p.realm_id=NEW.root_realm_id AND p.id=NEW.proof_ref WHERE d.root_realm_id=NEW.root_realm_id AND d.fulfillment_id=f.id AND d.action='PAID' AND p.created_at>=r.created_at) THEN RAISE EXCEPTION 'Exact verified CG09 recovery required' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'Unsupported delivery event' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_aid_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['state','revision','approval_case_ref','updated_at'])=(to_jsonb(OLD)-ARRAY['state','revision','approval_case_ref','updated_at'])
 AND NEW.revision=OLD.revision+1 AND ((OLD.state='DRAFT' AND NEW.state='SUBMITTED') OR (OLD.state='SUBMITTED' AND NEW.state IN('APPROVED','RETURNED','REJECTED') AND NEW.approval_case_ref=OLD.approval_case_ref)) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Original assistance request is immutable';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_aid_voucher_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM assistance_fulfillment WHERE root_realm_id=OLD.root_realm_id AND voucher_ref=OLD.id)
 AND (TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['status','approval_case_id','proof_file_id','proof_file_revision','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','approval_case_id','proof_file_id','proof_file_revision','updated_at'])) THEN
 RAISE EXCEPTION 'Original assistance payment source cannot be repurposed';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_assistance_approval_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.assistance_review_ref,NEW.assistance_source_digest) IS DISTINCT FROM (OLD.assistance_review_ref,OLD.assistance_source_digest) THEN RAISE EXCEPTION 'Assistance approval source cannot change'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_guard_beneficiary_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.beneficiary_review_ref,NEW.beneficiary_id,NEW.beneficiary_source_revision,NEW.beneficiary_source_digest)
  IS DISTINCT FROM (OLD.beneficiary_review_ref,OLD.beneficiary_id,OLD.beneficiary_source_revision,OLD.beneficiary_source_digest) THEN
  RAISE EXCEPTION 'Frozen beneficiary verification source cannot change';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_immutable_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Beneficiary history is immutable'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg06_recovery_journal(root uuid, fulfillment uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
 SELECT j.id FROM assistance_recovery r
 JOIN assistance_fulfillment f ON f.root_realm_id=r.root_realm_id AND f.id=r.fulfillment_id
 JOIN finance_voucher v ON v.root_realm_id=r.root_realm_id AND v.id=r.voucher_ref AND v.version=r.voucher_revision
 JOIN finance_voucher original ON original.root_realm_id=f.root_realm_id AND original.id=f.voucher_ref
 JOIN finance_voucher_posting p ON p.root_realm_id=v.root_realm_id AND p.voucher_id=v.id AND p.voucher_revision=v.version
 JOIN journal j ON j.root_realm_id=p.root_realm_id AND j.id=p.journal_id
 JOIN finance_account account ON account.root_realm_id=v.root_realm_id AND account.id=v.debit_account_id
 JOIN cg19_stored_file proof ON proof.realm_id=v.root_realm_id AND proof.id=v.proof_file_id AND proof.revision=v.proof_file_revision
 JOIN cg19_upload_intent intent ON intent.realm_id=proof.realm_id AND intent.id=proof.upload_intent_id
 WHERE r.root_realm_id=root AND r.fulfillment_id=fulfillment AND v.status='POSTED' AND j.status='POSTED' AND j.posting_kind='VOUCHER'
 AND v.total_minor=f.amount_minor AND v.debit_account_id=original.credit_account_id AND v.credit_account_id=original.debit_account_id
 AND proof.revoked_at IS NULL AND proof.scan_status='CLEAN_VERIFIED' AND intent.status='VALIDATED'
 AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2
 AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id AND l.account_id=v.debit_account_id AND l.debit_minor=f.amount_minor AND l.credit_minor=0 AND l.branch_id IS NOT DISTINCT FROM v.branch_id)
 AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id AND l.account_id=v.credit_account_id AND l.credit_minor=f.amount_minor AND l.debit_minor=0 AND l.branch_id IS NOT DISTINCT FROM v.branch_id)
 AND (account.account_kind='CASH' OR account.account_kind='BANK' AND EXISTS(
 SELECT 1 FROM finance_bank_reconciliation bank JOIN finance_reconciliation_decision d ON d.root_realm_id=bank.root_realm_id AND d.reconciliation_id=bank.id AND d.action='VERIFY'
 JOIN cg19_stored_file bf ON bf.realm_id=d.root_realm_id AND bf.id=d.statement_file_id AND bf.revision=d.statement_file_version AND bf.reconciliation_id=bank.id
 JOIN cg19_upload_intent bu ON bu.realm_id=bf.realm_id AND bu.id=bf.upload_intent_id AND bu.reconciliation_id=bank.id
 WHERE bank.root_realm_id=j.root_realm_id AND bank.journal_id=j.id AND bank.bank_account_id=v.debit_account_id AND bank.status='VERIFIED' AND bank.variance_minor=0 AND bank.posted_amount_minor=f.amount_minor AND bank.statement_amount_minor=f.amount_minor
 AND bf.owner_kind='CG09_BANK_STATEMENT' AND bu.owner_kind='CG09_BANK_STATEMENT' AND bf.revoked_at IS NULL AND bf.scan_status='CLEAN_VERIFIED' AND bu.status='VALIDATED'))
 LIMIT 1
$function$
;
CREATE OR REPLACE FUNCTION public.cg06_recovery_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM assistance_case WHERE root_realm_id=NEW.root_realm_id AND id=NEW.assistance_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM assistance_recovery r JOIN finance_voucher v ON v.root_realm_id=r.root_realm_id AND v.id=r.voucher_ref WHERE r.root_realm_id=NEW.root_realm_id AND r.fulfillment_id=NEW.fulfillment_id AND v.status NOT IN('RETURNED','REJECTED')) THEN RAISE EXCEPTION 'Original recovery already exists' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM assistance_fulfillment f JOIN assistance_delivery_event d ON d.root_realm_id=f.root_realm_id AND d.fulfillment_id=f.id AND d.action='PAID'
 JOIN finance_voucher vo ON vo.root_realm_id=f.root_realm_id AND vo.id=f.voucher_ref
 JOIN finance_voucher v ON v.root_realm_id=f.root_realm_id AND v.id=NEW.voucher_ref
 WHERE f.root_realm_id=NEW.root_realm_id AND f.id=NEW.fulfillment_id AND f.assistance_id=NEW.assistance_id AND f.action='PAYMENT'
 AND v.id<>vo.id AND v.voucher_type='GENERAL' AND v.status='DRAFT' AND v.version=NEW.voucher_revision AND v.created_by=NEW.actor_ref
 AND v.total_minor=f.amount_minor AND v.branch_id IS NOT DISTINCT FROM vo.branch_id AND v.debit_account_id=vo.credit_account_id AND v.credit_account_id=vo.debit_account_id
 AND EXISTS(SELECT 1 FROM finance_voucher_draft_revision r WHERE r.root_realm_id=v.root_realm_id AND r.voucher_id=v.id AND r.version=v.version AND r.request_key=NEW.request_key AND r.actor_ref=NEW.actor_ref))
 THEN RAISE EXCEPTION 'Exact original paid allocation and opposite finance accounts required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_bank_collection_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original bank donation collection cannot be deleted'; END IF;
 IF TG_OP='INSERT' AND NEW.source_status<>'PENDING' THEN
  RAISE EXCEPTION 'Bank donation starts pending review';
 END IF;
 IF TG_OP='UPDATE' AND
  (OLD.source_status<>'PENDING' OR NEW.source_status NOT IN('VERIFIED_POSTED','REJECTED_REVERSED')
   OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
   OR NEW.id IS DISTINCT FROM OLD.id
   OR NEW.donation_id IS DISTINCT FROM OLD.donation_id
   OR NEW.attempt_id IS DISTINCT FROM OLD.attempt_id
   OR NEW.reconciliation_id IS DISTINCT FROM OLD.reconciliation_id
   OR NEW.initial_journal_id IS DISTINCT FROM OLD.initial_journal_id
   OR NEW.method IS DISTINCT FROM OLD.method
   OR NEW.bank_account_ref IS DISTINCT FROM OLD.bank_account_ref
   OR NEW.suspense_account_ref IS DISTINCT FROM OLD.suspense_account_ref
   OR NEW.income_account_ref IS DISTINCT FROM OLD.income_account_ref
   OR NEW.financial_year_ref IS DISTINCT FROM OLD.financial_year_ref
   OR NEW.posting_date IS DISTINCT FROM OLD.posting_date
   OR NEW.bank_item_ref IS DISTINCT FROM OLD.bank_item_ref
   OR NEW.amount_minor IS DISTINCT FROM OLD.amount_minor
   OR NEW.request_key IS DISTINCT FROM OLD.request_key
   OR NEW.source_digest IS DISTINCT FROM OLD.source_digest
   OR NEW.recorded_by IS DISTINCT FROM OLD.recorded_by
   OR NEW.created_at IS DISTINCT FROM OLD.created_at)
 THEN RAISE EXCEPTION 'Bank donation source identity is immutable'; END IF;
 RETURN NEW;
END;$function$
;
CREATE OR REPLACE FUNCTION public.cg07_bank_collection_proof_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM donation d
  JOIN donation_payment_attempt a ON a.root_realm_id=d.root_realm_id AND a.donation_id=d.id
  JOIN finance_bank_reconciliation r ON r.id=NEW.reconciliation_id AND r.root_realm_id=d.root_realm_id
  JOIN journal provisional ON provisional.root_realm_id=r.root_realm_id AND provisional.id=r.journal_id
  WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.donation_id
   AND a.id=NEW.attempt_id AND a.method=NEW.method
   AND r.bank_account_id=NEW.bank_account_ref
   AND r.journal_id=NEW.initial_journal_id AND r.recorded_by=NEW.recorded_by
   AND r.bank_item_ref=NEW.bank_item_ref AND r.variance_minor=0
   AND r.statement_amount_minor=NEW.amount_minor AND r.posted_amount_minor=NEW.amount_minor
   AND provisional.status='POSTED' AND provisional.source_ref=d.id
   AND provisional.immutable_payload_digest=NEW.source_digest
   AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=provisional.root_realm_id
     AND l.journal_id=provisional.id)=2
   AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=provisional.root_realm_id
    AND l.journal_id=provisional.id AND l.account_id=NEW.bank_account_ref
    AND l.debit_minor=NEW.amount_minor AND l.credit_minor=0)
   AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=provisional.root_realm_id
    AND l.journal_id=provisional.id AND l.account_id=NEW.suspense_account_ref
    AND l.credit_minor=NEW.amount_minor AND l.debit_minor=0)
 ) THEN RAISE EXCEPTION 'Original provisional bank journal/reconciliation proof missing'; END IF;
 IF NEW.source_status='PENDING' THEN RETURN NULL; END IF;
 IF NOT EXISTS(
  SELECT 1 FROM finance_bank_reconciliation r
  JOIN finance_reconciliation_decision decision
   ON decision.root_realm_id=r.root_realm_id AND decision.reconciliation_id=r.id
  WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.reconciliation_id
   AND decision.actor_ref=NEW.verified_by AND r.verified_by=NEW.verified_by
   AND r.recorded_by=NEW.recorded_by
   AND ((NEW.source_status='VERIFIED_POSTED' AND r.status='VERIFIED'
     AND decision.action='VERIFY' AND decision.statement_file_id IS NOT NULL
     AND decision.statement_file_version IS NOT NULL)
    OR (NEW.source_status='REJECTED_REVERSED' AND r.status='REJECTED'
     AND decision.action='REJECT'))
 ) THEN RAISE EXCEPTION 'Real independent CG09 bank decision and CG19 proof required'; END IF;
 IF NEW.source_status='VERIFIED_POSTED' THEN
  IF NOT EXISTS(SELECT 1 FROM donation d
   JOIN donation_finance_effect e ON e.root_realm_id=d.root_realm_id AND e.donation_id=d.id
   JOIN journal j ON j.root_realm_id=e.root_realm_id AND j.id=e.journal_id
   WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.donation_id
    AND d.source_status='RECEIVED_POSTED' AND e.status='POSTED'
    AND j.id=NEW.final_journal_id AND j.status='POSTED' AND j.source_ref=d.id
    AND j.immutable_source_event_key=e.source_event_key
    AND j.immutable_payload_digest=e.immutable_digest
    AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2
    AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id
     AND l.account_id=NEW.suspense_account_ref AND l.debit_minor=NEW.amount_minor AND l.credit_minor=0)
    AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id
     AND l.account_id=NEW.income_account_ref AND l.credit_minor=NEW.amount_minor AND l.debit_minor=0))
  THEN RAISE EXCEPTION 'Bank donation requires real income reclassification'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM journal j WHERE j.root_realm_id=NEW.root_realm_id
   AND j.id=NEW.reversal_journal_id AND j.status='POSTED' AND j.source_ref=NEW.id
   AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2
   AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id
    AND l.account_id=NEW.suspense_account_ref AND l.debit_minor=NEW.amount_minor AND l.credit_minor=0)
   AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id
    AND l.account_id=NEW.bank_account_ref AND l.credit_minor=NEW.amount_minor AND l.debit_minor=0))
  THEN RAISE EXCEPTION 'Rejected bank collection requires real CG09 offset'; END IF;
 END IF;
 RETURN NULL;
END;$function$
;
CREATE OR REPLACE FUNCTION public.cg07_campaign_event_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Original campaign event cannot be changed';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_campaign_media_proof_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE cover text; banner text; supporting jsonb; document_ref text; proof_count integer;
BEGIN
 IF NEW.source_status NOT IN('SUBMITTED','APPROVED') THEN RETURN NULL; END IF;
 SELECT step5_media_refs->>'coverRef',step5_media_refs->>'fileRef',
    COALESCE(step5_media_refs->'supportingFileRefs','[]'::jsonb)
 INTO cover,banner,supporting FROM campaign_revision
 WHERE root_realm_id=NEW.root_realm_id
  AND campaign_id=NEW.id AND revision_no=NEW.current_revision;
 IF supporting IS NULL OR jsonb_typeof(supporting)<>'array'
  OR jsonb_array_length(supporting)>6
 THEN RAISE EXCEPTION 'Campaign supporting document proof shape is invalid'; END IF;
 IF cover IS NOT NULL AND cover<>'' THEN
  SELECT count(*) INTO proof_count FROM cg19_stored_file f
  JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  WHERE f.realm_id=NEW.root_realm_id AND f.campaign_id=NEW.id
    AND f.id=cover::uuid AND f.proposal_revision<=NEW.current_revision
    AND f.owner_kind='CG07_CAMPAIGN'
    AND f.original_mime IN('image/jpeg','image/png')
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND i.owner_kind='CG07_CAMPAIGN' AND i.campaign_media_rights_confirmed
    AND i.status='VALIDATED' AND i.classification='CAMPAIGN_COVER'
    AND i.campaign_id=NEW.id;
  IF proof_count<>1 THEN RAISE EXCEPTION 'Original campaign cover proof is no longer verified'; END IF;
 END IF;
 IF banner IS NOT NULL AND banner<>'' THEN
  SELECT count(*) INTO proof_count FROM cg19_stored_file f
  JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  WHERE f.realm_id=NEW.root_realm_id AND f.campaign_id=NEW.id
    AND f.id=banner::uuid AND f.proposal_revision<=NEW.current_revision
    AND f.owner_kind='CG07_CAMPAIGN'
    AND f.original_mime IN('image/jpeg','image/png','image/webp')
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND i.owner_kind='CG07_CAMPAIGN' AND i.campaign_media_rights_confirmed
    AND i.status='VALIDATED' AND i.classification='CAMPAIGN_BANNER'
    AND i.campaign_id=NEW.id;
  IF proof_count<>1 THEN RAISE EXCEPTION 'Original campaign banner proof is no longer verified'; END IF;
 END IF;
 FOR document_ref IN SELECT jsonb_array_elements_text(supporting) LOOP
  SELECT count(*) INTO proof_count FROM cg19_stored_file f
  JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  WHERE f.realm_id=NEW.root_realm_id AND f.campaign_id=NEW.id
    AND f.id=document_ref::uuid AND f.proposal_revision<=NEW.current_revision
    AND f.owner_kind='CG07_CAMPAIGN'
    AND f.original_mime IN('image/jpeg','image/png','image/webp','application/pdf')
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND i.owner_kind='CG07_CAMPAIGN' AND i.campaign_media_rights_confirmed
    AND i.status='VALIDATED' AND i.classification='CAMPAIGN_DOCUMENT'
    AND i.campaign_id=NEW.id;
  IF proof_count<>1 THEN RAISE EXCEPTION 'Original campaign supporting document proof is no longer verified'; END IF;
 END LOOP;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg07_campaign_revision_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Original campaign revisions are immutable';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_campaign_status_proof_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE expected_action text; current_digest char(64);
BEGIN
 SELECT immutable_digest INTO current_digest FROM campaign_revision
 WHERE root_realm_id=NEW.root_realm_id AND campaign_id=NEW.id AND revision_no=NEW.current_revision;
 IF current_digest IS NULL THEN
  RAISE EXCEPTION 'Campaign current original revision is unavailable';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.source_status<>'DRAFT' OR NEW.version<>1 OR NEW.current_revision<>1 OR
   NOT EXISTS(SELECT 1 FROM campaign_status_event e
    WHERE e.root_realm_id=NEW.root_realm_id AND e.campaign_id=NEW.id
     AND e.operation='CREATE_DRAFT' AND e.source_revision=NEW.current_revision
     AND e.digest=current_digest AND e.resulting_version=NEW.version
     AND e.resulting_status='DRAFT' AND e.prior_status IS NULL
     AND e.actor_ref=NEW.created_by)
  THEN RAISE EXCEPTION 'Campaign creation must be an original draft revision'; END IF;
  RETURN NULL;
 END IF;
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
  NEW.id IS DISTINCT FROM OLD.id OR NEW.code_norm IS DISTINCT FROM OLD.code_norm OR
  NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at OR
  NEW.version<>OLD.version+1 THEN
  RAISE EXCEPTION 'Campaign source identity/version is immutable';
 END IF;
 IF (OLD.source_status='DRAFT' AND NEW.source_status='DRAFT') OR
    (OLD.source_status='RETURNED' AND NEW.source_status='DRAFT') THEN
  expected_action:='SAVE_DRAFT';
  IF NEW.current_revision<>OLD.current_revision+1 THEN
   RAISE EXCEPTION 'Campaign draft edit must create a new immutable revision'; END IF;
 ELSIF OLD.source_status='DRAFT' AND NEW.source_status='SUBMITTED' THEN
  expected_action:='SUBMIT';
  IF NEW.current_revision<>OLD.current_revision OR
   NOT EXISTS(SELECT 1 FROM cg03_case c JOIN campaign_review_snapshot s
     ON s.root_realm_id=c.realm_id AND s.id=c.campaign_review_ref
    WHERE c.realm_id=NEW.root_realm_id AND c.campaign_id=NEW.id
     AND c.case_kind='CAMPAIGN_LAUNCH' AND c.status='SUBMITTED'
     AND c.campaign_source_revision=NEW.current_revision AND c.campaign_source_digest=current_digest
     AND c.campaign_source_revision=s.source_revision AND c.campaign_source_digest=s.source_digest)
  THEN RAISE EXCEPTION 'Campaign submission requires original CG03 source case'; END IF;
 ELSIF OLD.source_status='SUBMITTED' AND NEW.source_status IN('APPROVED','RETURNED','REJECTED') THEN
  expected_action:='REVIEW_'||(CASE NEW.source_status WHEN 'APPROVED' THEN 'APPROVE'
   WHEN 'RETURNED' THEN 'RETURN' ELSE 'REJECT' END);
  IF NEW.current_revision<>OLD.current_revision OR
   NOT EXISTS(SELECT 1 FROM cg03_case c JOIN cg03_case_decision d
      ON d.realm_id=c.realm_id AND d.case_id=c.id
    WHERE c.realm_id=NEW.root_realm_id AND c.campaign_id=NEW.id
     AND c.case_kind='CAMPAIGN_LAUNCH'
     AND c.campaign_source_revision=NEW.current_revision AND c.campaign_source_digest=current_digest
     AND d.action=CASE NEW.source_status WHEN 'APPROVED' THEN 'APPROVE'
       WHEN 'RETURNED' THEN 'RETURN' ELSE 'REJECT' END
     AND d.fresh_password_verified_at IS NOT NULL
     AND c.status=CASE NEW.source_status WHEN 'APPROVED' THEN 'OWNER_COMPLETED'
       ELSE NEW.source_status END)
  THEN RAISE EXCEPTION 'Campaign status requires verified CG03 decision'; END IF;
  IF (NEW.title,NEW.category,NEW.branch_ref,NEW.project_source_ref,NEW.event_source_ref,
      NEW.volunteer_source_ref,NEW.goal_minor,NEW.currency,NEW.start_at,NEW.end_at) IS DISTINCT FROM
     (OLD.title,OLD.category,OLD.branch_ref,OLD.project_source_ref,OLD.event_source_ref,
      OLD.volunteer_source_ref,OLD.goal_minor,OLD.currency,OLD.start_at,OLD.end_at)
  THEN RAISE EXCEPTION 'Protected campaign decision cannot rewrite approved source'; END IF;
 ELSIF (OLD.source_status='DRAFT' AND NEW.source_status='WITHDRAWN')
   OR (OLD.source_status='RETURNED' AND NEW.source_status='WITHDRAWN')
   OR (OLD.source_status='APPROVED' AND NEW.source_status IN('PAUSED','CLOSED','WITHDRAWN'))
   OR (OLD.source_status='PAUSED' AND NEW.source_status IN('APPROVED','CLOSED','WITHDRAWN'))
 THEN
  IF NEW.current_revision<>OLD.current_revision OR
   (NEW.title,NEW.category,NEW.branch_ref,NEW.project_source_ref,NEW.event_source_ref,
    NEW.volunteer_source_ref,NEW.goal_minor,NEW.currency,NEW.start_at,NEW.end_at)
   IS DISTINCT FROM
   (OLD.title,OLD.category,OLD.branch_ref,OLD.project_source_ref,OLD.event_source_ref,
    OLD.volunteer_source_ref,OLD.goal_minor,OLD.currency,OLD.start_at,OLD.end_at)
  THEN RAISE EXCEPTION 'Campaign lifecycle cannot rewrite original frozen source'; END IF;
  expected_action:=CASE
   WHEN OLD.source_status IN('DRAFT','RETURNED') THEN 'CANCEL_DRAFT'
   WHEN NEW.source_status='PAUSED' THEN 'PAUSE'
   WHEN NEW.source_status='APPROVED' THEN 'RESUME'
   WHEN NEW.source_status='CLOSED' THEN 'CLOSE'
   ELSE 'WITHDRAW' END;
  IF expected_action='RESUME' AND
   (NEW.end_at IS NULL OR NEW.end_at<(now() AT TIME ZONE 'Asia/Kolkata')::date OR
    NOT EXISTS(SELECT 1 FROM cg03_case c JOIN cg03_case_decision d
      ON d.realm_id=c.realm_id AND d.case_id=c.id
     WHERE c.realm_id=NEW.root_realm_id AND c.campaign_id=NEW.id
       AND c.case_kind='CAMPAIGN_LAUNCH' AND c.status='OWNER_COMPLETED'
       AND c.campaign_source_revision=NEW.current_revision
       AND c.campaign_source_digest=current_digest
       AND d.action='APPROVE' AND d.actor_id<>c.proposer_id
       AND d.fresh_password_verified_at IS NOT NULL))
  THEN RAISE EXCEPTION 'Resuming requires original current independent approval and valid campaign period'; END IF;
 ELSE
  RAISE EXCEPTION 'Campaign lifecycle change has no original owner route';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM campaign_status_event e
   WHERE e.root_realm_id=NEW.root_realm_id AND e.campaign_id=NEW.id
    AND e.operation=expected_action AND e.source_revision=NEW.current_revision
    AND e.digest=current_digest AND e.resulting_version=NEW.version
    AND e.prior_status IS NOT DISTINCT FROM OLD.source_status
    AND e.resulting_status=NEW.source_status)
 THEN RAISE EXCEPTION 'Campaign state must have one matching immutable owner event'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_donation_branch_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original_campaign_branch uuid;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.branch_ref IS DISTINCT FROM OLD.branch_ref OR
     NEW.donation_kind IS DISTINCT FROM OLD.donation_kind OR
     NEW.campaign_id IS DISTINCT FROM OLD.campaign_id OR
     NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id THEN
   RAISE EXCEPTION 'Original donation source and branch are immutable';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.donation_kind='GENERAL' THEN
  IF NEW.campaign_id IS NOT NULL OR NEW.branch_ref IS NOT NULL THEN
   RAISE EXCEPTION 'Foundation-wide donation cannot be assigned to a branch';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.donation_kind<>'CAMPAIGN' OR NEW.campaign_id IS NULL THEN
  RAISE EXCEPTION 'Campaign donation requires a real campaign source';
 END IF;
 SELECT c.branch_ref INTO original_campaign_branch
 FROM campaign c
 WHERE c.root_realm_id=NEW.root_realm_id AND c.id=NEW.campaign_id
 FOR SHARE;
 IF NOT FOUND OR NEW.branch_ref IS DISTINCT FROM original_campaign_branch THEN
  RAISE EXCEPTION 'Campaign donation must inherit the original current campaign branch';
 END IF;
 RETURN NEW;
END;$function$
;
CREATE OR REPLACE FUNCTION public.cg07_donation_finance_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.source_status<>'REQUESTED' OR NEW.version<>1 THEN
   RAISE EXCEPTION 'New donation must be an unverified original request';
  END IF;
  RETURN NULL;
 END IF;
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR NEW.id IS DISTINCT FROM OLD.id OR
  NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR NEW.currency IS DISTINCT FROM OLD.currency OR
  NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
  NEW.campaign_id IS DISTINCT FROM OLD.campaign_id OR
  NEW.donor_private_ciphertext IS DISTINCT FROM OLD.donor_private_ciphertext OR
  NEW.status_token_digest IS DISTINCT FROM OLD.status_token_digest THEN
  RAISE EXCEPTION 'Donation source identity or original consent cannot change';
 END IF;
 IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Donation version must advance once'; END IF;
 IF NEW.source_status='RECEIVED_POSTED' AND
  NOT EXISTS(SELECT 1 FROM donation_finance_effect e JOIN journal j
   ON j.id=e.journal_id AND j.root_realm_id=e.root_realm_id
   WHERE e.root_realm_id=NEW.root_realm_id AND e.donation_id=NEW.id
     AND e.status='POSTED' AND j.status='POSTED'
     AND j.source_ref=NEW.id AND j.posting_kind='GENERAL'
     AND j.immutable_source_event_key=e.source_event_key
     AND j.immutable_payload_digest=e.immutable_digest
     AND (SELECT count(*) FROM journal_line l
          WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2
     AND (SELECT coalesce(sum(l.debit_minor),0) FROM journal_line l
          WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=NEW.amount_minor
     AND (SELECT coalesce(sum(l.credit_minor),0) FROM journal_line l
          WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=NEW.amount_minor
     AND NOT EXISTS(SELECT 1 FROM journal_line l
          WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id
           AND l.branch_id IS DISTINCT FROM NEW.branch_ref))
 THEN RAISE EXCEPTION 'Original verified CG09 journal required for received donation'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_guard_payment_event_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM donation_payment_attempt a
  JOIN donation d ON d.root_realm_id=a.root_realm_id AND d.id=a.donation_id
  WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.attempt_id
   AND a.donation_id=NEW.donation_id AND a.method='ONLINE'
   AND a.provider=NEW.provider AND a.merchant_reference=NEW.merchant_reference
   AND a.external_reference IS NOT NULL
   AND d.amount_minor=NEW.amount_minor AND d.currency=NEW.currency)
 THEN RAISE EXCEPTION 'Verified payment source/merchant/amount is not exact'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_manual_evidence_lifecycle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF OLD.status='POSTED' THEN RAISE EXCEPTION 'Posted donation proof is immutable'; END IF;
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
    NEW.id IS DISTINCT FROM OLD.id OR NEW.donation_id IS DISTINCT FROM OLD.donation_id OR
    NEW.attempt_id IS DISTINCT FROM OLD.attempt_id OR
    NEW.request_key IS DISTINCT FROM OLD.request_key OR
    NEW.source_digest IS DISTINCT FROM OLD.source_digest OR
    NEW.voucher_reference IS DISTINCT FROM OLD.voucher_reference OR
    NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR
    NEW.recorded_by IS DISTINCT FROM OLD.recorded_by OR
    NEW.cash_account_ref IS DISTINCT FROM OLD.cash_account_ref OR
    NEW.income_account_ref IS DISTINCT FROM OLD.income_account_ref OR
    NEW.financial_year_ref IS DISTINCT FROM OLD.financial_year_ref OR
    NEW.posting_date IS DISTINCT FROM OLD.posting_date OR
    NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN
  RAISE EXCEPTION 'Original cash proof cannot be rewritten'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_one_active_payment_path()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM donation d WHERE d.root_realm_id=NEW.root_realm_id
  AND d.id=NEW.donation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original donation unavailable'; END IF;
 IF NEW.status NOT IN('FAILED','EXPIRED') AND EXISTS(
  SELECT 1 FROM donation_payment_attempt a
  WHERE a.root_realm_id=NEW.root_realm_id AND a.donation_id=NEW.donation_id
   AND a.status NOT IN('FAILED','EXPIRED'))
 THEN RAISE EXCEPTION 'An unresolved payment path must be reconciled first'
  USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_provider_refund_channel_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM donation_refund_request r
  JOIN donation d ON d.root_realm_id=r.root_realm_id AND d.id=r.donation_id
  JOIN donation_finance_effect e ON e.root_realm_id=d.root_realm_id AND e.donation_id=d.id
  JOIN journal j ON j.root_realm_id=e.root_realm_id AND j.id=e.journal_id
  WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.refund_request_id
   AND r.donation_id=NEW.donation_id
   AND r.settlement_method='ONLINE' AND r.status='REQUESTED'
   AND d.source_status='RECEIVED_POSTED' AND e.status='POSTED'
   AND j.status='POSTED' AND j.source_ref=d.id
 ) THEN
  RAISE EXCEPTION 'Signed provider refund requires an original ONLINE posted donation';
 END IF;
 RETURN NEW;
END;$function$
;
CREATE OR REPLACE FUNCTION public.cg07_provider_refund_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original provider refund history is immutable'; END IF;
 IF TG_OP='INSERT' AND NEW.state<>'RESERVED'
  THEN RAISE EXCEPTION 'Provider refund starts RESERVED'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.state IN('PROVIDER_FAILED','FINANCE_POSTED') OR
   NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
   NEW.refund_request_id IS DISTINCT FROM OLD.refund_request_id OR
   NEW.donation_id IS DISTINCT FROM OLD.donation_id OR
   NEW.captured_event_id IS DISTINCT FROM OLD.captured_event_id OR
   NEW.captured_payment_id IS DISTINCT FROM OLD.captured_payment_id OR
   NEW.provider_receipt IS DISTINCT FROM OLD.provider_receipt OR
   NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR
   NEW.request_key IS DISTINCT FROM OLD.request_key OR
   NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
   NEW.authorized_by IS DISTINCT FROM OLD.authorized_by OR
   NEW.created_at IS DISTINCT FROM OLD.created_at OR
   (OLD.provider_refund_id IS NOT NULL AND
    NEW.provider_refund_id IS DISTINCT FROM OLD.provider_refund_id) OR
   (OLD.signed_event_id IS NOT NULL AND
    NEW.signed_event_id IS DISTINCT FROM OLD.signed_event_id) OR
   (OLD.signed_digest IS NOT NULL AND NEW.signed_digest IS DISTINCT FROM OLD.signed_digest) OR
   (OLD.processed_at IS NOT NULL AND NEW.processed_at IS DISTINCT FROM OLD.processed_at) OR
   (OLD.state='PROVIDER_PROCESSED' AND NEW.state<>'FINANCE_POSTED') OR
   (OLD.state IN('RESERVED','OUTCOME_UNKNOWN') AND
    NEW.state NOT IN('OUTCOME_UNKNOWN','PROVIDER_PENDING','PROVIDER_PROCESSED','PROVIDER_FAILED')) OR
   (OLD.state='PROVIDER_PENDING' AND NEW.state NOT IN
    ('PROVIDER_PROCESSED','PROVIDER_FAILED','OUTCOME_UNKNOWN'))
  THEN RAISE EXCEPTION 'Original provider refund attempt cannot be rewritten'; END IF;
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM donation_refund_request r JOIN donation_payment_event capture
   ON capture.root_realm_id=r.root_realm_id
  WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.refund_request_id
   AND r.donation_id=NEW.donation_id AND r.amount_minor=NEW.amount_minor
   AND capture.id=NEW.captured_event_id AND capture.donation_id=r.donation_id
   AND capture.outcome='SUCCESS' AND capture.provider='razorpay'
   AND capture.provider_payment_id=NEW.captured_payment_id
   AND r.requested_by<>NEW.authorized_by)
 THEN RAISE EXCEPTION 'Actual separately authorized captured donation refund source required'; END IF;
 RETURN NEW;
END;$function$
;
CREATE OR REPLACE FUNCTION public.cg07_refund_channel_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.settlement_method IS DISTINCT FROM OLD.settlement_method THEN
  RAISE EXCEPTION 'Original refund payout channel cannot be changed';
 END IF;
 RETURN NEW;
END;$function$
;
CREATE OR REPLACE FUNCTION public.cg07_refund_finance_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$

BEGIN
 IF NEW.status<>'FINANCE_REVERSED' THEN RETURN NULL; END IF;
 IF NEW.settlement_method='ONLINE' THEN
  IF NOT EXISTS(SELECT 1 FROM donation_provider_refund p
   JOIN donation_payment_event original
    ON original.root_realm_id=p.root_realm_id AND original.id=p.captured_event_id
   JOIN journal j ON j.root_realm_id=p.root_realm_id AND j.id=NEW.reversal_journal_ref
   JOIN donation_finance_effect e ON e.root_realm_id=p.root_realm_id AND e.donation_id=p.donation_id
   JOIN journal received ON received.root_realm_id=e.root_realm_id AND received.id=e.journal_id
   WHERE p.root_realm_id=NEW.root_realm_id AND p.refund_request_id=NEW.id
    AND p.donation_id=NEW.donation_id AND p.state='FINANCE_POSTED'
    AND p.posted_by=NEW.approved_by AND p.approval_request_key=NEW.approval_request_key
    AND p.signed_event_id IS NOT NULL AND p.signed_digest IS NOT NULL
    AND p.provider_refund_id IS NOT NULL AND p.processed_at IS NOT NULL
    AND original.outcome='SUCCESS' AND original.provider='razorpay'
    AND original.provider_payment_id=p.captured_payment_id
    AND original.amount_minor>=NEW.amount_minor
    AND e.status='POSTED' AND received.status='POSTED'
    AND received.source_ref=NEW.donation_id
    AND j.status='POSTED' AND j.posting_kind='GENERAL'
    AND j.source_ref=NEW.id AND j.immutable_source_event_key=NEW.approval_request_key
    AND j.created_by=NEW.approved_by AND j.financial_year_id=NEW.financial_year_ref
    AND j.posting_date=NEW.posting_date
    AND j.immutable_payload_digest=p.finance_digest
    AND (SELECT count(*) FROM journal_line l
     WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2
    AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id
     AND l.journal_id=j.id AND l.account_id=NEW.income_account_ref
     AND l.debit_minor=NEW.amount_minor AND l.credit_minor=0)
    AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=j.root_realm_id
     AND l.journal_id=j.id AND l.account_id=NEW.cash_account_ref
     AND l.credit_minor=NEW.amount_minor AND l.debit_minor=0))
  THEN RAISE EXCEPTION 'Refund requires processed signed Razorpay payout and exact CG09 reversal'; END IF;
  RETURN NULL;
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM journal j JOIN donation d
   ON d.root_realm_id=j.root_realm_id
  JOIN donation_finance_effect e ON e.root_realm_id=d.root_realm_id AND e.donation_id=d.id
  WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.donation_id
   AND j.id=NEW.reversal_journal_ref AND j.root_realm_id=NEW.root_realm_id
   AND j.source_ref=NEW.id AND j.status='POSTED' AND j.posting_kind='GENERAL'
   AND j.immutable_source_event_key=NEW.approval_request_key
   AND EXISTS(SELECT 1 FROM donation_manual_evidence original
     WHERE original.root_realm_id=NEW.root_realm_id
       AND original.donation_id=NEW.donation_id AND original.status='POSTED'
       AND original.cash_account_ref=NEW.cash_account_ref
       AND original.income_account_ref=NEW.income_account_ref)
   AND EXISTS(SELECT 1 FROM journal_line ln
     WHERE ln.root_realm_id=j.root_realm_id AND ln.journal_id=j.id
       AND ln.account_id=NEW.income_account_ref
       AND ln.debit_minor=NEW.amount_minor AND ln.credit_minor=0)
   AND EXISTS(SELECT 1 FROM journal_line ln
     WHERE ln.root_realm_id=j.root_realm_id AND ln.journal_id=j.id
       AND ln.account_id=NEW.cash_account_ref
       AND ln.credit_minor=NEW.amount_minor AND ln.debit_minor=0)
   AND j.created_by=NEW.approved_by AND j.financial_year_id=NEW.financial_year_ref
   AND j.posting_date=NEW.posting_date
   AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=j.root_realm_id
      AND l.journal_id=j.id)=2
   AND (SELECT coalesce(sum(l.debit_minor),0) FROM journal_line l
      WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=NEW.amount_minor
   AND (SELECT coalesce(sum(l.credit_minor),0) FROM journal_line l
      WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=NEW.amount_minor
   AND e.status='POSTED')
 THEN RAISE EXCEPTION 'Original CG09 posted refund finance proof is missing'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg07_refund_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE received bigint; reserved numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Refund requests are immutable'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.status<>'REQUESTED' OR NEW.status NOT IN('FINANCE_REVERSED','CANCELLED') OR
   NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
   NEW.id IS DISTINCT FROM OLD.id OR NEW.donation_id IS DISTINCT FROM OLD.donation_id OR
   NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR
   NEW.request_key IS DISTINCT FROM OLD.request_key OR
   NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
   NEW.reason IS DISTINCT FROM OLD.reason OR NEW.requested_by IS DISTINCT FROM OLD.requested_by OR
   NEW.requested_at IS DISTINCT FROM OLD.requested_at THEN
   RAISE EXCEPTION 'Refund source must not be rewritten'; END IF;
 ELSE
  IF NEW.status<>'REQUESTED' THEN RAISE EXCEPTION 'New refunds must await verification'; END IF;
 END IF;
 SELECT d.amount_minor INTO received FROM donation d
 JOIN donation_finance_effect e ON e.root_realm_id=d.root_realm_id AND e.donation_id=d.id
 JOIN journal j ON j.root_realm_id=e.root_realm_id AND j.id=e.journal_id
 WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.donation_id
  AND d.source_status='RECEIVED_POSTED' AND e.status='POSTED'
  AND j.status='POSTED' AND j.source_ref=d.id FOR UPDATE OF d;
 IF received IS NULL THEN RAISE EXCEPTION 'Refund requires an original verified received donation'; END IF;
 IF NEW.status<>'CANCELLED' THEN
  SELECT coalesce(sum(amount_minor),0) INTO reserved
  FROM donation_refund_request
  WHERE root_realm_id=NEW.root_realm_id AND donation_id=NEW.donation_id
   AND status<>'CANCELLED' AND id<>NEW.id;
  IF reserved+NEW.amount_minor>received THEN
   RAISE EXCEPTION 'Combined refund requests exceed original received amount';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;

-- Functions 136-180
CREATE OR REPLACE FUNCTION public.cg08_funding_proposal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM access_realm
  WHERE id=NEW.root_realm_id AND realm_key='FOUNDATION_ROOT')
 THEN RAISE EXCEPTION 'Foundation funding source required'; END IF;
 IF NEW.branch_ref IS NOT NULL AND NEW.status IN('DRAFT','SUBMITTED','APPROVED')
  AND NOT EXISTS(
  SELECT 1 FROM branch WHERE id=NEW.branch_ref
   AND root_realm_id=NEW.root_realm_id AND status='ACTIVE' FOR SHARE)
 THEN RAISE EXCEPTION 'Active original CG02 funding branch required'; END IF;
 IF NEW.csr_partner_id IS NOT NULL AND NEW.status IN('DRAFT','SUBMITTED','APPROVED')
  AND NOT EXISTS(
  SELECT 1 FROM csr_partner WHERE id=NEW.csr_partner_id
   AND root_realm_id=NEW.root_realm_id AND status='APPROVED'
   AND (branch_ref IS NULL OR branch_ref IS NOT DISTINCT FROM NEW.branch_ref)
   FOR SHARE)
 THEN RAISE EXCEPTION 'Original approved CSR funder required'; END IF;
 IF NEW.project_ref IS NOT NULL AND NEW.status IN('DRAFT','SUBMITTED','APPROVED')
  AND NOT (TG_OP='UPDATE' AND OLD.status='RETURNED' AND NEW.status='DRAFT')
  AND NOT EXISTS(
   SELECT 1 FROM project WHERE id=NEW.project_ref
    AND root_realm_id=NEW.root_realm_id AND status IN('PLANNED','ACTIVE')
    AND branch_ref IS NOT DISTINCT FROM NEW.branch_ref
    AND version=NEW.project_source_version FOR SHARE)
 THEN RAISE EXCEPTION 'Current original CG05 funding target required'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1
  THEN RAISE EXCEPTION 'Funding starts as draft'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.version<>OLD.version+1 OR
  (NEW.id,NEW.root_realm_id,NEW.branch_ref,NEW.csr_partner_id,
   NEW.created_by,NEW.created_at) IS DISTINCT FROM
  (OLD.id,OLD.root_realm_id,OLD.branch_ref,OLD.csr_partner_id,
   OLD.created_by,OLD.created_at)
 THEN RAISE EXCEPTION 'Original funding identity/branch/revision cannot change'; END IF;
 IF NOT ((OLD.status='DRAFT' AND NEW.status IN('DRAFT','SUBMITTED'))
   OR (OLD.status='RETURNED' AND NEW.status='DRAFT')
   OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED','RETURNED','REJECTED')))
 THEN RAISE EXCEPTION 'Independent funding review is required'; END IF;
 IF NEW.status<>OLD.status AND
  (NEW.project_ref,NEW.project_source_version,NEW.purpose,NEW.fund_type,
   NEW.currency,NEW.requested_minor,NEW.csr_share_bps,NEW.foundation_share_bps,
   NEW.proposed_from,NEW.proposed_until,NEW.agreement_summary)
  IS DISTINCT FROM
  (OLD.project_ref,OLD.project_source_version,OLD.purpose,OLD.fund_type,
   OLD.currency,OLD.requested_minor,OLD.csr_share_bps,OLD.foundation_share_bps,
   OLD.proposed_from,OLD.proposed_until,OLD.agreement_summary)
 THEN RAISE EXCEPTION 'Funding terms are frozen on reviewer state transition'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg08_funding_review_status_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'UPDATE' OR NEW.status IS NOT DISTINCT FROM OLD.status
  OR NEW.status NOT IN('SUBMITTED','APPROVED','RETURNED','REJECTED')
 THEN RETURN NULL; END IF;
 IF NEW.status='SUBMITTED' THEN
  IF NOT EXISTS(
   SELECT 1 FROM cg03_case c JOIN csr_funding_review_snapshot snap
    ON snap.root_realm_id=c.realm_id AND snap.id=c.csr_funding_review_ref
   JOIN cg19_stored_file f ON f.realm_id=snap.root_realm_id
    AND f.id=snap.evidence_file_id AND f.funding_proposal_id=snap.proposal_id
   JOIN cg19_upload_intent i ON i.realm_id=f.realm_id AND i.id=f.upload_intent_id
   WHERE c.realm_id=NEW.root_realm_id AND c.csr_funding_proposal_id=NEW.id
    AND c.case_kind='CSR_FUNDING_REVIEW' AND c.status='SUBMITTED'
    AND c.csr_funding_source_version=OLD.version
    AND c.csr_funding_source_digest=snap.source_digest
    AND snap.source_version=OLD.version AND snap.evidence_file_id=f.id
    AND f.proposal_revision=OLD.version
    AND f.owner_kind='CG08_FUNDING_AGREEMENT'
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND i.owner_kind='CG08_FUNDING_AGREEMENT'
    AND i.classification='CSR_FUNDING_AGREEMENT' AND i.status='VALIDATED'
  ) THEN RAISE EXCEPTION 'Original CG03 and CG19 signed funding review required'; END IF;
 ELSE
  IF NOT EXISTS(
   SELECT 1 FROM cg03_case c JOIN cg03_case_decision d
    ON d.realm_id=c.realm_id AND d.case_id=c.id
   WHERE c.realm_id=NEW.root_realm_id AND c.csr_funding_proposal_id=NEW.id
    AND c.case_kind='CSR_FUNDING_REVIEW'
    AND c.csr_funding_source_version+1=OLD.version
    AND d.actor_id<>c.proposer_id AND d.fresh_password_verified_at IS NOT NULL
    AND d.action=CASE NEW.status WHEN 'APPROVED' THEN 'APPROVE'
      WHEN 'RETURNED' THEN 'RETURN' ELSE 'REJECT' END
    AND c.status=CASE NEW.status WHEN 'APPROVED' THEN 'OWNER_COMPLETED'
      ELSE NEW.status END
  ) THEN RAISE EXCEPTION 'Original CG03 funding decision not independently proven'; END IF;
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg08_partner_command_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'CSR partner command history cannot be edited';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg08_partner_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM access_realm WHERE id=NEW.root_realm_id AND realm_key='FOUNDATION_ROOT') THEN
  RAISE EXCEPTION 'CSR partner requires a real Foundation root'; END IF;
 IF NEW.branch_ref IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM branch WHERE id=NEW.branch_ref AND root_realm_id=NEW.root_realm_id AND status='ACTIVE' FOR SHARE)
 THEN RAISE EXCEPTION 'Original active CSR branch required'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1 THEN RAISE EXCEPTION 'CSR partner starts as draft'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.version<>OLD.version+1 OR
  (NEW.id,NEW.root_realm_id,NEW.branch_ref,NEW.created_by,NEW.created_at) IS DISTINCT FROM
  (OLD.id,OLD.root_realm_id,OLD.branch_ref,OLD.created_by,OLD.created_at)
 THEN RAISE EXCEPTION 'CSR partner original source/branch/version cannot change'; END IF;
 IF NOT ((OLD.status='DRAFT' AND NEW.status IN('DRAFT','INACTIVE','SUBMITTED'))
  OR (OLD.status='RETURNED' AND NEW.status IN('DRAFT','INACTIVE'))
  OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED','RETURNED','REJECTED')))
 THEN RAISE EXCEPTION 'Unapproved CSR state transition'; END IF;
 IF NEW.status IN('SUBMITTED','APPROVED','RETURNED','REJECTED') AND
  (NEW.legal_name,NEW.registration_reference,NEW.contact_name,NEW.contact_email,
   NEW.contact_mobile,NEW.support_summary) IS DISTINCT FROM
  (OLD.legal_name,OLD.registration_reference,OLD.contact_name,OLD.contact_email,
   OLD.contact_mobile,OLD.support_summary)
 THEN RAISE EXCEPTION 'Protected CSR approval cannot edit original agreement source'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg08_partner_status_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'UPDATE' OR NEW.status IS NOT DISTINCT FROM OLD.status OR NEW.status NOT IN
  ('SUBMITTED','APPROVED','RETURNED','REJECTED') THEN RETURN NULL; END IF;
 IF NEW.status='SUBMITTED' THEN
  IF NOT EXISTS(
   SELECT 1 FROM cg03_case c JOIN csr_partner_review_snapshot r
    ON r.root_realm_id=c.realm_id AND r.id=c.csr_review_ref
   JOIN cg19_stored_file f ON f.realm_id=r.root_realm_id
    AND f.id=r.evidence_file_id AND f.csr_partner_id=r.partner_id
   JOIN cg19_upload_intent i ON i.realm_id=f.realm_id AND i.id=f.upload_intent_id
   WHERE c.realm_id=NEW.root_realm_id AND c.csr_partner_id=NEW.id
    AND c.case_kind='CSR_PARTNER_REVIEW' AND c.status='SUBMITTED'
    AND c.csr_source_version=OLD.version AND c.csr_source_digest=r.source_digest
    AND r.evidence_file_id=f.id AND f.proposal_revision=OLD.version
    AND f.owner_kind='CG08_CSR_AGREEMENT' AND f.scan_status='CLEAN_VERIFIED'
    AND f.revoked_at IS NULL AND i.owner_kind='CG08_CSR_AGREEMENT'
    AND i.classification='CSR_AGREEMENT' AND i.status='VALIDATED'
   ) THEN RAISE EXCEPTION 'CSR submission requires original verified CG03/CG19 proof'; END IF;
 ELSE
  IF NOT EXISTS(
   SELECT 1 FROM cg03_case c JOIN cg03_case_decision d
     ON d.realm_id=c.realm_id AND d.case_id=c.id
   WHERE c.realm_id=NEW.root_realm_id AND c.csr_partner_id=NEW.id
    AND c.case_kind='CSR_PARTNER_REVIEW' AND c.csr_source_version+1=OLD.version
    AND d.fresh_password_verified_at IS NOT NULL
    AND d.action=CASE NEW.status WHEN 'APPROVED' THEN 'APPROVE'
      WHEN 'RETURNED' THEN 'RETURN' ELSE 'REJECT' END
    AND c.status=CASE NEW.status WHEN 'APPROVED' THEN 'OWNER_COMPLETED' ELSE NEW.status END
  ) THEN RAISE EXCEPTION 'CSR decision requires original CG03 signed reviewer proof'; END IF;
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg08_public_release_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.root_realm_id,NEW.partner_id) IS DISTINCT FROM
     (OLD.root_realm_id,OLD.partner_id) OR NEW.version<>OLD.version+1
     OR NOT ((OLD.state='AUTHORIZED' AND NEW.state='WITHDRAWN'
        AND (NEW.evidence_file_id,NEW.authorized_by,NEW.authorized_at,NEW.public_summary)
         IS NOT DISTINCT FROM
            (OLD.evidence_file_id,OLD.authorized_by,OLD.authorized_at,OLD.public_summary))
       OR (OLD.state='WITHDRAWN' AND NEW.state='AUTHORIZED'
        AND NEW.withdrawn_at IS NULL AND NEW.authorized_at>=OLD.authorized_at))
  THEN RAISE EXCEPTION 'CSR public release revision or immutable identity invalid'; END IF;
 END IF;
 IF NEW.state='AUTHORIZED' AND NOT EXISTS(
  SELECT 1 FROM csr_partner p
  JOIN csr_partner_review_snapshot s
   ON s.root_realm_id=p.root_realm_id AND s.partner_id=p.id AND
      s.evidence_file_id=NEW.evidence_file_id
  JOIN cg03_case c ON c.realm_id=s.root_realm_id
   AND c.csr_review_ref=s.id AND c.csr_partner_id=p.id
   AND c.csr_source_version=s.source_version AND c.csr_source_digest=s.source_digest
   AND c.case_kind='CSR_PARTNER_REVIEW' AND c.status='OWNER_COMPLETED'
  JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
   AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL
  JOIN cg19_stored_file f ON f.id=s.evidence_file_id
   AND f.realm_id=p.root_realm_id AND f.csr_partner_id=p.id
   AND f.owner_kind='CG08_CSR_AGREEMENT' AND f.scan_status='CLEAN_VERIFIED'
   AND f.revoked_at IS NULL
  JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
   AND i.csr_partner_id=f.csr_partner_id AND i.owner_kind='CG08_CSR_AGREEMENT'
   AND i.status='VALIDATED'
  WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.partner_id
    AND p.status='APPROVED'
 ) THEN RAISE EXCEPTION 'Current CG03 approval and clean CG19 publicity evidence required'; END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg09_bank_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE current_status text;
BEGIN
 SELECT a.status INTO current_status FROM finance_account a
  WHERE a.id=NEW.account_id AND a.root_realm_id=NEW.root_realm_id
   AND a.account_kind=NEW.kind FOR SHARE;
 IF NOT FOUND OR NEW.status<>current_status THEN
  RAISE EXCEPTION 'Cash/bank account status must match finance account' USING ERRCODE='P0905';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
   OR NEW.account_id IS DISTINCT FROM OLD.account_id
   OR NEW.kind IS DISTINCT FROM OLD.kind
   OR NEW.display_label IS DISTINCT FROM OLD.display_label
   OR NEW.masked_details IS DISTINCT FROM OLD.masked_details
   OR NEW.created_at IS DISTINCT FROM OLD.created_at
   OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
   RAISE EXCEPTION 'Cash/bank account identity cannot change' USING ERRCODE='P0907';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_bank_decision_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.action='VERIFY' THEN
  PERFORM 1 FROM cg19_stored_file f JOIN cg19_upload_intent i
   ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
   JOIN finance_bank_reconciliation r
    ON r.id=f.reconciliation_id AND r.root_realm_id=f.realm_id
   WHERE f.id=NEW.statement_file_id AND f.realm_id=NEW.root_realm_id
    AND r.recorded_by=i.requested_by AND r.recorded_by=f.created_by
    AND f.reconciliation_id=NEW.reconciliation_id
    AND f.revision=NEW.statement_file_version
    AND f.owner_kind='CG09_BANK_STATEMENT' AND i.owner_kind='CG09_BANK_STATEMENT'
    AND i.reconciliation_id=NEW.reconciliation_id AND i.status='VALIDATED'
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
   FOR SHARE OF f,i;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'A clean original bank statement file is required'
    USING ERRCODE='P0928';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_budget_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b record; used bigint; committed bigint; released bigint; allocated bigint; deallocated bigint; applied bigint; outstanding bigint;
 journal_total bigint;
BEGIN
 SELECT status,approved_ceiling_minor,financial_year_id,branch_id,category_label,period_start,period_end INTO b
  FROM finance_budget WHERE id=NEW.budget_id AND root_realm_id=NEW.root_realm_id FOR UPDATE;
 IF NOT FOUND OR b.status<>'APPROVED' THEN
  RAISE EXCEPTION 'Budget must have protected approval' USING ERRCODE='P0924';
 END IF;
 SELECT COALESCE(SUM(CASE WHEN e.kind='UTILIZE' AND NOT EXISTS(
  SELECT 1 FROM journal reversal WHERE reversal.root_realm_id=e.root_realm_id
   AND reversal.reversal_of_id=e.source_journal_id
   AND reversal.posting_kind='REVERSAL' AND reversal.status='POSTED'
 ) THEN e.amount_minor ELSE 0 END),0),
  COALESCE(SUM(amount_minor) FILTER(WHERE kind='COMMIT'),0),
  COALESCE(SUM(amount_minor) FILTER(WHERE kind='RELEASE'),0),
  COALESCE(SUM(amount_minor) FILTER(WHERE kind='ALLOCATE'),0),
  COALESCE(SUM(amount_minor) FILTER(WHERE kind='DEALLOCATE'),0),
  COALESCE(SUM(CASE WHEN e.kind='UTILIZE' AND NOT EXISTS(
   SELECT 1 FROM journal reversal WHERE reversal.root_realm_id=e.root_realm_id
    AND reversal.reversal_of_id=e.source_journal_id
    AND reversal.posting_kind='REVERSAL' AND reversal.status='POSTED'
  ) THEN e.commitment_applied_minor ELSE 0 END),0)
 INTO used,committed,released,allocated,deallocated,applied
 FROM finance_budget_event e WHERE e.root_realm_id=NEW.root_realm_id AND e.budget_id=NEW.budget_id;
 IF NEW.kind='UTILIZE' THEN
  PERFORM 1 FROM journal j JOIN finance_voucher v
     ON v.id=j.source_ref AND v.root_realm_id=j.root_realm_id
    JOIN finance_account a ON a.id=v.debit_account_id AND a.root_realm_id=v.root_realm_id
    JOIN account_group g ON g.id=a.group_id AND g.root_realm_id=a.root_realm_id
   WHERE j.id=NEW.source_journal_id AND j.root_realm_id=NEW.root_realm_id
    AND j.status='POSTED' AND j.financial_year_id=b.financial_year_id
    AND j.posting_kind='VOUCHER' AND j.posting_date BETWEEN b.period_start AND b.period_end
    AND v.voucher_type='EXPENSE' AND g.category='EXPENSE' AND g.code=b.category_label
    AND v.status IN('POSTED','PAYMENT_REQUESTED','PAID_VERIFIED')
   FOR SHARE OF j,v,a,g;
  IF NOT FOUND THEN RAISE EXCEPTION 'Real posted journal required' USING ERRCODE='P0924'; END IF;
  SELECT COALESCE(SUM(l.debit_minor),0) INTO journal_total FROM journal_line l
   JOIN finance_account a ON a.id=l.account_id AND a.root_realm_id=l.root_realm_id
   JOIN account_group g ON g.id=a.group_id AND g.root_realm_id=a.root_realm_id
   WHERE l.journal_id=NEW.source_journal_id AND l.root_realm_id=NEW.root_realm_id
    AND (b.branch_id IS NULL OR l.branch_id=b.branch_id)
    AND g.category='EXPENSE';
  IF journal_total<>NEW.amount_minor OR journal_total<1 THEN
   RAISE EXCEPTION 'Budget utilization must match original actual posted expense' USING ERRCODE='P0924';
  END IF;
 END IF;
 -- Consumption of a real posted expense fulfills an existing obligation
 -- first. Do not double count a committed amount AND its later utilization.
 outstanding=committed-released-applied;
 IF outstanding<0 THEN
  RAISE EXCEPTION 'Original budget commitments are inconsistent' USING ERRCODE='P0924';
 END IF;
 IF NEW.kind='UTILIZE' THEN
  NEW.commitment_applied_minor=LEAST(outstanding,NEW.amount_minor);
 ELSE
  NEW.commitment_applied_minor=0;
 END IF;
 IF NEW.kind='RELEASE' AND NEW.amount_minor>outstanding THEN
  RAISE EXCEPTION 'Cannot release more than unmatched outstanding commitment' USING ERRCODE='P0924';
 END IF;
 IF NEW.kind='ALLOCATE' AND allocated-deallocated+NEW.amount_minor>b.approved_ceiling_minor THEN
  RAISE EXCEPTION 'Cannot allocate beyond approved budget' USING ERRCODE='P0924';
 END IF;
 IF NEW.kind='DEALLOCATE' AND
   (NEW.amount_minor>allocated-deallocated OR
    NEW.amount_minor>allocated-deallocated-used) THEN
  RAISE EXCEPTION 'Cannot reverse an allocation already spent or previously corrected'
   USING ERRCODE='P0924';
 END IF;
 IF NEW.kind IN('COMMIT','UTILIZE') AND
    used+outstanding+NEW.amount_minor-NEW.commitment_applied_minor>
     b.approved_ceiling_minor THEN
  RAISE EXCEPTION 'Budget remaining amount is insufficient' USING ERRCODE='P0924';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_budget_item_revision_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source record;
BEGIN
 SELECT status,version INTO source FROM finance_budget
 WHERE root_realm_id=NEW.root_realm_id AND id=NEW.budget_id FOR UPDATE;
 IF NOT FOUND OR NOT (
  (source.status='DRAFT' AND
   (NEW.version=source.version OR NEW.version=source.version+1))
  OR (source.status='RETURNED' AND NEW.version=source.version+1)
 ) THEN
  RAISE EXCEPTION 'A reviewed original budget revision cannot gain new item lines'
   USING ERRCODE='P0924';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_budget_itemized_submit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE line_count integer; item_total numeric;
BEGIN
 IF NEW.status='SUBMITTED' AND OLD.status IS DISTINCT FROM 'SUBMITTED' THEN
  SELECT count(*)::integer,coalesce(sum(line_total_minor),0)
   INTO line_count,item_total
  FROM finance_budget_item_revision
  WHERE root_realm_id=NEW.root_realm_id AND budget_id=NEW.id AND version=NEW.version;
  IF line_count>0 AND item_total<>NEW.approved_ceiling_minor THEN
   RAISE EXCEPTION 'Reviewed item quantities and rates must equal the approved ceiling'
    USING ERRCODE='P0924';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_budget_new_effect_scope_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b record; y record; source record;
BEGIN
 SELECT financial_year_id,branch_id,category_label,period_start,period_end,status
  INTO b FROM finance_budget
  WHERE id=NEW.budget_id AND root_realm_id=NEW.root_realm_id FOR UPDATE;
 IF NOT FOUND OR b.status<>'APPROVED' THEN
  RAISE EXCEPTION 'An approved original budget is required'
   USING ERRCODE='P0924';
 END IF;
 SELECT status,start_on,end_on INTO y FROM financial_year
  WHERE id=b.financial_year_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR y.status<>'OPEN' OR
  b.period_start<y.start_on OR b.period_end>y.end_on THEN
  RAISE EXCEPTION 'No new budget movement in closed or changed financial period'
   USING ERRCODE='P0924';
 END IF;
 IF b.branch_id IS NOT NULL THEN
  PERFORM 1 FROM branch
   WHERE id=b.branch_id AND root_realm_id=NEW.root_realm_id
    AND status='ACTIVE' FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Cannot move a budget for an inactive branch'
    USING ERRCODE='P0924';
  END IF;
 END IF;
 IF NEW.kind='UTILIZE' THEN
  SELECT v.branch_id,j.posting_date,j.financial_year_id,j.posting_kind
   INTO source
   FROM journal j
   JOIN finance_voucher v ON v.id=j.source_ref
    AND v.root_realm_id=j.root_realm_id
   WHERE j.id=NEW.source_journal_id AND j.root_realm_id=NEW.root_realm_id
    AND j.status='POSTED' AND v.voucher_type='EXPENSE'
    AND NOT EXISTS(SELECT 1 FROM journal reversal
      WHERE reversal.root_realm_id=j.root_realm_id
       AND reversal.reversal_of_id=j.id
       AND reversal.posting_kind='REVERSAL' AND reversal.status='POSTED')
   FOR SHARE OF j,v;
  IF NOT FOUND OR source.posting_kind<>'VOUCHER'
   OR source.financial_year_id<>b.financial_year_id
   OR source.posting_date NOT BETWEEN b.period_start AND b.period_end
   OR (b.branch_id IS NOT NULL AND source.branch_id IS DISTINCT FROM b.branch_id) THEN
   RAISE EXCEPTION 'Budget utilization requires a current same-scope posted voucher'
    USING ERRCODE='P0924';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_budget_revision_exists()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM finance_budget_revision r
  WHERE r.root_realm_id=NEW.root_realm_id AND r.budget_id=NEW.id
    AND r.version=NEW.version AND r.source_digest=NEW.current_digest;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Original budget revision missing' USING ERRCODE='P0925';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_budget_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE case_status record; grant_row record;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original budget cannot be deleted' USING ERRCODE='P0925';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1 THEN
   RAISE EXCEPTION 'Budget starts as a draft' USING ERRCODE='P0925';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR
    NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
    NEW.budget_number IS DISTINCT FROM OLD.budget_number OR
    NEW.created_by IS DISTINCT FROM OLD.created_by OR
    NEW.currency IS DISTINCT FROM OLD.currency OR
    NEW.created_at IS DISTINCT FROM OLD.created_at THEN
  RAISE EXCEPTION 'Original budget identity cannot be changed' USING ERRCODE='P0925';
 END IF;
 IF OLD.status IN('DRAFT','RETURNED') AND NEW.status='DRAFT' THEN
  IF NEW.version<>OLD.version+1 OR NEW.approval_case_id IS NOT NULL OR
     NEW.current_digest IS NOT DISTINCT FROM OLD.current_digest THEN
   RAISE EXCEPTION 'Budget correction needs new immutable revision' USING ERRCODE='P0925';
  END IF;
  IF OLD.status='RETURNED' THEN
   PERFORM 1 FROM cg03_case c JOIN cg03_case_decision d
    ON d.case_id=c.id AND d.realm_id=c.realm_id
    WHERE c.id=OLD.approval_case_id AND c.realm_id=OLD.root_realm_id
     AND c.case_kind='FINANCE_BUDGET' AND c.finance_budget_id=OLD.id
     AND c.finance_budget_revision=OLD.version AND c.status='RETURNED'
     AND d.action='RETURN' AND d.fresh_password_verified_at IS NOT NULL
    FOR SHARE OF c,d;
   IF NOT FOUND THEN RAISE EXCEPTION 'An actual returned budget decision is required'
    USING ERRCODE='P0925'; END IF;
  END IF;
 ELSIF OLD.status='DRAFT' AND NEW.status='SUBMITTED' THEN
  IF (to_jsonb(NEW)-'status'-'approval_case_id'-'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD)-'status'-'approval_case_id'-'updated_at') THEN
   RAISE EXCEPTION 'Submitted budget fields cannot change' USING ERRCODE='P0925';
  END IF;
  SELECT c.status,c.finance_budget_digest INTO case_status
   FROM cg03_case c WHERE c.id=NEW.approval_case_id AND c.realm_id=NEW.root_realm_id
    AND c.case_kind='FINANCE_BUDGET' AND c.finance_budget_id=NEW.id
    AND c.finance_budget_revision=NEW.version
    AND c.finance_budget_digest=NEW.current_digest
    AND c.status IN('SUBMITTED','IN_REVIEW') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Original budget reviewer case is missing'
    USING ERRCODE='P0925'; END IF;
  PERFORM 1 FROM financial_year fy WHERE fy.id=NEW.financial_year_id
    AND fy.root_realm_id=NEW.root_realm_id AND fy.status='OPEN'
    AND NEW.period_start BETWEEN fy.start_on AND fy.end_on
    AND NEW.period_end BETWEEN fy.start_on AND fy.end_on FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Budget period is outside current year' USING ERRCODE='P0925'; END IF;
  PERFORM 1 FROM account_group WHERE root_realm_id=NEW.root_realm_id
   AND category='EXPENSE' AND name=NEW.category_label FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Budget category must refer to a real expense group'
     USING ERRCODE='P0925';
  END IF;
  IF NEW.branch_id IS NOT NULL THEN
   PERFORM 1 FROM branch WHERE id=NEW.branch_id AND root_realm_id=NEW.root_realm_id
    AND status='ACTIVE' FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Budget branch is unavailable' USING ERRCODE='P0925'; END IF;
  END IF;
 ELSIF OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED') THEN
  IF (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM
     (to_jsonb(OLD)-'status'-'updated_at') THEN
   RAISE EXCEPTION 'Protected submitted budget cannot be changed' USING ERRCODE='P0925';
  END IF;
  SELECT c.status INTO case_status FROM cg03_case c
   WHERE c.id=OLD.approval_case_id AND c.realm_id=OLD.root_realm_id
    AND c.case_kind='FINANCE_BUDGET' AND c.finance_budget_id=OLD.id
    AND c.finance_budget_revision=OLD.version FOR SHARE;
  IF NOT FOUND OR
     (NEW.status='RETURNED' AND case_status.status<>'RETURNED') OR
     (NEW.status='REJECTED' AND case_status.status<>'REJECTED') OR
     (NEW.status='APPROVED' AND case_status.status NOT IN('PENDING_OWNER','OWNER_COMPLETED')) THEN
   RAISE EXCEPTION 'Protected budget decision is not confirmed' USING ERRCODE='P0925';
  END IF;
  IF NEW.status='APPROVED' THEN
   PERFORM 1 FROM cg03_finance_owner_effect e JOIN cg03_case_decision d
    ON d.id=e.final_decision_id AND d.case_id=e.case_id
    WHERE e.case_id=OLD.approval_case_id AND e.realm_id=OLD.root_realm_id
     AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL
    FOR SHARE OF e,d;
   IF NOT FOUND THEN RAISE EXCEPTION 'Protected budget approval missing' USING ERRCODE='P0925'; END IF;
  END IF;
 ELSIF OLD.status='APPROVED' AND NEW.status='ARCHIVED' THEN
  IF (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM
    (to_jsonb(OLD)-'status'-'updated_at') THEN
   RAISE EXCEPTION 'Archived budget cannot edit original approved ceiling' USING ERRCODE='P0925';
  END IF;
 ELSE
  RAISE EXCEPTION 'Budget workflow transition is not allowed' USING ERRCODE='P0925';
 END IF;
 PERFORM 1 FROM finance_budget_revision r
 WHERE r.root_realm_id=NEW.root_realm_id AND r.budget_id=NEW.id
   AND r.version=NEW.version AND r.source_digest=NEW.current_digest
   AND r.name=NEW.budget_name AND r.category_label=NEW.category_label
   AND r.financial_year_id=NEW.financial_year_id
   AND r.branch_id IS NOT DISTINCT FROM NEW.branch_id
   AND r.period_start=NEW.period_start AND r.period_end=NEW.period_end
   AND r.funding_note=NEW.funding_note
   AND r.approved_ceiling_minor=NEW.approved_ceiling_minor
 FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Budget immutable source revision does not match' USING ERRCODE='P0925';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_check_balanced_posting()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_journal uuid; r uuid; line_count int; total_debit numeric; total_credit numeric;
BEGIN
 IF TG_TABLE_NAME='journal' THEN
  v_journal:=NEW.id;
 ELSE
  v_journal:=NEW.journal_id;
 END IF;
 r:=NEW.root_realm_id;
 SELECT count(*),coalesce(sum(debit_minor),0),coalesce(sum(credit_minor),0)
 INTO line_count,total_debit,total_credit
 FROM journal_line WHERE journal_id=v_journal AND root_realm_id=r;
 IF NOT EXISTS (
   SELECT 1 FROM journal j JOIN financial_year fy
    ON fy.id=j.financial_year_id AND fy.root_realm_id=j.root_realm_id
   WHERE j.id=v_journal AND j.root_realm_id=r
    AND j.posting_date BETWEEN fy.start_on AND fy.end_on
 ) THEN RAISE EXCEPTION 'Posting date outside financial year' USING ERRCODE='P0901'; END IF;
 IF EXISTS (
   SELECT 1 FROM journal_line l JOIN finance_account a
    ON a.id=l.account_id AND a.root_realm_id=l.root_realm_id
   WHERE l.journal_id=v_journal AND l.root_realm_id=r
    AND (a.scope_kind='BRANCH' AND a.branch_id IS DISTINCT FROM l.branch_id)
 ) OR (SELECT count(DISTINCT l.branch_id) FROM journal_line l
        WHERE l.journal_id=v_journal AND l.root_realm_id=r)>1 AND NOT EXISTS(
  SELECT 1 FROM payroll_accrual a WHERE a.root_realm_id=r AND a.journal_ref=v_journal
 UNION ALL SELECT 1 FROM finance_voucher_posting p JOIN payroll_payout_attempt t ON t.root_realm_id=p.root_realm_id AND t.voucher_ref=p.voucher_id WHERE p.root_realm_id=r AND p.journal_id=v_journal
 UNION ALL SELECT 1 FROM finance_manual_journal_reversal rev WHERE rev.root_realm_id=r AND rev.reversal_journal_id=v_journal AND rev.payroll_return_bank_reference IS NOT NULL
 ) THEN
  RAISE EXCEPTION 'Finance journal branch and account scope do not match' USING ERRCODE='P0904';
 END IF;
 IF EXISTS(SELECT 1 FROM payroll_accrual a WHERE a.root_realm_id=r AND a.journal_ref=v_journal
 UNION ALL SELECT 1 FROM finance_voucher_posting p JOIN payroll_payout_attempt t ON t.root_realm_id=p.root_realm_id AND t.voucher_ref=p.voucher_id WHERE p.root_realm_id=r AND p.journal_id=v_journal
 UNION ALL SELECT 1 FROM finance_manual_journal_reversal rev WHERE rev.root_realm_id=r AND rev.reversal_journal_id=v_journal AND rev.payroll_return_bank_reference IS NOT NULL)
 AND EXISTS(SELECT 1 FROM journal_line l WHERE l.root_realm_id=r AND l.journal_id=v_journal GROUP BY l.branch_id HAVING sum(l.debit_minor)<>sum(l.credit_minor))
 THEN RAISE EXCEPTION 'Payroll branch posting must balance' USING ERRCODE='P0903'; END IF;
 IF line_count<2 OR total_debit<=0 OR total_debit<>total_credit THEN
   RAISE EXCEPTION 'Unbalanced posted journal' USING ERRCODE='P0903'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_claim_hr_origin_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (NEW.source_kind,NEW.hr_employee_id,NEW.hr_assignment_id,NEW.hr_branch_id)
   IS DISTINCT FROM (OLD.source_kind,OLD.hr_employee_id,OLD.hr_assignment_id,OLD.hr_branch_id)
  THEN RAISE EXCEPTION 'Original claim origin cannot change' USING ERRCODE='P0919'; END IF;
  -- Historic approved/submitted claims remain finance-owned after an employee exits.
  IF NOT (OLD.status='DRAFT' AND NEW.status='SUBMITTED' OR OLD.status='RETURNED' AND NEW.status='DRAFT') THEN RETURN NEW; END IF;
 END IF;
 IF NEW.source_kind='HR_ALLOWANCE' THEN
  PERFORM 1 FROM hr_employee e JOIN hr_employee_application p ON p.id=e.application_id AND p.root_realm_id=e.root_realm_id AND p.state='ACTIVE'
   JOIN hr_employment_assignment a ON a.employee_id=e.id AND a.root_realm_id=e.root_realm_id
   JOIN branch b ON b.id=a.branch_ref AND b.root_realm_id=a.root_realm_id AND b.status='ACTIVE'
   JOIN account ac ON ac.id=e.account_ref AND ac.realm_id=e.root_realm_id AND ac.status='ACTIVE'
   WHERE e.root_realm_id=NEW.root_realm_id AND e.id=NEW.hr_employee_id AND e.account_ref=NEW.requested_by
    AND e.status IN('ACTIVE','PROBATION') AND a.id=NEW.hr_assignment_id AND a.branch_ref=NEW.hr_branch_id
    AND a.valid_from<=CURRENT_DATE AND (a.valid_to IS NULL OR a.valid_to>CURRENT_DATE)
   FOR SHARE OF e,p,a,b,ac;
  IF NOT FOUND THEN RAISE EXCEPTION 'Current approved HR allowance source required' USING ERRCODE='P0919'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_claim_number_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.claim_number IS DISTINCT FROM OLD.claim_number THEN
  RAISE EXCEPTION 'Original claim number is immutable' USING ERRCODE='P0920';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_claim_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original_case record;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original claim history cannot be deleted' USING ERRCODE='P0919';
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR
    NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
    NEW.requested_by IS DISTINCT FROM OLD.requested_by OR
    NEW.currency IS DISTINCT FROM OLD.currency OR
    NEW.create_request_key IS DISTINCT FROM OLD.create_request_key OR
    NEW.create_digest IS DISTINCT FROM OLD.create_digest OR
    NEW.created_at IS DISTINCT FROM OLD.created_at THEN
  RAISE EXCEPTION 'Original claim identity cannot change' USING ERRCODE='P0919';
 END IF;
 IF OLD.status='RETURNED' AND NEW.status='DRAFT' THEN
  -- Corrections keep one claim ID but must create a separate immutable version
  -- and clear approval/evidence until the new bill passes actual scanning.
  IF NEW.version<>OLD.version+1 OR
     NEW.current_digest IS NOT DISTINCT FROM OLD.current_digest OR
     NEW.bill_file_id IS NOT NULL OR NEW.bill_file_version IS NOT NULL OR
     NEW.approval_case_id IS NOT NULL THEN
   RAISE EXCEPTION 'Return correction needs new revision' USING ERRCODE='P0919';
  END IF;
  PERFORM 1 FROM cg03_case c
   JOIN cg03_case_decision d ON d.case_id=c.id AND d.realm_id=c.realm_id
   WHERE c.id=OLD.approval_case_id AND c.realm_id=OLD.root_realm_id
    AND c.case_kind='FINANCE_REIMBURSEMENT'
    AND c.finance_claim_id=OLD.id AND c.finance_claim_revision=OLD.version
    AND c.status='RETURNED' AND d.action='RETURN'
    AND d.fresh_password_verified_at IS NOT NULL FOR SHARE OF c,d;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'A genuine returned reviewer case is required' USING ERRCODE='P0919';
  END IF;
 ELSIF OLD.status='DRAFT' AND NEW.status='SUBMITTED' THEN
  IF (to_jsonb(NEW)-'status'-'bill_file_id'-'bill_file_version'-'approval_case_id')
      IS DISTINCT FROM
     (to_jsonb(OLD)-'status'-'bill_file_id'-'bill_file_version'-'approval_case_id')
  THEN RAISE EXCEPTION 'Submitted claim source cannot change' USING ERRCODE='P0919'; END IF;
  PERFORM 1 FROM cg03_case c
   JOIN cg19_stored_file f ON f.id=c.finance_claim_bill_id
    AND f.realm_id=c.realm_id AND f.claim_id=c.finance_claim_id
    AND f.claim_version=c.finance_claim_revision
   JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
   WHERE c.id=NEW.approval_case_id AND c.realm_id=NEW.root_realm_id
    AND c.case_kind='FINANCE_REIMBURSEMENT'
    AND c.finance_claim_id=NEW.id AND c.finance_claim_revision=NEW.version
    AND c.finance_claim_digest=NEW.current_digest
    AND c.finance_claim_bill_id=NEW.bill_file_id
    AND c.finance_claim_bill_version=NEW.bill_file_version
    AND c.status IN('SUBMITTED','IN_REVIEW')
    AND f.revoked_at IS NULL AND f.revision=NEW.bill_file_version
    AND f.owner_kind='CG09_CLAIM' AND f.scan_status='CLEAN_VERIFIED'
    AND i.owner_kind='CG09_CLAIM' AND i.status='VALIDATED'
    FOR SHARE OF c,f,i;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'A verified original bill and case are required' USING ERRCODE='P0919';
  END IF;
 ELSIF OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED') THEN
  IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') THEN
   RAISE EXCEPTION 'Frozen submitted claim cannot be changed' USING ERRCODE='P0919';
  END IF;
  SELECT c.status INTO original_case FROM cg03_case c
   WHERE c.id=OLD.approval_case_id AND c.realm_id=OLD.root_realm_id
    AND c.case_kind='FINANCE_REIMBURSEMENT'
    AND c.finance_claim_id=OLD.id AND c.finance_claim_revision=OLD.version
    FOR SHARE;
  IF NOT FOUND OR
    (NEW.status='RETURNED' AND original_case.status<>'RETURNED') OR
    (NEW.status='REJECTED' AND original_case.status<>'REJECTED') OR
    (NEW.status='APPROVED' AND original_case.status NOT IN('PENDING_OWNER','OWNER_COMPLETED')) THEN
   RAISE EXCEPTION 'A genuine protected reviewer decision is required' USING ERRCODE='P0919';
  END IF;
  IF NEW.status='APPROVED' THEN
   PERFORM 1 FROM cg03_finance_owner_effect e
    JOIN cg03_case_decision d ON d.id=e.final_decision_id AND d.case_id=e.case_id
    WHERE e.case_id=OLD.approval_case_id AND e.realm_id=OLD.root_realm_id
     AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL
     FOR SHARE OF e,d;
   IF NOT FOUND THEN
    RAISE EXCEPTION 'Protected reviewer approval is not current' USING ERRCODE='P0919';
   END IF;
  END IF;
 ELSE RAISE EXCEPTION 'This claim transition is not allowed' USING ERRCODE='P0919';
 END IF;
 -- Confirm the immutable source version matches the exact currently stored
 -- purpose, category, date, amount and digest on every accepted transition.
 PERFORM 1 FROM expense_claim_revision r
 WHERE r.root_realm_id=NEW.root_realm_id AND r.claim_id=NEW.id
   AND r.version=NEW.version AND r.current_digest=NEW.current_digest
   AND r.category_label=NEW.category_label AND r.purpose=NEW.purpose
   AND r.expense_date=NEW.expense_date AND r.amount_minor=NEW.amount_minor
 FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Current claim revision lacks original history' USING ERRCODE='P0919';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_claim_voucher_link_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original record; voucher_row record; payable record; debit_category text; credit_category text;
BEGIN
 SELECT status,amount_minor,version,bill_file_id,bill_file_version INTO original FROM expense_claim
 WHERE id=NEW.claim_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR original.status<>'APPROVED' THEN
  RAISE EXCEPTION 'Only approved claims may link vouchers' USING ERRCODE='P0920';
 END IF;
 PERFORM 1 FROM cg19_stored_file f JOIN cg19_upload_intent i
   ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  WHERE f.id=original.bill_file_id AND f.realm_id=NEW.root_realm_id
    AND f.claim_id=NEW.claim_id AND f.claim_version=original.version
    AND f.revision=original.bill_file_version AND f.owner_kind='CG09_CLAIM'
    AND f.revoked_at IS NULL AND f.scan_status='CLEAN_VERIFIED'
    AND i.owner_kind='CG09_CLAIM' AND i.status='VALIDATED' FOR SHARE OF f,i;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Approved claim bill is no longer valid for payment' USING ERRCODE='P0920';
 END IF;
 SELECT v.id,v.status,v.voucher_type,v.total_minor,v.debit_account_id,
   v.credit_account_id,v.expense_claim_id,v.expense_claim_version,p.journal_id
   INTO voucher_row FROM finance_voucher v JOIN finance_voucher_posting p
   ON p.voucher_id=v.id AND p.root_realm_id=v.root_realm_id
 WHERE v.id=NEW.voucher_id AND v.root_realm_id=NEW.root_realm_id
 FOR SHARE OF v,p;
 IF NOT FOUND OR voucher_row.status<>'POSTED' OR
    voucher_row.expense_claim_id IS DISTINCT FROM NEW.claim_id OR
    voucher_row.expense_claim_version<>original.version OR
    voucher_row.total_minor<>original.amount_minor OR
    voucher_row.journal_id IS DISTINCT FROM NEW.ledger_journal_id THEN
   RAISE EXCEPTION 'The original verified claim voucher is not eligible' USING ERRCODE='P0920';
 END IF;
 IF NEW.link_kind='PAYABLE' THEN
  SELECT g.category INTO debit_category FROM finance_account a
   JOIN account_group g ON g.id=a.group_id AND g.root_realm_id=a.root_realm_id
   WHERE a.id=voucher_row.debit_account_id AND a.root_realm_id=NEW.root_realm_id;
  SELECT g.category INTO credit_category FROM finance_account a
   JOIN account_group g ON g.id=a.group_id AND g.root_realm_id=a.root_realm_id
   WHERE a.id=voucher_row.credit_account_id AND a.root_realm_id=NEW.root_realm_id;
  IF voucher_row.voucher_type<>'EXPENSE' OR
     debit_category<>'EXPENSE' OR credit_category<>'LIABILITY' THEN
   RAISE EXCEPTION 'Payable must be one posted expense to liability' USING ERRCODE='P0920';
  END IF;
 ELSE
  SELECT v.credit_account_id INTO payable FROM expense_claim_voucher_link l
   JOIN finance_voucher v ON v.id=l.voucher_id AND v.root_realm_id=l.root_realm_id
   WHERE l.claim_id=NEW.claim_id AND l.root_realm_id=NEW.root_realm_id
     AND l.link_kind='PAYABLE' FOR SHARE OF l,v;
  IF NOT FOUND OR voucher_row.voucher_type<>'PAYMENT'
    OR voucher_row.debit_account_id IS DISTINCT FROM payable.credit_account_id THEN
   RAISE EXCEPTION 'Payout must clear the original posted claim liability' USING ERRCODE='P0920';
  END IF;
  PERFORM 1 FROM finance_voucher_payment_verification
   WHERE root_realm_id=NEW.root_realm_id AND voucher_id=NEW.voucher_id
    AND status='VERIFIED' FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Payout requires separately verified real money' USING ERRCODE='P0920';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_csr_budget_effect_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; e record; received numeric; allocated numeric; utilized numeric;
BEGIN
 SELECT id,root_realm_id,status,version,branch_ref,project_ref,csr_partner_id,
 csr_requested_minor,foundation_requested_minor INTO p
 FROM csr_funding_proposal
 WHERE id=NEW.funding_proposal_id AND root_realm_id=NEW.root_realm_id FOR UPDATE;
 IF NOT FOUND OR p.status<>'APPROVED' OR p.version<>NEW.approved_source_version
  OR (NEW.party_kind='CSR' AND p.csr_partner_id IS NULL) THEN
  RAISE EXCEPTION 'Current approved original funding commitment required' USING ERRCODE='P3410';
 END IF;
 SELECT ev.id,ev.kind,ev.amount_minor,ev.budget_id,ev.source_journal_id,
   bud.branch_id,bud.project_ref,bud.status AS budget_status INTO e
 FROM finance_budget_event ev JOIN finance_budget bud
  ON bud.id=ev.budget_id AND bud.root_realm_id=ev.root_realm_id
 WHERE ev.id=NEW.budget_event_id AND ev.root_realm_id=NEW.root_realm_id
 FOR SHARE OF ev,bud;
 IF NOT FOUND OR e.kind NOT IN('ALLOCATE','UTILIZE','DEALLOCATE') OR e.budget_status<>'APPROVED'
  OR e.branch_id IS DISTINCT FROM p.branch_ref
  OR e.project_ref IS DISTINCT FROM p.project_ref THEN
  RAISE EXCEPTION 'Original approved project/category budget effect required' USING ERRCODE='P3410';
 END IF;
 SELECT COALESCE(sum(rec.posted_amount_minor),0) INTO received
 FROM finance_csr_verified_receipt_link link
 JOIN finance_bank_reconciliation rec
  ON rec.id=link.reconciliation_id AND rec.root_realm_id=link.root_realm_id
  AND rec.status='VERIFIED' AND rec.variance_minor=0
 JOIN journal j ON j.id=rec.journal_id AND j.root_realm_id=rec.root_realm_id
 JOIN finance_reconciliation_decision d ON d.root_realm_id=rec.root_realm_id
  AND d.reconciliation_id=rec.id AND d.action='VERIFY'
 JOIN cg19_stored_file f ON f.id=d.statement_file_id AND f.realm_id=d.root_realm_id
  AND f.reconciliation_id=d.reconciliation_id AND f.revision=d.statement_file_version
  AND f.owner_kind='CG09_BANK_STATEMENT' AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
 JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  AND i.reconciliation_id=rec.id AND i.owner_kind='CG09_BANK_STATEMENT' AND i.status='VALIDATED'
 WHERE link.root_realm_id=NEW.root_realm_id AND link.funding_proposal_id=NEW.funding_proposal_id
  AND link.party_kind=NEW.party_kind AND link.remitter_attested
  AND NOT EXISTS(SELECT 1 FROM journal reversal
   WHERE reversal.root_realm_id=j.root_realm_id AND reversal.reversal_of_id=j.id
    AND reversal.posting_kind='REVERSAL');
 SELECT COALESCE(sum(ev.amount_minor) FILTER (WHERE ev.kind='ALLOCATE'),0),
        COALESCE(sum(ev.amount_minor) FILTER (WHERE ev.kind='UTILIZE'),0)
  INTO allocated,utilized
 FROM finance_csr_budget_effect link JOIN finance_budget_event ev
  ON ev.id=link.budget_event_id AND ev.root_realm_id=link.root_realm_id
 WHERE link.root_realm_id=NEW.root_realm_id AND link.funding_proposal_id=NEW.funding_proposal_id
  AND link.party_kind=NEW.party_kind AND ev.budget_id=e.budget_id
  AND (ev.kind='ALLOCATE' OR NOT EXISTS(SELECT 1 FROM journal reversal
    WHERE reversal.root_realm_id=ev.root_realm_id AND reversal.reversal_of_id=ev.source_journal_id
     AND reversal.posting_kind='REVERSAL'));
 IF e.kind='DEALLOCATE' THEN
  IF NEW.correction_of_event_id IS NULL THEN
   RAISE EXCEPTION 'Select the original CG09 allocation to correct' USING ERRCODE='P3410';
  END IF;
  DECLARE original_allocation record; corrected numeric; net_allocated numeric;
   net_utilized numeric;
  BEGIN
   SELECT original.id,original.amount_minor,original.budget_id
    INTO original_allocation FROM finance_budget_event original
    JOIN finance_csr_budget_effect original_link
     ON original_link.budget_event_id=original.id
     AND original_link.root_realm_id=original.root_realm_id
    WHERE original.id=NEW.correction_of_event_id
     AND original.root_realm_id=NEW.root_realm_id AND original.kind='ALLOCATE'
     AND original.budget_id=e.budget_id
     AND original_link.funding_proposal_id=NEW.funding_proposal_id
     AND original_link.party_kind=NEW.party_kind FOR SHARE OF original,original_link;
   IF NOT FOUND THEN RAISE EXCEPTION 'Original allocation is not from this funding share'
     USING ERRCODE='P3410'; END IF;
   SELECT COALESCE(sum(ce.amount_minor),0) INTO corrected
   FROM finance_csr_budget_effect correction
   JOIN finance_budget_event ce ON ce.id=correction.budget_event_id
    AND ce.root_realm_id=correction.root_realm_id AND ce.kind='DEALLOCATE'
   WHERE correction.root_realm_id=NEW.root_realm_id
    AND correction.correction_of_event_id=NEW.correction_of_event_id;
   IF corrected+e.amount_minor>original_allocation.amount_minor THEN
    RAISE EXCEPTION 'Cannot correct more than this original allocation'
     USING ERRCODE='P3410';
   END IF;
   SELECT COALESCE(sum(CASE WHEN event.kind='ALLOCATE' THEN event.amount_minor
    WHEN event.kind='DEALLOCATE' THEN -event.amount_minor ELSE 0 END),0),
    COALESCE(sum(CASE WHEN event.kind='UTILIZE' AND NOT EXISTS(
     SELECT 1 FROM journal reversal WHERE reversal.root_realm_id=event.root_realm_id
      AND reversal.reversal_of_id=event.source_journal_id
      AND reversal.posting_kind='REVERSAL') THEN event.amount_minor ELSE 0 END),0)
    INTO net_allocated,net_utilized
   FROM finance_csr_budget_effect linked
   JOIN finance_budget_event event ON event.id=linked.budget_event_id
    AND event.root_realm_id=linked.root_realm_id
   WHERE linked.root_realm_id=NEW.root_realm_id
    AND linked.funding_proposal_id=NEW.funding_proposal_id
    AND linked.party_kind=NEW.party_kind AND event.budget_id=e.budget_id;
   IF net_allocated-e.amount_minor<net_utilized THEN
    RAISE EXCEPTION 'Only unspent original allocation can be corrected'
     USING ERRCODE='P3410';
   END IF;
  END;
 ELSIF e.kind='ALLOCATE' THEN
  IF NEW.correction_of_event_id IS NOT NULL THEN
   RAISE EXCEPTION 'Only a deallocation can reference an original allocation'
    USING ERRCODE='P3410';
  END IF;
  -- Sum across all budgets for this party before comparing against bank cash.
  SELECT COALESCE(sum(CASE ev.kind WHEN 'ALLOCATE' THEN ev.amount_minor
   WHEN 'DEALLOCATE' THEN -ev.amount_minor ELSE 0 END),0) INTO allocated
  FROM finance_csr_budget_effect link JOIN finance_budget_event ev
   ON ev.id=link.budget_event_id AND ev.root_realm_id=link.root_realm_id
  WHERE link.root_realm_id=NEW.root_realm_id AND link.funding_proposal_id=NEW.funding_proposal_id
   AND link.party_kind=NEW.party_kind AND ev.kind IN('ALLOCATE','DEALLOCATE');
  IF allocated+e.amount_minor>received THEN
   RAISE EXCEPTION 'CSR budget allocation exceeds currently verified original bank receipts' USING ERRCODE='P3410';
  END IF;
 ELSE
  IF NEW.correction_of_event_id IS NOT NULL THEN
   RAISE EXCEPTION 'Only a deallocation can reference an original allocation' USING ERRCODE='P3410';
  END IF;
  -- Compare to net same-budget allocation (allocation less all prior corrections).
  SELECT COALESCE(sum(CASE WHEN ev.kind='ALLOCATE' THEN ev.amount_minor
   WHEN ev.kind='DEALLOCATE' THEN -ev.amount_minor ELSE 0 END),0)
   INTO allocated
  FROM finance_csr_budget_effect link JOIN finance_budget_event ev
   ON ev.id=link.budget_event_id AND ev.root_realm_id=link.root_realm_id
  WHERE link.root_realm_id=NEW.root_realm_id AND link.funding_proposal_id=NEW.funding_proposal_id
   AND link.party_kind=NEW.party_kind AND ev.budget_id=e.budget_id;
  IF utilized+e.amount_minor>allocated THEN
   RAISE EXCEPTION 'CSR utilization exceeds same-budget attributed allocation' USING ERRCODE='P3410';
  END IF;
  IF EXISTS(SELECT 1 FROM journal reversal WHERE root_realm_id=NEW.root_realm_id
   AND reversal_of_id=e.source_journal_id AND posting_kind='REVERSAL') THEN
   RAISE EXCEPTION 'Reversed CG09 expense cannot be utilized' USING ERRCODE='P3410';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_current_project_finance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; change_binding boolean; entering_effect boolean;
BEGIN
 IF TG_OP='INSERT' THEN
  change_binding:=NEW.project_ref IS NOT NULL;
  entering_effect:=false;
 ELSE
  change_binding:=NEW.project_ref IS DISTINCT FROM OLD.project_ref OR NEW.project_label IS DISTINCT FROM OLD.project_label;
  IF change_binding AND OLD.status NOT IN('DRAFT','RETURNED') THEN
   RAISE EXCEPTION 'Approved project finance source is immutable' USING ERRCODE='P0924';
  END IF;
  entering_effect:=NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN('SUBMITTED','APPROVED','POSTED');
 END IF;
 IF NEW.project_ref IS NULL THEN RETURN NEW; END IF;
 IF NOT change_binding AND NOT entering_effect THEN
  IF TG_OP='UPDATE' AND NEW.branch_id IS NOT DISTINCT FROM OLD.branch_id THEN RETURN NEW; END IF;
 END IF;
 SELECT branch_ref,code_norm,title,status INTO p FROM project
  WHERE root_realm_id=NEW.root_realm_id AND id=NEW.project_ref FOR SHARE;
 IF NOT FOUND OR p.branch_ref IS DISTINCT FROM NEW.branch_id OR p.status NOT IN('PLANNED','ACTIVE','ON_HOLD') THEN
  RAISE EXCEPTION 'Choose an eligible current project in the same finance branch' USING ERRCODE='P0924';
 END IF;
 IF change_binding AND NEW.project_label IS DISTINCT FROM p.code_norm||' · '||p.title THEN
  RAISE EXCEPTION 'The project label must be read from the original source' USING ERRCODE='P0924';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg09_deallocation_has_csr_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM finance_csr_budget_effect link
  WHERE link.root_realm_id=NEW.root_realm_id
   AND link.budget_event_id=NEW.id
   AND link.correction_of_event_id IS NOT NULL
 ) THEN
  RAISE EXCEPTION 'A deallocation requires same-transaction original CSR provenance'
   USING ERRCODE='P3410';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_account_category()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE group_category text; expected_side text;
BEGIN
 SELECT category INTO group_category FROM account_group
  WHERE id=NEW.group_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF group_category IS NULL THEN
  RAISE EXCEPTION 'Finance group is unavailable' USING ERRCODE='P0908'; END IF;
 expected_side:=CASE WHEN group_category IN('ASSET','EXPENSE') THEN 'DEBIT' ELSE 'CREDIT' END;
 IF NEW.normal_side<>expected_side OR
  (NEW.account_kind IN('CASH','BANK') AND group_category<>'ASSET') THEN
  RAISE EXCEPTION 'Invalid finance account category and balance side' USING ERRCODE='P0905'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR
    NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
    NEW.name IS DISTINCT FROM OLD.name OR
    NEW.group_id IS DISTINCT FROM OLD.group_id OR
    NEW.code IS DISTINCT FROM OLD.code OR
    NEW.normal_side IS DISTINCT FROM OLD.normal_side OR
    NEW.account_kind IS DISTINCT FROM OLD.account_kind OR
    NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR
    NEW.branch_id IS DISTINCT FROM OLD.branch_id OR
    NEW.created_by IS DISTINCT FROM OLD.created_by OR
    NEW.created_at IS DISTINCT FROM OLD.created_at OR
    NEW.version<>OLD.version+1 OR
    NEW.status IS NOT DISTINCT FROM OLD.status THEN
   RAISE EXCEPTION 'Account identity cannot change during a status update' USING ERRCODE='P0907';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_csr_verified_receipt_link()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE f record; r record; used numeric; cap numeric; eligible integer;
BEGIN
 SELECT status,version,branch_ref,csr_partner_id,
  csr_requested_minor,foundation_requested_minor INTO f
 FROM csr_funding_proposal
 WHERE id=NEW.funding_proposal_id AND root_realm_id=NEW.root_realm_id
 FOR UPDATE;
 IF NOT FOUND OR f.status<>'APPROVED' OR f.version<>NEW.approved_source_version THEN
  RAISE EXCEPTION 'Independently approved original CSR commitment required' USING ERRCODE='P3409';
 END IF;
 IF NEW.party_kind='CSR' AND f.csr_partner_id IS NULL THEN
  RAISE EXCEPTION 'Original approved CSR partner required' USING ERRCODE='P3409';
 END IF;
 PERFORM 1 FROM cg03_case c JOIN cg03_case_decision d
  ON d.case_id=c.id AND d.realm_id=c.realm_id
 WHERE c.realm_id=NEW.root_realm_id AND c.csr_funding_proposal_id=NEW.funding_proposal_id
  AND c.case_kind='CSR_FUNDING_REVIEW' AND c.status='OWNER_COMPLETED'
  AND c.csr_funding_source_version+2=f.version
  AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL
  AND d.actor_id<>c.proposer_id FOR SHARE OF c,d;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Original independently approved funding review missing' USING ERRCODE='P3409';
 END IF;
 SELECT rec.id,rec.bank_account_id,rec.journal_id,rec.posted_amount_minor,
  rec.statement_amount_minor,rec.variance_minor,j.posting_kind,
  j.source_ref,j.immutable_source_event_key,j.financial_year_id
 INTO r
 FROM finance_bank_reconciliation rec
 JOIN finance_reconciliation_decision d ON d.root_realm_id=rec.root_realm_id
  AND d.reconciliation_id=rec.id AND d.actor_ref=rec.verified_by
  AND d.action='VERIFY' AND d.password_verified_at IS NOT NULL
 JOIN cg19_stored_file evidence
  ON evidence.id=d.statement_file_id AND evidence.realm_id=d.root_realm_id
  AND evidence.reconciliation_id=d.reconciliation_id
  AND evidence.revision=d.statement_file_version
  AND evidence.owner_kind='CG09_BANK_STATEMENT'
  AND evidence.scan_status='CLEAN_VERIFIED' AND evidence.revoked_at IS NULL
 JOIN cg19_upload_intent intent ON intent.id=evidence.upload_intent_id
  AND intent.realm_id=evidence.realm_id AND intent.reconciliation_id=rec.id
  AND intent.owner_kind='CG09_BANK_STATEMENT' AND intent.status='VALIDATED'
 JOIN journal j ON j.id=rec.journal_id AND j.root_realm_id=rec.root_realm_id
  AND j.status='POSTED' AND j.posting_kind='GENERAL'
 JOIN finance_command command ON command.root_realm_id=j.root_realm_id
  AND command.command_kind='GENERAL_POST'
  AND command.request_key=j.immutable_source_event_key
  AND command.entity_ref=j.id AND j.source_ref=command.request_key
 JOIN financial_year yr ON yr.id=j.financial_year_id
  AND yr.root_realm_id=j.root_realm_id AND yr.status='OPEN'
 WHERE rec.root_realm_id=NEW.root_realm_id AND rec.id=NEW.reconciliation_id
  AND rec.status='VERIFIED' AND rec.variance_minor=0
  AND rec.statement_amount_minor=rec.posted_amount_minor
  AND rec.posted_amount_minor>0
  AND NOT EXISTS(SELECT 1 FROM journal reversal WHERE
   reversal.root_realm_id=j.root_realm_id
   AND reversal.reversal_of_id=j.id AND reversal.posting_kind='REVERSAL')
  AND NOT EXISTS(SELECT 1 FROM finance_invoice_receipt invoice
   WHERE invoice.root_realm_id=rec.root_realm_id AND invoice.reconciliation_id=rec.id)
  AND NOT EXISTS(SELECT 1 FROM donation_bank_collection bank_donation
   WHERE bank_donation.root_realm_id=rec.root_realm_id AND bank_donation.reconciliation_id=rec.id)
  AND NOT EXISTS(SELECT 1 FROM finance_membership_collection member
   WHERE member.root_realm_id=rec.root_realm_id AND member.journal_id=rec.journal_id)
 FOR SHARE OF rec,d,evidence,intent,j,command,yr;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Current original verified bank deposit is unavailable' USING ERRCODE='P3409';
 END IF;
 -- Require precisely one debit to the independently reconciled BANK asset
 -- and precisely one credit to an actual INCOME/FUND account, both in the
 -- agreed original branch. Never infer a payer from a journal description.
 SELECT count(*)::integer INTO eligible FROM journal_line l
 JOIN finance_account a ON a.root_realm_id=l.root_realm_id AND a.id=l.account_id
 JOIN account_group g ON g.root_realm_id=a.root_realm_id AND g.id=a.group_id
 WHERE l.root_realm_id=NEW.root_realm_id AND l.journal_id=r.journal_id
  AND l.branch_id IS NOT DISTINCT FROM f.branch_ref
  AND (
   (l.account_id=r.bank_account_id AND a.account_kind='BANK'
    AND g.category='ASSET' AND l.debit_minor=r.posted_amount_minor AND l.credit_minor=0)
   OR (l.account_id<>r.bank_account_id AND g.category IN('INCOME','FUND')
    AND l.credit_minor=r.posted_amount_minor AND l.debit_minor=0)
  );
 IF eligible<>2 OR (SELECT count(*) FROM journal_line
    WHERE root_realm_id=NEW.root_realm_id AND journal_id=r.journal_id)<>2 THEN
  RAISE EXCEPTION 'Bank deposit must credit the original funding/income account' USING ERRCODE='P3409';
 END IF;
 cap=CASE NEW.party_kind WHEN 'CSR' THEN f.csr_requested_minor
  ELSE f.foundation_requested_minor END;
 SELECT COALESCE(sum(rec.posted_amount_minor),0) INTO used
 FROM finance_csr_verified_receipt_link linked
 JOIN finance_bank_reconciliation rec
  ON rec.root_realm_id=linked.root_realm_id AND rec.id=linked.reconciliation_id
 JOIN journal original ON original.id=rec.journal_id
  AND original.root_realm_id=rec.root_realm_id
 WHERE linked.root_realm_id=NEW.root_realm_id
  AND linked.funding_proposal_id=NEW.funding_proposal_id
  AND linked.party_kind=NEW.party_kind
  AND NOT EXISTS(SELECT 1 FROM journal reversal
   WHERE reversal.root_realm_id=original.root_realm_id
    AND reversal.reversal_of_id=original.id AND reversal.posting_kind='REVERSAL');
 IF used+r.posted_amount_minor>cap THEN
  RAISE EXCEPTION 'Verified bank receipts exceed original approved funding share' USING ERRCODE='P3409';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_finance_command()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.actor_ref IS DISTINCT FROM OLD.actor_ref
  OR NEW.command_kind IS DISTINCT FROM OLD.command_kind
  OR NEW.request_key IS DISTINCT FROM OLD.request_key
  OR NEW.payload_digest IS DISTINCT FROM OLD.payload_digest
  OR NEW.created_at IS DISTINCT FROM OLD.created_at
  OR OLD.entity_ref IS NOT NULL OR NEW.entity_ref IS NULL THEN
  RAISE EXCEPTION 'Finance command cannot be rewritten' USING ERRCODE='P0907';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_group_structure()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_category text;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR
    NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
    NEW.category IS DISTINCT FROM OLD.category OR
    NEW.code IS DISTINCT FROM OLD.code OR
    NEW.parent_id IS DISTINCT FROM OLD.parent_id THEN
   RAISE EXCEPTION 'Financial account group hierarchy is immutable' USING ERRCODE='P0908';
  END IF;
 END IF;
 IF NEW.parent_id IS NOT NULL THEN
  SELECT category INTO parent_category FROM account_group
    WHERE id=NEW.parent_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
  IF parent_category IS NULL OR parent_category<>NEW.category THEN
   RAISE EXCEPTION 'Financial group must use its parent category' USING ERRCODE='P0908'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_payroll_destination_verification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE pinned char(64);
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.payroll_destination_fingerprint IS NOT NULL OR NEW.payroll_failure_verified THEN RAISE EXCEPTION 'Independent review required' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM finance_voucher_payment_verification p WHERE p.root_realm_id=NEW.root_realm_id AND p.voucher_id=NEW.voucher_id AND p.payroll_failure_verified) THEN RAISE EXCEPTION 'Original failed transfer is terminal' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 SELECT i.destination_fingerprint INTO pinned FROM payroll_payout_attempt t
 JOIN payroll_batch_item i ON i.root_realm_id=t.root_realm_id AND i.id=t.item_ref
 JOIN payroll_batch b ON b.root_realm_id=i.root_realm_id AND b.id=i.batch_ref AND b.method='BANK'
 WHERE t.root_realm_id=NEW.root_realm_id AND t.voucher_ref=NEW.voucher_id;
 IF NEW.payroll_failure_verified AND (NEW.status<>'REJECTED' OR pinned IS NULL OR NEW.method<>'BANK_STATEMENT') THEN RAISE EXCEPTION 'Verified original failed bank transfer required' USING ERRCODE='23514'; END IF;
 IF (NEW.status='VERIFIED' OR NEW.payroll_failure_verified) AND pinned IS NOT NULL THEN
  IF NEW.payroll_destination_fingerprint IS DISTINCT FROM pinned THEN RAISE EXCEPTION 'Original recipient proof required' USING ERRCODE='23514'; END IF;
 ELSIF NEW.payroll_destination_fingerprint IS NOT NULL THEN
  RAISE EXCEPTION 'Unexpected payroll recipient proof' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_posted_invoice_cancel()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE inv record; original record; reversing record; mismatch integer;
BEGIN
 SELECT status,version,created_by INTO inv
 FROM finance_invoice WHERE id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 SELECT p.journal_id,j.posting_kind,j.status,j.financial_year_id,
  j.immutable_payload_digest INTO original
 FROM finance_invoice_posting p JOIN journal j
  ON j.id=p.journal_id AND j.root_realm_id=p.root_realm_id
 WHERE p.invoice_id=NEW.invoice_id AND p.root_realm_id=NEW.root_realm_id
 FOR SHARE OF p,j;
 SELECT reversal_of_id,source_ref,posting_kind,status,created_by INTO reversing
 FROM journal WHERE id=NEW.reversal_journal_id AND root_realm_id=NEW.root_realm_id
 FOR SHARE;
 IF inv.status IS DISTINCT FROM 'POSTED' OR inv.version<>NEW.invoice_version
  OR inv.created_by=NEW.reviewer_id
  OR original.journal_id IS DISTINCT FROM NEW.original_journal_id
  OR original.posting_kind<>'INVOICE' OR original.status<>'POSTED'
  OR reversing.reversal_of_id IS DISTINCT FROM original.journal_id
  OR reversing.source_ref IS DISTINCT FROM NEW.invoice_id
  OR reversing.posting_kind<>'REVERSAL' OR reversing.status<>'POSTED'
  OR reversing.created_by<>NEW.reviewer_id
  OR NEW.password_verified_at>NEW.cancelled_at+interval '1 minute'
  OR NEW.password_verified_at<NEW.cancelled_at-interval '5 minutes' THEN
  RAISE EXCEPTION 'Independent protected reversal of an original posted invoice is required'
   USING ERRCODE='P0930';
 END IF;
 -- No issue request (including provider UNKNOWN) and no bank collection.
 -- A partially paid, issued or undetermined invoice cannot be silently voided.
 PERFORM 1 FROM cg19_finance_invoice_document d
  WHERE d.root_realm_id=NEW.root_realm_id AND d.invoice_id=NEW.invoice_id FOR SHARE;
 IF FOUND THEN
  RAISE EXCEPTION 'Original invoice issue process already exists' USING ERRCODE='P0930';
 END IF;
 PERFORM 1 FROM journal j WHERE j.root_realm_id=NEW.root_realm_id
  AND j.source_ref=NEW.invoice_id AND j.posting_kind='GENERAL' AND j.status='POSTED'
  FOR SHARE;
 IF FOUND THEN
  RAISE EXCEPTION 'Original invoice bank collection already recorded' USING ERRCODE='P0930';
 END IF;
 PERFORM 1 FROM finance_invoice_receipt r
  WHERE r.root_realm_id=NEW.root_realm_id AND r.invoice_id=NEW.invoice_id FOR SHARE;
 IF FOUND THEN
  RAISE EXCEPTION 'Original paid receipts cannot be cancelled as an unissued invoice'
   USING ERRCODE='P0930';
 END IF;
 WITH prior AS (
  SELECT account_id,branch_id,COUNT(*) AS n,
   SUM(debit_minor) AS dr,SUM(credit_minor) AS cr
  FROM journal_line WHERE root_realm_id=NEW.root_realm_id AND journal_id=NEW.original_journal_id
  GROUP BY account_id,branch_id
 ), after AS (
  SELECT account_id,branch_id,COUNT(*) AS n,
   SUM(debit_minor) AS dr,SUM(credit_minor) AS cr
  FROM journal_line WHERE root_realm_id=NEW.root_realm_id AND journal_id=NEW.reversal_journal_id
  GROUP BY account_id,branch_id
 )
 SELECT COUNT(*) INTO mismatch FROM prior p FULL OUTER JOIN after a
  ON a.account_id=p.account_id
  AND a.branch_id IS NOT DISTINCT FROM p.branch_id
 WHERE p.account_id IS NULL OR a.account_id IS NULL OR p.n<>a.n
  OR p.dr<>a.cr OR p.cr<>a.dr;
 IF mismatch<>0 THEN
  RAISE EXCEPTION 'Cancellation must offset every original invoice accounting line'
   USING ERRCODE='P0930';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_posting_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_status text; v_scope text; v_branch uuid;
BEGIN
 SELECT a.status,a.scope_kind,a.branch_id INTO v_status,v_scope,v_branch
  FROM finance_account a WHERE a.id=NEW.account_id
   AND a.root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR v_status<>'ACTIVE' THEN
  RAISE EXCEPTION 'Finance posting account is unavailable' USING ERRCODE='P0902';
 END IF;
 IF v_scope='BRANCH' AND v_branch IS DISTINCT FROM NEW.branch_id THEN
  RAISE EXCEPTION 'Finance posting account is in another branch' USING ERRCODE='P0904';
 END IF;
 IF NEW.branch_id IS NOT NULL THEN
  PERFORM 1 FROM branch b
   WHERE b.id=NEW.branch_id AND b.root_realm_id=NEW.root_realm_id
    AND b.status='ACTIVE' FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Finance posting branch is not active' USING ERRCODE='P0904';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_posting_period()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_start date; v_end date; v_status text;
BEGIN
 SELECT fy.start_on,fy.end_on,fy.status INTO v_start,v_end,v_status
  FROM financial_year fy
  WHERE fy.id=NEW.financial_year_id AND fy.root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR v_status<>'OPEN' THEN
  RAISE EXCEPTION 'Finance posting period is not open' USING ERRCODE='P0901';
 END IF;
 IF NEW.posting_date<v_start OR NEW.posting_date>v_end THEN
  RAISE EXCEPTION 'Finance posting date is outside selected year' USING ERRCODE='P0911';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_refund_statement_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE bank journal%ROWTYPE; requested record;
BEGIN
 SELECT * INTO bank FROM journal
  WHERE id=NEW.journal_id AND root_realm_id=NEW.root_realm_id;
 IF NOT FOUND OR bank.posting_kind<>'REFUND' THEN RETURN NEW; END IF;
 -- Match a real CG04 outbound transfer to the exact originally collected
 -- bank account and amount, preserving the CG09 original invoice branch below.
 SELECT c.bank_account_id,r.amount_minor,p.transfer_reference INTO requested
 FROM finance_membership_refund_posting p
 JOIN finance_membership_refund_request r ON r.root_realm_id=p.root_realm_id AND r.application_id=p.application_id
 JOIN finance_membership_collection c ON c.root_realm_id=r.root_realm_id AND c.application_id=r.application_id
 WHERE p.root_realm_id=NEW.root_realm_id AND p.journal_id=NEW.journal_id AND p.application_id=bank.source_ref FOR SHARE OF p,r,c;
 IF FOUND THEN
  IF NEW.bank_account_id IS DISTINCT FROM requested.bank_account_id
   OR NEW.bank_item_ref IS DISTINCT FROM requested.transfer_reference
   OR NEW.statement_amount_minor IS DISTINCT FROM -requested.amount_minor
   OR NEW.posted_amount_minor IS DISTINCT FROM -requested.amount_minor THEN
   RAISE EXCEPTION 'Match the actual outbound membership refund bank reference and amount'
    USING ERRCODE='P0932';
  END IF;
  RETURN NEW;
 END IF;
 SELECT r.bank_account_id,r.amount_minor,r.transfer_reference,r.status
  INTO requested FROM finance_invoice_refund r
  WHERE r.id=bank.source_ref AND r.root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR requested.status<>'BANK_POSTED' OR
    NEW.bank_account_id IS DISTINCT FROM requested.bank_account_id OR
    NEW.bank_item_ref IS DISTINCT FROM requested.transfer_reference OR
    NEW.statement_amount_minor IS DISTINCT FROM -requested.amount_minor OR
    NEW.posted_amount_minor IS DISTINCT FROM -requested.amount_minor THEN
  RAISE EXCEPTION 'Use the actual matching outbound refund transfer reference'
   USING ERRCODE='P0932';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_reissue_link()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original record; replacement record; credit record;
BEGIN
 SELECT id,status,branch_id INTO original FROM finance_invoice
  WHERE root_realm_id=NEW.root_realm_id AND id=NEW.original_invoice_id
  FOR UPDATE;
 SELECT id,status,branch_id,created_by INTO replacement FROM finance_invoice
  WHERE root_realm_id=NEW.root_realm_id AND id=NEW.replacement_invoice_id
  FOR SHARE;
 SELECT id,invoice_id INTO credit FROM finance_invoice_credit_note
  WHERE id=NEW.original_credit_note_id AND root_realm_id=NEW.root_realm_id
  FOR SHARE;
 IF original.id IS NULL OR replacement.id IS NULL OR credit.id IS NULL
  OR original.status<>'ISSUED' OR replacement.status<>'SUBMITTED'
  OR credit.invoice_id IS DISTINCT FROM NEW.original_invoice_id
  OR replacement.branch_id IS DISTINCT FROM original.branch_id
  OR replacement.created_by IS DISTINCT FROM NEW.recorded_by THEN
  RAISE EXCEPTION 'Replacement must be a current staged invoice for a credited source'
    USING ERRCODE='P0933';
 END IF;
 IF EXISTS (
  SELECT 1 FROM finance_invoice_reissue_link l
   JOIN finance_invoice other ON other.id=l.replacement_invoice_id
     AND other.root_realm_id=l.root_realm_id
  WHERE l.root_realm_id=NEW.root_realm_id
    AND l.original_invoice_id=NEW.original_invoice_id
    AND other.status<>'REJECTED'
 ) THEN
  RAISE EXCEPTION 'An active replacement already exists for this credit note'
   USING ERRCODE='P0933';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_voucher_draft()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE y record;case_state text;
BEGIN
 SELECT fy.start_on,fy.end_on,fy.status INTO y FROM financial_year fy
 WHERE fy.id=NEW.financial_year_id AND fy.root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Financial year is not available' USING ERRCODE='P0901';
 END IF;
 IF NEW.posting_date<y.start_on OR NEW.posting_date>y.end_on THEN
  RAISE EXCEPTION 'Voucher date is outside financial year' USING ERRCODE='P0911';
 END IF;
 IF NEW.branch_id IS NOT NULL THEN
  PERFORM 1 FROM branch
   WHERE id=NEW.branch_id AND root_realm_id=NEW.root_realm_id AND status='ACTIVE' FOR SHARE;
  IF NOT FOUND AND NEW.status IN('DRAFT','SUBMITTED','APPROVED','PAYMENT_REQUESTED') THEN
   RAISE EXCEPTION 'Voucher branch is not active' USING ERRCODE='P0904';
  END IF;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR y.status<>'OPEN' THEN
   RAISE EXCEPTION 'New voucher must be a draft in an open year' USING ERRCODE='P0901';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.voucher_number IS DISTINCT FROM OLD.voucher_number OR
    NEW.created_by IS DISTINCT FROM OLD.created_by OR
    NEW.created_at IS DISTINCT FROM OLD.created_at THEN
  RAISE EXCEPTION 'Voucher source identity is immutable' USING ERRCODE='P0907';
 END IF;
 IF (OLD.status='DRAFT' OR OLD.status='RETURNED') AND NEW.status='DRAFT' THEN
  IF y.status<>'OPEN' OR NEW.version<>OLD.version+1 OR
    NEW.approval_case_id IS NOT NULL OR NEW.proof_file_id IS NOT NULL OR
    NEW.proof_file_revision IS NOT NULL THEN
   RAISE EXCEPTION 'Draft revision or correction is not current' USING ERRCODE='P0907';
  END IF;
 ELSIF OLD.status='DRAFT' AND NEW.status='SUBMITTED' THEN
  IF y.status<>'OPEN' OR NEW.version<>OLD.version OR
   NEW.approval_case_id IS NULL OR NEW.proof_file_id IS NULL OR
   NEW.proof_file_revision IS NULL THEN
   RAISE EXCEPTION 'Submitted voucher needs real approval and evidence' USING ERRCODE='P0913';
  END IF;
  PERFORM 1 FROM cg03_case c
   JOIN cg19_stored_file f ON f.id=NEW.proof_file_id AND f.realm_id=NEW.root_realm_id
    AND f.voucher_id=NEW.id AND f.voucher_version=NEW.version
   JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
   WHERE c.id=NEW.approval_case_id AND c.realm_id=NEW.root_realm_id
    AND c.case_kind='FINANCE_VOUCHER' AND c.finance_voucher_id=NEW.id
    AND c.finance_voucher_revision=NEW.version AND
    c.finance_proof_file_id=f.id AND c.finance_proof_revision=f.revision
    AND c.status IN('SUBMITTED','IN_REVIEW') AND f.revision=NEW.proof_file_revision
    AND f.revoked_at IS NULL AND f.scan_status='CLEAN_VERIFIED'
    AND i.status='VALIDATED' FOR SHARE OF c,f,i;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Original review case or clean proof is missing' USING ERRCODE='P0913';
  END IF;
 ELSIF OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED') THEN
  IF NEW.version<>OLD.version THEN
   RAISE EXCEPTION 'Submitted voucher version is immutable' USING ERRCODE='P0907';
  END IF;
  SELECT status INTO case_state FROM cg03_case
   WHERE id=NEW.approval_case_id AND realm_id=NEW.root_realm_id
    AND finance_voucher_id=NEW.id AND finance_voucher_revision=NEW.version
    AND case_kind='FINANCE_VOUCHER' FOR SHARE;
  IF NOT FOUND OR
    (NEW.status='RETURNED' AND case_state<>'RETURNED') OR
    (NEW.status='REJECTED' AND case_state<>'REJECTED') OR
    (NEW.status='APPROVED' AND case_state NOT IN('PENDING_OWNER','OWNER_COMPLETED')) THEN
   RAISE EXCEPTION 'Committed reviewer outcome is required' USING ERRCODE='P0913';
  END IF;
  IF NEW.status='APPROVED' THEN
   PERFORM 1 FROM cg03_finance_owner_effect effect
     JOIN cg03_case_decision d ON d.id=effect.final_decision_id
   WHERE effect.case_id=NEW.approval_case_id
    AND effect.realm_id=NEW.root_realm_id
    AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL
    FOR SHARE OF effect,d;
   IF NOT FOUND THEN
    RAISE EXCEPTION 'Protected reviewer proof is unavailable' USING ERRCODE='P0913';
   END IF;
  END IF;
 ELSIF OLD.status='APPROVED' AND NEW.status='PAYMENT_REQUESTED' THEN
  IF NEW.voucher_type NOT IN('PAYMENT','CONTRA') OR y.status<>'OPEN' THEN
   RAISE EXCEPTION 'Payment request is not allowed' USING ERRCODE='P0913';
  END IF;
 ELSIF OLD.status='PAYMENT_REQUESTED' AND NEW.status='PAID_VERIFIED' THEN
  PERFORM 1 FROM finance_voucher_payment_verification p
   WHERE p.voucher_id=NEW.id AND p.root_realm_id=NEW.root_realm_id
    AND p.voucher_revision=NEW.version AND p.status='VERIFIED' FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Independent verified money source is required' USING ERRCODE='P0913';
  END IF;
 ELSIF OLD.status IN('APPROVED','PAID_VERIFIED') AND NEW.status='POSTED' THEN
  IF (OLD.status='APPROVED' AND NEW.voucher_type IN('PAYMENT','CONTRA')) OR
     (OLD.status='PAID_VERIFIED' AND NEW.voucher_type NOT IN('PAYMENT','CONTRA')) OR
     y.status<>'OPEN' THEN
   RAISE EXCEPTION 'Voucher posting requires open year and correct payment stage'
     USING ERRCODE='P0901';
  END IF;
  PERFORM 1 FROM finance_voucher_posting p JOIN journal j
     ON j.id=p.journal_id AND j.root_realm_id=p.root_realm_id
   WHERE p.voucher_id=NEW.id AND p.root_realm_id=NEW.root_realm_id
    AND p.voucher_revision=NEW.version AND p.approval_case_id=NEW.approval_case_id
    AND j.posting_kind='VOUCHER' AND j.status='POSTED'
    AND j.source_ref=NEW.id AND j.immutable_payload_digest=p.original_digest
    AND j.financial_year_id=NEW.financial_year_id AND j.posting_date=NEW.posting_date
    AND (cg11_payroll_journal_matches(NEW.root_realm_id,NEW.id,j.id) OR (NOT EXISTS(SELECT 1 FROM payroll_payout_attempt t WHERE t.root_realm_id=NEW.root_realm_id AND t.voucher_ref=NEW.id) AND (
     SELECT count(*)=2 AND COALESCE(sum(l.debit_minor),0)=NEW.total_minor
      AND COALESCE(sum(l.credit_minor),0)=NEW.total_minor
      AND count(*) FILTER (WHERE l.account_id=NEW.debit_account_id
       AND l.branch_id IS NOT DISTINCT FROM NEW.branch_id
       AND l.debit_minor=NEW.total_minor AND l.credit_minor=0)=1
      AND count(*) FILTER (WHERE l.account_id=NEW.credit_account_id
       AND l.branch_id IS NOT DISTINCT FROM NEW.branch_id
       AND l.credit_minor=NEW.total_minor AND l.debit_minor=0)=1
     FROM journal_line l WHERE l.journal_id=j.id AND l.root_realm_id=NEW.root_realm_id
    )))
   FOR SHARE OF p,j;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Balanced original journal posting is required' USING ERRCODE='P0913';
  END IF;
 ELSE
  RAISE EXCEPTION 'Voucher workflow transition not permitted' USING ERRCODE='P0907';
 END IF;
 -- Once a draft is submitted, all financial facts and source refs are immutable.
 IF OLD.status NOT IN('DRAFT','RETURNED') AND
    (NEW.financial_year_id IS DISTINCT FROM OLD.financial_year_id OR
     NEW.branch_id IS DISTINCT FROM OLD.branch_id OR
     NEW.voucher_type IS DISTINCT FROM OLD.voucher_type OR
     NEW.posting_date IS DISTINCT FROM OLD.posting_date OR
     NEW.payee_name IS DISTINCT FROM OLD.payee_name OR
     NEW.purpose IS DISTINCT FROM OLD.purpose OR
     NEW.gross_minor IS DISTINCT FROM OLD.gross_minor OR
     NEW.tax_minor IS DISTINCT FROM OLD.tax_minor OR
     NEW.charges_minor IS DISTINCT FROM OLD.charges_minor OR
     NEW.total_minor IS DISTINCT FROM OLD.total_minor OR
     NEW.debit_account_id IS DISTINCT FROM OLD.debit_account_id OR
     NEW.credit_account_id IS DISTINCT FROM OLD.credit_account_id OR
     NEW.payment_account_id IS DISTINCT FROM OLD.payment_account_id OR
     NEW.approval_case_id IS DISTINCT FROM OLD.approval_case_id OR
     NEW.proof_file_id IS DISTINCT FROM OLD.proof_file_id OR
     NEW.proof_file_revision IS DISTINCT FROM OLD.proof_file_revision OR
     NEW.version<>OLD.version) THEN
  IF NOT(OLD.status='DRAFT' AND NEW.status='SUBMITTED' AND
    NEW.financial_year_id IS NOT DISTINCT FROM OLD.financial_year_id AND
    NEW.branch_id IS NOT DISTINCT FROM OLD.branch_id AND
    NEW.voucher_type IS NOT DISTINCT FROM OLD.voucher_type AND
    NEW.posting_date IS NOT DISTINCT FROM OLD.posting_date AND
    NEW.payee_name IS NOT DISTINCT FROM OLD.payee_name AND
    NEW.purpose IS NOT DISTINCT FROM OLD.purpose AND
    NEW.gross_minor IS NOT DISTINCT FROM OLD.gross_minor AND
    NEW.tax_minor IS NOT DISTINCT FROM OLD.tax_minor AND
    NEW.charges_minor IS NOT DISTINCT FROM OLD.charges_minor AND
    NEW.total_minor IS NOT DISTINCT FROM OLD.total_minor AND
    NEW.debit_account_id IS NOT DISTINCT FROM OLD.debit_account_id AND
    NEW.credit_account_id IS NOT DISTINCT FROM OLD.credit_account_id AND
    NEW.payment_account_id IS NOT DISTINCT FROM OLD.payment_account_id AND
    NEW.version=OLD.version) THEN
   RAISE EXCEPTION 'Frozen submitted voucher facts cannot change' USING ERRCODE='P0907';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_voucher_payment_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE selected_account record;
BEGIN
 IF NEW.voucher_type IN ('PAYMENT','CONTRA') AND NEW.payment_account_id IS NULL THEN
  RAISE EXCEPTION 'Choose an active cash or bank account for this voucher'
   USING ERRCODE='P0914';
 END IF;
 IF TG_OP='UPDATE' AND OLD.status IN('SUBMITTED','APPROVED','REJECTED') AND
   NEW.payment_account_id IS DISTINCT FROM OLD.payment_account_id THEN
  RAISE EXCEPTION 'Submitted account selection is immutable'
   USING ERRCODE='P0907';
 END IF;
 IF NEW.payment_account_id IS NOT NULL AND NEW.status IN('DRAFT','SUBMITTED') THEN
  SELECT a.status,a.branch_id,a.scope_kind,c.status AS cash_status
    INTO selected_account FROM finance_account a
   JOIN cash_bank_account c ON c.account_id=a.id
    AND c.root_realm_id=a.root_realm_id
   WHERE a.id=NEW.payment_account_id AND a.root_realm_id=NEW.root_realm_id
    AND a.account_kind IN('CASH','BANK') FOR SHARE OF a,c;
  IF NOT FOUND OR selected_account.status<>'ACTIVE' OR selected_account.cash_status<>'ACTIVE'
    OR (selected_account.scope_kind='BRANCH' AND selected_account.branch_id IS DISTINCT FROM NEW.branch_id) THEN
   RAISE EXCEPTION 'Selected cash or bank account is not available in this branch'
    USING ERRCODE='P0914';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_guard_year_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id
   OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
   OR NEW.name IS DISTINCT FROM OLD.name
   OR NEW.start_on IS DISTINCT FROM OLD.start_on
   OR NEW.end_on IS DISTINCT FROM OLD.end_on
   OR NEW.created_by IS DISTINCT FROM OLD.created_by
   OR NEW.created_at IS DISTINCT FROM OLD.created_at
   OR NEW.version<>OLD.version+1
   OR NEW.status<>'CLOSED' OR OLD.status<>'OPEN'
 THEN RAISE EXCEPTION 'Financial year identity is immutable; only a reviewed close is allowed' USING ERRCODE='P0906'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_immutable_record()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Posted finance records cannot be edited' USING ERRCODE='P0912'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_invoice_draft_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE y record; a record; i record; t record; line jsonb; gross bigint:=0;
 rate bigint; qty integer; n integer;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original invoice cannot be deleted' USING ERRCODE='P0922';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>1 THEN
   RAISE EXCEPTION 'An original invoice starts in draft' USING ERRCODE='P0922';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
   OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
   OR NEW.created_by IS DISTINCT FROM OLD.created_by
   OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
  RAISE EXCEPTION 'Invoice source identity is immutable' USING ERRCODE='P0922';
 END IF;
 IF OLD.status IN('DRAFT','RETURNED') AND NEW.status='DRAFT' THEN
  IF NEW.version<>OLD.version+1 OR NEW.approval_case_id IS NOT NULL OR
    NEW.financial_year_id IS NOT NULL OR NEW.branch_id IS NOT NULL OR
    NEW.invoice_date IS NOT NULL OR NEW.due_date IS NOT NULL OR
    NEW.category_label IS NOT NULL OR NEW.purpose IS NOT NULL OR
    NEW.counterparty_name IS NOT NULL OR NEW.counterparty_address IS NOT NULL OR
    NEW.gross_minor IS NOT NULL OR NEW.tax_minor IS NOT NULL OR
    NEW.charges_minor IS NOT NULL OR NEW.total_minor IS NOT NULL OR
    NEW.receivable_account_id IS NOT NULL OR NEW.income_account_id IS NOT NULL OR
    NEW.tax_account_id IS NOT NULL THEN
   RAISE EXCEPTION 'Only a new invoice draft revision can be saved' USING ERRCODE='P0922';
  END IF;
  IF OLD.status='RETURNED' THEN
   PERFORM 1 FROM cg03_case c JOIN cg03_case_decision d
    ON d.case_id=c.id AND d.realm_id=c.realm_id
    WHERE c.id=OLD.approval_case_id AND c.realm_id=OLD.root_realm_id
     AND c.case_kind='FINANCE_INVOICE' AND c.finance_invoice_id=OLD.id
     AND c.finance_invoice_revision=OLD.version AND c.status='RETURNED'
     AND d.action='RETURN' AND d.fresh_password_verified_at IS NOT NULL
    FOR SHARE OF c,d;
   IF NOT FOUND THEN RAISE EXCEPTION 'Actual RETURN reviewer case required' USING ERRCODE='P0922'; END IF;
  END IF;
  RETURN NEW;
 ELSIF OLD.status='DRAFT' AND NEW.status='SUBMITTED' THEN
  IF NEW.version<>OLD.version OR NEW.current_digest<>OLD.current_digest OR
    NEW.draft_payload<>OLD.draft_payload OR NEW.approval_case_id IS NULL OR
    NEW.financial_year_id IS NULL OR NEW.invoice_date IS NULL OR
    NEW.due_date IS NULL OR NEW.category_label IS NULL OR
    NEW.purpose IS NULL OR NEW.counterparty_name IS NULL OR
    NEW.gross_minor IS NULL OR NEW.tax_minor IS NULL OR
    NEW.charges_minor IS NULL OR NEW.total_minor IS NULL OR
    NEW.receivable_account_id IS NULL OR NEW.income_account_id IS NULL OR
    (NEW.tax_minor>0 AND NEW.tax_account_id IS NULL) THEN
   RAISE EXCEPTION 'Complete frozen invoice required before submission' USING ERRCODE='P0922';
  END IF;
  SELECT start_on,end_on,status INTO y FROM financial_year
   WHERE id=NEW.financial_year_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
  IF NOT FOUND OR y.status<>'OPEN' OR NEW.invoice_date<y.start_on OR
     NEW.invoice_date>y.end_on OR NEW.due_date<NEW.invoice_date THEN
   RAISE EXCEPTION 'Invoice financial period is unavailable' USING ERRCODE='P0922';
  END IF;
  IF NEW.branch_id IS NOT NULL THEN
   PERFORM 1 FROM branch WHERE id=NEW.branch_id
      AND root_realm_id=NEW.root_realm_id AND status='ACTIVE' FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Inactive invoice branch' USING ERRCODE='P0922'; END IF;
  END IF;
  SELECT status,account_kind,branch_id,g.category INTO a FROM finance_account f
   JOIN account_group g ON g.id=f.group_id AND g.root_realm_id=f.root_realm_id
   WHERE f.id=NEW.receivable_account_id AND f.root_realm_id=NEW.root_realm_id
   FOR SHARE OF f,g;
  IF NOT FOUND OR a.status<>'ACTIVE' OR a.category<>'ASSET' OR a.account_kind<>'GENERAL' OR
     (a.branch_id IS NOT NULL AND a.branch_id IS DISTINCT FROM NEW.branch_id) THEN
   RAISE EXCEPTION 'Original receivable account not eligible' USING ERRCODE='P0922';
  END IF;
  SELECT status,branch_id,g.category INTO i FROM finance_account f
   JOIN account_group g ON g.id=f.group_id AND g.root_realm_id=f.root_realm_id
   WHERE f.id=NEW.income_account_id AND f.root_realm_id=NEW.root_realm_id
   FOR SHARE OF f,g;
  IF NOT FOUND OR i.status<>'ACTIVE' OR i.category<>'INCOME' OR
    (i.branch_id IS NOT NULL AND i.branch_id IS DISTINCT FROM NEW.branch_id) THEN
   RAISE EXCEPTION 'Original income account not eligible' USING ERRCODE='P0922';
  END IF;
  IF NEW.tax_minor>0 THEN
   SELECT status,branch_id,g.category INTO t FROM finance_account f
    JOIN account_group g ON g.id=f.group_id AND g.root_realm_id=f.root_realm_id
    WHERE f.id=NEW.tax_account_id AND f.root_realm_id=NEW.root_realm_id
    FOR SHARE OF f,g;
   IF NOT FOUND OR t.status<>'ACTIVE' OR t.category<>'LIABILITY' OR
     (t.branch_id IS NOT NULL AND t.branch_id IS DISTINCT FROM NEW.branch_id) THEN
    RAISE EXCEPTION 'Original tax liability account not eligible' USING ERRCODE='P0922';
   END IF;
  END IF;
  SELECT c.status INTO y FROM cg03_case c
   WHERE c.id=NEW.approval_case_id AND c.realm_id=NEW.root_realm_id
     AND c.case_kind='FINANCE_INVOICE' AND c.finance_invoice_id=NEW.id
     AND c.finance_invoice_revision=NEW.version
     AND c.finance_invoice_digest=NEW.current_digest
     AND c.status IN('SUBMITTED','IN_REVIEW') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Actual invoice reviewer case not found' USING ERRCODE='P0922'; END IF;
  -- The only submitted financial facts are those already frozen in the
  -- original trusted CG-09 draft revision; arbitrary SQL writes cannot retarget.
  IF NEW.financial_year_id::text IS DISTINCT FROM NEW.draft_payload#>>'{info,financialYearRef}' OR
     NEW.branch_id::text IS DISTINCT FROM NULLIF(NEW.draft_payload#>>'{info,branchRef}','') OR
     NEW.invoice_date::text IS DISTINCT FROM NEW.draft_payload#>>'{info,invoiceDate}' OR
     NEW.due_date::text IS DISTINCT FROM NEW.draft_payload#>>'{info,dueDate}' OR
     NEW.category_label IS DISTINCT FROM NEW.draft_payload#>>'{info,category}' OR
     NEW.purpose IS DISTINCT FROM NEW.draft_payload#>>'{info,purpose}' OR
     NEW.counterparty_name IS DISTINCT FROM NEW.draft_payload#>>'{info,counterpartyName}' OR
     NEW.counterparty_address IS DISTINCT FROM NEW.draft_payload#>>'{info,counterpartyAddress}' OR
     NEW.receivable_account_id::text IS DISTINCT FROM NEW.draft_payload#>>'{payment,receivableAccountRef}' OR
     NEW.income_account_id::text IS DISTINCT FROM NEW.draft_payload#>>'{payment,incomeAccountRef}' OR
     NEW.tax_account_id::text IS DISTINCT FROM NULLIF(NEW.draft_payload#>>'{payment,taxAccountRef}','') OR
     NEW.gross_minor::text IS DISTINCT FROM NEW.draft_payload#>>'{items,grossMinor}' OR
     NEW.tax_minor::text IS DISTINCT FROM NEW.draft_payload#>>'{items,taxMinor}' OR
     NEW.charges_minor::text IS DISTINCT FROM NEW.draft_payload#>>'{items,chargesMinor}' OR
     NEW.total_minor::text IS DISTINCT FROM NEW.draft_payload#>>'{items,totalMinor}' THEN
   RAISE EXCEPTION 'Frozen original invoice does not match submitted facts' USING ERRCODE='P0922';
  END IF;
  IF jsonb_typeof(NEW.draft_payload->'items'->'rows')<>'array' THEN
   RAISE EXCEPTION 'Original invoice items missing' USING ERRCODE='P0922';
  END IF;
  n=jsonb_array_length(NEW.draft_payload->'items'->'rows');
  IF n<1 OR n>40 THEN
   RAISE EXCEPTION 'Original invoice item count invalid' USING ERRCODE='P0922';
  END IF;
  FOR line IN SELECT value FROM jsonb_array_elements(NEW.draft_payload->'items'->'rows') LOOP
   IF jsonb_typeof(line)<>'object' OR
     COALESCE(line->>'unitRateMinor','') !~ '^[1-9][0-9]{0,13}$' OR
     COALESCE(line->>'lineTotalMinor','') !~ '^[1-9][0-9]{0,13}$' OR
     COALESCE(line->>'quantity','') !~ '^[1-9][0-9]{0,6}$' OR
     char_length(btrim(COALESCE(line->>'description',''))) NOT BETWEEN 2 AND 180 THEN
    RAISE EXCEPTION 'Invalid immutable original invoice item' USING ERRCODE='P0922';
   END IF;
   rate=(line->>'unitRateMinor')::bigint;qty=(line->>'quantity')::integer;
   IF qty>1000000 OR rate>99999999999999/qty OR rate*qty<1 OR
      rate*qty<>(line->>'lineTotalMinor')::bigint THEN
    RAISE EXCEPTION 'Original invoice line does not balance' USING ERRCODE='P0922';
   END IF;
   gross=gross+rate*qty;
  END LOOP;
  IF gross<>NEW.gross_minor OR NEW.total_minor<>NEW.gross_minor+NEW.tax_minor+NEW.charges_minor THEN
   RAISE EXCEPTION 'Invoice arithmetic does not balance' USING ERRCODE='P0922';
  END IF;
  RETURN NEW;
 ELSIF OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED') THEN
  IF (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at') THEN
   RAISE EXCEPTION 'Submitted invoice snapshot is immutable' USING ERRCODE='P0922';
  END IF;
  SELECT status INTO y FROM cg03_case c WHERE c.id=OLD.approval_case_id
    AND c.realm_id=OLD.root_realm_id AND c.case_kind='FINANCE_INVOICE'
    AND c.finance_invoice_id=OLD.id AND c.finance_invoice_revision=OLD.version FOR SHARE;
  IF NOT FOUND OR
    (NEW.status='RETURNED' AND y.status<>'RETURNED') OR
    (NEW.status='REJECTED' AND y.status<>'REJECTED') OR
    (NEW.status='APPROVED' AND y.status NOT IN('PENDING_OWNER','OWNER_COMPLETED')) THEN
   RAISE EXCEPTION 'Genuine invoice review outcome required' USING ERRCODE='P0922';
  END IF;
  IF NEW.status='APPROVED' THEN
   PERFORM 1 FROM cg03_finance_owner_effect ef
     JOIN cg03_case_decision d ON d.id=ef.final_decision_id
    WHERE ef.case_id=NEW.approval_case_id AND ef.realm_id=NEW.root_realm_id
     AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL
    FOR SHARE OF ef,d;
   IF NOT FOUND THEN RAISE EXCEPTION 'Protected invoice approval not confirmed' USING ERRCODE='P0922'; END IF;
  END IF;
  RETURN NEW;
 ELSIF OLD.status='APPROVED' AND NEW.status='POSTED' THEN
  IF (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at') THEN
   RAISE EXCEPTION 'Posted invoice cannot edit approved facts' USING ERRCODE='P0922';
  END IF;
  PERFORM 1 FROM finance_invoice_posting p JOIN journal j
   ON j.id=p.journal_id AND j.root_realm_id=p.root_realm_id
   WHERE p.invoice_id=NEW.id AND p.root_realm_id=NEW.root_realm_id
    AND p.invoice_version=NEW.version AND p.approval_case_id=NEW.approval_case_id
    AND j.source_ref=NEW.id AND j.posting_kind='INVOICE' AND j.status='POSTED'
    AND j.financial_year_id=NEW.financial_year_id
    AND j.posting_date=NEW.invoice_date
    AND j.immutable_payload_digest=p.original_digest
    AND (SELECT COALESCE(SUM(l.debit_minor),0)=NEW.total_minor
        AND COALESCE(SUM(l.credit_minor),0)=NEW.total_minor
        AND COUNT(*)=CASE WHEN NEW.tax_minor>0 THEN 3 ELSE 2 END
        AND COUNT(*) FILTER (WHERE l.account_id=NEW.receivable_account_id
          AND l.branch_id IS NOT DISTINCT FROM NEW.branch_id
          AND l.debit_minor=NEW.total_minor AND l.credit_minor=0)=1
        AND COUNT(*) FILTER (WHERE l.account_id=NEW.income_account_id
          AND l.branch_id IS NOT DISTINCT FROM NEW.branch_id
          AND l.credit_minor=NEW.gross_minor+NEW.charges_minor AND l.debit_minor=0)=1
        AND (NEW.tax_minor=0 OR COUNT(*) FILTER
          (WHERE l.account_id=NEW.tax_account_id
           AND l.branch_id IS NOT DISTINCT FROM NEW.branch_id AND l.credit_minor=NEW.tax_minor
           AND l.debit_minor=0)=1)
      FROM journal_line l WHERE l.journal_id=j.id AND l.root_realm_id=NEW.root_realm_id)
   FOR SHARE OF p,j;
  IF NOT FOUND THEN RAISE EXCEPTION 'Only balanced posted original invoice may proceed' USING ERRCODE='P0922'; END IF;
  RETURN NEW;
 ELSIF OLD.status='POSTED' AND NEW.status='ISSUED' THEN
  IF (to_jsonb(NEW)-'status'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'updated_at') THEN
   RAISE EXCEPTION 'Issued invoice cannot edit financial facts' USING ERRCODE='P0922';
  END IF;
  PERFORM 1 FROM cg19_finance_invoice_document d
   WHERE d.root_realm_id=NEW.root_realm_id AND d.invoice_id=NEW.id
     AND d.source_version=NEW.version AND d.status='ISSUED'
     AND d.object_version IS NOT NULL AND d.content_sha256 IS NOT NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Actual protected PDF must be issued first' USING ERRCODE='P0922'; END IF;
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Invoice workflow transition not permitted' USING ERRCODE='P0922';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_invoice_has_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM finance_invoice_revision r
 WHERE r.root_realm_id=NEW.root_realm_id AND r.invoice_id=NEW.id
  AND r.version=NEW.version AND r.payload_digest=NEW.current_digest
  AND r.draft_payload=NEW.draft_payload;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Original immutable invoice draft revision is missing'
   USING ERRCODE='P0921';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_member_collection_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM membership_application a JOIN membership_review_snapshot s ON s.root_realm_id=a.root_realm_id AND s.application_id=a.id
 JOIN cg03_case c ON c.realm_id=s.root_realm_id AND c.membership_review_ref=s.id AND c.case_kind='MEMBER_APPLICATION'
 JOIN journal j ON j.root_realm_id=a.root_realm_id AND j.id=NEW.journal_id
 JOIN journal_line debit ON debit.root_realm_id=j.root_realm_id AND debit.journal_id=j.id AND debit.account_id=NEW.bank_account_id
 JOIN journal_line credit ON credit.root_realm_id=j.root_realm_id AND credit.journal_id=j.id AND credit.account_id=NEW.income_account_id
 JOIN finance_account bank ON bank.root_realm_id=j.root_realm_id AND bank.id=debit.account_id
 JOIN finance_account income ON income.root_realm_id=j.root_realm_id AND income.id=credit.account_id
 JOIN account_group g ON g.root_realm_id=income.root_realm_id AND g.id=income.group_id
 WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.application_id AND a.status='SUBMITTED'
   AND a.accepted_fee_minor=NEW.amount_minor AND a.branch_ref IS NOT DISTINCT FROM NEW.branch_id
   AND s.application_version=NEW.submitted_version AND s.source_digest=NEW.submitted_digest
   AND a.version=s.application_version AND a.submitted_digest=s.source_digest
   AND c.status IN('SUBMITTED','PENDING_OWNER') AND j.source_ref=a.id AND j.source_owner='CG-09' AND j.posting_kind='GENERAL' AND j.status='POSTED'
   AND j.immutable_source_event_key=NEW.request_key AND j.created_by=NEW.recorded_by
   AND debit.debit_minor=NEW.amount_minor AND debit.credit_minor=0 AND credit.credit_minor=NEW.amount_minor AND credit.debit_minor=0
   AND debit.branch_id IS NOT DISTINCT FROM NEW.branch_id AND credit.branch_id IS NOT DISTINCT FROM NEW.branch_id
   AND bank.account_kind='BANK' AND income.account_kind='GENERAL' AND g.category='INCOME'
   AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2)
 THEN RAISE EXCEPTION 'Membership collection must match the original submitted fee and posted journal'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_member_refund_posting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM finance_membership_refund_request r
 JOIN finance_membership_collection m ON m.root_realm_id=r.root_realm_id AND m.application_id=r.application_id
 JOIN finance_membership_verified_collection v ON v.root_realm_id=r.root_realm_id AND v.application_id=r.application_id AND v.reconciliation_id=r.original_reconciliation_id
 JOIN journal j ON j.root_realm_id=r.root_realm_id AND j.id=NEW.journal_id
 JOIN journal_line bank ON bank.root_realm_id=j.root_realm_id AND bank.journal_id=j.id AND bank.account_id=m.bank_account_id
 JOIN journal_line income ON income.root_realm_id=j.root_realm_id AND income.journal_id=j.id AND income.account_id=m.income_account_id
 WHERE r.root_realm_id=NEW.root_realm_id AND r.application_id=NEW.application_id AND r.requested_by<>NEW.approved_by AND m.recorded_by<>NEW.approved_by
 AND j.source_owner='CG-09' AND j.source_ref=r.application_id AND j.status='POSTED' AND j.posting_kind='REFUND' AND j.created_by=NEW.approved_by AND j.immutable_source_event_key=NEW.request_key
 AND bank.credit_minor=r.amount_minor AND bank.debit_minor=0 AND income.debit_minor=r.amount_minor AND income.credit_minor=0
 AND bank.branch_id IS NOT DISTINCT FROM m.branch_id AND income.branch_id IS NOT DISTINCT FROM m.branch_id
 AND (SELECT count(*) FROM journal_line l WHERE l.root_realm_id=j.root_realm_id AND l.journal_id=j.id)=2
 AND EXISTS(SELECT 1 FROM account a JOIN account_role ar ON ar.account_id=a.id AND ar.realm_id=a.realm_id AND ar.revoked_at IS NULL JOIN role role ON role.id=ar.role_id AND role.realm_id=a.realm_id AND role.active AND role.is_protected WHERE a.id=NEW.approved_by AND a.realm_id=NEW.root_realm_id AND a.status='ACTIVE'))
 THEN RAISE EXCEPTION 'Refund requires distinct protected approval and exact original verified fee'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_membership_fee_pin_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM finance_membership_collection m WHERE m.root_realm_id=OLD.root_realm_id AND m.application_id=OLD.id)
 AND (NEW.tier_version_id,NEW.accepted_fee_minor,NEW.currency,NEW.branch_ref) IS DISTINCT FROM (OLD.tier_version_id,OLD.accepted_fee_minor,OLD.currency,OLD.branch_ref)
 THEN RAISE EXCEPTION 'The recorded membership fee and funding scope cannot be repriced'; END IF;
 IF NEW.status='CANCELLED' AND EXISTS(SELECT 1 FROM finance_membership_collection m WHERE m.root_realm_id=OLD.root_realm_id AND m.application_id=OLD.id)
 THEN RAISE EXCEPTION 'A recorded fee must follow the original rejection and refund flow'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_membership_refund_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM finance_membership_verified_collection v JOIN membership_application a ON a.root_realm_id=v.root_realm_id AND a.id=v.application_id
 JOIN cg03_case c ON c.realm_id=a.root_realm_id AND c.membership_application_id=a.id 
 WHERE v.root_realm_id=NEW.root_realm_id AND v.application_id=NEW.application_id AND v.journal_id=NEW.original_journal_id
 AND v.reconciliation_id=NEW.original_reconciliation_id AND v.amount_minor=NEW.amount_minor 
 AND a.status='REJECTED' AND c.case_kind='MEMBER_APPLICATION' AND c.status='REJECTED' AND c.membership_review_digest=a.submitted_digest)
 THEN RAISE EXCEPTION 'Refund must be linked to the exact verified original rejected fee'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_payment_verification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE current_voucher record;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
   OR NEW.voucher_id IS DISTINCT FROM OLD.voucher_id OR NEW.voucher_revision<>OLD.voucher_revision
   OR NEW.case_id IS DISTINCT FROM OLD.case_id
   OR NEW.proof_file_id IS DISTINCT FROM OLD.proof_file_id
   OR NEW.proof_file_version<>OLD.proof_file_version
   OR NEW.method<>OLD.method OR NEW.bank_reference IS DISTINCT FROM OLD.bank_reference
   OR NEW.amount_minor<>OLD.amount_minor OR NEW.requested_by IS DISTINCT FROM OLD.requested_by
   OR NEW.request_key IS DISTINCT FROM OLD.request_key OR NEW.request_digest IS DISTINCT FROM OLD.request_digest
   OR NEW.created_at IS DISTINCT FROM OLD.created_at OR OLD.status<>'PENDING_REVIEW'
   OR NEW.status NOT IN('VERIFIED','REJECTED') THEN
   RAISE EXCEPTION 'Original payment verification cannot change'
    USING ERRCODE='P0917';
  END IF;
 ELSE
  IF NEW.status<>'PENDING_REVIEW' THEN
   RAISE EXCEPTION 'Payment needs independent verification' USING ERRCODE='P0917';
  END IF;
 END IF;
 SELECT v.status,v.version,v.approval_case_id,v.total_minor,v.created_by,
    v.payment_account_id,a.account_kind
  INTO current_voucher FROM finance_voucher v
  JOIN finance_account a ON a.id=v.payment_account_id AND a.root_realm_id=v.root_realm_id
  WHERE v.id=NEW.voucher_id AND v.root_realm_id=NEW.root_realm_id
   AND v.voucher_type IN('PAYMENT','CONTRA') FOR SHARE OF v,a;
 IF NOT FOUND OR current_voucher.status<>'PAYMENT_REQUESTED' OR
  current_voucher.version<>NEW.voucher_revision OR
  current_voucher.approval_case_id IS DISTINCT FROM NEW.case_id OR
  current_voucher.total_minor<>NEW.amount_minor OR
  (NEW.method='BANK_STATEMENT' AND current_voucher.account_kind<>'BANK') OR
  (NEW.method='CASH_RECEIPT' AND current_voucher.account_kind<>'CASH') OR
  (NEW.method='BANK_STATEMENT' AND NEW.bank_reference IS NULL) THEN
  RAISE EXCEPTION 'Payment amount or verified source is not eligible'
   USING ERRCODE='P0917';
 END IF;
 IF NEW.status='VERIFIED' AND (NEW.verified_by=current_voucher.created_by OR
    NEW.verified_by=NEW.requested_by) THEN
  RAISE EXCEPTION 'A different reviewer must verify the payment'
   USING ERRCODE='P0917';
 END IF;
 PERFORM 1 FROM cg19_stored_file f JOIN cg19_upload_intent i
   ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
 WHERE f.id=NEW.proof_file_id AND f.realm_id=NEW.root_realm_id
  AND f.voucher_id=NEW.voucher_id AND f.voucher_version=NEW.voucher_revision
  AND f.owner_kind='CG09_PAYMENT' AND f.revision=NEW.proof_file_version
  AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
  AND i.owner_kind='CG09_PAYMENT' AND i.status='VALIDATED'
 FOR SHARE OF f,i;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original private payment proof is not verified'
   USING ERRCODE='P0917'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_project_budget_effect_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b record; p record; v record;
BEGIN
 SELECT project_ref,branch_id INTO b FROM finance_budget WHERE root_realm_id=NEW.root_realm_id AND id=NEW.budget_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original budget unavailable' USING ERRCODE='P0924'; END IF;
 IF b.project_ref IS NULL THEN RETURN NEW; END IF;
 IF NEW.kind<>'RELEASE' THEN
  SELECT branch_ref,status INTO p FROM project WHERE root_realm_id=NEW.root_realm_id AND id=b.project_ref FOR SHARE;
  IF NOT FOUND OR p.branch_ref IS DISTINCT FROM b.branch_id OR p.status NOT IN('PLANNED','ACTIVE','ON_HOLD') THEN
   RAISE EXCEPTION 'Project no longer eligible in this budget scope' USING ERRCODE='P0924';
  END IF;
 END IF;
 IF NEW.kind='UTILIZE' THEN
  SELECT f.project_ref,f.branch_id INTO v FROM journal j JOIN finance_voucher f
   ON f.root_realm_id=j.root_realm_id AND f.id=j.source_ref
   WHERE j.root_realm_id=NEW.root_realm_id AND j.id=NEW.source_journal_id
    AND j.posting_kind='VOUCHER' AND j.status='POSTED' FOR SHARE OF j,f;
  IF NOT FOUND OR v.project_ref IS DISTINCT FROM b.project_ref OR v.branch_id IS DISTINCT FROM b.branch_id THEN
   RAISE EXCEPTION 'Project budget utilization requires its own posted expense voucher' USING ERRCODE='P0924';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg09_receipt_current_statement_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM finance_reconciliation_decision d
 JOIN cg19_stored_file f
  ON f.id=d.statement_file_id AND f.realm_id=d.root_realm_id
  AND f.reconciliation_id=d.reconciliation_id AND f.revision=d.statement_file_version
 JOIN cg19_upload_intent i
  ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  AND i.reconciliation_id=d.reconciliation_id
 WHERE d.root_realm_id=NEW.root_realm_id
  AND d.reconciliation_id=NEW.reconciliation_id AND d.action='VERIFY'
  AND f.owner_kind='CG09_BANK_STATEMENT'
  AND i.owner_kind='CG09_BANK_STATEMENT' AND i.status='VALIDATED'
  AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
 FOR SHARE OF d,f,i;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Original verified bank statement proof is unavailable'
   USING ERRCODE='P0928';
 END IF;
 RETURN NEW;
END; $function$
;

-- Functions 181-225
CREATE OR REPLACE FUNCTION public.cg09_receipt_verified_posting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE inv record; r record; posted record; journal_date date; already_paid numeric;
BEGIN
 SELECT status,version,total_minor,receivable_account_id,branch_id INTO inv
 FROM finance_invoice WHERE id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id
 FOR UPDATE;
 IF NOT FOUND OR inv.status<>'ISSUED' OR inv.version<>NEW.source_invoice_version OR
    NEW.amount_minor>inv.total_minor THEN
  RAISE EXCEPTION 'Valid issued original invoice and receipt required' USING ERRCODE='P0927';
 END IF;
 SELECT COALESCE(SUM(amount_minor),0) INTO already_paid
 FROM finance_invoice_receipt WHERE invoice_id=NEW.invoice_id
  AND root_realm_id=NEW.root_realm_id;
 IF already_paid+NEW.amount_minor>inv.total_minor THEN
  RAISE EXCEPTION 'Receipt exceeds original invoice outstanding amount' USING ERRCODE='P0927';
 END IF;
 SELECT bank_account_id,journal_id,statement_date,statement_amount_minor,
  posted_amount_minor,variance_minor,status INTO r
 FROM finance_bank_reconciliation
 WHERE id=NEW.reconciliation_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR r.status<>'VERIFIED' OR r.variance_minor<>0 OR
    r.statement_amount_minor<>NEW.amount_minor OR r.posted_amount_minor<>NEW.amount_minor
    OR r.journal_id<>NEW.journal_id OR r.statement_date<>NEW.receipt_date THEN
  RAISE EXCEPTION 'Independently verified real bank receipt is required' USING ERRCODE='P0927';
 END IF;
 SELECT j.posting_date INTO journal_date FROM journal j
 WHERE j.id=NEW.journal_id AND j.root_realm_id=NEW.root_realm_id
  AND j.status='POSTED' AND j.posting_kind='GENERAL' AND j.source_ref=NEW.invoice_id FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'An existing posted balanced receipt journal is required' USING ERRCODE='P0927';
 END IF;
 SELECT COUNT(*)::int AS line_count,
  COALESCE(SUM(l.debit_minor),0) AS debit_total,
  COALESCE(SUM(l.credit_minor),0) AS credit_total,
  COUNT(*) FILTER (WHERE l.account_id=r.bank_account_id
    AND l.branch_id IS NOT DISTINCT FROM inv.branch_id
    AND l.debit_minor=NEW.amount_minor AND l.credit_minor=0) AS bank_line_count,
  COUNT(*) FILTER (WHERE l.account_id=inv.receivable_account_id
    AND l.branch_id IS NOT DISTINCT FROM inv.branch_id
    AND l.credit_minor=NEW.amount_minor AND l.debit_minor=0) AS receivable_line_count
 INTO posted FROM journal_line l WHERE l.journal_id=NEW.journal_id
   AND l.root_realm_id=NEW.root_realm_id;
 IF posted.line_count<>2 OR posted.debit_total<>NEW.amount_minor OR
  posted.credit_total<>NEW.amount_minor OR posted.bank_line_count<>1 OR
  posted.receivable_line_count<>1 THEN
  RAISE EXCEPTION 'Real receipt must be a bank debit against this original invoice receivable'
   USING ERRCODE='P0927';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_reconciliation_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_account_kind text; bank_line_count bigint; bank_amount bigint; source_year uuid;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Bank reconciliation source cannot be deleted' USING ERRCODE='P0926';
 END IF;
 IF TG_OP='INSERT' THEN
  SELECT a.account_kind INTO v_account_kind FROM finance_account a
   WHERE a.id=NEW.bank_account_id AND a.root_realm_id=NEW.root_realm_id FOR SHARE;
  IF NOT FOUND OR v_account_kind<>'BANK' THEN
   RAISE EXCEPTION 'An actual bank account is required' USING ERRCODE='P0926';
  END IF;
  SELECT j.financial_year_id,COUNT(l.id),COALESCE(SUM(l.debit_minor-l.credit_minor),0)
   INTO source_year,bank_line_count,bank_amount
   FROM journal j JOIN journal_line l ON l.journal_id=j.id AND l.root_realm_id=j.root_realm_id
   WHERE j.id=NEW.journal_id AND j.root_realm_id=NEW.root_realm_id
    AND j.status='POSTED' AND l.account_id=NEW.bank_account_id
   GROUP BY j.id,j.financial_year_id;
  IF NOT FOUND OR (bank_line_count<>1 AND NOT cg11_root_payroll_journal(NEW.root_realm_id,NEW.journal_id)) OR source_year<>NEW.financial_year_id OR
     bank_amount<>NEW.posted_amount_minor OR
     NEW.variance_minor<>NEW.statement_amount_minor-bank_amount THEN
    RAISE EXCEPTION 'Bank reconciliation must match exactly one posted bank line' USING ERRCODE='P0926';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR
    NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
    NEW.bank_account_id IS DISTINCT FROM OLD.bank_account_id OR
    NEW.journal_id IS DISTINCT FROM OLD.journal_id OR
    NEW.financial_year_id IS DISTINCT FROM OLD.financial_year_id OR
    NEW.statement_date IS DISTINCT FROM OLD.statement_date OR
    NEW.bank_item_ref IS DISTINCT FROM OLD.bank_item_ref OR
    NEW.statement_amount_minor<>OLD.statement_amount_minor OR
    NEW.posted_amount_minor<>OLD.posted_amount_minor OR
    NEW.variance_minor<>OLD.variance_minor OR
    NEW.recorded_by IS DISTINCT FROM OLD.recorded_by OR
    NEW.request_key IS DISTINCT FROM OLD.request_key OR
    NEW.content_digest IS DISTINCT FROM OLD.content_digest OR
    NEW.recorded_at IS DISTINCT FROM OLD.recorded_at OR
    OLD.status<>'PENDING' OR NEW.status NOT IN('VERIFIED','REJECTED') OR
    NEW.verified_by IS NULL OR NEW.verified_at IS NULL THEN
  RAISE EXCEPTION 'A bank statement match cannot be rewritten' USING ERRCODE='P0926';
 END IF;
 PERFORM 1 FROM finance_reconciliation_decision d
 WHERE d.reconciliation_id=NEW.id AND d.root_realm_id=NEW.root_realm_id
   AND d.actor_ref=NEW.verified_by AND
   ((NEW.status='VERIFIED' AND d.action='VERIFY' AND NEW.variance_minor=0)
     OR(NEW.status='REJECTED' AND d.action='REJECT'))
   AND d.original_digest=NEW.content_digest
 FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'An independent signed bank reconciliation decision is required'
   USING ERRCODE='P0926';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_refund_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c record; inv record; bank record; j record; lines record;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original refunds are immutable' USING ERRCODE='P0932';
 END IF;
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-
    'status'-'approved_by'-'approved_at'-'password_verified_at'-
    'approval_key'-'approval_journal_id'-'transfer_reference')
   IS DISTINCT FROM (to_jsonb(OLD)-
    'status'-'approved_by'-'approved_at'-'password_verified_at'-
    'approval_key'-'approval_journal_id'-'transfer_reference') THEN
  RAISE EXCEPTION 'Only the protected reviewer can post a refund' USING ERRCODE='P0932';
 END IF;
 SELECT invoice_id,collected_minor,refund_liability_account_id INTO c
 FROM finance_invoice_credit_note WHERE id=NEW.credit_note_id
  AND root_realm_id=NEW.root_realm_id FOR SHARE;
 SELECT branch_id INTO inv FROM finance_invoice
  WHERE id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 SELECT a.account_kind,a.status,a.branch_id INTO bank FROM finance_account a
  WHERE a.id=NEW.bank_account_id AND a.root_realm_id=NEW.root_realm_id FOR SHARE;
 IF NOT FOUND OR c.invoice_id IS DISTINCT FROM NEW.invoice_id OR
  NEW.amount_minor<>c.collected_minor OR bank.account_kind<>'BANK'
  OR bank.status<>'ACTIVE' OR
  (bank.branch_id IS NOT NULL AND bank.branch_id IS DISTINCT FROM inv.branch_id) THEN
  RAISE EXCEPTION 'Refund must use the original verified collected amount and bank'
   USING ERRCODE='P0932';
 END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.status<>'REQUESTED' OR NEW.status<>'BANK_POSTED' OR
     NEW.transfer_reference IS NULL OR
     NEW.approved_by=NEW.requested_by OR NEW.approved_at IS NULL OR
     NEW.password_verified_at<NEW.approved_at-interval '5 minutes' OR
     NEW.password_verified_at>NEW.approved_at+interval '1 minute' THEN
   RAISE EXCEPTION 'Independent protected refund approval required' USING ERRCODE='P0932';
  END IF;
  SELECT posting_kind,status,source_ref,created_by,financial_year_id,posting_date
  INTO j FROM journal WHERE id=NEW.approval_journal_id
   AND root_realm_id=NEW.root_realm_id FOR SHARE;
  IF j.posting_kind<>'REFUND' OR j.status<>'POSTED' OR
    j.source_ref IS DISTINCT FROM NEW.id OR
    j.created_by IS DISTINCT FROM NEW.approved_by OR
    j.financial_year_id IS DISTINCT FROM NEW.financial_year_id OR
    j.posting_date IS DISTINCT FROM NEW.posting_date THEN
    RAISE EXCEPTION 'Original reviewer refund journal required' USING ERRCODE='P0932';
  END IF;
  SELECT COUNT(*)::integer AS n,
   COUNT(*) FILTER(WHERE account_id=c.refund_liability_account_id
     AND branch_id IS NOT DISTINCT FROM inv.branch_id AND debit_minor=NEW.amount_minor
     AND credit_minor=0) AS dr,
   COUNT(*) FILTER(WHERE account_id=NEW.bank_account_id
     AND branch_id IS NOT DISTINCT FROM inv.branch_id AND credit_minor=NEW.amount_minor
     AND debit_minor=0) AS cr
  INTO lines FROM journal_line WHERE root_realm_id=NEW.root_realm_id
   AND journal_id=NEW.approval_journal_id;
  IF lines.n<>2 OR lines.dr<>1 OR lines.cr<>1 THEN
   RAISE EXCEPTION 'Refund posting is not the approved refund payable offset'
    USING ERRCODE='P0932';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_require_invoice_adjustment_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.posting_kind='CREDIT_NOTE' THEN
  PERFORM 1 FROM finance_invoice_credit_note c
   WHERE c.root_realm_id=NEW.root_realm_id
    AND c.adjustment_journal_id=NEW.id AND c.original_journal_id=NEW.reversal_of_id
   FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Source-bound credit note proof required' USING ERRCODE='P0931';
  END IF;
 ELSIF NEW.posting_kind='REFUND' THEN
  -- CG04 additionally uses CG09's original independently approved refund
  -- event, not the invoice refund source. Both are verified inside this
  -- same transaction by their respective immutable record guards.
  IF EXISTS(SELECT 1 FROM finance_membership_refund_posting m
    JOIN finance_membership_refund_request requested ON requested.root_realm_id=m.root_realm_id AND requested.application_id=m.application_id
    WHERE m.root_realm_id=NEW.root_realm_id AND m.journal_id=NEW.id
      AND m.application_id=NEW.source_ref AND m.request_key=NEW.immutable_source_event_key
      AND m.approved_by=NEW.created_by AND m.approved_by<>requested.requested_by)
    THEN RETURN NULL; END IF;
  PERFORM 1 FROM finance_invoice_refund r
   WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.source_ref
     AND r.approval_journal_id=NEW.id AND r.status='BANK_POSTED'
   FOR SHARE;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Independently reviewed refund proof required' USING ERRCODE='P0932';
  END IF;
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_require_manual_reversal_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.posting_kind<>'REVERSAL' THEN RETURN NULL; END IF;
 PERFORM 1 FROM finance_manual_journal_reversal f
 WHERE f.root_realm_id=NEW.root_realm_id
  AND f.reversal_journal_id=NEW.id AND f.original_journal_id=NEW.reversal_of_id
 FOR SHARE;
 IF FOUND THEN RETURN NULL; END IF;
 PERFORM 1 FROM cg17_liability_correction f
 WHERE f.root_realm_id=NEW.root_realm_id
  AND f.reversal_journal_ref=NEW.id AND f.original_journal_ref=NEW.reversal_of_id
 FOR SHARE;
 IF FOUND THEN RETURN NULL; END IF;
 PERFORM 1 FROM cg17_provider_claim_correction f
 WHERE f.root_realm_id=NEW.root_realm_id
  AND f.reversal_journal_ref=NEW.id AND f.original_journal_ref=NEW.reversal_of_id
 FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Protected original reversal proof is required'
   USING ERRCODE='P0929';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg09_stop_invoice_collection_after_credit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.posting_kind<>'GENERAL' THEN RETURN NEW; END IF;
 PERFORM 1 FROM finance_invoice i
  WHERE i.id=NEW.source_ref AND i.root_realm_id=NEW.root_realm_id FOR UPDATE;
 IF FOUND THEN
  PERFORM 1 FROM finance_invoice_credit_note c
   WHERE c.root_realm_id=NEW.root_realm_id AND c.invoice_id=NEW.source_ref FOR SHARE;
  IF FOUND THEN
   RAISE EXCEPTION 'This issued invoice was credited; do not collect again'
    USING ERRCODE='P0931';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_stop_invoice_receipt_after_credit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM finance_invoice
  WHERE id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id FOR UPDATE;
 PERFORM 1 FROM finance_invoice_credit_note
  WHERE invoice_id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF FOUND THEN
  RAISE EXCEPTION 'This original invoice has an issued credit note'
   USING ERRCODE='P0931';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_validate_issued_credit_note()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE inv record; orig record; correction record; paid bigint; collected bigint;
 actual record; liability record;
BEGIN
 SELECT status,version,created_by,total_minor,gross_minor,tax_minor,charges_minor,
  branch_id,receivable_account_id,income_account_id,tax_account_id
 INTO inv FROM finance_invoice
 WHERE id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id FOR UPDATE;
 IF NOT FOUND OR inv.status<>'ISSUED' OR inv.version<>NEW.invoice_version
   OR inv.created_by=NEW.approved_by OR NEW.total_minor<>inv.total_minor
   OR NEW.password_verified_at>NEW.created_at+interval '1 minute'
   OR NEW.password_verified_at<NEW.created_at-interval '5 minutes' THEN
  RAISE EXCEPTION 'Genuine issued invoice and independent protected reviewer required'
   USING ERRCODE='P0931';
 END IF;
 PERFORM 1 FROM finance_invoice_posted_cancellation
  WHERE root_realm_id=NEW.root_realm_id AND invoice_id=NEW.invoice_id FOR SHARE;
 IF FOUND THEN
  RAISE EXCEPTION 'Already cancelled invoice cannot be credited' USING ERRCODE='P0931';
 END IF;
 SELECT p.journal_id,j.status,j.posting_kind INTO orig
 FROM finance_invoice_posting p JOIN journal j ON j.id=p.journal_id
   AND j.root_realm_id=p.root_realm_id
 WHERE p.root_realm_id=NEW.root_realm_id AND p.invoice_id=NEW.invoice_id FOR SHARE OF p,j;
 SELECT posting_kind,status,source_ref,reversal_of_id,created_by INTO correction
 FROM journal WHERE id=NEW.adjustment_journal_id
  AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF orig.journal_id IS DISTINCT FROM NEW.original_journal_id
   OR orig.status<>'POSTED' OR orig.posting_kind<>'INVOICE'
   OR correction.posting_kind<>'CREDIT_NOTE' OR correction.status<>'POSTED'
   OR correction.source_ref IS DISTINCT FROM NEW.invoice_id
   OR correction.reversal_of_id IS DISTINCT FROM NEW.original_journal_id
   OR correction.created_by IS DISTINCT FROM NEW.approved_by THEN
  RAISE EXCEPTION 'Credit note must offset the actual original invoice' USING ERRCODE='P0931';
 END IF;
 SELECT COALESCE(SUM(amount_minor),0)::bigint INTO paid
 FROM finance_invoice_receipt WHERE root_realm_id=NEW.root_realm_id
  AND invoice_id=NEW.invoice_id;
 -- Pending or unmatched collections are not silently treated as verified.
 SELECT COALESCE(SUM(l.debit_minor),0)::bigint INTO collected
 FROM journal j JOIN journal_line l
  ON l.journal_id=j.id AND l.root_realm_id=j.root_realm_id
 JOIN finance_account a ON a.id=l.account_id AND a.root_realm_id=l.root_realm_id
 WHERE j.root_realm_id=NEW.root_realm_id AND j.source_ref=NEW.invoice_id
  AND j.posting_kind='GENERAL' AND a.account_kind='BANK';
 IF paid IS DISTINCT FROM NEW.collected_minor OR paid<>collected THEN
  RAISE EXCEPTION 'Resolve pending bank collections before issuing a credit note'
   USING ERRCODE='P0931';
 END IF;
 IF paid>0 THEN
  SELECT a.account_kind,g.category,a.branch_id INTO liability
  FROM finance_account a JOIN account_group g
   ON g.id=a.group_id AND g.root_realm_id=a.root_realm_id
  WHERE a.id=NEW.refund_liability_account_id AND a.root_realm_id=NEW.root_realm_id
   AND a.status='ACTIVE' FOR SHARE OF a,g;
  IF NOT FOUND OR liability.category<>'LIABILITY' OR
   liability.account_kind<>'GENERAL' OR
   (liability.branch_id IS NOT NULL AND liability.branch_id IS DISTINCT FROM inv.branch_id) OR
   NEW.refund_liability_account_id=inv.tax_account_id THEN
   RAISE EXCEPTION 'Select an eligible separate refund payable account' USING ERRCODE='P0931';
  END IF;
 END IF;
 SELECT COUNT(*)::integer AS n,
  COALESCE(SUM(debit_minor),0)::bigint AS dr,
  COALESCE(SUM(credit_minor),0)::bigint AS cr,
  COUNT(*) FILTER(WHERE account_id=inv.income_account_id
    AND branch_id IS NOT DISTINCT FROM inv.branch_id
    AND debit_minor=inv.gross_minor+inv.charges_minor AND credit_minor=0) AS income_leg,
  COUNT(*) FILTER(WHERE account_id=inv.tax_account_id
    AND branch_id IS NOT DISTINCT FROM inv.branch_id
    AND debit_minor=inv.tax_minor AND credit_minor=0) AS tax_leg,
  COUNT(*) FILTER(WHERE account_id=inv.receivable_account_id
    AND branch_id IS NOT DISTINCT FROM inv.branch_id
    AND credit_minor=inv.total_minor-paid AND debit_minor=0) AS receivable_leg,
  COUNT(*) FILTER(WHERE account_id=NEW.refund_liability_account_id
    AND branch_id IS NOT DISTINCT FROM inv.branch_id
    AND credit_minor=paid AND debit_minor=0) AS payable_leg
 INTO actual FROM journal_line
 WHERE root_realm_id=NEW.root_realm_id AND journal_id=NEW.adjustment_journal_id;
 IF actual.dr<>inv.total_minor OR actual.cr<>inv.total_minor OR
   actual.n<>(1+CASE WHEN inv.tax_minor>0 THEN 1 ELSE 0 END+
      CASE WHEN inv.total_minor>paid THEN 1 ELSE 0 END+
      CASE WHEN paid>0 THEN 1 ELSE 0 END)
   OR actual.income_leg<>1
   OR (inv.tax_minor>0 AND actual.tax_leg<>1)
   OR (inv.total_minor>paid AND actual.receivable_leg<>1)
   OR (paid>0 AND actual.payable_leg<>1) THEN
  RAISE EXCEPTION 'Credit note monetary lines do not match the original invoice'
   USING ERRCODE='P0931';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_verify_manual_reversal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original record; changed record; o record; r record; mismatch integer;
BEGIN
 SELECT posting_kind,source_ref,immutable_source_event_key,created_by,
  immutable_payload_digest,status
  INTO original FROM journal
  WHERE id=NEW.original_journal_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 SELECT posting_kind,reversal_of_id,source_ref,created_by,status
  INTO changed FROM journal
  WHERE id=NEW.reversal_journal_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 IF original.status<>'POSTED' OR
  NOT ((original.posting_kind='GENERAL' AND original.source_ref=original.immutable_source_event_key AND NEW.payroll_return_bank_reference IS NULL)
   OR (original.posting_kind='VOUCHER' AND NEW.payroll_return_bank_reference IS NOT NULL
    AND cg11_original_settled_bank_journal(NEW.root_realm_id,NEW.original_journal_id)
    AND NOT EXISTS(SELECT 1 FROM finance_bank_reconciliation br WHERE br.root_realm_id=NEW.root_realm_id AND br.journal_id=NEW.original_journal_id AND upper(btrim(br.bank_item_ref))=NEW.payroll_return_bank_reference)))
  OR original.created_by=NEW.reviewer_id
  OR changed.posting_kind<>'REVERSAL' OR changed.status<>'POSTED'
  OR changed.reversal_of_id<>NEW.original_journal_id
  OR changed.source_ref<>NEW.original_journal_id
  OR changed.created_by<>NEW.reviewer_id
  OR NEW.password_verified_at>NEW.created_at+interval '1 minute'
  OR NEW.password_verified_at<NEW.created_at-interval '5 minutes' THEN
  RAISE EXCEPTION 'Original manual journal and distinct reviewer proof required'
   USING ERRCODE='P0929';
 END IF;
 -- Compare actual reversal balances BY account and real branch and number of
 -- lines; aggregate equality rejects hidden positive or negative extra legs.
 WITH prior AS (
  SELECT account_id,branch_id,COUNT(*) AS n,
   SUM(debit_minor) AS debits,SUM(credit_minor) AS credits
  FROM journal_line WHERE root_realm_id=NEW.root_realm_id
   AND journal_id=NEW.original_journal_id GROUP BY account_id,branch_id
 ), after AS (
  SELECT account_id,branch_id,COUNT(*) AS n,
   SUM(debit_minor) AS debits,SUM(credit_minor) AS credits
  FROM journal_line WHERE root_realm_id=NEW.root_realm_id
   AND journal_id=NEW.reversal_journal_id GROUP BY account_id,branch_id
 )
 SELECT COUNT(*) INTO mismatch FROM prior p FULL OUTER JOIN after a
  ON a.account_id=p.account_id
  AND a.branch_id IS NOT DISTINCT FROM p.branch_id
 WHERE p.account_id IS NULL OR a.account_id IS NULL OR p.n<>a.n
  OR p.debits<>a.credits OR p.credits<>a.debits;
 IF mismatch<>0 THEN
  RAISE EXCEPTION 'A correction must reverse the exact original double entry'
   USING ERRCODE='P0929';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_verify_voucher_accounting_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE header jsonb;
BEGIN
 SELECT header_snapshot INTO header
 FROM finance_voucher_draft_revision
 WHERE voucher_id=NEW.id AND root_realm_id=NEW.root_realm_id AND version=NEW.version;
 IF NOT FOUND OR header->>'debitAccountRef' IS DISTINCT FROM NEW.debit_account_id::text
    OR header->>'creditAccountRef' IS DISTINCT FROM NEW.credit_account_id::text THEN
  RAISE EXCEPTION 'Frozen financial account sides do not match the voucher source'
   USING ERRCODE='P0913';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_verify_voucher_draft_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE item jsonb; qty numeric; rate numeric; subtotal numeric; total numeric:=0;
BEGIN
 PERFORM 1 FROM finance_voucher v
  WHERE v.id=NEW.voucher_id AND v.root_realm_id=NEW.root_realm_id
   AND v.version=NEW.version AND v.status='DRAFT' FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Voucher revision must match the current draft' USING ERRCODE='P0913';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(NEW.line_snapshot) LOOP
  IF jsonb_typeof(item)<>'object'
   OR (item->>'description') IS NULL
   OR char_length(btrim(item->>'description')) NOT BETWEEN 2 AND 180
   OR (item->>'quantity') IS NULL
   OR (item->>'quantity') !~ '^[0-9]{1,7}$'
   OR (item->>'unitRateMinor') IS NULL
   OR (item->>'unitRateMinor') !~ '^[0-9]{1,16}$'
   OR (item->>'lineTotalMinor') IS NULL
   OR (item->>'lineTotalMinor') !~ '^[0-9]{1,16}$' THEN
    RAISE EXCEPTION 'Voucher item is invalid' USING ERRCODE='P0913';
  END IF;
  qty:=(item->>'quantity')::numeric;
  rate:=(item->>'unitRateMinor')::numeric;
  subtotal:=(item->>'lineTotalMinor')::numeric;
  IF qty<1 OR qty>1000000 OR rate<=0 OR rate>99999999999999
     OR subtotal<=0 OR subtotal>99999999999999 OR subtotal<>qty*rate THEN
    RAISE EXCEPTION 'Voucher item total does not match quantity and rate' USING ERRCODE='P0913';
  END IF;
  total:=total+subtotal;
 END LOOP;
 IF total<>NEW.gross_minor OR
  NEW.total_minor<>NEW.gross_minor+NEW.tax_minor+NEW.charges_minor THEN
  RAISE EXCEPTION 'Voucher items do not balance against the draft amount' USING ERRCODE='P0913';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_verify_voucher_revision_link()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE h jsonb; r record;
BEGIN
 SELECT revision.header_snapshot,revision.gross_minor,revision.tax_minor,
   revision.charges_minor,revision.total_minor
  INTO r
 FROM finance_voucher_draft_revision revision
 WHERE revision.voucher_id=NEW.id AND revision.root_realm_id=NEW.root_realm_id
   AND revision.version=NEW.version;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Voucher revision is required before a draft is visible' USING ERRCODE='P0913';
 END IF;
 h:=r.header_snapshot;
 IF r.gross_minor<>NEW.gross_minor OR r.tax_minor<>NEW.tax_minor
  OR r.charges_minor<>NEW.charges_minor OR r.total_minor<>NEW.total_minor
  OR h->>'financialYearRef' IS DISTINCT FROM NEW.financial_year_id::text
  OR h->>'branchRef' IS DISTINCT FROM NEW.branch_id::text
  OR h->>'type' IS DISTINCT FROM NEW.voucher_type
  OR h->>'postingDate' IS DISTINCT FROM NEW.posting_date::text
  OR h->>'payeeName' IS DISTINCT FROM NEW.payee_name
  OR h->>'purpose' IS DISTINCT FROM NEW.purpose THEN
   RAISE EXCEPTION 'Voucher revision does not match the current draft' USING ERRCODE='P0913';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_voucher_accounting_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a record; b record;
BEGIN
 IF TG_OP='UPDATE' AND OLD.status IN
  ('SUBMITTED','APPROVED','REJECTED','POSTED','PAYMENT_REQUESTED','PAID_VERIFIED')
  AND (NEW.debit_account_id IS DISTINCT FROM OLD.debit_account_id
    OR NEW.credit_account_id IS DISTINCT FROM OLD.credit_account_id) THEN
   RAISE EXCEPTION 'Approved voucher accounts cannot change' USING ERRCODE='P0907';
 END IF;
 IF NEW.status IN('DRAFT','SUBMITTED') THEN
  SELECT fa.status,fa.account_kind,fa.branch_id,g.category INTO a
  FROM finance_account fa JOIN account_group g ON g.id=fa.group_id
    AND g.root_realm_id=fa.root_realm_id
  WHERE fa.id=NEW.debit_account_id AND fa.root_realm_id=NEW.root_realm_id FOR SHARE OF fa,g;
  IF NOT FOUND OR a.status<>'ACTIVE' OR
     (a.branch_id IS NOT NULL AND a.branch_id IS DISTINCT FROM NEW.branch_id) THEN
   RAISE EXCEPTION 'Selected debit account is not available' USING ERRCODE='P0916';
  END IF;
  SELECT fb.status,fb.account_kind,fb.branch_id,g.category INTO b
  FROM finance_account fb JOIN account_group g ON g.id=fb.group_id
    AND g.root_realm_id=fb.root_realm_id
  WHERE fb.id=NEW.credit_account_id AND fb.root_realm_id=NEW.root_realm_id FOR SHARE OF fb,g;
  IF NOT FOUND OR b.status<>'ACTIVE' OR
     (b.branch_id IS NOT NULL AND b.branch_id IS DISTINCT FROM NEW.branch_id) THEN
   RAISE EXCEPTION 'Selected credit account is not available' USING ERRCODE='P0916';
  END IF;
  IF NEW.voucher_type='PAYMENT' AND
     (NEW.credit_account_id IS DISTINCT FROM NEW.payment_account_id OR
      a.category NOT IN('EXPENSE','LIABILITY','ASSET')) THEN
   RAISE EXCEPTION 'Payment voucher must debit an expense, payable or asset and credit its selected cash or bank'
    USING ERRCODE='P0916';
  END IF;
  IF NEW.voucher_type='CONTRA' AND
     (NEW.credit_account_id IS DISTINCT FROM NEW.payment_account_id OR
      a.account_kind NOT IN('CASH','BANK') OR b.account_kind NOT IN('CASH','BANK')) THEN
   RAISE EXCEPTION 'Contra voucher must transfer between different cash or bank accounts'
    USING ERRCODE='P0916';
  END IF;
  IF NEW.voucher_type='EXPENSE' AND (a.category<>'EXPENSE' OR b.category<>'LIABILITY') THEN
   RAISE EXCEPTION 'Unpaid expense must debit an expense account and credit a payable account'
    USING ERRCODE='P0916';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_voucher_claim_origin_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE eligible record;
BEGIN
 IF TG_OP='UPDATE' AND (NEW.expense_claim_id IS DISTINCT FROM OLD.expense_claim_id
   OR NEW.expense_claim_version IS DISTINCT FROM OLD.expense_claim_version) THEN
  RAISE EXCEPTION 'Claim source cannot change after voucher creation' USING ERRCODE='P0920';
 END IF;
 IF NEW.expense_claim_id IS NOT NULL THEN
  IF NEW.voucher_type NOT IN('EXPENSE','PAYMENT') THEN
   RAISE EXCEPTION 'Unsupported claim voucher type' USING ERRCODE='P0920';
  END IF;
  SELECT status,version,amount_minor,bill_file_id,bill_file_version INTO eligible
   FROM expense_claim WHERE id=NEW.expense_claim_id
    AND root_realm_id=NEW.root_realm_id FOR SHARE;
  IF NOT FOUND OR eligible.status<>'APPROVED' OR
     eligible.version<>NEW.expense_claim_version OR
     eligible.amount_minor<>NEW.total_minor THEN
   RAISE EXCEPTION 'An approved original claim with equal amount is required'
    USING ERRCODE='P0920';
  END IF;
  PERFORM 1 FROM cg19_stored_file f JOIN cg19_upload_intent i
    ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
   WHERE f.id=eligible.bill_file_id AND f.realm_id=NEW.root_realm_id
    AND f.claim_id=NEW.expense_claim_id AND f.claim_version=NEW.expense_claim_version
    AND f.revision=eligible.bill_file_version AND f.owner_kind='CG09_CLAIM'
    AND f.revoked_at IS NULL AND f.scan_status='CLEAN_VERIFIED'
    AND i.owner_kind='CG09_CLAIM' AND i.status='VALIDATED' FOR SHARE OF f,i;
  IF NOT FOUND THEN
   RAISE EXCEPTION 'Approved claim original bill is no longer verified' USING ERRCODE='P0920';
  END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg09_voucher_payment_snapshot_matches()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE h jsonb;
BEGIN
 SELECT header_snapshot INTO h FROM finance_voucher_draft_revision
  WHERE voucher_id=NEW.id AND root_realm_id=NEW.root_realm_id
    AND version=NEW.version;
 IF NOT FOUND OR h->>'paymentAccountRef' IS DISTINCT FROM NEW.payment_account_id::text THEN
  RAISE EXCEPTION 'Frozen cash or bank selection does not match this voucher'
   USING ERRCODE='P0913';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_appraisal_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Appraisal history cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.revision<>1 THEN RAISE EXCEPTION 'Appraisal starts as draft'; END IF;
  IF NOT EXISTS(SELECT 1 FROM hr_employee e WHERE e.root_realm_id=NEW.root_realm_id
   AND e.id=NEW.reviewer_employee_ref AND e.account_ref=NEW.reviewer_account_ref AND e.status IN('ACTIVE','PROBATION'))
  THEN RAISE EXCEPTION 'Appraisal must have its actual reviewer account'; END IF;
  RETURN NEW;
 END IF;
 IF (NEW.id,NEW.root_realm_id,NEW.reference,NEW.employee_id,NEW.assignment_id,NEW.reviewer_employee_ref,
  NEW.reviewer_account_ref,NEW.period_start,NEW.period_end,NEW.request_key,NEW.request_digest,NEW.created_at)
 IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.reference,OLD.employee_id,OLD.assignment_id,OLD.reviewer_employee_ref,
  OLD.reviewer_account_ref,OLD.period_start,OLD.period_end,OLD.request_key,OLD.request_digest,OLD.created_at)
 OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Appraisal source or revision changed'; END IF;
 IF OLD.status='RELEASED' OR (OLD.status='SUBMITTED' AND NEW.status<>'RELEASED')
 OR (OLD.status='DRAFT' AND NEW.status NOT IN('DRAFT','SUBMITTED')) THEN
  RAISE EXCEPTION 'Invalid appraisal state transition';
 END IF;
 IF OLD.status<>'DRAFT' OR NEW.status<>'DRAFT' THEN
  IF (NEW.goal_delivery_score,NEW.competency_score,NEW.attendance_conduct_score,NEW.feedback_ciphertext,
    NEW.feedback_nonce,NEW.feedback_tag) IS DISTINCT FROM
   (OLD.goal_delivery_score,OLD.competency_score,OLD.attendance_conduct_score,OLD.feedback_ciphertext,
    OLD.feedback_nonce,OLD.feedback_tag) THEN RAISE EXCEPTION 'Submitted scores and feedback are frozen'; END IF;
 END IF;
 IF OLD.submitted_at IS NOT NULL AND NEW.submitted_at IS DISTINCT FROM OLD.submitted_at THEN
  RAISE EXCEPTION 'Original submission time is immutable';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_assignment_no_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM id FROM hr_employee WHERE root_realm_id=NEW.root_realm_id AND id=NEW.employee_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM hr_employment_assignment a WHERE a.root_realm_id=NEW.root_realm_id
  AND a.employee_id=NEW.employee_id AND a.id<>NEW.id
  AND daterange(a.valid_from,a.valid_to,'[)') && daterange(NEW.valid_from,NEW.valid_to,'[)'))
 THEN RAISE EXCEPTION 'Employee assignment intervals overlap'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_attendance_leave_effect_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.leave_request_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM hr_leave_request r JOIN hr_leave_policy lp ON lp.id=r.policy_id AND lp.root_realm_id=r.root_realm_id
  JOIN hr_shift_policy sp ON sp.id=r.shift_policy_id AND sp.root_realm_id=r.root_realm_id
  WHERE r.id=NEW.leave_request_id AND r.root_realm_id=NEW.root_realm_id AND r.employee_id=NEW.employee_id
   AND r.status='APPROVED' AND r.assignment_id=NEW.assignment_id AND r.shift_id=NEW.shift_id
   AND r.shift_policy_id=NEW.policy_id AND NEW.local_date BETWEEN r.start_date AND r.end_date
   AND (lp.count_weekly_off OR NOT (extract(dow from NEW.local_date)::integer=ANY(sp.weekly_off_days)))
   AND NEW.leave_half_days=CASE WHEN r.half_day THEN 1 ELSE 2 END
 ) THEN RAISE EXCEPTION 'Original approved leave is required'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.leave_request_id IS NOT NULL AND
   (OLD.leave_request_id,OLD.leave_half_days) IS DISTINCT FROM (NEW.leave_request_id,NEW.leave_half_days)
  THEN RAISE EXCEPTION 'Approved leave attendance evidence cannot be removed'; END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg10_attendance_pending_employment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM id FROM hr_employee WHERE id=NEW.employee_id AND root_realm_id=NEW.root_realm_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM hr_employment_change h WHERE h.root_realm_id=NEW.root_realm_id
  AND h.employee_id=NEW.employee_id AND h.prior_assignment_id=NEW.assignment_id
  AND h.status='APPROVED_PENDING_EFFECT' AND h.effective_date<=NEW.local_date)
 THEN RAISE EXCEPTION 'Approved employment change must be applied before recording this date'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_correction_effect_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status='APPROVED' AND NOT EXISTS(
  SELECT 1 FROM hr_attendance_day d JOIN cg03_case c ON c.id=NEW.case_ref AND c.realm_id=NEW.root_realm_id
  WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.attendance_day_id AND d.employee_id=NEW.employee_id
   AND d.version=NEW.expected_version+1 AND c.status='OWNER_COMPLETED'
   AND d.status=NEW.proposed_snapshot->>'status'
   AND d.checked_in_at IS NOT DISTINCT FROM (NEW.proposed_snapshot->>'checkInAt')::timestamptz
   AND d.checked_out_at IS NOT DISTINCT FROM (NEW.proposed_snapshot->>'checkOutAt')::timestamptz
   AND d.worked_minutes IS NOT DISTINCT FROM (NEW.proposed_snapshot->>'workedMinutes')::integer
   AND COALESCE(d.leave_half_days,0)/2.0=(NEW.proposed_snapshot->>'leaveDays')::numeric
 ) THEN RAISE EXCEPTION 'Original approved correction effect was not applied'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_correction_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original attendance correction cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'SUBMITTED' OR NEW.case_ref IS NOT NULL OR NEW.decision_ref IS NOT NULL THEN
   RAISE EXCEPTION 'Correction must begin as a submission';
  END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['case_ref','status','decision_ref','decided_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['case_ref','status','decision_ref','decided_at']) THEN
  RAISE EXCEPTION 'Frozen correction evidence cannot be rewritten';
 END IF;
 IF OLD.status='SUBMITTED' AND OLD.case_ref IS NULL AND NEW.status='SUBMITTED'
 AND NEW.case_ref IS NOT NULL AND NEW.decision_ref IS NULL AND EXISTS(
  SELECT 1 FROM cg03_case c WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.case_ref AND c.case_kind='ATTENDANCE_CORRECTION'
   AND c.hr_attendance_change_id=NEW.id AND c.hr_attendance_change_digest=NEW.source_digest
   AND c.proposal_revision=NEW.expected_version AND c.proposer_id=NEW.submitted_by
 ) THEN RETURN NEW; END IF;
 IF OLD.status='SUBMITTED' AND OLD.case_ref IS NOT NULL AND NEW.case_ref=OLD.case_ref
  AND NEW.status IN('APPROVED','RETURNED','REJECTED') AND EXISTS(
   SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.case_id=c.id AND d.realm_id=c.realm_id
   JOIN account reviewer ON reviewer.id=d.actor_id AND reviewer.realm_id=d.realm_id AND reviewer.status='ACTIVE'
   JOIN account_role ar ON ar.account_id=reviewer.id AND ar.realm_id=reviewer.realm_id AND ar.revoked_at IS NULL
   JOIN role rr ON rr.id=ar.role_id AND rr.realm_id=ar.realm_id AND rr.active AND rr.is_protected
   JOIN hr_employee e ON e.id=NEW.employee_id AND e.root_realm_id=NEW.root_realm_id
   WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.case_ref AND c.case_kind='ATTENDANCE_CORRECTION'
    AND c.hr_attendance_change_id=NEW.id AND c.hr_attendance_change_digest=NEW.source_digest AND d.id=NEW.decision_ref
    AND d.actor_id<>NEW.submitted_by AND d.actor_id IS DISTINCT FROM e.account_ref
    AND d.fresh_password_verified_at IS NOT NULL AND d.accepted_case_revision=c.revision
    AND ((NEW.status='APPROVED' AND d.action='APPROVE' AND c.status='PENDING_OWNER')
     OR (NEW.status='RETURNED' AND d.action='RETURN' AND c.status='RETURNED')
     OR (NEW.status='REJECTED' AND d.action='REJECT' AND c.status='REJECTED'))
 ) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Original independent correction decision is required';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_correction_link_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_attendance_change r JOIN cg03_case c
  ON c.id=r.case_ref AND c.realm_id=r.root_realm_id AND c.hr_attendance_change_id=r.id
  AND c.hr_attendance_change_digest=r.source_digest AND c.case_kind='ATTENDANCE_CORRECTION'
  AND c.proposer_id=r.submitted_by AND c.proposal_revision=r.expected_version
  WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.id)
 THEN RAISE EXCEPTION 'Original correction case required before commit'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_document_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Document intent history cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.revision<>1 OR NOT EXISTS(SELECT 1 FROM cg19_document_template t
   WHERE t.id=NEW.template_id AND t.realm_id=NEW.root_realm_id AND t.version=NEW.template_version AND t.template_kind='HR_'||NEW.kind AND t.status='APPROVED')
  THEN RAISE EXCEPTION 'Approved matching HR template required'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['status','case_ref','decision_ref','decided_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['status','case_ref','decision_ref','decided_at'])
 THEN RAISE EXCEPTION 'Original document intent cannot change'; END IF;
 IF OLD.status='DRAFT' AND NEW.status='SUBMITTED' AND EXISTS(SELECT 1 FROM cg03_case c
  WHERE c.id=NEW.case_ref AND c.realm_id=NEW.root_realm_id AND c.hr_document_request_id=NEW.id AND c.hr_document_source_digest=NEW.source_digest
  AND c.proposal_revision=NEW.revision AND c.proposer_id=NEW.created_by AND c.status='SUBMITTED')
 THEN RETURN NEW; END IF;
 IF OLD.status='SUBMITTED' AND NEW.case_ref=OLD.case_ref AND EXISTS(
  SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.case_id=c.id AND d.realm_id=c.realm_id
  JOIN account a ON a.id=d.actor_id AND a.realm_id=d.realm_id AND a.status='ACTIVE'
  JOIN account_role ar ON ar.account_id=a.id AND ar.realm_id=a.realm_id AND ar.revoked_at IS NULL
  JOIN role r ON r.id=ar.role_id AND r.realm_id=ar.realm_id AND r.active AND r.is_protected
  WHERE c.id=NEW.case_ref AND c.realm_id=NEW.root_realm_id AND c.hr_document_request_id=NEW.id AND c.hr_document_source_digest=NEW.source_digest
   AND d.id=NEW.decision_ref AND d.actor_id<>NEW.created_by AND d.fresh_password_verified_at IS NOT NULL AND d.accepted_case_revision=c.revision
   AND NOT EXISTS(SELECT 1 FROM hr_employee e WHERE e.root_realm_id=NEW.root_realm_id AND e.id=NEW.employee_id AND e.account_ref=d.actor_id)
   AND NOT EXISTS(SELECT 1 FROM hr_employee_application ap WHERE ap.root_realm_id=NEW.root_realm_id AND ap.id=NEW.application_id AND ap.applicant_account_ref=d.actor_id)
   AND ((NEW.status='APPROVED' AND d.action='APPROVE' AND c.status='FINAL_APPROVED')
    OR (NEW.status='RETURNED' AND d.action='RETURN' AND c.status='RETURNED')
    OR (NEW.status='REJECTED' AND d.action='REJECT' AND c.status='REJECTED'))
 ) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Actual original independent document decision required';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_employment_change_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Employment change history cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.revision<>1 THEN RAISE EXCEPTION 'Employment change starts as draft'; END IF;
  RETURN NEW;
 END IF;
 IF (NEW.id,NEW.root_realm_id,NEW.reference,NEW.employee_id,NEW.kind,NEW.created_by,NEW.request_key,NEW.request_digest,NEW.created_at)
 IS DISTINCT FROM (OLD.id,OLD.root_realm_id,OLD.reference,OLD.employee_id,OLD.kind,OLD.created_by,OLD.request_key,OLD.request_digest,OLD.created_at)
 THEN RAISE EXCEPTION 'Original employment change identity cannot change'; END IF;
 IF OLD.status='APPROVED_PENDING_EFFECT' AND NEW.status=OLD.status AND NEW.effect_attempt_count=OLD.effect_attempt_count+1
  AND NEW.next_effect_attempt_at>now() AND
  (to_jsonb(NEW)-ARRAY['effect_attempt_count','next_effect_attempt_at','updated_at']) =
  (to_jsonb(OLD)-ARRAY['effect_attempt_count','next_effect_attempt_at','updated_at'])
 THEN RETURN NEW; END IF;
 IF OLD.status='DRAFT' AND NEW.status='DRAFT' AND NEW.revision=OLD.revision+1 THEN RETURN NEW; END IF;
 IF (to_jsonb(NEW)-ARRAY['status','case_ref','decision_ref','cancel_event_ref','new_assignment_ref','decided_at','applied_at','updated_at','last_command_key','last_command_digest'])
 IS DISTINCT FROM
 (to_jsonb(OLD)-ARRAY['status','case_ref','decision_ref','cancel_event_ref','new_assignment_ref','decided_at','applied_at','updated_at','last_command_key','last_command_digest'])
 THEN RAISE EXCEPTION 'Submitted employment change evidence is frozen'; END IF;
 IF OLD.status='DRAFT' AND NEW.status='SUBMITTED' AND EXISTS(
  SELECT 1 FROM cg03_case c WHERE c.id=NEW.case_ref AND c.realm_id=NEW.root_realm_id AND c.hr_employment_change_id=NEW.id
   AND c.hr_employment_change_digest=NEW.source_digest AND c.proposal_revision=NEW.revision AND c.proposer_id=NEW.created_by
   AND c.status='SUBMITTED' AND c.case_kind=CASE WHEN NEW.kind IN('RESIGNATION','EXIT') THEN 'HR_EXIT_REVIEW' ELSE 'HR_TRANSFER_PROMOTION' END
 ) THEN RETURN NEW; END IF;
 IF NEW.case_ref IS DISTINCT FROM OLD.case_ref THEN RAISE EXCEPTION 'Original case cannot change'; END IF;
 IF OLD.status='SUBMITTED' AND NEW.status='WITHDRAWN' AND EXISTS(
  SELECT 1 FROM cg03_case c JOIN cg03_case_event ev ON ev.case_id=c.id AND ev.realm_id=c.realm_id
   WHERE c.id=NEW.case_ref AND c.realm_id=NEW.root_realm_id AND c.status='CANCELLED'
    AND c.hr_employment_change_id=NEW.id AND ev.id=NEW.cancel_event_ref AND ev.actor_id=NEW.created_by AND ev.action='CANCELLED'
 ) THEN RETURN NEW; END IF;
 IF OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','APPROVED_PENDING_EFFECT') AND EXISTS(
  SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.case_id=c.id AND d.realm_id=c.realm_id
   JOIN hr_employee e ON e.id=NEW.employee_id AND e.root_realm_id=NEW.root_realm_id
   JOIN account reviewer ON reviewer.id=d.actor_id AND reviewer.realm_id=d.realm_id AND reviewer.status='ACTIVE'
   JOIN account_role ar ON ar.account_id=d.actor_id AND ar.realm_id=d.realm_id AND ar.revoked_at IS NULL
   JOIN role rr ON rr.id=ar.role_id AND rr.realm_id=ar.realm_id AND rr.active AND rr.is_protected
   WHERE c.id=NEW.case_ref AND c.realm_id=NEW.root_realm_id AND c.hr_employment_change_id=NEW.id
    AND c.hr_employment_change_digest=NEW.source_digest AND c.proposal_revision=NEW.revision
    AND d.id=NEW.decision_ref AND d.actor_id<>NEW.created_by AND d.actor_id IS DISTINCT FROM e.account_ref
    AND d.fresh_password_verified_at IS NOT NULL AND d.accepted_case_revision=c.revision
    AND ((NEW.status='APPROVED_PENDING_EFFECT' AND d.action='APPROVE' AND c.status='PENDING_OWNER')
     OR (NEW.status='RETURNED' AND d.action='RETURN' AND c.status='RETURNED')
     OR (NEW.status='REJECTED' AND d.action='REJECT' AND c.status='REJECTED'))
 ) THEN RETURN NEW; END IF;
 IF OLD.status='APPROVED_PENDING_EFFECT' AND NEW.status='APPLIED' AND NEW.decision_ref=OLD.decision_ref
  AND NEW.decided_at=OLD.decided_at AND NEW.effective_date<=CURRENT_DATE
  AND (NEW.target_account_ref IS NULL OR EXISTS(SELECT 1 FROM cg01_hr_employment_effect eff
   WHERE eff.realm_id=NEW.root_realm_id AND eff.change_ref=NEW.id AND eff.source_digest=NEW.source_digest
    AND eff.source_revision=NEW.revision AND eff.case_ref=NEW.case_ref AND eff.decision_ref=NEW.decision_ref
    AND eff.target_account_ref=NEW.target_account_ref AND eff.prior_access_version=NEW.expected_access_version
    AND eff.approved_role_ref IS NOT DISTINCT FROM NEW.proposed_role_ref
    AND eff.approved_role_revision IS NOT DISTINCT FROM NEW.expected_role_revision))
  AND EXISTS(
   SELECT 1 FROM hr_employment_assignment prior JOIN hr_employee e ON e.id=NEW.employee_id AND e.root_realm_id=NEW.root_realm_id
    WHERE prior.id=NEW.prior_assignment_id AND prior.root_realm_id=NEW.root_realm_id AND prior.employee_id=e.id
    AND prior.valid_to=NEW.effective_date AND prior.assignment_version=NEW.prior_assignment_version+1
    AND e.status_version=NEW.prior_employee_version+1 AND (
     (NEW.kind IN('RESIGNATION','EXIT') AND e.status='EXITED' AND NOT EXISTS(SELECT 1 FROM hr_employment_assignment a
       WHERE a.root_realm_id=e.root_realm_id AND a.employee_id=e.id AND a.valid_to IS NULL))
     OR (NEW.kind IN('TRANSFER','PROMOTION','DEPUTATION') AND e.status IN('ACTIVE','PROBATION') AND EXISTS(
      SELECT 1 FROM hr_employment_assignment a WHERE a.root_realm_id=e.root_realm_id AND a.employee_id=e.id
      AND a.id=NEW.new_assignment_ref AND a.valid_from=NEW.effective_date AND a.valid_to IS NULL
      AND a.branch_ref=NEW.proposed_branch_ref AND a.department_ref IS NOT DISTINCT FROM NEW.proposed_department_ref
      AND a.manager_employee_ref IS NOT DISTINCT FROM NEW.proposed_manager_ref AND a.designation=NEW.proposed_designation)))
  ) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Matching original employment decision/effect required';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_hr_template_ready_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (TG_OP='INSERT' OR NEW.status IN('SUBMITTED','APPROVED')) AND NOT EXISTS(SELECT 1 FROM cg19_document_template t
 WHERE t.realm_id=NEW.root_realm_id AND t.id=NEW.template_id AND t.version=NEW.template_version AND t.status='APPROVED'
 AND t.hr_signatory_name IS NOT NULL AND cg19_hr_template_assets_ready(t.realm_id,t.hr_signature_file_ref,t.hr_seal_file_ref))
 THEN RAISE EXCEPTION 'Original authorized template assets unavailable'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg10_leave_link_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM hr_leave_request r JOIN cg03_case c
  ON c.id=r.case_ref AND c.realm_id=r.root_realm_id AND c.hr_leave_request_id=r.id
  AND c.hr_leave_source_digest=r.source_digest AND c.case_kind='LEAVE_REQUEST'
  AND c.proposer_id=r.submitted_by
  WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.id)
 THEN RAISE EXCEPTION 'An original leave case is required before commit'; END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg10_leave_request_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Leave requests cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'SUBMITTED' OR NEW.case_ref IS NOT NULL OR NEW.decision_ref IS NOT NULL THEN
   RAISE EXCEPTION 'New leave must begin as an original submission';
  END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['case_ref','status','decision_ref','cancel_event_ref','decided_at']) IS DISTINCT FROM
    (to_jsonb(OLD)-ARRAY['case_ref','status','decision_ref','cancel_event_ref','decided_at']) THEN
  RAISE EXCEPTION 'Submitted leave evidence cannot be changed';
 END IF;
 IF OLD.case_ref IS NULL AND NEW.case_ref IS NOT NULL AND OLD.status='SUBMITTED' AND
   NEW.status='SUBMITTED' AND NEW.decision_ref IS NULL AND EXISTS(
    SELECT 1 FROM cg03_case c WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.case_ref
     AND c.case_kind='LEAVE_REQUEST' AND c.hr_leave_request_id=NEW.id
     AND c.hr_leave_source_digest=NEW.source_digest AND c.proposer_id=NEW.submitted_by
   ) THEN RETURN NEW; END IF;
 IF OLD.status='SUBMITTED' AND OLD.case_ref IS NOT NULL AND NEW.case_ref=OLD.case_ref AND NEW.status='CANCELLED' AND EXISTS(
   SELECT 1 FROM cg03_case c JOIN cg03_case_event ev ON ev.case_id=c.id AND ev.realm_id=c.realm_id
   WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.case_ref AND c.case_kind='LEAVE_REQUEST'
    AND c.hr_leave_request_id=NEW.id AND c.hr_leave_source_digest=NEW.source_digest
    AND c.status='CANCELLED' AND c.proposer_id=NEW.submitted_by
    AND ev.id=NEW.cancel_event_ref AND ev.action='CANCELLED' AND ev.actor_id=NEW.submitted_by
 ) THEN RETURN NEW; END IF;
 IF OLD.status='SUBMITTED' AND OLD.case_ref IS NOT NULL AND NEW.case_ref=OLD.case_ref AND
   NEW.status IN('APPROVED','RETURNED','REJECTED') AND EXISTS(
    SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.case_id=c.id AND d.realm_id=c.realm_id
    JOIN account reviewer ON reviewer.id=d.actor_id AND reviewer.realm_id=d.realm_id AND reviewer.status='ACTIVE'
    JOIN account_role ar ON ar.account_id=reviewer.id AND ar.realm_id=reviewer.realm_id AND ar.revoked_at IS NULL
    JOIN role cr ON cr.id=ar.role_id AND cr.realm_id=ar.realm_id AND cr.active AND cr.is_protected
    WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.case_ref
     AND c.case_kind='LEAVE_REQUEST' AND c.hr_leave_request_id=NEW.id
     AND c.hr_leave_source_digest=NEW.source_digest AND d.id=NEW.decision_ref
     AND d.actor_id<>NEW.submitted_by AND d.fresh_password_verified_at IS NOT NULL
     AND d.accepted_case_revision=c.revision
     AND ((NEW.status='APPROVED' AND d.action='APPROVE' AND c.status='PENDING_OWNER') OR
          (NEW.status='RETURNED' AND d.action='RETURN' AND c.status='RETURNED') OR
          (NEW.status='REJECTED' AND d.action='REJECT' AND c.status='REJECTED'))
   ) THEN
  IF NEW.status='APPROVED' THEN
   PERFORM id FROM hr_employee WHERE root_realm_id=NEW.root_realm_id AND id=NEW.employee_id FOR UPDATE;
   IF EXISTS(SELECT 1 FROM hr_leave_request other WHERE other.root_realm_id=NEW.root_realm_id
      AND other.employee_id=NEW.employee_id AND other.id<>NEW.id AND other.status='APPROVED'
      AND other.start_date<=NEW.end_date AND other.end_date>=NEW.start_date) THEN
    RAISE EXCEPTION 'Approved leave dates overlap';
   END IF;
  END IF;
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Matching original leave decision is required';
END $function$
;
CREATE OR REPLACE FUNCTION public.cg10_revision_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Submitted employee revisions cannot be deleted';
 END IF;
 IF OLD.cg03_case_ref IS NULL AND NEW.cg03_case_ref IS NOT NULL AND
    (OLD.id,OLD.root_realm_id,OLD.application_id,OLD.revision_no,
     OLD.source_digest,OLD.source_snapshot,OLD.private_file_versions,
     OLD.submitted_by,OLD.submitted_at)
    IS NOT DISTINCT FROM
    (NEW.id,NEW.root_realm_id,NEW.application_id,NEW.revision_no,
     NEW.source_digest,NEW.source_snapshot,NEW.private_file_versions,
     NEW.submitted_by,NEW.submitted_at)
 THEN RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Submitted employee revisions cannot be changed';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_accrual_expected(p_root uuid, p_run uuid, p_expense uuid, p_payable uuid, p_deduction uuid, p_employer uuid, p_statutory uuid)
 RETURNS TABLE(account_ref uuid, branch_ref uuid, dr numeric, cr numeric)
 LANGUAGE sql
 STABLE
AS $function$
 WITH totals AS (
 SELECT a.branch_ref,sum(a.gross) gross,sum(a.deductions) deductions,sum(a.net) net,sum(a.employer) employer,sum(a.statutory) statutory
 FROM payroll_line l CROSS JOIN LATERAL cg11_frozen_branch_allocation(l.root_realm_id,l.id) a
 WHERE l.root_realm_id=p_root AND l.run_id=p_run GROUP BY a.branch_ref
 )
 SELECT v.ref,t.branch_ref,v.dr,v.cr FROM totals t CROSS JOIN LATERAL (VALUES
 (p_expense,t.gross+t.employer,0::numeric),(p_payable,0::numeric,t.net),(p_deduction,0::numeric,t.deductions-t.statutory),
 (p_employer,0::numeric,t.employer),(p_statutory,0::numeric,t.statutory)) v(ref,dr,cr)
 WHERE v.ref IS NOT NULL AND (v.dr>0 OR v.cr>0)
 ORDER BY t.branch_ref,v.ref
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_adjustment_original_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM payroll_adjustment x JOIN payroll_run r ON r.root_realm_id=x.root_realm_id AND r.id=x.target_run_ref
 JOIN cg03_case c ON c.realm_id=r.root_realm_id AND c.id=r.approval_case_ref AND c.status='PENDING_OWNER' AND c.case_kind='PAYROLL_RUN_RELEASE'
 JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id AND d.id=NEW.decision_ref AND d.action='APPROVE' AND d.actor_id<>c.proposer_id AND d.fresh_password_verified_at IS NOT NULL
 JOIN payroll_run_review_snapshot s ON s.root_realm_id=c.realm_id AND s.id=c.payroll_run_review_ref
 JOIN payroll_run_revision v ON v.root_realm_id=s.root_realm_id AND v.run_id=s.run_id AND v.revision=s.source_revision AND v.source_digest=s.source_digest
 CROSS JOIN LATERAL jsonb_array_elements(v.snapshot->'adjustments') adj
 WHERE x.root_realm_id=NEW.root_realm_id AND x.id=NEW.adjustment_ref AND x.target_run_ref=NEW.target_run_ref AND x.original_line_ref=NEW.original_line_ref AND x.correction_digest=NEW.correction_digest
 AND r.status='SUBMITTED' AND adj->>'sourceRef'=x.id::text AND adj->>'sourceDigest'=x.correction_digest
 AND (adj->>'minor')::bigint=abs(x.delta_minor)
 AND adj->>'kind'=CASE WHEN x.delta_minor>0 THEN 'LATE_ARREARS' ELSE 'LATE_RECOVERY' END
 ) THEN RAISE EXCEPTION 'Original late adjustment review required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_attempt_allocation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Original attempt allocation is source-generated'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE i payroll_batch_item%ROWTYPE;b payroll_batch%ROWTYPE;l payroll_line%ROWTYPE;a payroll_accrual%ROWTYPE;r payroll_run%ROWTYPE; paid numeric;
BEGIN
 SELECT * INTO i FROM payroll_batch_item WHERE root_realm_id=NEW.root_realm_id AND id=NEW.item_ref FOR UPDATE;
 SELECT * INTO b FROM payroll_batch WHERE root_realm_id=NEW.root_realm_id AND id=i.batch_ref;
 SELECT * INTO l FROM payroll_line WHERE root_realm_id=NEW.root_realm_id AND id=i.line_ref;
 SELECT * INTO a FROM payroll_accrual WHERE root_realm_id=NEW.root_realm_id AND run_id=b.run_id;
 SELECT * INTO r FROM payroll_run WHERE root_realm_id=NEW.root_realm_id AND id=b.run_id;
 SELECT coalesce(sum(paid_minor),0) INTO paid FROM payroll_attempt_outcome WHERE root_realm_id=NEW.root_realm_id AND item_ref=i.id;
 IF EXISTS(SELECT 1 FROM payroll_attempt_outcome WHERE root_realm_id=NEW.root_realm_id AND item_ref=i.id AND (attempt_status NOT IN('POSTED','REJECTED','FAILED_VERIFIED','RETURNED_VERIFIED') OR reversed OR (attempt_status='POSTED' AND paid_minor<>amount_minor)))
 OR paid+NEW.amount_minor>l.net_minor OR NOT EXISTS(SELECT 1 FROM finance_voucher v WHERE v.root_realm_id=NEW.root_realm_id AND v.id=NEW.voucher_ref AND v.status='DRAFT' AND v.version=1 AND v.voucher_type='PAYMENT' AND v.total_minor=NEW.amount_minor AND v.debit_account_id=a.payable_ref AND v.credit_account_id=b.payment_account_ref AND v.payment_account_id=b.payment_account_ref AND v.branch_id IS NOT DISTINCT FROM r.branch_ref)
 THEN RAISE EXCEPTION 'Original payout pending or remaining due exceeded' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Payroll audit history is immutable'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_batch_item_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b payroll_batch%ROWTYPE;l payroll_line%ROWTYPE;
BEGIN
 SELECT * INTO b FROM payroll_batch WHERE root_realm_id=NEW.root_realm_id AND id=NEW.batch_ref;
 SELECT * INTO l FROM payroll_line WHERE root_realm_id=NEW.root_realm_id AND id=NEW.line_ref;
 IF l.run_id IS DISTINCT FROM b.run_id OR l.entitlement_state<>'RELEASE_ELIGIBLE' OR l.net_minor<=0 OR
 (b.method='BANK' AND NOT EXISTS(SELECT 1 FROM employee_payout_instruction_effective p WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.destination_ref AND p.employee_ref=l.employee_ref AND p.revision=NEW.destination_revision AND p.destination_fingerprint=NEW.destination_fingerprint AND p.status='APPROVED' AND p.effective_from<=(now() AT TIME ZONE 'Asia/Kolkata')::date AND (p.effective_until IS NULL OR p.effective_until>(now() AT TIME ZONE 'Asia/Kolkata')::date))) OR
 (b.method='CASH' AND NEW.destination_ref IS NOT NULL)
 THEN RAISE EXCEPTION 'Original eligible payroll entitlement and destination required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_component_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Payroll components are immutable; create a new policy version'; END IF;
 IF NOT EXISTS(SELECT 1 FROM payroll_policy p WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.policy_id AND p.status='DRAFT' FOR UPDATE) THEN RAISE EXCEPTION 'Draft policy required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_frozen_branch_allocation(p_root uuid, p_line uuid)
 RETURNS TABLE(branch_ref uuid, gross numeric, deductions numeric, net numeric, employer numeric, statutory numeric)
 LANGUAGE sql
 STABLE
AS $function$
 WITH original AS (
  SELECT l.* FROM payroll_line l WHERE l.root_realm_id=p_root AND l.id=p_line
 ), raw AS (
  SELECT (v->>'branchRef')::uuid branch_ref,
   (v->>'baseMinor')::numeric+(v->>'allowanceMinor')::numeric gross,
   (v->>'deductionMinor')::numeric deductions,(v->>'employerMinor')::numeric employer
  FROM original o CROSS JOIN LATERAL jsonb_array_elements(o.source_snapshot->'amounts'->'allocation') v
  UNION ALL SELECT o.branch_ref,0::numeric,0::numeric,0::numeric FROM original o
 ), grouped AS (
  SELECT raw.branch_ref,sum(raw.gross) gross,sum(raw.deductions) deductions,sum(raw.employer) employer FROM raw GROUP BY raw.branch_ref
 ), added AS (
  SELECT g.branch_ref,g.gross+CASE WHEN g.branch_ref=o.branch_ref THEN o.bonus_minor+o.arrears_minor ELSE 0 END gross,
   g.deductions,g.employer,o.deduction_minor-(SELECT sum(deductions) FROM grouped) extra,o.statutory_minor,
   CASE WHEN g.branch_ref=o.branch_ref THEN 0 ELSE 1 END priority FROM grouped g CROSS JOIN original o
 ), extra AS (
  SELECT a.*,least(a.gross-a.deductions,greatest(a.extra-coalesce(sum(a.gross-a.deductions) OVER(ORDER BY a.priority,a.branch_ref ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0),0)) additional FROM added a
 ), classified AS (
  SELECT x.branch_ref,x.gross,x.deductions+x.additional deductions,x.gross-x.deductions-x.additional net,x.employer,x.statutory_minor,x.priority FROM extra x
 )
 SELECT c.branch_ref,c.gross,c.deductions,c.net,c.employer,
 least(c.deductions,greatest(c.statutory_minor-coalesce(sum(c.deductions) OVER(ORDER BY c.priority,c.branch_ref ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0),0)) statutory
 FROM classified c ORDER BY c.branch_ref
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_guard_accrual()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r payroll_run%ROWTYPE; gross numeric; net numeric; deductions numeric; employer numeric; statutory numeric;
BEGIN
 SELECT * INTO r FROM payroll_run WHERE root_realm_id=NEW.root_realm_id AND id=NEW.run_id FOR UPDATE;
 IF NOT FOUND OR r.status<>'APPROVED_FROZEN' OR r.approved_decision_ref IS DISTINCT FROM NEW.decision_ref OR r.snapshot_digest IS DISTINCT FROM NEW.source_digest OR NOT EXISTS(
 SELECT 1 FROM cg03_case c JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
 WHERE c.realm_id=r.root_realm_id AND c.id=r.approval_case_ref AND c.status='OWNER_COMPLETED' AND c.case_kind='PAYROLL_RUN_RELEASE'
 AND d.id=NEW.decision_ref AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL AND d.actor_id<>c.proposer_id AND d.actor_id<>r.creator)
 THEN RAISE EXCEPTION 'Original payroll approval required' USING ERRCODE='23514'; END IF;
 SELECT coalesce(sum(gross_minor),0),coalesce(sum(net_minor),0),coalesce(sum(deduction_minor),0),coalesce(sum(employer_minor),0),coalesce(sum(statutory_minor),0)
 INTO gross,net,deductions,employer,statutory FROM payroll_line WHERE root_realm_id=r.root_realm_id AND run_id=r.id;
 IF gross+employer<=0 OR (SELECT count(DISTINCT v) FROM unnest(ARRAY[NEW.expense_ref,NEW.payable_ref,NEW.deduction_ref,NEW.employer_ref,NEW.statutory_ref]) v WHERE v IS NOT NULL)<>num_nonnulls(NEW.expense_ref,NEW.payable_ref,NEW.deduction_ref,NEW.employer_ref,NEW.statutory_ref)
 OR (deductions-statutory>0)<>(NEW.deduction_ref IS NOT NULL) OR (employer>0)<>(NEW.employer_ref IS NOT NULL) OR (statutory>0)<>(NEW.statutory_ref IS NOT NULL)
 THEN RAISE EXCEPTION 'Invalid payroll account classification' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM journal j JOIN financial_year y ON y.id=j.financial_year_id AND y.root_realm_id=j.root_realm_id
 WHERE j.id=NEW.journal_ref AND j.root_realm_id=r.root_realm_id AND j.source_ref=r.id AND j.immutable_source_event_key=NEW.decision_ref AND j.immutable_payload_digest=NEW.request_digest AND j.posting_kind='GENERAL' AND j.posting_date=r.period_until-1 AND y.status='OPEN')
 THEN RAISE EXCEPTION 'Original CG09 accrual required' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM payroll_line l CROSS JOIN LATERAL (
 SELECT coalesce(sum(x.gross),0) gross,coalesce(sum(x.deductions),0) deductions,coalesce(sum(x.net),0) net,coalesce(sum(x.employer),0) employer,coalesce(sum(x.statutory),0) statutory,
 count(*) n,coalesce(bool_or(x.gross<0 OR x.deductions<0 OR x.net<0 OR x.employer<0 OR x.statutory<0 OR x.statutory>x.deductions OR (r.branch_ref IS NOT NULL AND x.branch_ref<>r.branch_ref)),true) invalid
 FROM cg11_frozen_branch_allocation(l.root_realm_id,l.id) x) a
 WHERE l.root_realm_id=r.root_realm_id AND l.run_id=r.id AND (a.n=0 OR a.invalid OR (a.gross,a.deductions,a.net,a.employer,a.statutory) IS DISTINCT FROM (l.gross_minor::numeric,l.deduction_minor::numeric,l.net_minor::numeric,l.employer_minor::numeric,l.statutory_minor::numeric)))
 OR EXISTS(SELECT 1 FROM (VALUES(NEW.expense_ref,'EXPENSE'),(NEW.payable_ref,'LIABILITY'),(NEW.deduction_ref,'LIABILITY'),(NEW.employer_ref,'LIABILITY'),(NEW.statutory_ref,'LIABILITY')) x(ref,category)
 WHERE x.ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM finance_account a JOIN account_group g ON g.root_realm_id=a.root_realm_id AND g.id=a.group_id WHERE a.root_realm_id=r.root_realm_id AND a.id=x.ref AND a.account_kind='GENERAL' AND a.status='ACTIVE' AND g.category=x.category AND (a.branch_id IS NULL OR a.branch_id=r.branch_ref)))
 OR EXISTS(WITH expected AS (SELECT * FROM cg11_accrual_expected(r.root_realm_id,r.id,NEW.expense_ref,NEW.payable_ref,NEW.deduction_ref,NEW.employer_ref,NEW.statutory_ref)),
 actual AS(SELECT account_id,branch_id,debit_minor::numeric,credit_minor::numeric FROM journal_line WHERE root_realm_id=r.root_realm_id AND journal_id=NEW.journal_ref)
 (SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected))
 THEN RAISE EXCEPTION 'Payroll accrual does not match original frozen branch obligations' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_guard_bank_release()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b payroll_batch%ROWTYPE; t payroll_payout_attempt%ROWTYPE; signer uuid;
BEGIN
 IF OLD.status<>'APPROVED' OR NEW.status<>'PAYMENT_REQUESTED' THEN RETURN NEW; END IF;
 -- Serialize every original outgoing bank request on its genuine funding account;
 -- original journal posting also locks this account. No separate funds ledger.
 IF NEW.payment_account_id IS NOT NULL THEN
 PERFORM 1 FROM finance_account fa WHERE fa.root_realm_id=NEW.root_realm_id AND fa.id=NEW.payment_account_id AND fa.account_kind='BANK' FOR UPDATE;
 END IF;
 SELECT * INTO t FROM payroll_payout_attempt WHERE root_realm_id=NEW.root_realm_id AND voucher_ref=NEW.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT batch.* INTO b FROM payroll_batch_item i JOIN payroll_batch batch ON batch.root_realm_id=i.root_realm_id AND batch.id=i.batch_ref
 WHERE i.root_realm_id=t.root_realm_id AND i.id=t.item_ref;
 IF b.method<>'BANK' THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM finance_account a JOIN cash_bank_account c ON c.root_realm_id=a.root_realm_id AND c.account_id=a.id
 WHERE a.root_realm_id=t.root_realm_id AND a.id=b.payment_account_ref AND a.status='ACTIVE' AND c.status='ACTIVE' AND c.kind='BANK'
 AND (a.branch_id IS NULL OR a.branch_id=NEW.branch_id) AND NEW.payment_account_id=a.id AND NEW.credit_account_id=a.id)
 THEN RAISE EXCEPTION 'Original active bank account unavailable' USING ERRCODE='P0916'; END IF;
 SELECT d.actor_id INTO signer FROM cg03_case c
 JOIN cg03_finance_owner_effect e ON e.realm_id=c.realm_id AND e.case_id=c.id
 JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id AND d.id=e.final_decision_id
 JOIN account a ON a.realm_id=d.realm_id AND a.id=d.actor_id AND a.status='ACTIVE'
 WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.approval_case_id AND c.case_kind='FINANCE_VOUCHER' AND c.finance_voucher_id=NEW.id
 AND c.finance_voucher_revision=NEW.version AND c.status IN('PENDING_OWNER','OWNER_COMPLETED')
 AND d.action='APPROVE' AND d.fresh_password_verified_at IS NOT NULL AND d.actor_id<>c.proposer_id AND d.actor_id<>NEW.created_by
 AND EXISTS(SELECT 1 FROM account_role ar JOIN role rr ON rr.id=ar.role_id AND rr.realm_id=ar.realm_id AND rr.active AND rr.is_protected
 WHERE ar.realm_id=a.realm_id AND ar.account_id=a.id AND ar.revoked_at IS NULL)
 FOR SHARE OF c,e,d,a;
 IF signer IS NULL THEN RAISE EXCEPTION 'Current independent payment signing authority required' USING ERRCODE='P0938'; END IF;
 IF cg11_reconciled_bank_available(NEW.root_realm_id,b.payment_account_ref,NEW.id)<NEW.total_minor
 THEN RAISE EXCEPTION 'Insufficient independently reconciled bank funds' USING ERRCODE='P0939'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_guard_bound_voucher()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE i payroll_batch_item%ROWTYPE;b payroll_batch%ROWTYPE;l payroll_line%ROWTYPE;
BEGIN
 SELECT item.* INTO i FROM payroll_payout_attempt t JOIN payroll_batch_item item ON item.root_realm_id=t.root_realm_id AND item.id=t.item_ref WHERE t.root_realm_id=OLD.root_realm_id AND t.voucher_ref=OLD.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.version<>OLD.version OR (to_jsonb(NEW)-ARRAY['status','approval_case_id','proof_file_id','proof_file_revision','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','approval_case_id','proof_file_id','proof_file_revision','updated_at'])
 THEN RAISE EXCEPTION 'Payroll voucher financial source cannot change' USING ERRCODE='23514'; END IF;
 IF NEW.status='PAYMENT_REQUESTED' AND OLD.status='APPROVED' THEN
 SELECT * INTO b FROM payroll_batch WHERE root_realm_id=i.root_realm_id AND id=i.batch_ref;
 SELECT * INTO l FROM payroll_line WHERE root_realm_id=i.root_realm_id AND id=i.line_ref;
 PERFORM 1 FROM hr_employee WHERE root_realm_id=l.root_realm_id AND id=l.employee_ref FOR UPDATE;
 IF b.method='BANK' AND NOT EXISTS(SELECT 1 FROM employee_payout_instruction_effective p WHERE p.root_realm_id=i.root_realm_id AND p.id=i.destination_ref AND p.employee_ref=l.employee_ref AND p.status='APPROVED' AND p.revision=i.destination_revision AND p.destination_fingerprint=i.destination_fingerprint AND p.effective_from<=(now() AT TIME ZONE 'Asia/Kolkata')::date AND (p.effective_until IS NULL OR p.effective_until>(now() AT TIME ZONE 'Asia/Kolkata')::date))
 THEN RAISE EXCEPTION 'Pinned employee destination changed' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM cash_bank_account c JOIN finance_account f ON f.root_realm_id=c.root_realm_id AND f.id=c.account_id WHERE c.root_realm_id=b.root_realm_id AND c.account_id=b.payment_account_ref AND c.status='ACTIVE' AND f.status='ACTIVE' AND f.account_kind=b.method)
 THEN RAISE EXCEPTION 'Original payout account unavailable' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_guard_provider_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t payroll_payout_attempt%ROWTYPE;
BEGIN
 IF TG_OP<>'UPDATE' OR (NEW.status<>'VERIFIED' AND NOT NEW.payroll_failure_verified) THEN RETURN NEW; END IF;
 SELECT * INTO t FROM payroll_payout_attempt WHERE root_realm_id=NEW.root_realm_id AND voucher_ref=NEW.voucher_id FOR SHARE;
 IF NOT FOUND OR t.provider_state='NOT_ENABLED' THEN RETURN NEW; END IF;
 IF (NEW.status='VERIFIED' AND (t.provider_state<>'PROCESSED_AWAITING_PROOF' OR NEW.method<>'BANK_STATEMENT' OR NEW.bank_reference IS NULL OR t.provider_utr_digest IS NULL OR t.provider_utr_digest<>encode(digest(t.id::text||':'||upper(btrim(NEW.bank_reference)),'sha256'),'hex')))
 OR (NEW.payroll_failure_verified AND t.provider_state<>'FAILED_AWAITING_PROOF')
 THEN RAISE EXCEPTION 'Original provider status and independent bank proof must agree' USING ERRCODE='P0940'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_guard_return_reconciliation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE expected record;
BEGIN
 SELECT rev.payroll_return_bank_reference AS ref,t.amount_minor AS amount,b.payment_account_ref AS bank
 INTO expected
 FROM finance_manual_journal_reversal rev JOIN finance_voucher_posting fp ON fp.root_realm_id=rev.root_realm_id AND fp.journal_id=rev.original_journal_id
 JOIN payroll_payout_attempt t ON t.root_realm_id=fp.root_realm_id AND t.voucher_ref=fp.voucher_id
 JOIN payroll_batch_item i ON i.root_realm_id=t.root_realm_id AND i.id=t.item_ref
 JOIN payroll_batch b ON b.root_realm_id=i.root_realm_id AND b.id=i.batch_ref
 WHERE rev.root_realm_id=NEW.root_realm_id AND rev.reversal_journal_id=NEW.journal_id AND rev.payroll_return_bank_reference IS NOT NULL;
 IF FOUND AND (NEW.bank_account_id<>expected.bank OR NEW.statement_amount_minor<>expected.amount OR NEW.posted_amount_minor<>expected.amount OR NEW.variance_minor<>0 OR upper(btrim(NEW.bank_item_ref))<>expected.ref) THEN
  RAISE EXCEPTION 'Return requires the exact original bank credit' USING ERRCODE='P0926';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_line_original_review()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
 SELECT 1 FROM payroll_run r JOIN cg03_case c ON c.realm_id=r.root_realm_id AND c.id=r.approval_case_ref AND c.case_kind='PAYROLL_RUN_RELEASE' AND c.status='PENDING_OWNER'
 JOIN payroll_run_review_snapshot s ON s.root_realm_id=c.realm_id AND s.id=c.payroll_run_review_ref AND s.run_id=r.id AND s.source_revision=NEW.source_revision AND s.source_digest=r.snapshot_digest
 JOIN payroll_run_revision v ON v.root_realm_id=s.root_realm_id AND v.run_id=s.run_id AND v.revision=s.source_revision AND v.source_digest=s.source_digest
 CROSS JOIN LATERAL jsonb_array_elements(v.snapshot->'lines') l
 WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.run_id AND r.status='SUBMITTED' AND r.period_key=NEW.period_key
 AND l->>'employeeRef'=NEW.employee_ref::text AND l->>'branchRef'=NEW.branch_ref::text AND ((l->>'status'='CALCULATED' AND NEW.entitlement_state='RELEASE_ELIGIBLE') OR (l->>'status'='HELD' AND NEW.entitlement_state='HELD'))
 AND l=NEW.source_snapshot AND (l->'amounts'->>'baseMinor')::bigint=NEW.base_minor
 AND (l->'amounts'->>'allowanceMinor')::bigint=NEW.allowance_minor AND (l->'amounts'->>'bonusMinor')::bigint=NEW.bonus_minor AND (l->'amounts'->>'arrearsMinor')::bigint=NEW.arrears_minor
 AND (l->'amounts'->>'deductionMinor')::bigint=NEW.deduction_minor AND (l->'amounts'->>'grossMinor')::bigint=NEW.gross_minor
 AND (l->'amounts'->>'netMinor')::bigint=NEW.net_minor AND (l->'amounts'->>'employerMinor')::bigint=NEW.employer_minor AND (l->'amounts'->>'statutoryMinor')::bigint=NEW.statutory_minor
 AND EXISTS(SELECT 1 FROM cg03_case_decision d WHERE d.realm_id=c.realm_id AND d.case_id=c.id AND d.action='APPROVE' AND d.actor_id<>c.proposer_id AND d.actor_id<>r.creator AND d.fresh_password_verified_at IS NOT NULL)
 ) THEN RAISE EXCEPTION 'Original approved run line required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_original_settled_bank_journal(p_root uuid, p_journal uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(
 SELECT 1 FROM finance_voucher_posting fp JOIN finance_voucher v ON v.root_realm_id=fp.root_realm_id AND v.id=fp.voucher_id AND v.version=fp.voucher_revision
 JOIN payroll_payout_attempt t ON t.root_realm_id=v.root_realm_id AND t.voucher_ref=v.id
 JOIN payroll_batch_item i ON i.root_realm_id=t.root_realm_id AND i.id=t.item_ref
 JOIN payroll_batch b ON b.root_realm_id=i.root_realm_id AND b.id=i.batch_ref AND b.method='BANK'
 JOIN finance_voucher_payment_verification p ON p.root_realm_id=v.root_realm_id AND p.voucher_id=v.id AND p.voucher_revision=v.version
 JOIN finance_bank_reconciliation br ON br.root_realm_id=fp.root_realm_id AND br.journal_id=fp.journal_id
 JOIN finance_reconciliation_decision d ON d.root_realm_id=br.root_realm_id AND d.reconciliation_id=br.id AND d.action='VERIFY'
 WHERE fp.root_realm_id=p_root AND fp.journal_id=p_journal AND v.status='POSTED'
 AND p.status='VERIFIED' AND p.method='BANK_STATEMENT' AND p.amount_minor=t.amount_minor AND p.payroll_destination_fingerprint=i.destination_fingerprint
 AND br.bank_account_id=b.payment_account_ref AND br.status='VERIFIED' AND br.variance_minor=0
 AND br.statement_amount_minor=-t.amount_minor AND br.posted_amount_minor=-t.amount_minor AND upper(btrim(br.bank_item_ref))=p.bank_reference
 AND d.statement_file_id IS NOT NULL)
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_payout_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Employee payout history is immutable'; END IF;
 IF TG_OP='INSERT' AND (NEW.status<>'DRAFT' OR NEW.revision<>1 OR NEW.approval_case_ref IS NOT NULL) THEN RAISE EXCEPTION 'New payout instruction must be a draft'; END IF;
 IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-ARRAY['status','revision','approval_case_ref']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','approval_case_ref'])
 OR NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='DRAFT' AND NEW.status='SUBMITTED') OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED','RETURNED','REJECTED') AND NEW.approval_case_ref=OLD.approval_case_ref))) THEN RAISE EXCEPTION 'Payout instruction is immutable'; END IF;
 IF NEW.status IN('DRAFT','SUBMITTED','APPROVED') THEN
 PERFORM 1 FROM hr_employee WHERE root_realm_id=NEW.root_realm_id AND id=NEW.employee_ref FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM hr_employment_assignment a JOIN hr_employee e ON e.root_realm_id=a.root_realm_id AND e.id=a.employee_id
 JOIN branch b ON b.root_realm_id=a.root_realm_id AND b.id=a.branch_ref AND b.status='ACTIVE'
 WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.assignment_ref AND a.employee_id=NEW.employee_ref AND a.branch_ref=NEW.branch_ref AND a.assignment_version=NEW.assignment_version AND e.status_version=NEW.employee_status_version AND e.status IN('ACTIVE','PROBATION') AND a.valid_from<=NEW.effective_from AND (a.valid_to IS NULL OR a.valid_to>NEW.effective_from)) THEN RAISE EXCEPTION 'Original employee payout eligibility changed' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='APPROVED' AND NEW.supersedes_ref IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM employee_payout_instruction p WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.supersedes_ref AND p.employee_ref=NEW.employee_ref AND p.status='APPROVED' AND p.effective_from<NEW.effective_from AND (p.effective_to IS NULL OR NEW.effective_from<=p.effective_to) AND NOT EXISTS(SELECT 1 FROM employee_payout_instruction successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED')) THEN
   RAISE EXCEPTION 'Original approved predecessor changed' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='APPROVED' AND EXISTS(SELECT 1 FROM employee_payout_instruction p WHERE p.root_realm_id=NEW.root_realm_id AND p.employee_ref=NEW.employee_ref AND p.id<>NEW.id AND p.id IS DISTINCT FROM NEW.supersedes_ref AND p.status='APPROVED' AND daterange(p.effective_from,LEAST(p.effective_to,(SELECT successor.effective_from FROM employee_payout_instruction successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED')),'[)') && daterange(NEW.effective_from,NEW.effective_to,'[)')) THEN RAISE EXCEPTION 'Overlapping approved payout destination' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_payroll_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.payroll_review_ref,NEW.payroll_source_revision,NEW.payroll_source_digest) IS DISTINCT FROM (OLD.payroll_review_ref,OLD.payroll_source_revision,OLD.payroll_source_digest) THEN RAISE EXCEPTION 'Frozen payroll review cannot change'; END IF;
 RETURN NEW;
END; $function$
;

-- Functions 226-270
CREATE OR REPLACE FUNCTION public.cg11_payroll_journal_matches(p_root uuid, p_voucher uuid, p_journal uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(SELECT 1 FROM payroll_payout_attempt t WHERE t.root_realm_id=p_root AND t.voucher_ref=p_voucher)
 AND EXISTS(SELECT 1 FROM cg11_payroll_posting_lines(p_root,p_voucher))
 AND NOT EXISTS(WITH expected AS(SELECT * FROM cg11_payroll_posting_lines(p_root,p_voucher)),
 actual AS(SELECT account_id,branch_id,debit_minor::numeric,credit_minor::numeric FROM journal_line WHERE root_realm_id=p_root AND journal_id=p_journal)
 (SELECT * FROM expected EXCEPT ALL SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT ALL SELECT * FROM expected))
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_payroll_posting_lines(p_root uuid, p_voucher uuid)
 RETURNS TABLE(account_ref uuid, branch_ref uuid, dr numeric, cr numeric)
 LANGUAGE sql
 STABLE
AS $function$
 SELECT v.ref,a.branch_ref,v.dr,v.cr FROM payroll_payout_attempt t
 JOIN payroll_attempt_allocation a ON a.root_realm_id=t.root_realm_id AND a.attempt_ref=t.id
 JOIN finance_voucher f ON f.root_realm_id=t.root_realm_id AND f.id=t.voucher_ref
 CROSS JOIN LATERAL(VALUES(f.debit_account_id,a.amount_minor::numeric,0::numeric),(f.credit_account_id,0::numeric,a.amount_minor::numeric)) v(ref,dr,cr)
 WHERE t.root_realm_id=p_root AND t.voucher_ref=p_voucher ORDER BY a.branch_ref,v.ref
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_pin_attempt_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE total numeric;
BEGIN
 -- Original BEFORE trigger already locks the item and verifies remaining due.
 INSERT INTO payroll_attempt_allocation(root_realm_id,attempt_ref,branch_ref,amount_minor)
 WITH due AS(
  SELECT x.branch_ref,x.net-coalesce(p.paid,0) due,CASE WHEN x.branch_ref=l.branch_ref THEN 0 ELSE 1 END priority
  FROM payroll_batch_item i JOIN payroll_line l ON l.root_realm_id=i.root_realm_id AND l.id=i.line_ref
  CROSS JOIN LATERAL cg11_frozen_branch_allocation(l.root_realm_id,l.id) x
  LEFT JOIN LATERAL(SELECT sum(a.amount_minor) paid FROM payroll_attempt_outcome o JOIN payroll_attempt_allocation a
    ON a.root_realm_id=o.root_realm_id AND a.attempt_ref=o.id
    WHERE o.root_realm_id=i.root_realm_id AND o.item_ref=i.id AND o.id<>NEW.id AND o.paid_minor=o.amount_minor AND a.branch_ref=x.branch_ref)p ON true
  WHERE i.root_realm_id=NEW.root_realm_id AND i.id=NEW.item_ref AND x.net>0
 ), split AS(
 SELECT d.branch_ref,least(d.due,greatest(NEW.amount_minor-coalesce(sum(d.due) OVER(ORDER BY d.priority,d.branch_ref ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0),0)) amount
 FROM due d WHERE d.due>0
 )
 SELECT NEW.root_realm_id,NEW.id,s.branch_ref,s.amount::bigint FROM split s WHERE s.amount>0;
 SELECT coalesce(sum(a.amount_minor),0) INTO total FROM payroll_attempt_allocation a WHERE a.root_realm_id=NEW.root_realm_id AND a.attempt_ref=NEW.id;
 IF total<>NEW.amount_minor THEN RAISE EXCEPTION 'Original branch payable allocation unavailable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' AND (NEW.status<>'DRAFT' OR NEW.revision<>1 OR NEW.approval_case_ref IS NOT NULL) THEN RAISE EXCEPTION 'New payroll source must be a draft'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Payroll policy history is immutable'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','revision','approval_case_ref']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','approval_case_ref'])
   OR NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='DRAFT' AND NEW.status='SUBMITTED') OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED','RETURNED','REJECTED') AND NEW.approval_case_ref=OLD.approval_case_ref)) THEN
   RAISE EXCEPTION 'Payroll policy version is immutable'; END IF;
 END IF;
 IF NEW.status='APPROVED' THEN
  PERFORM 1 FROM access_realm WHERE id=NEW.root_realm_id FOR UPDATE;
  IF NEW.branch_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM branch WHERE root_realm_id=NEW.root_realm_id AND id=NEW.branch_ref AND status='ACTIVE') THEN RAISE EXCEPTION 'Inactive payroll branch' USING ERRCODE='23514'; END IF;
 IF NEW.status='APPROVED' AND NEW.supersedes_ref IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM payroll_policy p WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.supersedes_ref AND p.branch_ref IS NOT DISTINCT FROM NEW.branch_ref AND p.cycle=NEW.cycle AND p.status='APPROVED' AND p.effective_from<NEW.effective_from AND (p.effective_to IS NULL OR NEW.effective_from<=p.effective_to) AND NOT EXISTS(SELECT 1 FROM payroll_policy successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED')) THEN
   RAISE EXCEPTION 'Original approved predecessor changed' USING ERRCODE='23514'; END IF;
 END IF;
  IF EXISTS(SELECT 1 FROM payroll_policy p WHERE p.root_realm_id=NEW.root_realm_id AND p.branch_ref IS NOT DISTINCT FROM NEW.branch_ref AND p.cycle=NEW.cycle AND p.status='APPROVED' AND p.id<>NEW.id AND p.id IS DISTINCT FROM NEW.supersedes_ref AND daterange(p.effective_from,LEAST(p.effective_to,(SELECT successor.effective_from FROM payroll_policy successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED')),'[)') && daterange(NEW.effective_from,NEW.effective_to,'[)')) THEN
   RAISE EXCEPTION 'Overlapping payroll policy' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_provider_attempt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original payout attempt retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.provider_state<>'NOT_ENABLED' OR NEW.provider_checks<>0 OR num_nonnulls(NEW.provider_connection_ref,NEW.provider_credential_revision,NEW.provider_due_at,NEW.provider_claim,NEW.provider_claim_until,NEW.provider_checked_at,NEW.provider_ref,NEW.provider_utr_digest,NEW.dispatch_actor_ref,NEW.dispatch_authorized_at,NEW.dispatch_started_at,NEW.provider_account_binding)<>0
  THEN RAISE EXCEPTION 'New original payout must not contain provider outcomes'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['provider_connection_ref','provider_credential_revision','provider_state','provider_due_at','provider_claim','provider_claim_until','provider_checks','provider_checked_at','provider_ref','provider_utr_digest','dispatch_actor_ref','dispatch_authorized_at','dispatch_started_at','provider_account_binding'])
 IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['provider_connection_ref','provider_credential_revision','provider_state','provider_due_at','provider_claim','provider_claim_until','provider_checks','provider_checked_at','provider_ref','provider_utr_digest','dispatch_actor_ref','dispatch_authorized_at','dispatch_started_at','provider_account_binding'])
 OR NEW.provider_checks<OLD.provider_checks OR NEW.provider_checks>OLD.provider_checks+1
 OR (OLD.provider_connection_ref IS NOT NULL AND (NEW.provider_connection_ref,NEW.provider_credential_revision) IS DISTINCT FROM (OLD.provider_connection_ref,OLD.provider_credential_revision))
 OR (OLD.provider_ref IS NOT NULL AND NEW.provider_ref IS DISTINCT FROM OLD.provider_ref)
 OR (OLD.provider_utr_digest IS NOT NULL AND NEW.provider_utr_digest IS DISTINCT FROM OLD.provider_utr_digest)
 OR (OLD.provider_state<>'NOT_ENABLED' AND (NEW.dispatch_actor_ref,NEW.dispatch_authorized_at,NEW.provider_account_binding) IS DISTINCT FROM (OLD.dispatch_actor_ref,OLD.dispatch_authorized_at,OLD.provider_account_binding))
 OR (OLD.dispatch_started_at IS NOT NULL AND NEW.dispatch_started_at IS DISTINCT FROM OLD.dispatch_started_at)
 OR (OLD.provider_state IN('PROCESSED_AWAITING_PROOF','FAILED_AWAITING_PROOF','REVIEW_REQUIRED','EXHAUSTED'))
 THEN RAISE EXCEPTION 'Original payout identity or terminal readback immutable'; END IF;
 IF OLD.provider_state='NOT_ENABLED' THEN
  IF NEW.provider_account_binding IS NULL OR NEW.dispatch_started_at IS NOT NULL OR NEW.provider_claim IS NOT NULL OR NEW.provider_checked_at IS NOT NULL OR NEW.provider_utr_digest IS NOT NULL THEN RAISE EXCEPTION 'Original provider binding required'; END IF;
  IF NEW.dispatch_actor_ref IS NOT NULL AND (NEW.provider_state<>'UNKNOWN_WRITE_STATUS' OR NOT EXISTS(SELECT 1 FROM account a JOIN account_role ar ON ar.realm_id=a.realm_id AND ar.account_id=a.id AND ar.revoked_at IS NULL JOIN role rr ON rr.id=ar.role_id AND rr.realm_id=ar.realm_id AND rr.active AND rr.is_protected WHERE a.realm_id=NEW.root_realm_id AND a.id=NEW.dispatch_actor_ref AND a.status='ACTIVE') OR NEW.dispatch_authorized_at<now()-interval '1 minute' OR NEW.dispatch_authorized_at>now()+interval '1 minute') THEN RAISE EXCEPTION 'Current protected dispatch authorization required'; END IF;
  IF NEW.provider_state NOT IN('AWAITING_BANK','UNKNOWN_WRITE_STATUS') OR NEW.provider_checks<>0 OR NEW.provider_ref IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM integration_connection c JOIN finance_voucher v ON v.root_realm_id=c.foundation_realm_id
   JOIN payroll_batch_item i ON i.root_realm_id=v.root_realm_id AND i.id=NEW.item_ref
   JOIN payroll_batch b ON b.root_realm_id=i.root_realm_id AND b.id=i.batch_ref
   WHERE c.id=NEW.provider_connection_ref AND c.foundation_realm_id=NEW.root_realm_id AND c.provider='razorpayx' AND c.purpose='payroll'
   AND c.credential_revision=NEW.provider_credential_revision AND c.verification_status='VERIFIED' AND b.method='BANK' AND v.id=NEW.voucher_ref AND v.status='PAYMENT_REQUESTED')
  THEN RAISE EXCEPTION 'Original configured bank payment request required'; END IF;
 ELSE
  -- A dispatch start is a one-shot CAS under a fresh source authorization.
  IF NEW.dispatch_started_at IS DISTINCT FROM OLD.dispatch_started_at THEN
   IF OLD.dispatch_actor_ref IS NULL OR OLD.dispatch_authorized_at<now()-interval '1 minute'
    OR OLD.provider_state<>'UNKNOWN_WRITE_STATUS' OR OLD.provider_claim IS NOT NULL OR OLD.provider_checks<>0
    OR NEW.dispatch_started_at<now()-interval '1 minute' OR NEW.dispatch_started_at>now()+interval '1 minute'
    OR (to_jsonb(NEW)-'dispatch_started_at') IS DISTINCT FROM (to_jsonb(OLD)-'dispatch_started_at')
   THEN RAISE EXCEPTION 'Original payout dispatch is already started or authorization expired'; END IF;
  ELSIF NEW.provider_checks=OLD.provider_checks+1 THEN
   IF OLD.provider_due_at>now() OR (OLD.provider_claim_until IS NOT NULL AND OLD.provider_claim_until>now()) OR NEW.provider_claim IS NULL OR NEW.provider_claim IS NOT DISTINCT FROM OLD.provider_claim
    OR NEW.provider_claim_until<=now()
    OR (to_jsonb(NEW)-ARRAY['provider_claim','provider_claim_until','provider_checks']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['provider_claim','provider_claim_until','provider_checks'])
   THEN RAISE EXCEPTION 'Original provider lease unavailable'; END IF;
  ELSIF OLD.provider_claim IS NOT NULL AND NEW.provider_claim IS NULL THEN
   IF OLD.provider_claim_until<=now() AND NOT(OLD.provider_checks=8 AND NEW.provider_state='EXHAUSTED') THEN RAISE EXCEPTION 'Original provider lease expired'; END IF;
  ELSIF OLD.provider_claim IS NULL AND NEW.provider_claim IS NULL AND NEW.provider_state='EXHAUSTED' AND OLD.provider_checks=8 AND OLD.provider_due_at<=now() THEN
   NULL; -- recover exhausted final attempt after a crashed worker
  ELSIF OLD.dispatch_started_at IS NOT NULL AND OLD.provider_claim IS NULL AND OLD.provider_state='UNKNOWN_WRITE_STATUS'
   AND (to_jsonb(NEW)-'provider_due_at') IS NOT DISTINCT FROM (to_jsonb(OLD)-'provider_due_at') THEN
   NULL; -- immediate read-only wake following the one-shot provider call
  ELSE RAISE EXCEPTION 'Original provider result requires a current lease'; END IF;
  IF NEW.provider_state='PROCESSED_AWAITING_PROOF' AND (NEW.provider_ref IS NULL OR NEW.provider_utr_digest IS NULL) THEN RAISE EXCEPTION 'Original provider settlement reference required'; END IF;
  IF NEW.provider_state='FAILED_AWAITING_PROOF' AND NEW.provider_ref IS NULL THEN RAISE EXCEPTION 'Original provider terminal transfer required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_reconciled_bank_available(p_root uuid, p_account uuid, p_exclude uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
 SELECT
 coalesce((SELECT sum(br.posted_amount_minor) FROM finance_bank_reconciliation br
 JOIN finance_reconciliation_decision d ON d.root_realm_id=br.root_realm_id AND d.reconciliation_id=br.id AND d.action='VERIFY'
 JOIN cg19_stored_file f ON f.realm_id=d.root_realm_id AND f.id=d.statement_file_id AND f.reconciliation_id=br.id AND f.revision=d.statement_file_version AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
 JOIN cg19_upload_intent u ON u.realm_id=f.realm_id AND u.id=f.upload_intent_id AND u.status='VALIDATED'
 WHERE br.root_realm_id=p_root AND br.bank_account_id=p_account AND br.status='VERIFIED' AND br.variance_minor=0 AND br.posted_amount_minor>0),0)
 -coalesce((SELECT sum(l.credit_minor) FROM journal_line l JOIN journal j ON j.root_realm_id=l.root_realm_id AND j.id=l.journal_id AND j.status='POSTED' WHERE l.root_realm_id=p_root AND l.account_id=p_account),0)
 -coalesce((SELECT sum(v.total_minor) FROM finance_voucher v
 WHERE v.root_realm_id=p_root AND v.payment_account_id=p_account AND v.credit_account_id=p_account AND v.id<>p_exclude
 AND v.status IN('PAYMENT_REQUESTED','PAID_VERIFIED')
 AND NOT EXISTS(SELECT 1 FROM finance_voucher_payment_verification p WHERE p.root_realm_id=v.root_realm_id AND p.voucher_id=v.id AND p.voucher_revision=v.version AND p.payroll_failure_verified)),0)
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_require_original_review()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status IN('SUBMITTED','APPROVED','RETURNED','REJECTED') AND NOT EXISTS(
 SELECT 1 FROM cg03_case c JOIN payroll_review_snapshot s ON s.root_realm_id=c.realm_id AND s.id=c.payroll_review_ref
 WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.approval_case_ref AND c.case_kind='PAYROLL_COMPENSATION_REVIEW' AND c.proposal_revision=1
 AND ((TG_TABLE_NAME='payroll_policy' AND s.policy_ref=NEW.id) OR (TG_TABLE_NAME='employee_compensation' AND s.compensation_ref=NEW.id) OR (TG_TABLE_NAME='employee_payout_instruction' AND s.payout_ref=NEW.id))
 AND s.submitted_by=c.proposer_id AND s.submitted_by=NEW.created_by
 AND ((NEW.status='SUBMITTED' AND c.status='SUBMITTED') OR (NEW.status='APPROVED' AND c.status='PENDING_OWNER') OR (NEW.status='RETURNED' AND c.status='RETURNED') OR (NEW.status='REJECTED' AND c.status='REJECTED'))
 AND (NEW.status='SUBMITTED' OR EXISTS(SELECT 1 FROM cg03_case_decision d WHERE d.realm_id=c.realm_id AND d.case_id=c.id AND d.actor_id<>c.proposer_id AND d.actor_id<>NEW.created_by AND d.fresh_password_verified_at IS NOT NULL AND d.action=CASE NEW.status WHEN 'APPROVED' THEN 'APPROVE' WHEN 'RETURNED' THEN 'RETURN' ELSE 'REJECT' END))
 ) THEN RAISE EXCEPTION 'Original independent payroll decision required' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_root_payroll_journal(p_root uuid, p_journal uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(SELECT 1 FROM finance_voucher_posting p JOIN payroll_payout_attempt t ON t.root_realm_id=p.root_realm_id AND t.voucher_ref=p.voucher_id
 JOIN finance_voucher v ON v.root_realm_id=p.root_realm_id AND v.id=p.voucher_id
 WHERE p.root_realm_id=p_root AND v.branch_id IS NULL AND (p.journal_id=p_journal OR EXISTS(SELECT 1 FROM finance_manual_journal_reversal rev WHERE rev.root_realm_id=p.root_realm_id AND rev.original_journal_id=p.journal_id AND rev.reversal_journal_id=p_journal AND rev.payroll_return_bank_reference IS NOT NULL)))
$function$
;
CREATE OR REPLACE FUNCTION public.cg11_run_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.payroll_run_review_ref,NEW.payroll_run_revision,NEW.payroll_run_digest) IS DISTINCT FROM (OLD.payroll_run_review_ref,OLD.payroll_run_revision,OLD.payroll_run_digest) THEN RAISE EXCEPTION 'Frozen run case cannot change'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_run_original_review()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status IN('SUBMITTED','APPROVED_FROZEN','RETURNED','REJECTED') AND NOT EXISTS(
  SELECT 1 FROM cg03_case c JOIN payroll_run_review_snapshot s ON s.root_realm_id=c.realm_id AND s.id=c.payroll_run_review_ref
  WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.approval_case_ref AND c.case_kind='PAYROLL_RUN_RELEASE' AND s.run_id=NEW.id AND s.source_digest=NEW.snapshot_digest AND s.submitted_by=c.proposer_id
  AND ((NEW.status='SUBMITTED' AND c.status='SUBMITTED' AND s.source_revision=OLD.revision AND NEW.approved_decision_ref IS NULL)
   OR (NEW.status<>'SUBMITTED' AND OLD.approval_case_ref=c.id AND OLD.revision=s.source_revision+1 AND EXISTS(
     SELECT 1 FROM cg03_case_decision d WHERE d.realm_id=c.realm_id AND d.case_id=c.id AND d.id=NEW.approved_decision_ref AND d.actor_id<>c.proposer_id AND d.actor_id<>NEW.creator AND d.fresh_password_verified_at IS NOT NULL
     AND ((NEW.status='APPROVED_FROZEN' AND c.status='PENDING_OWNER' AND d.action='APPROVE') OR (NEW.status='RETURNED' AND c.status='RETURNED' AND d.action='RETURN') OR (NEW.status='REJECTED' AND c.status='REJECTED' AND d.action='REJECT')))))
 ) THEN RAISE EXCEPTION 'Original independent payroll run decision required' USING ERRCODE='23514'; END IF;
 IF NEW.status='APPROVED_FROZEN' AND (
 (SELECT count(*) FROM payroll_line WHERE root_realm_id=NEW.root_realm_id AND run_id=NEW.id) IS DISTINCT FROM
 (SELECT (v.snapshot->'totals'->>'calculated')::bigint+(v.snapshot->'totals'->>'held')::bigint FROM payroll_run_revision v JOIN payroll_run_review_snapshot s ON s.root_realm_id=v.root_realm_id AND s.run_id=v.run_id AND s.source_revision=v.revision AND s.source_digest=v.source_digest JOIN cg03_case c ON c.realm_id=s.root_realm_id AND c.payroll_run_review_ref=s.id WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.approval_case_ref)
 OR NOT EXISTS(SELECT 1 FROM payroll_line WHERE root_realm_id=NEW.root_realm_id AND run_id=NEW.id)) THEN RAISE EXCEPTION 'Incomplete frozen payroll entitlement'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_run_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Payroll run is immutable'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.revision<>1 OR num_nonnulls(NEW.snapshot_digest,NEW.approval_case_ref,NEW.approved_decision_ref)<>0 THEN RAISE EXCEPTION 'New payroll run must be a draft'; END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['status','revision','snapshot_digest','approval_case_ref','approved_decision_ref']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','snapshot_digest','approval_case_ref','approved_decision_ref']) OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'Invalid payroll revision'; END IF;
 IF NOT ((OLD.status IN('DRAFT','ATTENDANCE_IMPORTED','CALCULATED','RETURNED') AND NEW.status='ATTENDANCE_IMPORTED')
 OR (OLD.status IN('ATTENDANCE_IMPORTED','CALCULATED') AND NEW.status IN('ATTENDANCE_IMPORTED','CALCULATED'))
 OR (OLD.status='CALCULATED' AND NEW.status='SUBMITTED')
 OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED_FROZEN','RETURNED','REJECTED'))) THEN RAISE EXCEPTION 'Invalid payroll transition'; END IF;
 IF NEW.status IN('ATTENDANCE_IMPORTED','CALCULATED') AND NOT EXISTS(SELECT 1 FROM payroll_run_revision s WHERE s.root_realm_id=NEW.root_realm_id AND s.run_id=NEW.id AND s.revision=NEW.revision AND s.source_digest=NEW.snapshot_digest) THEN RAISE EXCEPTION 'Original payroll revision required'; END IF;
 IF NEW.status IN('ATTENDANCE_IMPORTED','CALCULATED') AND num_nonnulls(NEW.approval_case_ref,NEW.approved_decision_ref)<>0 THEN RAISE EXCEPTION 'Draft cannot be approved'; END IF;
 IF NEW.status IN('SUBMITTED','APPROVED_FROZEN','RETURNED','REJECTED') AND NEW.snapshot_digest IS DISTINCT FROM OLD.snapshot_digest THEN RAISE EXCEPTION 'Frozen payroll digest cannot change'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_salary_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' AND (NEW.status<>'DRAFT' OR NEW.revision<>1 OR NEW.approval_case_ref IS NOT NULL) THEN RAISE EXCEPTION 'New payroll source must be a draft'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Salary history is immutable'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','revision','approval_case_ref']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','revision','approval_case_ref'])
   OR NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='DRAFT' AND NEW.status='SUBMITTED') OR (OLD.status='SUBMITTED' AND NEW.status IN('APPROVED','RETURNED','REJECTED') AND NEW.approval_case_ref=OLD.approval_case_ref)) THEN
   RAISE EXCEPTION 'Salary version is immutable'; END IF;
 END IF;
 IF NEW.status IN('DRAFT','SUBMITTED','APPROVED') THEN
 PERFORM 1 FROM hr_employee WHERE root_realm_id=NEW.root_realm_id AND id=NEW.employee_ref FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM hr_employment_assignment a JOIN hr_employee e ON e.root_realm_id=a.root_realm_id AND e.id=a.employee_id WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.assignment_ref AND a.employee_id=NEW.employee_ref AND a.branch_ref=NEW.branch_ref AND a.assignment_version=NEW.assignment_version AND e.status_version=NEW.employee_status_version AND e.status IN('ACTIVE','PROBATION') AND a.valid_from<=NEW.effective_from AND (a.valid_to IS NULL OR a.valid_to>NEW.effective_from)) THEN
  RAISE EXCEPTION 'Original HR eligibility changed' USING ERRCODE='23514'; END IF;
 IF NEW.source_hr_proposal_ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM hr_employment_change h JOIN cg03_case c ON c.realm_id=h.root_realm_id AND c.id=h.case_ref AND c.hr_employment_change_id=h.id AND c.hr_employment_change_digest=h.source_digest AND c.status='OWNER_COMPLETED' JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id AND d.id=h.decision_ref AND d.action='APPROVE' WHERE h.root_realm_id=NEW.root_realm_id AND h.id=NEW.source_hr_proposal_ref AND h.employee_id=NEW.employee_ref AND h.new_assignment_ref=NEW.assignment_ref AND h.proposed_branch_ref=NEW.branch_ref AND h.status='APPLIED' AND h.effective_date=NEW.effective_from) THEN RAISE EXCEPTION 'Original HR proposal no longer applies' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM payroll_policy p WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.policy_id AND (p.branch_ref=NEW.branch_ref OR p.branch_ref IS NULL) AND p.revision=NEW.policy_revision AND p.status='APPROVED' AND p.effective_from<=NEW.effective_from AND (LEAST(p.effective_to,(SELECT successor.effective_from FROM payroll_policy successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED')) IS NULL OR (NEW.effective_to IS NOT NULL AND NEW.effective_to<=LEAST(p.effective_to,(SELECT successor.effective_from FROM payroll_policy successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED'))))) THEN
  RAISE EXCEPTION 'Approved policy required' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='APPROVED' AND NEW.supersedes_ref IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM employee_compensation p WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.supersedes_ref AND p.employee_ref=NEW.employee_ref AND p.status='APPROVED' AND p.effective_from<NEW.effective_from AND (p.effective_to IS NULL OR NEW.effective_from<=p.effective_to) AND NOT EXISTS(SELECT 1 FROM employee_compensation successor WHERE successor.root_realm_id=p.root_realm_id AND successor.supersedes_ref=p.id AND successor.status='APPROVED')) THEN
   RAISE EXCEPTION 'Original approved predecessor changed' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='APPROVED' AND EXISTS(SELECT 1 FROM employee_compensation c WHERE c.root_realm_id=NEW.root_realm_id AND c.employee_ref=NEW.employee_ref AND c.status='APPROVED' AND c.id<>NEW.id AND c.id IS DISTINCT FROM NEW.supersedes_ref AND daterange(c.effective_from,LEAST(c.effective_to,(SELECT successor.effective_from FROM employee_compensation successor WHERE successor.root_realm_id=c.root_realm_id AND successor.supersedes_ref=c.id AND successor.status='APPROVED')),'[)') && daterange(NEW.effective_from,NEW.effective_to,'[)')) THEN
  RAISE EXCEPTION 'Overlapping approved salary' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg11_verified_bank_return(p_root uuid, p_attempt uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(SELECT 1 FROM payroll_payout_attempt t
 JOIN payroll_batch_item i ON i.root_realm_id=t.root_realm_id AND i.id=t.item_ref
 JOIN payroll_batch b ON b.root_realm_id=i.root_realm_id AND b.id=i.batch_ref AND b.method='BANK'
 JOIN finance_voucher_posting fp ON fp.root_realm_id=t.root_realm_id AND fp.voucher_id=t.voucher_ref
 JOIN finance_manual_journal_reversal rev ON rev.root_realm_id=fp.root_realm_id AND rev.original_journal_id=fp.journal_id
 JOIN finance_bank_reconciliation br ON br.root_realm_id=rev.root_realm_id AND br.journal_id=rev.reversal_journal_id
 JOIN finance_reconciliation_decision d ON d.root_realm_id=br.root_realm_id AND d.reconciliation_id=br.id AND d.action='VERIFY'
 WHERE t.root_realm_id=p_root AND t.id=p_attempt AND rev.payroll_return_bank_reference IS NOT NULL
 AND br.status='VERIFIED' AND br.bank_account_id=b.payment_account_ref AND br.variance_minor=0
 AND br.statement_amount_minor=t.amount_minor AND br.posted_amount_minor=t.amount_minor
 AND upper(btrim(br.bank_item_ref))=rev.payroll_return_bank_reference AND d.statement_file_id IS NOT NULL
 AND cg11_original_settled_bank_journal(t.root_realm_id,fp.journal_id))
$function$
;
CREATE OR REPLACE FUNCTION public.cg12_adjustment_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.stock_adjustment_id,NEW.stock_adjustment_version,NEW.stock_adjustment_digest) IS DISTINCT FROM (OLD.stock_adjustment_id,OLD.stock_adjustment_version,OLD.stock_adjustment_digest) THEN RAISE EXCEPTION 'Frozen adjustment source cannot be edited'; END IF; RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_alert_item()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE loc uuid;
BEGIN
 FOR loc IN
  SELECT l.id FROM inventory_location l
  WHERE l.root_realm_id=NEW.root_realm_id AND
   (EXISTS(SELECT 1 FROM stock_low_alert a WHERE a.root_realm_id=l.root_realm_id AND a.location_id=l.id AND a.item_id=NEW.id)
    OR EXISTS(SELECT 1 FROM inventory_item_location_policy p WHERE p.root_realm_id=l.root_realm_id AND p.location_id=l.id AND p.item_id=NEW.id)
    OR EXISTS(SELECT 1 FROM stock_balance b WHERE b.root_realm_id=l.root_realm_id AND b.location_id=l.id AND b.item_id=NEW.id)
    OR (NEW.status='ACTIVE' AND NEW.low_stock_threshold>0 AND l.status='ACTIVE'))
  ORDER BY l.id
 LOOP
  PERFORM cg12_refresh_low_alert(NEW.root_realm_id,NEW.id,loc);
 END LOOP;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_alert_location()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE item uuid;
BEGIN
 FOR item IN
  SELECT i.id FROM inventory_item i
  WHERE i.root_realm_id=NEW.root_realm_id AND
   (EXISTS(SELECT 1 FROM stock_low_alert a WHERE a.root_realm_id=i.root_realm_id AND a.location_id=NEW.id AND a.item_id=i.id)
    OR EXISTS(SELECT 1 FROM inventory_item_location_policy p WHERE p.root_realm_id=i.root_realm_id AND p.location_id=NEW.id AND p.item_id=i.id)
    OR EXISTS(SELECT 1 FROM stock_balance b WHERE b.root_realm_id=i.root_realm_id AND b.location_id=NEW.id AND b.item_id=i.id)
    OR (NEW.status='ACTIVE' AND i.status='ACTIVE' AND i.low_stock_threshold>0))
  ORDER BY i.id
 LOOP
  PERFORM cg12_refresh_low_alert(NEW.root_realm_id,item,NEW.id);
 END LOOP;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_alert_pair()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN PERFORM cg12_refresh_low_alert(NEW.root_realm_id,NEW.item_id,NEW.location_id); RETURN NEW; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_inventory_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Inventory audit is immutable'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_item_identity_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (NEW.root_realm_id,NEW.id,NEW.sku_norm,NEW.unit_code,NEW.qty_scale) IS DISTINCT FROM
    (OLD.root_realm_id,OLD.id,OLD.sku_norm,OLD.unit_code,OLD.qty_scale) THEN
  RAISE EXCEPTION 'Original catalog identity and counting units are immutable';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_line_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM cg03_case c JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
 JOIN material_request_line l ON l.root_realm_id=c.realm_id AND l.request_id=c.material_request_id
 WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.case_id AND c.case_kind='MATERIAL_REQUEST_REVIEW'
 AND c.material_request_id=NEW.request_id AND d.id=NEW.decision_id AND d.action='APPROVE'
 AND d.actor_id<>c.proposer_id AND d.fresh_password_verified_at IS NOT NULL
 AND l.id=NEW.line_id AND l.item_id=NEW.item_id AND l.approved_qty=NEW.approved_qty
 FOR SHARE OF c,d,l;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original material approval quantity changed'; END IF; RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_material_case_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.material_request_id IS DISTINCT FROM OLD.material_request_id OR NEW.material_revision_id IS DISTINCT FROM OLD.material_revision_id OR NEW.material_revision_no IS DISTINCT FROM OLD.material_revision_no OR NEW.material_digest IS DISTINCT FROM OLD.material_digest THEN RAISE EXCEPTION 'Frozen material source cannot be edited'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_operation_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-'status')=(to_jsonb(OLD)-'status') AND
 ((OLD.status='DRAFT' AND NEW.status IN('SUBMITTED','CONFIRMED')) OR (OLD.status='SUBMITTED' AND NEW.status IN('RETURNED','REJECTED','CONFIRMED'))) THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Original stock operation source cannot be edited or deleted';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_receipt_source_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='DRAFT' AND NEW.status='CONFIRMED'
 AND (NEW.id,NEW.root_realm_id,NEW.supplier_id,NEW.location_id,NEW.receipt_date,NEW.source_note,
   NEW.created_by,NEW.request_key,NEW.payload_digest,NEW.source_version,NEW.created_at)
 IS NOT DISTINCT FROM
 (OLD.id,OLD.root_realm_id,OLD.supplier_id,OLD.location_id,OLD.receipt_date,OLD.source_note,
   OLD.created_by,OLD.request_key,OLD.payload_digest,OLD.source_version,OLD.created_at)
 THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'Frozen receipt source cannot be changed';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_refresh_low_alert(p_root uuid, p_item uuid, p_loc uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE low boolean;
BEGIN
 SELECT i.status='ACTIVE' AND l.status='ACTIVE' AND COALESCE(b.on_hand_qty-b.reserved_qty,0)<COALESCE(p.threshold,i.low_stock_threshold) INTO low
 FROM inventory_item i JOIN inventory_location l ON l.root_realm_id=i.root_realm_id AND l.id=p_loc
 LEFT JOIN stock_balance b ON b.root_realm_id=i.root_realm_id AND b.item_id=i.id AND b.location_id=l.id
 LEFT JOIN inventory_item_location_policy p ON p.root_realm_id=i.root_realm_id AND p.item_id=i.id AND p.location_id=l.id
 WHERE i.root_realm_id=p_root AND i.id=p_item;
 IF low IS NULL THEN RETURN; END IF;
 INSERT INTO stock_low_alert(root_realm_id,item_id,location_id,active) VALUES(p_root,p_item,p_loc,low)
 ON CONFLICT(root_realm_id,item_id,location_id) DO UPDATE SET active=EXCLUDED.active,changed_at=now()
 WHERE stock_low_alert.active IS DISTINCT FROM EXCLUDED.active;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_reward_hold_commit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE h record;reserved numeric;recorded numeric;
BEGIN
 SELECT * INTO h FROM stock_reward_hold
  WHERE root_realm_id=NEW.root_realm_id AND id=NEW.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original reward hold required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM stock_reward_hold_event e
  WHERE e.root_realm_id=h.root_realm_id AND e.hold_id=h.id
   AND e.event_kind='RESERVED' AND e.source_key=h.request_key)
 THEN RAISE EXCEPTION 'CG12 reward hold requires original reserve event'; END IF;
 IF h.state='RELEASED' AND NOT EXISTS(SELECT 1 FROM stock_reward_hold_event e
  WHERE e.root_realm_id=h.root_realm_id AND e.hold_id=h.id
   AND e.event_kind='RELEASED' AND e.source_key=h.request_key)
 THEN RAISE EXCEPTION 'CG12 release requires original source event'; END IF;
 IF h.state IN('ISSUED','RETURNED') AND NOT EXISTS(
  SELECT 1 FROM stock_reward_hold_event e JOIN stock_event se
   ON se.root_realm_id=e.root_realm_id AND se.id=e.original_stock_event_id
  WHERE e.root_realm_id=h.root_realm_id AND e.hold_id=h.id
   AND e.event_kind='ISSUED' AND e.source_key=h.issue_key
   AND se.event_kind='ISSUE' AND se.source_event_key=h.issue_key)
 THEN RAISE EXCEPTION 'CG12 ISSUE requires original stock_event'; END IF;
 IF h.state='RETURNED' AND NOT EXISTS(
  SELECT 1 FROM stock_reward_hold_event e JOIN stock_event se
   ON se.root_realm_id=e.root_realm_id AND se.id=e.original_stock_event_id
  WHERE e.root_realm_id=h.root_realm_id AND e.hold_id=h.id
   AND e.event_kind='RETURNED' AND se.event_kind='RETURN'
 ) THEN RAISE EXCEPTION 'CG12 RETURN requires original stock_event'; END IF;
 -- No parallel warehouse projection: original CG12 material_request holds
 -- plus live reward holds must equal the SAME stock_balance.reserved_qty.
 SELECT reserved_qty INTO reserved FROM stock_balance
  WHERE root_realm_id=h.root_realm_id AND item_id=h.item_id
   AND location_id=h.location_id;
 SELECT COALESCE((SELECT SUM(quantity) FROM stock_hold m
  WHERE m.root_realm_id=h.root_realm_id AND m.item_id=h.item_id
   AND m.location_id=h.location_id),0)+
  COALESCE((SELECT COUNT(*) FROM stock_reward_hold rw
  WHERE rw.root_realm_id=h.root_realm_id AND rw.item_id=h.item_id
   AND rw.location_id=h.location_id AND rw.state='HELD'),0)
 INTO recorded;
 IF reserved IS DISTINCT FROM recorded THEN
  RAISE EXCEPTION 'CG12 actual reserved projection differs from original holds';
 END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_reward_hold_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original CG12 reward stock hold must not be deleted'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (NEW.root_realm_id,NEW.id,NEW.redemption_id,NEW.item_id,NEW.location_id,
      NEW.recipient_account_ref,NEW.request_key,NEW.issue_key,NEW.created_at)
     IS DISTINCT FROM
     (OLD.root_realm_id,OLD.id,OLD.redemption_id,OLD.item_id,OLD.location_id,
      OLD.recipient_account_ref,OLD.request_key,OLD.issue_key,OLD.created_at)
     OR NEW.revision<>OLD.revision+1
     OR NOT (
      (OLD.state='HELD' AND NEW.state IN('RELEASED','ISSUED'))
      OR (OLD.state='ISSUED' AND NEW.state='RETURNED')
     )
  THEN RAISE EXCEPTION 'Only original source-backed CG12 hold state transitions allowed'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.state<>'HELD' OR NEW.revision<>1 THEN
  RAISE EXCEPTION 'A new reward stock hold must start HELD'; END IF;
 IF NOT EXISTS (
  SELECT 1 FROM redemption r
  JOIN reward_product_revision p ON p.root_realm_id=r.root_realm_id
   AND p.product_id=r.product_id AND p.revision=r.product_revision
  JOIN inventory_item item ON item.root_realm_id=p.root_realm_id
   AND item.id=p.cg12_item_ref
  JOIN inventory_location loc ON loc.root_realm_id=p.root_realm_id
   AND loc.id=p.cg12_location_ref
  WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.redemption_id
   AND r.state='HELD' AND r.product_type='PHYSICAL'
   AND r.recipient_account_ref=NEW.recipient_account_ref
   AND r.request_key=NEW.request_key
   AND p.product_type='PHYSICAL'
   AND p.cg12_item_ref=NEW.item_id AND p.cg12_location_ref=NEW.location_id
   AND item.status='ACTIVE' AND item.unit_code='PIECE' AND item.qty_scale=0
   AND loc.status='ACTIVE'
   AND (loc.branch_ref IS NULL OR EXISTS(
    SELECT 1 FROM branch b WHERE b.root_realm_id=loc.root_realm_id
     AND b.id=loc.branch_ref AND b.status='ACTIVE'))
 ) THEN RAISE EXCEPTION 'Verified original reward, item and warehouse required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg12_threshold_scale()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE scale smallint;
BEGIN
 SELECT qty_scale INTO STRICT scale FROM inventory_item WHERE root_realm_id=NEW.root_realm_id AND id=NEW.item_id FOR SHARE;
 IF NEW.threshold<>round(NEW.threshold,scale) THEN RAISE EXCEPTION 'Invalid threshold quantity precision'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_committed_attribution_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM referral_code code
    WHERE code.root_realm_id=NEW.root_realm_id
     AND code.id=NEW.referral_code_ref AND code.programme_id=NEW.programme_id
     AND code.referrer_account_ref=NEW.referrer_account_ref
     AND code.referrer_kind=NEW.referrer_kind
     AND code.referrer_relationship_ref=NEW.referrer_relationship_ref
     AND cg13_referral_code_current(code.root_realm_id,code.code_value)
 ) THEN RAISE EXCEPTION 'Current verified referral code source required'; END IF;
 IF NEW.applicant_kind='MEMBER' THEN
  IF EXISTS(SELECT 1 FROM member m WHERE m.root_realm_id=NEW.root_realm_id
   AND m.account_ref=NEW.applicant_account_ref)
  THEN RAISE EXCEPTION 'Membership renewal is not a new referral qualification'; END IF;
  IF NOT EXISTS(SELECT 1 FROM membership_application app
   JOIN referral_code code ON code.root_realm_id=app.root_realm_id
    AND code.id=NEW.referral_code_ref
   WHERE app.root_realm_id=NEW.root_realm_id
    AND app.id=NEW.member_application_ref
    AND app.applicant_account_ref=NEW.applicant_account_ref
    AND app.status='SUBMITTED'
    AND app.version=NEW.application_revision
    AND app.submitted_digest=NEW.submitted_digest
    AND app.referral_input=code.code_value)
  THEN RAISE EXCEPTION 'Real committed member application referral source required'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM volunteer_application app
   JOIN referral_code code ON code.root_realm_id=app.root_realm_id
    AND code.id=NEW.referral_code_ref
   WHERE app.root_realm_id=NEW.root_realm_id
    AND app.id=NEW.volunteer_application_ref
    AND app.applicant_account_ref=NEW.applicant_account_ref
    AND app.status='SUBMITTED'
    AND app.version=NEW.application_revision
    AND app.submitted_digest=NEW.submitted_digest
    AND app.referral_input=code.code_value)
  THEN RAISE EXCEPTION 'Real committed volunteer application referral source required'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM referral_policy_version policy
  WHERE policy.root_realm_id=NEW.root_realm_id
   AND policy.programme_id=NEW.programme_id
   AND policy.version_no=NEW.policy_version
   AND policy.award_points=NEW.award_points
   AND policy.qualifying_event=NEW.qualifying_event
   AND policy.effective_from<=now())
 THEN RAISE EXCEPTION 'Frozen effective qualification rules required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_digital_redemption_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original redemptions must never be deleted'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (OLD.root_realm_id,OLD.id,OLD.programme_id,OLD.policy_version,OLD.points_account_id,
      OLD.recipient_account_ref,OLD.relationship_kind,OLD.relationship_ref,
      OLD.product_id,OLD.product_revision,OLD.product_type,OLD.points_cost,
      OLD.request_key,OLD.payload_digest,OLD.requested_at) IS DISTINCT FROM
     (NEW.root_realm_id,NEW.id,NEW.programme_id,NEW.policy_version,NEW.points_account_id,
      NEW.recipient_account_ref,NEW.relationship_kind,NEW.relationship_ref,
      NEW.product_id,NEW.product_revision,NEW.product_type,NEW.points_cost,
      NEW.request_key,NEW.payload_digest,NEW.requested_at)
    OR NEW.revision<>OLD.revision+1
    OR NOT (
     (OLD.state='HELD' AND NEW.state='ISSUED_AWAITING_HANDOVER'
      AND NEW.product_type='PHYSICAL'
      AND NEW.cancelled_at IS NULL AND NEW.fulfilled_at IS NULL
      AND EXISTS(
       SELECT 1 FROM stock_reward_hold h
       JOIN stock_reward_hold_event issued
        ON issued.root_realm_id=h.root_realm_id AND issued.hold_id=h.id
        AND issued.event_kind='ISSUED'
       JOIN stock_event stock ON stock.root_realm_id=issued.root_realm_id
        AND stock.id=issued.original_stock_event_id
       JOIN stock_operation_draft op ON op.root_realm_id=stock.root_realm_id
        AND op.id=stock.operation_id
       WHERE h.root_realm_id=NEW.root_realm_id AND h.redemption_id=NEW.id
        AND h.state='ISSUED' AND issued.source_key=h.issue_key
        AND stock.event_kind='ISSUE' AND stock.source_event_key=h.issue_key
        AND op.reward_hold_id=h.id AND op.status='CONFIRMED'))
     OR
     (OLD.state='HELD' AND NEW.state='CANCELLED'
      AND NEW.cancelled_at IS NOT NULL AND NEW.fulfilled_at IS NULL
      AND (NEW.product_type='DIGITAL' OR EXISTS(
       SELECT 1 FROM stock_reward_hold h
       WHERE h.root_realm_id=NEW.root_realm_id AND h.redemption_id=NEW.id
        AND h.recipient_account_ref=NEW.recipient_account_ref
        AND h.state='RELEASED')))
     OR
     (OLD.state='ISSUED_AWAITING_HANDOVER' AND NEW.state='FULFILLED'
      AND NEW.product_type='PHYSICAL'
      AND NEW.cancelled_at IS NULL AND NEW.fulfilled_at IS NOT NULL
      AND EXISTS(
       SELECT 1 FROM cg19_reward_handover actual
       WHERE actual.realm_id=NEW.root_realm_id
        AND actual.redemption_id=NEW.id
        AND actual.recipient_account_ref=NEW.recipient_account_ref
        AND actual.source_key=NEW.request_key))
     OR
     (OLD.state='HELD' AND NEW.state='FULFILLED'
      AND NEW.product_type='DIGITAL'
      AND NEW.cancelled_at IS NULL AND NEW.fulfilled_at IS NOT NULL
      AND EXISTS(
       SELECT 1 FROM cg19_reward_recognition proof
       WHERE proof.realm_id=NEW.root_realm_id AND proof.redemption_id=NEW.id
        AND proof.recipient_account_ref=NEW.recipient_account_ref
        AND proof.source_key=NEW.request_key
        AND proof.product_id=NEW.product_id
        AND proof.product_revision=NEW.product_revision))
    )
  THEN RAISE EXCEPTION 'Digital redemption requires exact verified original source transition'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.state<>'HELD' OR NEW.revision<>1 OR NEW.cancelled_at IS NOT NULL
   OR NEW.fulfilled_at IS NOT NULL THEN
  RAISE EXCEPTION 'Only actual digital pending holds may be requested'; END IF;
 IF NOT EXISTS(
  SELECT 1 FROM points_account wallet
  JOIN referral_program programme ON programme.root_realm_id=wallet.root_realm_id
   AND programme.id=wallet.programme_id AND programme.status='ACTIVE'
  JOIN reward_product product ON product.root_realm_id=wallet.root_realm_id
   AND product.programme_id=wallet.programme_id AND product.id=NEW.product_id
  WHERE wallet.root_realm_id=NEW.root_realm_id AND wallet.id=NEW.points_account_id
   AND wallet.programme_id=NEW.programme_id
   AND wallet.referrer_account_ref=NEW.recipient_account_ref
   AND wallet.referrer_kind=NEW.relationship_kind
   AND wallet.referrer_relationship_ref=NEW.relationship_ref
   AND product.product_type=NEW.product_type
   -- 3508 supplies this current CG19 delivery-method column before first
   -- operational redemption. PL/pgSQL query planning occurs at execution.
   -- Do not permit a database caller to hold points for future-only DIGITAL.
   AND (NEW.product_type='PHYSICAL' OR
    product.digital_fulfillment_method='ON_PLATFORM_RECOGNITION')
   AND product.status='ACTIVE' AND product.public_visible
   AND (programme.audience='BOTH' OR programme.audience=NEW.relationship_kind)
   AND (product.eligible_audience='BOTH' OR product.eligible_audience=NEW.relationship_kind)
   AND product.version=NEW.product_revision
   AND product.points_price=NEW.points_cost
   AND NEW.policy_version=(
    SELECT pv.version_no FROM referral_policy_version pv
     WHERE pv.root_realm_id=programme.root_realm_id
      AND pv.programme_id=programme.id AND pv.effective_from<=now()
     ORDER BY pv.effective_from DESC,pv.version_no DESC LIMIT 1)
   AND wallet.earned_points-wallet.reversed_points-wallet.held_points-wallet.spent_points>=GREATEST(
    NEW.points_cost,
    (SELECT pv.minimum_claim_points FROM referral_policy_version pv
     WHERE pv.root_realm_id=NEW.root_realm_id AND pv.programme_id=NEW.programme_id
      AND pv.version_no=NEW.policy_version))
   AND (
     (NEW.relationship_kind='MEMBER' AND EXISTS(
      SELECT 1 FROM member m JOIN membership_term term
       ON term.root_realm_id=m.root_realm_id AND term.member_id=m.id
      WHERE m.root_realm_id=wallet.root_realm_id AND m.id=NEW.relationship_ref
       AND m.account_ref=NEW.recipient_account_ref AND m.status='ACTIVE'
       AND (m.branch_ref IS NULL OR EXISTS(
        SELECT 1 FROM branch br WHERE br.root_realm_id=m.root_realm_id
         AND br.id=m.branch_ref AND br.status='ACTIVE'))
       AND term.starts_on<=(now() AT TIME ZONE 'Asia/Kolkata')::date
       AND (term.expires_on IS NULL
         OR term.expires_on>(now() AT TIME ZONE 'Asia/Kolkata')::date)
     ))
     OR (NEW.relationship_kind='VOLUNTEER' AND EXISTS(
      SELECT 1 FROM volunteer v WHERE v.root_realm_id=wallet.root_realm_id
       AND v.id=NEW.relationship_ref AND v.account_ref=NEW.recipient_account_ref
       AND v.status='ACTIVE'
       AND cg04_current_volunteer(v.root_realm_id,v.id,v.account_ref,v.branch_ref)
     ))
   )
  FOR UPDATE OF wallet
 ) THEN RAISE EXCEPTION 'Current eligible digital product, member and points are required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_immutable_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Original referral programme audit/revision cannot be edited'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_points_event_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 -- US003 uses this SAME immutable points_event table. Digital requests are
 -- checked against the original eligible reward and locked wallet via the
 -- independently guarded redemption table created in forward migration 3507.
 IF NEW.event_kind='POINTS_SPENT' THEN
  IF NOT EXISTS(
   SELECT 1 FROM redemption r
   JOIN points_account wallet ON wallet.root_realm_id=r.root_realm_id
    AND wallet.id=r.points_account_id
   WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.redemption_id
    AND r.state='FULFILLED'
    AND r.points_account_id=NEW.points_account_id
    AND wallet.referrer_account_ref=r.recipient_account_ref
    AND r.policy_version=NEW.policy_version
    AND r.payload_digest=NEW.qualifying_source_digest
    AND r.points_cost=NEW.points_delta
    AND (
     (r.product_type='DIGITAL' AND EXISTS(
      SELECT 1 FROM cg19_reward_recognition proof
      JOIN reward_product_revision product ON product.root_realm_id=r.root_realm_id
       AND product.product_id=r.product_id AND product.revision=r.product_revision
      WHERE proof.realm_id=r.root_realm_id AND proof.redemption_id=r.id
       AND proof.recipient_account_ref=r.recipient_account_ref
       AND proof.source_key=r.request_key
       AND product.digital_fulfillment_method='ON_PLATFORM_RECOGNITION'))
     OR
     (r.product_type='PHYSICAL' AND EXISTS(
      SELECT 1 FROM cg19_reward_handover proof
      JOIN stock_reward_hold hold ON hold.root_realm_id=r.root_realm_id
       AND hold.redemption_id=r.id AND hold.state='ISSUED'
      JOIN stock_reward_hold_event issued ON issued.root_realm_id=hold.root_realm_id
       AND issued.hold_id=hold.id AND issued.event_kind='ISSUED'
       AND issued.source_key=hold.issue_key
      WHERE proof.realm_id=r.root_realm_id AND proof.redemption_id=r.id
       AND proof.recipient_account_ref=r.recipient_account_ref
       AND proof.source_key=r.request_key
       AND proof.stock_issue_event_id=issued.original_stock_event_id))
    )
  ) THEN RAISE EXCEPTION 'Original CG19 acknowledged reward proof and genuine CG12 ISSUE required to spend points'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.event_kind IN('POINTS_HOLD','POINTS_RELEASE') THEN
  IF NOT EXISTS(
   SELECT 1 FROM redemption r JOIN points_account wallet
    ON wallet.root_realm_id=r.root_realm_id AND wallet.id=r.points_account_id
   WHERE r.root_realm_id=NEW.root_realm_id AND r.id=NEW.redemption_id
    AND wallet.id=NEW.points_account_id
    AND wallet.referrer_account_ref=r.recipient_account_ref
    AND r.policy_version=NEW.policy_version
    AND r.payload_digest=NEW.qualifying_source_digest
    AND ((NEW.event_kind='POINTS_HOLD' AND r.state='HELD'
      AND NEW.points_delta=r.points_cost)
     OR (NEW.event_kind='POINTS_RELEASE' AND r.state='CANCELLED'
      AND NEW.points_delta=-r.points_cost))
  ) THEN RAISE EXCEPTION 'Verified original redemption points source required'; END IF;
  RETURN NEW;
 END IF;
 -- No DIGITAL entitlement/CG19 issued proof or CG12 physical issue owner
 -- is yet available; refuse fabricated spend and post-activation reversal.
 IF NEW.event_kind<>'QUALIFICATION' THEN
  RAISE EXCEPTION 'An original verified reward or reversal effect is required';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM referral_attribution att
  JOIN points_account wallet ON wallet.root_realm_id=att.root_realm_id
   AND wallet.programme_id=att.programme_id AND wallet.referrer_kind=att.referrer_kind
   AND wallet.referrer_relationship_ref=att.referrer_relationship_ref
   AND wallet.referrer_account_ref=att.referrer_account_ref
  WHERE att.root_realm_id=NEW.root_realm_id AND att.id=NEW.attribution_id
   AND wallet.id=NEW.points_account_id AND att.state='PENDING'
   AND att.policy_version=NEW.policy_version
   AND att.award_points=NEW.points_delta
   -- The first attribution remains immutable across a returned/corrected
   -- application; the credit must instead match the CURRENT approved digest.
   AND cg13_referral_code_current(att.root_realm_id,
       (SELECT code_value FROM referral_code WHERE root_realm_id=att.root_realm_id
        AND id=att.referral_code_ref))
   AND (
    (att.applicant_kind='MEMBER' AND EXISTS(
      SELECT 1 FROM membership_application app
      JOIN member m ON m.root_realm_id=app.root_realm_id
       AND m.original_application_id=app.id
       AND m.account_ref=att.applicant_account_ref AND m.status='ACTIVE'
      JOIN membership_application_effect effect
       ON effect.root_realm_id=m.root_realm_id AND effect.member_id=m.id
       AND effect.application_id=app.id
      JOIN membership_term term ON term.root_realm_id=m.root_realm_id
       AND term.member_id=m.id AND term.original_application_id=app.id
      JOIN cg03_case review ON review.realm_id=effect.root_realm_id
       AND review.id=effect.case_id AND review.status='OWNER_COMPLETED'
      WHERE app.root_realm_id=att.root_realm_id AND app.id=att.member_application_ref
       AND app.status='APPROVED' AND app.submitted_digest=NEW.qualifying_source_digest
       AND app.referral_input=(SELECT code_value FROM referral_code code
        WHERE code.root_realm_id=att.root_realm_id AND code.id=att.referral_code_ref)
       AND app.applicant_account_ref=att.applicant_account_ref
       AND (app.accepted_fee_minor=0 OR EXISTS(
        SELECT 1 FROM finance_membership_verified_collection paid
         WHERE paid.root_realm_id=app.root_realm_id AND paid.application_id=app.id
          AND paid.amount_minor=app.accepted_fee_minor))
       AND NOT EXISTS(
        SELECT 1 FROM finance_membership_verified_refund refunded
         WHERE refunded.root_realm_id=app.root_realm_id AND refunded.application_id=app.id)
    ))
    OR
    (att.applicant_kind='VOLUNTEER' AND EXISTS(
      SELECT 1 FROM volunteer_application app
      JOIN volunteer v ON v.root_realm_id=app.root_realm_id
       AND v.original_application_id=app.id AND v.account_ref=att.applicant_account_ref
      JOIN volunteer_approval_effect effect ON effect.root_realm_id=v.root_realm_id
       AND effect.application_id=app.id AND effect.volunteer_id=v.id
      JOIN cg03_case review ON review.realm_id=effect.root_realm_id
       AND review.id=effect.case_id AND review.status='OWNER_COMPLETED'
      WHERE app.root_realm_id=att.root_realm_id
       AND app.id=att.volunteer_application_ref AND app.status='APPROVED'
       AND app.submitted_digest=NEW.qualifying_source_digest
       AND app.referral_input=(SELECT code_value FROM referral_code code
        WHERE code.root_realm_id=att.root_realm_id AND code.id=att.referral_code_ref)
       AND app.applicant_account_ref=att.applicant_account_ref
       AND cg04_current_volunteer(v.root_realm_id,v.id,v.account_ref,v.branch_ref)
    ))
   )
 ) THEN RAISE EXCEPTION 'Original verified CG04 activation required for referral credit'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_points_projection_at_commit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE wallet uuid; realm uuid; current_account record; totals record;
BEGIN
 -- Each trigger's NEW row has a DIFFERENT record type. Do not evaluate
 -- nonexistent fields in a shared CASE expression on the other table.
 IF TG_TABLE_NAME='points_event' THEN
  wallet:=NEW.points_account_id;
 ELSE
  wallet:=NEW.id;
 END IF;
 realm:=NEW.root_realm_id;
 SELECT * INTO current_account FROM points_account
  WHERE root_realm_id=realm AND id=wallet;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original points wallet is required'; END IF;
 SELECT COALESCE(SUM(points_delta) FILTER(WHERE event_kind='QUALIFICATION'),0)::bigint AS earned,
  COALESCE(-SUM(points_delta) FILTER(WHERE event_kind='QUALIFICATION_REVERSAL'),0)::bigint AS reversed,
  COUNT(*) FILTER(WHERE event_kind='QUALIFICATION')::integer-
   COUNT(*) FILTER(WHERE event_kind='QUALIFICATION_REVERSAL')::integer AS qualifying_count,
  COALESCE(SUM(points_delta) FILTER(WHERE event_kind='POINTS_HOLD'),0)::bigint+
   COALESCE(SUM(points_delta) FILTER(WHERE event_kind='POINTS_RELEASE'),0)::bigint-
   COALESCE(SUM(points_delta) FILTER(WHERE event_kind='POINTS_SPENT'),0)::bigint AS held,
  COALESCE(SUM(points_delta) FILTER(WHERE event_kind='POINTS_SPENT'),0)::bigint AS spent
  INTO totals FROM points_event WHERE root_realm_id=realm AND points_account_id=wallet;
 IF (current_account.earned_points,current_account.reversed_points,
    current_account.qualified_referrals,current_account.held_points,
    current_account.spent_points)
   IS DISTINCT FROM (totals.earned,totals.reversed,totals.qualifying_count,
    totals.held,totals.spent)
 THEN RAISE EXCEPTION 'Points account must match original immutable events'; END IF;
 IF TG_TABLE_NAME='points_event' AND NEW.event_kind='QUALIFICATION' AND NOT EXISTS(
  SELECT 1 FROM reward_rank_event rank
   WHERE rank.root_realm_id=realm AND rank.points_account_id=wallet
    AND rank.qualifying_points_event_id=NEW.id
 ) THEN RAISE EXCEPTION 'Verified points award requires frozen rank snapshot'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_product_current_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (
  (NEW.id,NEW.root_realm_id,NEW.programme_id,NEW.created_by,NEW.created_at)
   IS DISTINCT FROM
  (OLD.id,OLD.root_realm_id,OLD.programme_id,OLD.created_by,OLD.created_at)
  OR NEW.version<>OLD.version+1
 ) THEN RAISE EXCEPTION 'Reward product identity/version cannot be rewritten'; END IF;
 IF TG_OP='INSERT' AND NEW.version<>1 THEN
  RAISE EXCEPTION 'Reward product starts at revision one'; END IF;
 IF NEW.product_type='PHYSICAL' AND NEW.status<>'ARCHIVED' AND NOT EXISTS(
  SELECT 1 FROM inventory_item item JOIN inventory_location loc
    ON loc.root_realm_id=item.root_realm_id
  LEFT JOIN branch b ON b.id=loc.branch_ref AND b.root_realm_id=loc.root_realm_id
  WHERE item.id=NEW.cg12_item_ref AND loc.id=NEW.cg12_location_ref
   AND item.root_realm_id=NEW.root_realm_id
   AND item.status='ACTIVE' AND item.unit_code='PIECE' AND item.qty_scale=0
   AND loc.status='ACTIVE' AND (loc.branch_ref IS NULL OR b.status='ACTIVE')
  FOR SHARE OF item,loc
 ) THEN RAISE EXCEPTION 'Original CG12 ACTIVE whole-piece stock source is required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_programme_current_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM access_realm WHERE id=NEW.root_realm_id
  AND realm_key='FOUNDATION_ROOT') THEN
  RAISE EXCEPTION 'Only the Foundation may manage referral programmes'; END IF;
 IF TG_OP='UPDATE' AND (
  (NEW.id,NEW.root_realm_id,NEW.programme_code,NEW.created_by,NEW.created_at)
   IS DISTINCT FROM
  (OLD.id,OLD.root_realm_id,OLD.programme_code,OLD.created_by,OLD.created_at)
  OR NEW.version<>OLD.version+1 OR NEW.active_policy_version NOT IN
  (OLD.active_policy_version,OLD.active_policy_version+1)
 ) THEN RAISE EXCEPTION 'Referral programme identity/version cannot be rewritten'; END IF;
 IF TG_OP='INSERT' AND (NEW.version<>1 OR NEW.active_policy_version<>1)
  THEN RAISE EXCEPTION 'Referral programme starts with one policy version'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_rank_event_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM points_event e JOIN points_account wallet
   ON wallet.root_realm_id=e.root_realm_id AND wallet.id=e.points_account_id
  WHERE e.root_realm_id=NEW.root_realm_id
   AND e.id=NEW.qualifying_points_event_id
   AND e.points_account_id=NEW.points_account_id
   AND e.event_kind='QUALIFICATION'
   AND e.policy_version=NEW.policy_version
   AND wallet.current_rank_name IS NOT DISTINCT FROM NEW.resulting_rank_name
   AND wallet.current_rank_sort IS NOT DISTINCT FROM NEW.resulting_rank_sort
   AND wallet.qualified_referrals=NEW.qualified_referrals_snapshot
   AND GREATEST(wallet.earned_points-wallet.reversed_points-
    wallet.held_points-wallet.spent_points,0)=NEW.eligible_points_snapshot
 ) THEN RAISE EXCEPTION 'Frozen rank requires exact genuine wallet award and projection'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_redemption_commit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM points_event e JOIN redemption_event receipt
   ON receipt.root_realm_id=e.root_realm_id
    AND receipt.original_points_event_id=e.id AND receipt.redemption_id=NEW.id
  WHERE e.root_realm_id=NEW.root_realm_id AND e.redemption_id=NEW.id
   AND e.points_account_id=NEW.points_account_id
   AND e.event_kind='POINTS_HOLD' AND e.points_delta=NEW.points_cost
   AND receipt.event_kind='REQUESTED'
 ) THEN RAISE EXCEPTION 'Original points hold and source receipt required'; END IF;
 IF NEW.state='FULFILLED' AND NOT EXISTS(
  SELECT 1 FROM points_event e JOIN redemption_event receipt
   ON receipt.root_realm_id=e.root_realm_id
    AND receipt.original_points_event_id=e.id AND receipt.redemption_id=NEW.id
  LEFT JOIN cg19_reward_recognition proof ON proof.realm_id=NEW.root_realm_id
   AND proof.redemption_id=NEW.id
  LEFT JOIN cg19_reward_handover actual ON actual.realm_id=NEW.root_realm_id
   AND actual.redemption_id=NEW.id
  WHERE e.root_realm_id=NEW.root_realm_id AND e.redemption_id=NEW.id
   AND e.points_account_id=NEW.points_account_id
   AND e.event_kind='POINTS_SPENT' AND e.points_delta=NEW.points_cost
   AND e.policy_version=NEW.policy_version
   AND e.qualifying_source_digest=NEW.payload_digest
   AND ((NEW.product_type='DIGITAL'
    AND receipt.event_kind='RECOGNIZED'
    AND proof.recipient_account_ref=NEW.recipient_account_ref
    AND proof.source_key=NEW.request_key)
    OR (NEW.product_type='PHYSICAL'
    AND receipt.event_kind='HANDED_OVER'
    AND actual.recipient_account_ref=NEW.recipient_account_ref
    AND actual.source_key=NEW.request_key))
 ) THEN RAISE EXCEPTION 'Delivered reward needs exact spent points and original CG19 recipient proof'; END IF;
 IF NEW.product_type='PHYSICAL' AND NOT EXISTS(
  SELECT 1 FROM stock_reward_hold h
  JOIN reward_product_revision p ON p.root_realm_id=NEW.root_realm_id
   AND p.product_id=NEW.product_id AND p.revision=NEW.product_revision
  WHERE h.root_realm_id=NEW.root_realm_id AND h.redemption_id=NEW.id
   AND h.recipient_account_ref=NEW.recipient_account_ref
   AND h.item_id=p.cg12_item_ref AND h.location_id=p.cg12_location_ref
   AND ((NEW.state='HELD' AND h.state='HELD')
    OR (NEW.state='CANCELLED' AND h.state='RELEASED')
    OR (NEW.state='ISSUED_AWAITING_HANDOVER' AND h.state='ISSUED')
    OR (NEW.state='FULFILLED' AND h.state='ISSUED'))
 ) THEN RAISE EXCEPTION 'Original CG12 one-unit reservation source required'; END IF;
 IF NEW.state='CANCELLED' AND NOT EXISTS(
  SELECT 1 FROM points_event e JOIN redemption_event receipt
   ON receipt.root_realm_id=e.root_realm_id
    AND receipt.original_points_event_id=e.id AND receipt.redemption_id=NEW.id
  WHERE e.root_realm_id=NEW.root_realm_id AND e.redemption_id=NEW.id
   AND e.points_account_id=NEW.points_account_id
   AND e.event_kind='POINTS_RELEASE' AND e.points_delta=-NEW.points_cost
   AND receipt.event_kind='CANCELLED'
 ) THEN RAISE EXCEPTION 'Cancelled redemption needs exact original points release'; END IF;
 RETURN NULL;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg13_referral_code_current(root uuid, opaque text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(
  SELECT 1 FROM referral_code c
  JOIN referral_program p ON p.root_realm_id=c.root_realm_id AND p.id=c.programme_id
  WHERE c.root_realm_id=root AND c.code_value=opaque AND p.status='ACTIVE'
  AND (p.audience=c.referrer_kind OR p.audience='BOTH')
  AND EXISTS(SELECT 1 FROM referral_policy_version policy
   WHERE policy.root_realm_id=p.root_realm_id AND policy.programme_id=p.id
    AND policy.effective_from<=now())
  AND (
   (c.referrer_kind='MEMBER' AND EXISTS(
    SELECT 1 FROM member m
    JOIN membership_application_effect effect ON effect.root_realm_id=m.root_realm_id
     AND effect.member_id=m.id AND effect.application_id=m.original_application_id
    JOIN membership_application app ON app.root_realm_id=m.root_realm_id
     AND app.id=m.original_application_id AND app.status='APPROVED'
    JOIN cg03_case review ON review.realm_id=effect.root_realm_id
     AND review.id=effect.case_id AND review.status='OWNER_COMPLETED'
    JOIN account verified ON verified.realm_id=m.root_realm_id
     AND verified.id=m.account_ref AND verified.status='ACTIVE'
     AND verified.contact_phone_verified_at IS NOT NULL
    JOIN membership_term term ON term.root_realm_id=m.root_realm_id
     AND term.member_id=m.id
    LEFT JOIN branch branch ON branch.root_realm_id=m.root_realm_id
     AND branch.id=m.branch_ref
    WHERE m.root_realm_id=c.root_realm_id AND m.id=c.referrer_relationship_ref
     AND m.account_ref=c.referrer_account_ref AND m.status='ACTIVE'
     AND (m.branch_ref IS NULL OR branch.status='ACTIVE')
     AND term.starts_on<=(now() AT TIME ZONE 'Asia/Kolkata')::date
     AND (term.expires_on IS NULL OR
      term.expires_on>(now() AT TIME ZONE 'Asia/Kolkata')::date)
   )) OR
   (c.referrer_kind='VOLUNTEER' AND EXISTS(
    SELECT 1 FROM volunteer v WHERE v.root_realm_id=c.root_realm_id
     AND v.id=c.referrer_relationship_ref AND v.account_ref=c.referrer_account_ref
     AND cg04_current_volunteer(v.root_realm_id,v.id,v.account_ref,v.branch_ref)
   ))
  )
 );
$function$
;
CREATE OR REPLACE FUNCTION public.cg13_referral_code_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM referral_program p
  JOIN LATERAL (
   SELECT 1 FROM referral_policy_version policy
    WHERE policy.root_realm_id=p.root_realm_id AND policy.programme_id=p.id
     AND policy.effective_from<=now() LIMIT 1
  ) current_policy ON true
  WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.programme_id
    AND p.status='ACTIVE'
    AND (p.audience=NEW.referrer_kind OR p.audience='BOTH')
 ) THEN RAISE EXCEPTION 'Original active referral programme is required'; END IF;
 IF NEW.referrer_kind='MEMBER' THEN
  IF NOT EXISTS(
   SELECT 1 FROM member m
   JOIN membership_application_effect effect ON effect.root_realm_id=m.root_realm_id
    AND effect.member_id=m.id AND effect.application_id=m.original_application_id
   JOIN membership_application app ON app.root_realm_id=m.root_realm_id
    AND app.id=m.original_application_id AND app.status='APPROVED'
   JOIN cg03_case review ON review.realm_id=effect.root_realm_id
    AND review.id=effect.case_id AND review.status='OWNER_COMPLETED'
   JOIN account verified ON verified.realm_id=m.root_realm_id
    AND verified.id=m.account_ref AND verified.status='ACTIVE'
    AND verified.contact_phone_verified_at IS NOT NULL
   JOIN membership_term term
    ON term.root_realm_id=m.root_realm_id AND term.member_id=m.id
   LEFT JOIN branch b ON b.root_realm_id=m.root_realm_id AND b.id=m.branch_ref
   WHERE m.root_realm_id=NEW.root_realm_id
    AND m.id=NEW.referrer_relationship_ref
    AND m.account_ref=NEW.referrer_account_ref AND m.status='ACTIVE'
    AND (m.branch_ref IS NULL OR b.status='ACTIVE')
    AND term.starts_on<=(now() AT TIME ZONE 'Asia/Kolkata')::date
    AND (term.expires_on IS NULL OR
      term.expires_on>(now() AT TIME ZONE 'Asia/Kolkata')::date)
  ) THEN RAISE EXCEPTION 'Original active member required'; END IF;
 ELSE
  IF NOT EXISTS(
   SELECT 1 FROM volunteer v WHERE v.root_realm_id=NEW.root_realm_id
    AND v.id=NEW.referrer_relationship_ref
    AND v.account_ref=NEW.referrer_account_ref AND v.status='ACTIVE'
    AND cg04_current_volunteer(v.root_realm_id,v.id,v.account_ref,v.branch_ref)
  ) THEN RAISE EXCEPTION 'Original active volunteer required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg14_approved_fee_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
   IF OLD.status='APPROVED' THEN
     RAISE EXCEPTION 'Approved center fee history cannot be deleted';
   END IF;
   RETURN OLD;
 END IF;
 IF OLD.status='APPROVED' THEN
   IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
      NEW.doctor_center_id IS DISTINCT FROM OLD.doctor_center_id OR
      NEW.fee_kind IS DISTINCT FROM OLD.fee_kind OR
      NEW.consultation_mode IS DISTINCT FROM OLD.consultation_mode OR
      NEW.currency IS DISTINCT FROM OLD.currency OR
      NEW.amount_minor IS DISTINCT FROM OLD.amount_minor OR
      NEW.effective_from IS DISTINCT FROM OLD.effective_from OR
      NEW.proposed_by IS DISTINCT FROM OLD.proposed_by OR
      NEW.approved_by IS DISTINCT FROM OLD.approved_by OR
      NEW.approved_at IS DISTINCT FROM OLD.approved_at OR
      NEW.status IS DISTINCT FROM OLD.status OR
      NEW.created_at IS DISTINCT FROM OLD.created_at OR
      NEW.id IS DISTINCT FROM OLD.id THEN
     RAISE EXCEPTION 'Approved center fee amount and source are immutable';
   END IF;
   IF NEW.effective_to IS DISTINCT FROM OLD.effective_to THEN
     IF NEW.effective_to IS NULL OR NEW.effective_to<now() OR
       NEW.effective_to<=OLD.effective_from OR
       (OLD.effective_to IS NOT NULL AND
        NEW.effective_to>OLD.effective_to) THEN
       RAISE EXCEPTION 'Only future shortening of approved fee validity is allowed';
     END IF;
     IF NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
       RAISE EXCEPTION 'Accepted fee validity change requires next version';
     END IF;
   ELSIF NEW.version IS DISTINCT FROM OLD.version OR
         NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
     RAISE EXCEPTION 'Unchanged approved fee cannot be silently rewritten';
   END IF;
 END IF;
 RETURN NEW;
END $function$
;
