CREATE OR REPLACE FUNCTION public.cg15_exception_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original doctor schedule exception cannot be deleted';
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR
  NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
  NEW.schedule_id IS DISTINCT FROM OLD.schedule_id OR
  NEW.doctor_id IS DISTINCT FROM OLD.doctor_id OR
  NEW.center_id IS DISTINCT FROM OLD.center_id OR
  NEW.association_id IS DISTINCT FROM OLD.association_id OR
  NEW.kind IS DISTINCT FROM OLD.kind OR
  NEW.start_at IS DISTINCT FROM OLD.start_at OR
  NEW.end_at IS DISTINCT FROM OLD.end_at OR
  NEW.reason IS DISTINCT FROM OLD.reason OR
  NEW.source_digest IS DISTINCT FROM OLD.source_digest OR
  NEW.proposed_by IS DISTINCT FROM OLD.proposed_by OR
  NEW.created_at IS DISTINCT FROM OLD.created_at OR
  (OLD.original_case_ref IS NOT NULL AND
   NEW.original_case_ref IS DISTINCT FROM OLD.original_case_ref) OR
  (OLD.approved_case_ref IS NOT NULL AND
   NEW.approved_case_ref IS DISTINCT FROM OLD.approved_case_ref) OR
  NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
  RAISE EXCEPTION 'Original doctor schedule exception cannot be rewritten';
 END IF;
 IF NEW.state IS DISTINCT FROM OLD.state AND NOT (
    OLD.kind='LEAVE' AND OLD.state='PENDING' AND NEW.state='ACTIVE'
      AND NEW.original_case_ref IS NOT NULL
      AND NEW.approved_case_ref=NEW.original_case_ref
   OR NEW.state='CANCELLED' AND (
      OLD.kind='LEAVE' AND OLD.state='PENDING'
      OR OLD.kind<>'LEAVE' AND OLD.state='ACTIVE'
   )
 ) THEN
  RAISE EXCEPTION 'Invalid healthcare schedule exception transition';
 END IF;
 IF NEW.approved_case_ref IS DISTINCT FROM OLD.approved_case_ref AND NOT (
   OLD.approved_case_ref IS NULL AND NEW.kind='LEAVE'
   AND OLD.state='PENDING' AND NEW.state='ACTIVE'
   AND NEW.approved_case_ref=NEW.original_case_ref
 ) THEN
  RAISE EXCEPTION 'Approved doctor leave source cannot be rewritten';
 END IF;
 IF NEW.original_case_ref IS DISTINCT FROM OLD.original_case_ref AND NOT (
   OLD.kind='LEAVE' AND OLD.state='PENDING'
   AND OLD.original_case_ref IS NULL AND NEW.original_case_ref IS NOT NULL
   AND NEW.state='PENDING' AND NEW.approved_case_ref IS NULL
 ) THEN
  RAISE EXCEPTION 'Original doctor leave case may be linked only once';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg15_patient_center_claim_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Patient identity claim evidence cannot be deleted';
 END IF;
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
  NEW.id IS DISTINCT FROM OLD.id OR
  NEW.intake_id IS DISTINCT FROM OLD.intake_id OR
  NEW.patient_id IS DISTINCT FROM OLD.patient_id OR
  NEW.center_id IS DISTINCT FROM OLD.center_id OR
  NEW.issued_by_account IS DISTINCT FROM OLD.issued_by_account OR
  NEW.request_key IS DISTINCT FROM OLD.request_key OR
  NEW.claim_digest IS DISTINCT FROM OLD.claim_digest OR
  NEW.identity_checked_in_person IS DISTINCT FROM OLD.identity_checked_in_person OR
  NEW.expires_at IS DISTINCT FROM OLD.expires_at OR
  NEW.created_at IS DISTINCT FROM OLD.created_at OR
  (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at) OR
  (OLD.claimed_at IS NOT NULL AND NEW.claimed_at IS DISTINCT FROM OLD.claimed_at) OR
  (OLD.claimed_by_account IS NOT NULL AND
   NEW.claimed_by_account IS DISTINCT FROM OLD.claimed_by_account) OR
  (NEW.claimed_at IS NOT NULL AND
   (NEW.revoked_at IS NOT NULL OR NEW.claimed_by_account IS NULL)) OR
  (NEW.revoked_at IS NOT NULL AND NEW.claimed_at IS NOT NULL) THEN
  RAISE EXCEPTION 'Original patient identity claim evidence cannot be rewritten';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg15_patient_duplicate_review_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Patient identity review evidence is not deletable';
 END IF;
 IF OLD.status<>'PENDING' OR NEW.status NOT IN('APPROVED','REJECTED')
  OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.id IS DISTINCT FROM OLD.id
  OR NEW.source_patient_id IS DISTINCT FROM OLD.source_patient_id
  OR NEW.canonical_patient_id IS DISTINCT FROM OLD.canonical_patient_id
  OR NEW.proposed_by_account IS DISTINCT FROM OLD.proposed_by_account
  OR NEW.request_key IS DISTINCT FROM OLD.request_key
  OR NEW.request_digest IS DISTINCT FROM OLD.request_digest
  OR NEW.created_at IS DISTINCT FROM OLD.created_at
  OR NEW.revision<>2 OR NEW.decided_by_account IS NULL
  OR NEW.decided_by_account=OLD.proposed_by_account
  OR NEW.decision_at IS NULL THEN
  RAISE EXCEPTION 'Original restricted patient review source cannot be rewritten';
 END IF;
 RETURN NEW;
END; $function$
;
