CREATE OR REPLACE FUNCTION public.cg16_equipment_event_required()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM lab_equipment_event e
  WHERE e.root_realm_id=NEW.root_realm_id AND
   e.equipment_ref=NEW.id AND e.center_ref=NEW.center_ref AND
   e.prior_revision=OLD.revision AND e.new_revision=NEW.revision) THEN
   RAISE EXCEPTION 'Equipment state requires original auditable source event';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_equipment_ready_requires_quality()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.readiness='READY' THEN
  IF NEW.status<>'ACTIVE' OR NEW.evidence_file_ref IS NULL OR
     NEW.calibration_due_on IS NULL OR
     NEW.calibration_due_on<(SELECT (now() AT TIME ZONE center.time_zone)::date
        FROM health_center center WHERE
        center.root_realm_id=NEW.root_realm_id AND center.id=NEW.center_ref) OR
     NOT EXISTS(SELECT 1 FROM cg19_lab_quality_file f
      JOIN cg19_lab_quality_intent intent
       ON intent.root_realm_id=f.root_realm_id AND
          intent.id=f.intent_ref AND intent.status='VALIDATED'
      WHERE f.root_realm_id=NEW.root_realm_id AND f.center_ref=NEW.center_ref
       AND f.equipment_ref=NEW.id AND f.id=NEW.evidence_file_ref
       AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL)
  THEN RAISE EXCEPTION 'Ready equipment requires genuine clean scanned quality evidence';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_equipment_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.id IS DISTINCT FROM OLD.id OR NEW.center_ref IS DISTINCT FROM OLD.center_ref
  OR NEW.equipment_code IS DISTINCT FROM OLD.equipment_code
  OR NEW.display_name IS DISTINCT FROM OLD.display_name
  OR NEW.manufacturer IS DISTINCT FROM OLD.manufacturer
  OR NEW.model IS DISTINCT FROM OLD.model
  OR NEW.serial_number IS DISTINCT FROM OLD.serial_number
  OR NEW.created_by IS DISTINCT FROM OLD.created_by
  OR NEW.created_at IS DISTINCT FROM OLD.created_at OR
  NEW.revision<>OLD.revision+1 THEN
   RAISE EXCEPTION 'Registered equipment identity cannot be rewritten';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_lab_correction_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'An original laboratory correction cannot be edited';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM lab_result_revision previous
  JOIN cg16_lab_report_release prior ON
   prior.root_realm_id=previous.root_realm_id
   AND prior.order_ref=previous.order_ref
   AND prior.result_revision_ref=previous.id
  JOIN lab_result_revision next ON
   next.root_realm_id=previous.root_realm_id
   AND next.order_ref=previous.order_ref
  JOIN lab_order orders ON
   orders.root_realm_id=previous.root_realm_id
   AND orders.id=previous.order_ref AND orders.status='RESULT_READY'
  JOIN cg16_lab_result_professional_review review ON
   review.root_realm_id=prior.root_realm_id
   AND review.id=prior.professional_review_ref
   AND review.decision='APPROVE'
  WHERE previous.root_realm_id=NEW.root_realm_id
   AND previous.order_ref=NEW.order_ref
   AND previous.id=NEW.prior_result_ref
   AND previous.result_state='RESULT_READY'
   AND prior.id=NEW.prior_release_ref
   AND next.id=NEW.result_revision_ref
   AND next.result_state='DRAFT'
   AND next.corrects_revision_ref=previous.id
   AND next.operator_account_ref=NEW.created_by_account
   AND next.source_key=NEW.request_key
   AND next.version_no=previous.version_no+1
   AND next.version_no=(SELECT max(latest.version_no)
    FROM lab_result_revision latest
    WHERE latest.root_realm_id=next.root_realm_id
    AND latest.order_ref=next.order_ref)
   AND EXISTS(SELECT 1 FROM cg15_patient_consent consent
    WHERE consent.root_realm_id=orders.root_realm_id
    AND consent.patient_id=orders.patient_ref
    AND consent.purpose='PATIENT_CARE' AND consent.granted=true
    AND consent.revision_no=(SELECT max(latest.revision_no)
     FROM cg15_patient_consent latest
     WHERE latest.root_realm_id=consent.root_realm_id
     AND latest.patient_id=consent.patient_id
     AND latest.purpose='PATIENT_CARE'))
 ) THEN
  RAISE EXCEPTION 'Correction requires genuine prior released PDF and new linked version';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_lab_professional_review_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Professional lab report decision is immutable';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM health_doctor_revision professional
  JOIN health_doctor doctor ON
   doctor.root_realm_id=professional.root_realm_id AND
   doctor.id=professional.doctor_id
  JOIN health_doctor_center affiliation ON
   affiliation.root_realm_id=professional.root_realm_id AND
   affiliation.id=NEW.reviewer_affiliation_ref AND
   affiliation.doctor_id=professional.doctor_id
  JOIN health_doctor_account_link clinician ON
   clinician.root_realm_id=doctor.root_realm_id AND
   clinician.doctor_id=doctor.id AND clinician.account_id=NEW.reviewer_account_ref
   AND clinician.status='ACTIVE' AND clinician.revoked_at IS NULL
  JOIN cg03_case doctor_review ON
   doctor_review.realm_id=professional.root_realm_id AND
   doctor_review.id=professional.approval_case_ref AND
   doctor_review.case_kind='HEALTH_DOCTOR_VERIFICATION' AND
   doctor_review.health_doctor_id=doctor.id AND
   doctor_review.health_doctor_revision_id=professional.id AND
   doctor_review.health_source_digest=professional.source_digest AND
   doctor_review.status='OWNER_COMPLETED'
  JOIN cg03_case_decision original_decision ON
   original_decision.realm_id=doctor_review.realm_id AND
   original_decision.case_id=doctor_review.id AND
   original_decision.action='APPROVE' AND
   original_decision.actor_id<>doctor_review.proposer_id AND
   original_decision.fresh_password_verified_at IS NOT NULL
  JOIN cg19_stored_file original_proof ON
   original_proof.realm_id=professional.root_realm_id AND
   original_proof.id=professional.proof_file_ref AND
   original_proof.owner_kind='CG14_DOCTOR' AND
   original_proof.health_doctor_id=doctor.id AND
   original_proof.health_source_version=professional.source_version AND
   original_proof.scan_status='CLEAN_VERIFIED' AND
   original_proof.revoked_at IS NULL
  JOIN cg19_upload_intent original_upload ON
   original_upload.id=original_proof.upload_intent_id AND
   original_upload.realm_id=original_proof.realm_id AND
   original_upload.owner_kind='CG14_DOCTOR' AND
   original_upload.classification='HEALTH_DOCTOR_LICENSE' AND
   original_upload.status='VALIDATED'
  JOIN lab_order accepted ON
   accepted.root_realm_id=professional.root_realm_id AND
   accepted.center_ref=affiliation.center_id AND
   accepted.id=NEW.order_ref
  JOIN health_center center ON
   center.root_realm_id=accepted.root_realm_id AND
   center.id=accepted.center_ref
  WHERE professional.root_realm_id=NEW.root_realm_id
   AND professional.id=NEW.reviewer_revision_ref
   AND professional.doctor_id=NEW.reviewer_doctor_ref
   AND professional.proof_file_ref=NEW.reviewer_license_proof_ref
   AND doctor.professional_license_valid_through=NEW.reviewer_license_valid_through
   AND doctor.professional_license_valid_through>=
       (now() AT TIME ZONE center.time_zone)::date
   AND professional.source_snapshot->>'professionalLicenseValidThrough'=
       to_char(doctor.professional_license_valid_through,'YYYY-MM-DD')
   AND professional.revision_no=(SELECT max(latest.revision_no)
       FROM health_doctor_revision latest WHERE
       latest.root_realm_id=professional.root_realm_id AND
       latest.doctor_id=professional.doctor_id)
   AND doctor.status='VERIFIED'
   AND center.status='VERIFIED' AND center.access_state='ENABLED'
   AND affiliation.affiliation_state='APPROVED'
   AND affiliation.approved_from<=now()
   AND (affiliation.approved_to IS NULL OR affiliation.approved_to>now())
   AND EXISTS(
     SELECT 1 FROM cg15_patient_consent consent
     WHERE consent.root_realm_id=accepted.root_realm_id AND
     consent.patient_id=accepted.patient_ref AND
     consent.purpose='PATIENT_CARE' AND consent.granted=true AND
     consent.revision_no=(SELECT max(last.revision_no)
       FROM cg15_patient_consent last WHERE
       last.root_realm_id=consent.root_realm_id AND
       last.patient_id=consent.patient_id AND last.purpose='PATIENT_CARE')
   )
 ) THEN
  RAISE EXCEPTION 'Professional review requires actual currently verified clinician source';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM lab_result_revision result
  JOIN cg19_lab_result_file file ON
   file.root_realm_id=result.root_realm_id AND
   file.result_revision_ref=result.id AND
   file.id=NEW.original_cg19_file_ref AND
   file.order_ref=result.order_ref AND
   file.scan_status='CLEAN_VERIFIED' AND file.revoked_at IS NULL
  JOIN cg19_lab_result_intent intent ON
   intent.root_realm_id=file.root_realm_id AND
   intent.id=file.intent_ref AND intent.status='VALIDATED'
  WHERE result.root_realm_id=NEW.root_realm_id AND
   result.id=NEW.result_revision_ref AND
   result.order_ref=NEW.order_ref AND
   result.version_no=NEW.result_version AND
   result.result_state='RESULT_READY' AND
   result.original_cg19_file_ref=file.id AND
   result.report_digest=file.sha256 AND
   result.report_digest=NEW.report_digest AND
   result.operator_account_ref=NEW.operator_account_ref
   AND result.version_no=(SELECT max(latest.version_no)
     FROM lab_result_revision latest WHERE
     latest.root_realm_id=result.root_realm_id AND
     latest.order_ref=result.order_ref)
   AND EXISTS(SELECT 1 FROM cg16_lab_review_file_access viewed
     WHERE viewed.root_realm_id=NEW.root_realm_id
       AND viewed.result_revision_ref=NEW.result_revision_ref
       AND viewed.original_cg19_file_ref=NEW.original_cg19_file_ref
       AND viewed.reviewer_account_ref=NEW.reviewer_account_ref
       AND viewed.report_digest=NEW.report_digest)
 ) THEN
  RAISE EXCEPTION 'Professional decision requires exact original verified lab report';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_order_accepted_total_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE recorded bigint; lines bigint;
BEGIN
 SELECT count(*),COALESCE(sum(accepted_line_total_minor),0)
 INTO lines,recorded FROM lab_order_line
 WHERE root_realm_id=NEW.root_realm_id AND order_ref=NEW.id;
 IF lines=0 OR recorded<>NEW.accepted_center_total_minor THEN
  RAISE EXCEPTION 'Accepted laboratory total must match frozen test lines';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_order_command_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR
  NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
  NEW.actor_ref IS DISTINCT FROM OLD.actor_ref OR
  NEW.request_key IS DISTINCT FROM OLD.request_key OR
  NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
  NEW.created_at IS DISTINCT FROM OLD.created_at OR
  OLD.order_ref IS NOT NULL OR NEW.order_ref IS NULL THEN
   RAISE EXCEPTION 'Original clinical order command cannot be rewritten';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_order_line_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE m record; amount record;
BEGIN
 SELECT m.center_ref,m.test_or_package_kind,m.test_ref,m.package_ref,
        o.center_ref AS original_center
 INTO m
 FROM lab_center_test_mapping m JOIN lab_order o
 ON o.root_realm_id=m.root_realm_id AND o.id=NEW.order_ref
 WHERE m.root_realm_id=NEW.root_realm_id AND m.id=NEW.mapping_ref;
 SELECT p.center_test_mapping_ref,p.version_no,p.status,
        p.advertised_patient_price_minor
 INTO amount FROM lab_center_price_version p
 WHERE p.root_realm_id=NEW.root_realm_id AND p.id=NEW.price_ref;
 IF m.center_ref IS DISTINCT FROM m.original_center
   OR m.test_or_package_kind IS NULL
   OR amount.status IS DISTINCT FROM 'APPROVED'
   OR amount.center_test_mapping_ref IS DISTINCT FROM NEW.mapping_ref
   OR amount.version_no IS DISTINCT FROM NEW.accepted_price_version
   OR (NEW.source_package_ref IS NULL AND
       (m.test_or_package_kind<>'TEST' OR m.test_ref<>NEW.test_ref))
   OR (NEW.source_package_ref IS NOT NULL AND
       (m.test_or_package_kind<>'PACKAGE'
        OR m.package_ref<>NEW.source_package_ref
        OR NOT EXISTS(
          SELECT 1 FROM diagnostic_package_line line
          WHERE line.root_realm_id=NEW.root_realm_id
           AND line.package_ref=NEW.source_package_ref
           AND line.package_revision=NEW.package_revision
           AND line.test_ref=NEW.test_ref
           AND line.test_revision_at_approval=NEW.test_revision)))
 THEN
  RAISE EXCEPTION 'Original center lab price and test source mismatch';
 END IF;
 -- A package is distributed across individual lines by its accepted
 -- per-test quote allocation; one-to-one direct tests must match price.
 IF NEW.source_package_ref IS NULL AND
    NEW.accepted_unit_minor IS DISTINCT FROM amount.advertised_patient_price_minor THEN
  RAISE EXCEPTION 'Accepted test quote differs from original approved tariff';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_order_requires_real_custody()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE total_count bigint; collected_count bigint; processing_count bigint;
 pending_count bigint; rejected_count bigint; expected_event text;
 verified_source_key uuid;
BEGIN
 IF NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NULL; END IF;
 -- A scanner-verifiable report is RESULT_READY, NEVER approved/released.
 -- Prevent direct SQL bypasses of the exact source and custody guard.
 IF NEW.status='RESULT_READY' THEN
  IF OLD.status<>'PROCESSING' THEN
   RAISE EXCEPTION 'Only a processing lab order can have a verified result';
  END IF;
  SELECT result.source_key INTO verified_source_key
  FROM lab_result_revision result
  JOIN cg19_lab_result_file file ON
   file.root_realm_id=result.root_realm_id AND
   file.order_ref=result.order_ref AND
   file.result_revision_ref=result.id AND
   file.id=result.original_cg19_file_ref AND
   file.sha256=result.report_digest AND
   file.scan_status='CLEAN_VERIFIED' AND file.revoked_at IS NULL
  JOIN cg19_lab_result_intent intent ON
   intent.root_realm_id=file.root_realm_id AND intent.id=file.intent_ref
   AND intent.status='VALIDATED' AND
   intent.center_ref=NEW.center_ref AND intent.patient_ref=NEW.patient_ref
  WHERE result.root_realm_id=NEW.root_realm_id
   AND result.order_ref=NEW.id AND result.result_state='RESULT_READY'
   AND result.version_no=(SELECT max(last.version_no) FROM lab_result_revision last
     WHERE last.root_realm_id=NEW.root_realm_id AND last.order_ref=NEW.id);
  IF verified_source_key IS NULL THEN
   RAISE EXCEPTION 'Ready lab result requires original CG19 clean file';
  END IF;
  IF NOT EXISTS (
   SELECT 1 FROM lab_order_event event
   WHERE event.root_realm_id=NEW.root_realm_id AND event.order_ref=NEW.id
    AND event.prior_revision=OLD.revision AND event.new_revision=NEW.revision
    AND event.event_type='RESULT_FILE_READY' AND
    event.source_key=verified_source_key
  ) THEN
   RAISE EXCEPTION 'Original verified result requires the same immutable order event';
  END IF;
  SELECT count(*),count(*) FILTER(WHERE s.custody_state='PROCESSING')
  INTO total_count,processing_count
  FROM lab_sample s WHERE s.root_realm_id=NEW.root_realm_id AND s.order_ref=NEW.id
    AND NOT EXISTS (SELECT 1 FROM lab_sample replacement
      WHERE replacement.root_realm_id=s.root_realm_id AND
       replacement.order_ref=s.order_ref AND
       replacement.replacement_for_sample_ref=s.id);
  IF total_count=0 OR processing_count<>total_count THEN
   RAISE EXCEPTION 'Verified report requires every current specimen processing';
  END IF;
  RETURN NULL;
 END IF;
 -- Professional release/approval are not represented by this upload state.
 IF NEW.status='AWAITING_REVIEW' THEN
  RAISE EXCEPTION 'Professional review requires its own verified issuance source';
 END IF;

 -- A cancelled order cannot be revived by direct DB access.
 IF OLD.status IN('CANCELLED','RESULT_READY','AWAITING_REVIEW') THEN
  RAISE EXCEPTION 'Cancelled clinical order cannot resume';
 END IF;
 IF NEW.status='CANCELLED' THEN expected_event='CANCELLED';
 ELSIF NEW.status='RECOLLECTION_REQUIRED' OR
  (OLD.status='RECOLLECTION_REQUIRED' AND NEW.status='COLLECTION_PENDING') THEN
  -- Original rejected sample now has its own new replacement label.
  expected_event='RECOLLECTION_REQUESTED';
 ELSE expected_event='COLLECTION_RECORDED';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM lab_order_event e
  WHERE e.root_realm_id=NEW.root_realm_id AND e.order_ref=NEW.id
   AND e.prior_revision=OLD.revision AND e.new_revision=NEW.revision
   AND e.event_type=expected_event
 ) THEN
  RAISE EXCEPTION 'Clinical order state requires exact original source event';
 END IF;

 SELECT count(*),
  count(*) FILTER (WHERE s.custody_state IN ('COLLECTED','RECEIVED','PROCESSING','RESULT_READY')),
  count(*) FILTER (WHERE s.custody_state IN ('PROCESSING','RESULT_READY')),
  count(*) FILTER (WHERE s.custody_state='PENDING_COLLECTION'),
  count(*) FILTER (WHERE s.custody_state IN ('REJECTED','RECOLLECTION_REQUIRED'))
 INTO total_count,collected_count,processing_count,pending_count,rejected_count
 FROM lab_sample s
 WHERE s.root_realm_id=NEW.root_realm_id AND s.order_ref=NEW.id
  AND NOT EXISTS(
   SELECT 1 FROM lab_sample replacement
   WHERE replacement.root_realm_id=s.root_realm_id
    AND replacement.order_ref=s.order_ref
    AND replacement.replacement_for_sample_ref=s.id
  );

 IF NEW.status='COLLECTED' AND
  (total_count=0 OR collected_count<>total_count OR rejected_count<>0) THEN
  RAISE EXCEPTION 'Order collection requires all active original specimens collected';
 ELSIF NEW.status='PROCESSING' AND
  (total_count=0 OR processing_count<>total_count OR rejected_count<>0) THEN
  RAISE EXCEPTION 'Order processing requires all active original specimens processing';
 ELSIF NEW.status='RECOLLECTION_REQUIRED' AND rejected_count=0 THEN
  RAISE EXCEPTION 'Recollection status requires real rejected specimen evidence';
 ELSIF NEW.status='COLLECTION_PENDING' AND pending_count=0 THEN
  RAISE EXCEPTION 'Collection pending requires a real uncollected specimen';
 END IF;
 RETURN NULL;
END
$function$
;
CREATE OR REPLACE FUNCTION public.cg16_order_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.id IS DISTINCT FROM OLD.id
  OR NEW.display_order_ref IS DISTINCT FROM OLD.display_order_ref
  OR NEW.center_ref IS DISTINCT FROM OLD.center_ref
  OR NEW.patient_ref IS DISTINCT FROM OLD.patient_ref
  OR NEW.care_source_kind IS DISTINCT FROM OLD.care_source_kind
  OR NEW.center_intake_ref IS DISTINCT FROM OLD.center_intake_ref
  OR NEW.consultation_ref IS DISTINCT FROM OLD.consultation_ref
  OR NEW.care_purpose IS DISTINCT FROM OLD.care_purpose
  OR NEW.care_consent_revision IS DISTINCT FROM OLD.care_consent_revision
  OR NEW.consent_granted_at IS DISTINCT FROM OLD.consent_granted_at
  OR NEW.accepted_currency IS DISTINCT FROM OLD.accepted_currency
  OR NEW.accepted_center_total_minor IS DISTINCT FROM OLD.accepted_center_total_minor
  OR NEW.payment_verification_state IS DISTINCT FROM OLD.payment_verification_state
  OR NEW.source_key IS DISTINCT FROM OLD.source_key
  OR NEW.source_digest IS DISTINCT FROM OLD.source_digest
  OR NEW.created_by_account IS DISTINCT FROM OLD.created_by_account
  OR NEW.created_at IS DISTINCT FROM OLD.created_at
  OR NEW.revision<>OLD.revision+1 THEN
  RAISE EXCEPTION 'Accepted lab order source is immutable';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_price_requires_cg03_decision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.status IN ('APPROVED','REJECTED') THEN
   RAISE EXCEPTION 'Lab price cannot be final at creation without CG03 review';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.status IN ('APPROVED','REJECTED') AND
    NEW.status IS DISTINCT FROM OLD.status THEN
  RAISE EXCEPTION 'Reviewed lab price cannot be reopened';
 END IF;
 IF OLD.status='PROPOSED' AND NEW.status IN ('APPROVED','REJECTED') THEN
  IF NOT EXISTS(
   SELECT 1 FROM cg03_case c
   JOIN cg03_case_decision d ON d.realm_id=c.realm_id AND d.case_id=c.id
   WHERE c.realm_id=NEW.root_realm_id
    AND c.case_kind='HEALTH_LAB_PRICE_REVIEW'
    AND c.cg16_price_id=NEW.id
    AND c.cg16_price_version=NEW.version_no
    AND c.cg16_price_digest ~ '^[a-f0-9]{64}$'
    AND c.status=(CASE WHEN NEW.status='APPROVED' THEN 'PENDING_OWNER' ELSE 'REJECTED' END)
    AND d.action=(CASE WHEN NEW.status='APPROVED' THEN 'APPROVE' ELSE 'REJECT' END)
    AND (NEW.status='REJECTED' OR d.actor_id=NEW.approved_by)
    AND d.actor_id<>c.proposer_id
    AND c.proposer_id=NEW.proposed_by
    AND d.fresh_password_verified_at IS NOT NULL
    AND d.accepted_case_revision=c.revision
  ) THEN
   RAISE EXCEPTION 'Original CG03 lab price approval is required';
  END IF;
 END IF;
 RETURN NEW;
END
$function$
;
CREATE OR REPLACE FUNCTION public.cg16_professional_report_release_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Original clinician released report evidence is immutable';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM cg16_lab_result_professional_review review
  JOIN lab_result_revision result ON
   result.root_realm_id=review.root_realm_id AND
   result.id=review.result_revision_ref AND result.order_ref=review.order_ref
  JOIN lab_order orders ON
   orders.root_realm_id=result.root_realm_id AND orders.id=result.order_ref
  JOIN cg19_lab_result_file file ON
   file.root_realm_id=result.root_realm_id AND
   file.id=review.original_cg19_file_ref AND
   file.result_revision_ref=result.id AND file.order_ref=result.order_ref
  JOIN cg19_lab_result_intent intent ON
   intent.root_realm_id=file.root_realm_id AND intent.id=file.intent_ref
  JOIN health_doctor_account_link link ON
   link.root_realm_id=review.root_realm_id AND
   link.doctor_id=review.reviewer_doctor_ref AND
   link.account_id=NEW.clinician_account_ref
   AND link.status='ACTIVE' AND link.revoked_at IS NULL
  JOIN health_doctor doctor ON
   doctor.root_realm_id=link.root_realm_id AND doctor.id=link.doctor_id
   AND doctor.status='VERIFIED'
  JOIN health_center center ON
   center.root_realm_id=orders.root_realm_id AND center.id=orders.center_ref
   AND center.status='VERIFIED' AND center.access_state='ENABLED'
  JOIN health_doctor_center affiliation ON
   affiliation.root_realm_id=review.root_realm_id AND
   affiliation.id=review.reviewer_affiliation_ref
   AND affiliation.doctor_id=doctor.id
   AND affiliation.center_id=center.id
   AND affiliation.affiliation_state='APPROVED'
   AND affiliation.approved_from<=now()
   AND (affiliation.approved_to IS NULL OR affiliation.approved_to>now())
  WHERE review.root_realm_id=NEW.root_realm_id
   AND review.id=NEW.professional_review_ref
   AND review.order_ref=NEW.order_ref
   AND review.result_revision_ref=NEW.result_revision_ref
   AND review.original_cg19_file_ref=NEW.original_cg19_file_ref
   AND review.report_digest=NEW.report_digest
   AND review.decision='APPROVE'
   AND review.reviewer_account_ref=NEW.clinician_account_ref
   AND review.reviewer_doctor_ref=NEW.clinician_doctor_ref
   AND review.reviewer_revision_ref=NEW.clinician_revision_ref
   AND review.operator_account_ref<>NEW.clinician_account_ref
   AND orders.id=NEW.order_ref AND orders.patient_ref=NEW.patient_ref
   AND orders.center_ref=NEW.center_ref AND orders.status='RESULT_READY'
   AND result.result_state='RESULT_READY'
   AND result.report_digest=NEW.report_digest
   AND result.original_cg19_file_ref=NEW.original_cg19_file_ref
   AND result.version_no=(SELECT max(latest.version_no)
    FROM lab_result_revision latest WHERE
    latest.root_realm_id=result.root_realm_id AND latest.order_ref=result.order_ref)
   AND file.sha256=NEW.report_digest AND file.scan_status='CLEAN_VERIFIED'
   AND file.revoked_at IS NULL AND intent.status='VALIDATED'
   AND doctor.professional_license_valid_through >=
    (now() AT TIME ZONE center.time_zone)::date
   AND EXISTS(SELECT 1 FROM cg15_patient_consent consent
    WHERE consent.root_realm_id=orders.root_realm_id
    AND consent.patient_id=orders.patient_ref
    AND consent.purpose='PATIENT_CARE' AND consent.granted=true
    AND consent.revision_no=(SELECT max(last.revision_no)
     FROM cg15_patient_consent last
     WHERE last.root_realm_id=consent.root_realm_id
     AND last.patient_id=consent.patient_id AND last.purpose='PATIENT_CARE'))
 ) THEN
  RAISE EXCEPTION 'Patient release requires exact independent approved CG19 report and current clinician proof';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_result_once_verified()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR OLD.result_state<>'DRAFT' OR
  NEW.result_state<>'RESULT_READY' OR
  NEW.original_cg19_file_ref IS NULL OR NEW.report_digest IS NULL OR
  (to_jsonb(NEW)-'result_state'-'original_cg19_file_ref'-'report_digest')
   IS DISTINCT FROM
  (to_jsonb(OLD)-'result_state'-'original_cg19_file_ref'-'report_digest') OR
  NOT EXISTS(
   SELECT 1 FROM cg19_lab_result_file f
   JOIN cg19_lab_result_intent intent
    ON intent.root_realm_id=f.root_realm_id AND intent.id=f.intent_ref
   WHERE f.root_realm_id=NEW.root_realm_id AND f.id=NEW.original_cg19_file_ref
    AND f.result_revision_ref=NEW.id AND f.order_ref=NEW.order_ref
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND intent.status='VALIDATED' AND f.sha256=NEW.report_digest
  ) THEN
  RAISE EXCEPTION 'Result readiness requires exact original scanner verified CG19 report';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_sample_requires_custody_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM lab_sample_custody_event e
  WHERE e.root_realm_id=NEW.root_realm_id
   AND e.order_ref=NEW.order_ref
   AND e.sample_ref=NEW.id
   AND e.prior_revision=OLD.revision
   AND e.new_revision=NEW.revision
   AND e.from_status=OLD.custody_state
   AND e.to_status=NEW.custody_state
 ) THEN
  RAISE EXCEPTION 'A specimen custody change requires its original immutable event';
 END IF;
 RETURN NULL;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg16_sample_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.id IS DISTINCT FROM OLD.id OR NEW.order_ref IS DISTINCT FROM OLD.order_ref
  OR NEW.opaque_sample_label IS DISTINCT FROM OLD.opaque_sample_label
  OR NEW.material_type IS DISTINCT FROM OLD.material_type
  OR NEW.collection_location_ref IS DISTINCT FROM OLD.collection_location_ref
  OR NEW.replacement_for_sample_ref IS DISTINCT FROM OLD.replacement_for_sample_ref
  OR NEW.created_at IS DISTINCT FROM OLD.created_at
  OR NEW.revision IS DISTINCT FROM OLD.revision+1 THEN
  RAISE EXCEPTION 'Original specimen identity cannot be rewritten';
 END IF;
 -- No speculative clinical RESULT_READY until original CG19 result and
 -- licensed reviewer source are built and this guard is explicitly evolved.
 IF NOT (
   (OLD.custody_state='PENDING_COLLECTION' AND NEW.custody_state='COLLECTED')
   OR (OLD.custody_state='COLLECTED' AND NEW.custody_state IN('RECEIVED','REJECTED'))
   OR (OLD.custody_state='RECEIVED' AND NEW.custody_state IN('PROCESSING','REJECTED'))
   OR (OLD.custody_state='PROCESSING' AND NEW.custody_state='REJECTED')
   OR (OLD.custody_state='REJECTED' AND NEW.custody_state='RECOLLECTION_REQUIRED')
 ) THEN
  RAISE EXCEPTION 'Specimen custody must follow its original order';
 END IF;
 IF OLD.custody_state='PENDING_COLLECTION' THEN
  IF OLD.collected_at IS NOT NULL OR NEW.collected_at IS NULL
   OR NEW.received_at IS NOT NULL THEN
   RAISE EXCEPTION 'Specimen collection time must be recorded exactly once';
  END IF;
 ELSIF NEW.collected_at IS DISTINCT FROM OLD.collected_at THEN
  RAISE EXCEPTION 'Original specimen collection time is immutable';
 END IF;
 IF OLD.custody_state='COLLECTED' AND NEW.custody_state='RECEIVED' THEN
  IF OLD.received_at IS NOT NULL OR NEW.received_at IS NULL
   OR NEW.received_at<OLD.collected_at THEN
   RAISE EXCEPTION 'Specimen receipt cannot precede collection';
  END IF;
 ELSIF NEW.received_at IS DISTINCT FROM OLD.received_at THEN
  RAISE EXCEPTION 'Original specimen receipt time is immutable';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_block_claim_after_correction()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(
   SELECT 1 FROM cg17_liability_correction correction
   WHERE correction.root_realm_id=NEW.root_realm_id
     AND correction.liability_ref=NEW.liability_ref
 ) THEN
  RAISE EXCEPTION 'A reversed liability cannot be claimed again'
   USING ERRCODE='P1719';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_center_money_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Original center payment evidence is immutable; use a linked adjustment';
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_cg03_policy_source_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.cg17_policy_revision_id IS DISTINCT FROM OLD.cg17_policy_revision_id OR
    NEW.cg17_policy_version IS DISTINCT FROM OLD.cg17_policy_version OR
    NEW.cg17_policy_digest IS DISTINCT FROM OLD.cg17_policy_digest THEN
   RAISE EXCEPTION 'Original CG03 healthcare policy source cannot be rewritten';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_claim_patient_payment_scan_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Original patient payment-proof identity cannot be rewritten'
   USING ERRCODE='P1751';
 END IF;
 IF NEW.payment_file_ref IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM cg19_patient_private_file f
  JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id
   AND i.id=f.intent_id AND i.status='VALIDATED'
  WHERE f.realm_id=NEW.root_realm_id AND f.patient_id=NEW.patient_ref
   AND f.id=NEW.payment_file_ref
   AND f.classification='PATIENT_PARTNER_PAYMENT_PROOF'
   AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL)
 THEN RAISE EXCEPTION 'Original payment receipt is not verified'
  USING ERRCODE='P1752';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_claimed_correction_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE claim record; original record; changed record; source record;
 old_adjusted bigint; old_recovered bigint; needed bigint;
 originals bigint; reversed bigint; offset_mismatch bigint;
 payable_account uuid; bank_account uuid; bank_statement bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Claim correction evidence is immutable' USING ERRCODE='P1720';
 END IF;
 SELECT s.id,s.center_ref,s.approved_total_minor,s.paid_minor,s.state,s.proposed_by
 INTO claim FROM provider_settlement s
 WHERE s.root_realm_id=NEW.root_realm_id AND s.id=NEW.settlement_ref
   AND s.center_ref=NEW.center_ref FOR UPDATE;
 IF NOT FOUND OR claim.state NOT IN('PROPOSED','APPROVED','PARTIALLY_SETTLED','SETTLED') OR
    claim.proposed_by=NEW.reviewed_by_account OR
    EXISTS(SELECT 1 FROM cg17_liability_correction prior
     WHERE prior.root_realm_id=NEW.root_realm_id
       AND prior.liability_ref=NEW.liability_ref) THEN
  RAISE EXCEPTION 'Current original claim and different reviewer required'
   USING ERRCODE='P1720';
 END IF;
 SELECT l.id,l.amount_minor,l.source_digest,l.source_ref,
        e.id AS effect_ref,e.original_cg09_ref,e.posting_state,
        line.settlement_ref
 INTO source FROM foundation_liability l
 JOIN provider_settlement_line line ON line.root_realm_id=l.root_realm_id
   AND line.liability_ref=l.id AND line.center_ref=l.center_ref
   AND line.settlement_ref=NEW.settlement_ref
 JOIN cg17_financial_effect e ON e.root_realm_id=l.root_realm_id
   AND e.id=line.original_effect_ref AND e.liability_ref=l.id
   AND e.effect_kind='LIABILITY_ACCRUAL' AND e.posting_state='POSTED'
   AND e.source_digest=l.source_digest AND e.amount_minor=line.amount_minor
 WHERE l.root_realm_id=NEW.root_realm_id AND l.id=NEW.liability_ref
   AND l.center_ref=NEW.center_ref FOR SHARE OF l,e,line;
 IF NOT FOUND OR source.effect_ref<>NEW.original_effect_ref
    OR source.original_cg09_ref<>NEW.original_journal_ref
    OR source.amount_minor<>NEW.amount_minor
    OR EXISTS(SELECT 1 FROM cg17_provider_claim_correction prior
     WHERE prior.root_realm_id=NEW.root_realm_id
       AND prior.liability_ref=NEW.liability_ref) THEN
  RAISE EXCEPTION 'Original claimed liability changed or was already corrected'
   USING ERRCODE='P1720';
 END IF;
 SELECT coalesce(sum(amount_minor),0),coalesce(sum(recovery_minor),0)
 INTO old_adjusted,old_recovered
 FROM cg17_provider_claim_correction
 WHERE root_realm_id=NEW.root_realm_id AND settlement_ref=NEW.settlement_ref;
 IF old_adjusted+NEW.amount_minor>claim.approved_total_minor THEN
  RAISE EXCEPTION 'Correction exceeds the actual original claim' USING ERRCODE='P1720';
 END IF;
 needed=greatest(0,claim.paid_minor-old_recovered-
          (claim.approved_total_minor-old_adjusted-NEW.amount_minor));
 IF NEW.recovery_minor<>needed THEN
  RAISE EXCEPTION 'Actual overpaid bank recovery must match the claim deficit'
   USING ERRCODE='P1720';
 END IF;
 SELECT j.id,j.posting_kind,j.source_owner,j.source_ref,j.created_by,
        j.immutable_payload_digest,j.status,j.reversal_of_id
 INTO original FROM journal j
 WHERE j.root_realm_id=NEW.root_realm_id AND j.id=NEW.original_journal_ref
 FOR SHARE;
 SELECT j.id,j.posting_kind,j.source_owner,j.source_ref,j.created_by,
        j.immutable_payload_digest,j.status,j.reversal_of_id
 INTO changed FROM journal j
 WHERE j.root_realm_id=NEW.root_realm_id AND j.id=NEW.reversal_journal_ref
 FOR SHARE;
 IF original.id IS NULL OR changed.id IS NULL OR
    original.posting_kind<>'GENERAL' OR original.source_owner<>'CG-09' OR
    original.status<>'POSTED' OR original.reversal_of_id IS NOT NULL OR
    original.source_ref<>NEW.original_effect_ref OR
    original.immutable_payload_digest<>source.source_digest OR
    original.created_by=NEW.reviewed_by_account OR
    changed.posting_kind<>'REVERSAL' OR changed.source_owner<>'CG-09' OR
    changed.status<>'POSTED' OR changed.reversal_of_id<>original.id OR
    changed.source_ref<>original.id OR
    changed.created_by<>NEW.reviewed_by_account OR
    changed.immutable_payload_digest<>NEW.request_digest OR
    EXISTS(SELECT 1 FROM journal other
     WHERE other.root_realm_id=NEW.root_realm_id
       AND other.reversal_of_id=original.id AND other.id<>changed.id) OR
    NOT EXISTS(SELECT 1 FROM cg17_financial_effect e
     WHERE e.root_realm_id=NEW.root_realm_id AND
       e.id=NEW.reversal_effect_ref AND e.liability_ref=NEW.liability_ref
       AND e.effect_kind='LIABILITY_REVERSAL' AND e.posting_state='POSTED'
       AND e.original_cg09_ref=changed.id AND e.idempotency_key=NEW.request_key
       AND e.source_digest=NEW.request_digest
       AND e.amount_minor=NEW.amount_minor AND e.source_ref=source.source_ref)
 THEN
  RAISE EXCEPTION 'Exact CG09 posted original and correction effect required'
   USING ERRCODE='P1720';
 END IF;
 WITH prior AS (
   SELECT account_id,branch_id,count(*) AS n,
     sum(debit_minor) AS debit,sum(credit_minor) AS credit
   FROM journal_line WHERE root_realm_id=NEW.root_realm_id
     AND journal_id=original.id GROUP BY account_id,branch_id
 ), after AS (
   SELECT account_id,branch_id,count(*) AS n,
     sum(debit_minor) AS debit,sum(credit_minor) AS credit
   FROM journal_line WHERE root_realm_id=NEW.root_realm_id
     AND journal_id=changed.id GROUP BY account_id,branch_id
 ) SELECT count(*) INTO offset_mismatch
 FROM prior a FULL OUTER JOIN after b ON a.account_id=b.account_id
  AND a.branch_id IS NOT DISTINCT FROM b.branch_id
 WHERE a.account_id IS NULL OR b.account_id IS NULL OR a.n<>b.n
   OR a.debit<>b.credit OR a.credit<>b.debit;
 SELECT count(*) INTO originals
 FROM journal_line WHERE root_realm_id=NEW.root_realm_id
  AND journal_id=original.id;
 SELECT account_id INTO payable_account
 FROM journal_line
 WHERE root_realm_id=NEW.root_realm_id AND journal_id=original.id
  AND credit_minor=NEW.amount_minor AND debit_minor=0
  AND branch_id IS NULL
 LIMIT 2;
 SELECT count(*) INTO reversed FROM journal_line
 WHERE root_realm_id=NEW.root_realm_id AND journal_id=changed.id;
 IF offset_mismatch<>0 OR originals<>2 OR reversed<>2 OR payable_account IS NULL THEN
  RAISE EXCEPTION 'Original two-line accrual must be offset exactly'
   USING ERRCODE='P1720';
 END IF;
 IF needed>0 THEN
  -- Recover ONLY real independently verified CG09 incoming Foundation bank
  -- money; recorded-by/verified-by are distinct at the original CG09 owner.
  -- The credit is to the actual provider payable account, not invented income.
  SELECT bank.bank_account_id,bank.statement_amount_minor
  INTO bank_account,bank_statement
  FROM finance_bank_reconciliation bank
  JOIN journal recovery ON recovery.root_realm_id=bank.root_realm_id
   AND recovery.id=bank.journal_id
  JOIN finance_account incoming_bank
   ON incoming_bank.root_realm_id=bank.root_realm_id
   AND incoming_bank.id=bank.bank_account_id
   AND incoming_bank.account_kind='BANK'
   AND incoming_bank.scope_kind='FOUNDATION'
   AND incoming_bank.status='ACTIVE'
  JOIN finance_account original_payable
   ON original_payable.root_realm_id=bank.root_realm_id
   AND original_payable.id=payable_account
   AND original_payable.account_kind='GENERAL'
   AND original_payable.scope_kind='FOUNDATION'
   AND original_payable.status='ACTIVE'
  JOIN account_group payable_group
   ON payable_group.root_realm_id=original_payable.root_realm_id
   AND payable_group.id=original_payable.group_id
   AND payable_group.category='LIABILITY'
  WHERE bank.root_realm_id=NEW.root_realm_id
    AND bank.id=NEW.recovery_bank_ref
    AND bank.journal_id=NEW.recovery_journal_ref
    AND bank.status='VERIFIED' AND bank.variance_minor=0
    AND bank.statement_amount_minor=needed
    AND bank.posted_amount_minor=needed
    AND recovery.status='POSTED' AND recovery.source_owner='CG-09'
    AND recovery.posting_kind IN('GENERAL','VOUCHER')
    AND recovery.reversal_of_id IS NULL
  FOR SHARE OF bank,recovery;
  IF NOT FOUND OR bank_statement<>needed OR
     EXISTS(SELECT 1 FROM provider_settlement_payment used
       WHERE used.root_realm_id=NEW.root_realm_id
        AND used.bank_reconciliation_ref=NEW.recovery_bank_ref) OR
     (SELECT count(*) FROM journal_line legs
       WHERE legs.root_realm_id=NEW.root_realm_id
       AND legs.journal_id=NEW.recovery_journal_ref)<>2 OR
     (SELECT count(*) FROM journal_line legs
       WHERE legs.root_realm_id=NEW.root_realm_id AND
       legs.journal_id=NEW.recovery_journal_ref AND legs.branch_id IS NULL AND
       ((legs.account_id=bank_account AND legs.debit_minor=needed AND
         legs.credit_minor=0) OR
        (legs.account_id=payable_account AND legs.credit_minor=needed AND
         legs.debit_minor=0)))<>2
  THEN
   RAISE EXCEPTION 'Independent CG09 recovered bank amount and payable mismatch'
    USING ERRCODE='P1720';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_completed_liability_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Original approved healthcare assistance evidence is immutable';
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_disallow_claimed_correction_reclaim()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM cg17_provider_claim_correction c
   WHERE c.root_realm_id=NEW.root_realm_id AND c.liability_ref=NEW.liability_ref)
 THEN RAISE EXCEPTION 'Corrected original liability is not payable'
   USING ERRCODE='P1720';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_effective_payout_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE total bigint; paid bigint; adj bigint; recovered bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN RETURN NEW; END IF;
 SELECT approved_total_minor,paid_minor INTO total,paid
 FROM provider_settlement
 WHERE root_realm_id=NEW.root_realm_id AND id=NEW.settlement_ref
   AND center_ref=NEW.center_ref FOR UPDATE;
 SELECT coalesce(sum(amount_minor),0),coalesce(sum(recovery_minor),0)
 INTO adj,recovered FROM cg17_provider_claim_correction
 WHERE root_realm_id=NEW.root_realm_id AND settlement_ref=NEW.settlement_ref;
 IF total IS NULL OR total<adj OR NEW.amount_minor>total-adj-paid+recovered THEN
  RAISE EXCEPTION 'A bank payout cannot exceed the effective corrected payable'
   USING ERRCODE='P1720';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_financial_effect_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR
   (to_jsonb(NEW)-'posting_state'-'original_cg09_ref'-'updated_at') IS DISTINCT FROM
   (to_jsonb(OLD)-'posting_state'-'original_cg09_ref'-'updated_at') OR
   OLD.posting_state='POSTED' OR
   NOT ((OLD.posting_state='PENDING' AND NEW.posting_state IN('UNKNOWN','POSTED','FAILED'))
     OR (OLD.posting_state='UNKNOWN' AND NEW.posting_state IN('POSTED','FAILED')))
 THEN
  RAISE EXCEPTION 'Original CG17 financial source cannot be rewritten';
 END IF;
 RETURN NEW;
END $function$
;

-- Functions 316-360
CREATE OR REPLACE FUNCTION public.cg17_liability_completion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.source_kind='CG17_PARTNER_SERVICE' THEN
  IF NOT EXISTS(
   SELECT 1 FROM cg17_partner_service_claim claim
   JOIN cg17_partner_invoice_attestation att
    ON att.root_realm_id=claim.root_realm_id
    AND att.claim_ref=claim.id
   JOIN cg17_partner_invoice_decision decision
    ON decision.root_realm_id=claim.root_realm_id
    AND decision.claim_ref=claim.id AND decision.attestation_ref=att.id
    AND decision.outcome='APPROVED'
   JOIN health_center center ON center.root_realm_id=claim.root_realm_id
    AND center.id=claim.center_ref
   JOIN health_provider provider ON provider.root_realm_id=center.root_realm_id
    AND provider.id=center.provider_id
   JOIN healthcare_policy_revision policy
    ON policy.root_realm_id=claim.root_realm_id
    AND policy.id=claim.policy_revision_ref
   WHERE claim.root_realm_id=NEW.root_realm_id
    AND claim.id=NEW.partner_claim_ref AND claim.id=NEW.source_ref
    AND claim.center_ref=NEW.center_ref
    AND decision.id=NEW.partner_decision_ref
    AND decision.reviewed_by_account=NEW.created_by_account
    AND decision.approved_support_minor=NEW.amount_minor
    AND claim.estimated_support_minor=NEW.amount_minor
    AND claim.quoted_gross_minor=decision.accepted_gross_minor
    AND att.collected_minor=decision.accepted_patient_paid_minor
    AND att.collected_minor+NEW.amount_minor=claim.quoted_gross_minor
    AND claim.service_local_date=NEW.service_local_date
    AND NEW.service_completed_at IS NULL
    AND center.status='VERIFIED' AND center.access_state='ENABLED'
    AND provider.status='VERIFIED'
    AND policy.service_kind=claim.service_kind
    AND policy.approval_state='ACTIVE'
    AND NEW.source_digest=encode(digest(
      'CG17_PARTNER_LIABILITY_V1|'||claim.source_digest||'|'||
      att.evidence_digest||'|'||decision.decision_digest,
      'sha256'),'hex')
  ) THEN
   RAISE EXCEPTION 'Partner liability requires reviewed genuine service and direct patient payment'
    USING ERRCODE='P1744';
  END IF;
  RETURN NEW;
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM cg15_visit_event e
  JOIN cg15_visit_queue v ON v.root_realm_id=e.root_realm_id AND v.id=e.visit_id
    AND v.appointment_id=e.appointment_id
  JOIN cg15_consultation_appointment a ON a.root_realm_id=e.root_realm_id
    AND a.id=e.appointment_id
  JOIN patient_charge c ON c.root_realm_id=a.root_realm_id
    AND c.source_ref=a.id AND c.center_ref=a.center_id
  JOIN assistance_award award ON award.root_realm_id=c.root_realm_id
    AND award.charge_ref=c.id AND award.id=NEW.award_ref
  WHERE e.root_realm_id=NEW.root_realm_id AND e.id=NEW.completion_event_ref
   AND e.next_state='COMPLETED' AND e.appointment_id=NEW.source_ref
   AND v.state='COMPLETED' AND a.booking_state='COMPLETED'
   AND a.center_id=NEW.center_ref AND c.id=NEW.charge_ref
   AND c.charge_state='ACCEPTED' AND c.support_minor=NEW.amount_minor
   AND award.approved_support_minor=NEW.amount_minor
   AND award.policy_revision_ref=c.policy_revision_ref
   AND date_trunc('milliseconds',e.created_at)=NEW.service_completed_at
   AND (e.created_at AT TIME ZONE a.time_zone)::date=NEW.service_local_date
 ) THEN
  RAISE EXCEPTION 'Foundation liability requires completed original CG15 service and approved award';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_merchant_binding_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Merchant binding history cannot be deleted';
 END IF;
 IF (to_jsonb(NEW)-'verification_state'-'verified_by'-'verified_at'
    -'revoked_by'-'revoked_at'-'original_proof_ref'-'revision') IS DISTINCT FROM
    (to_jsonb(OLD)-'verification_state'-'verified_by'-'verified_at'
    -'revoked_by'-'revoked_at'-'original_proof_ref'-'revision') THEN
  RAISE EXCEPTION 'Merchant source, operator and credentials are immutable';
 END IF;
 IF NEW.revision<>OLD.revision+1 THEN
  RAISE EXCEPTION 'Merchant transition revision must advance exactly once';
 END IF;
 IF NOT ((OLD.verification_state='PENDING_VERIFICATION' AND
    NEW.verification_state IN('VERIFIED','REVOKED')) OR
   (OLD.verification_state='VERIFIED' AND NEW.verification_state='REVOKED'))
 THEN
  RAISE EXCEPTION 'Merchant transition invalid';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_partner_attestation_validate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source cg17_partner_service_claim%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Original partner attestation cannot be modified' USING ERRCODE='P1732';
 END IF;
 SELECT * INTO source FROM cg17_partner_service_claim
 WHERE root_realm_id=NEW.root_realm_id AND id=NEW.claim_ref
  AND center_ref=NEW.center_ref FOR SHARE;
 IF NOT FOUND OR NEW.patient_ref IS DISTINCT FROM source.patient_ref
  OR NEW.collected_minor IS DISTINCT FROM source.estimated_patient_due_minor
  OR NEW.attested_by_account=source.requested_by_account THEN
  RAISE EXCEPTION 'Current original patient invoice and actual collection are required'
   USING ERRCODE='P1733';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM health_center_account_affiliation f
  JOIN health_center c ON c.root_realm_id=f.root_realm_id AND c.id=f.center_id
  JOIN health_provider p ON p.root_realm_id=c.root_realm_id AND p.id=c.provider_id
  JOIN account a ON a.realm_id=f.root_realm_id AND a.id=f.account_ref
  WHERE f.root_realm_id=NEW.root_realm_id AND f.center_id=NEW.center_ref
   AND f.account_ref=NEW.attested_by_account AND f.status='ACTIVE'
   AND a.status='ACTIVE' AND c.status='VERIFIED'
   AND c.access_state='ENABLED' AND p.status='VERIFIED'
  ) THEN
  RAISE EXCEPTION 'Only assigned active partner representative may attest'
   USING ERRCODE='P1734';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM cg19_patient_private_file f
  JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id AND i.id=f.intent_id
  WHERE f.realm_id=source.root_realm_id AND f.id=source.invoice_file_ref
   AND f.patient_id=source.patient_ref AND f.scan_status='CLEAN_VERIFIED'
   AND f.classification='PATIENT_PARTNER_INVOICE'
   AND f.revoked_at IS NULL AND i.status='VALIDATED')
 OR (source.service_kind IN('NURSING','OT','LAB') AND NOT EXISTS(
  SELECT 1 FROM cg19_patient_private_file f
  JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id AND i.id=f.intent_id
  WHERE f.realm_id=source.root_realm_id AND f.id=source.completion_file_ref
   AND f.patient_id=source.patient_ref AND f.scan_status='CLEAN_VERIFIED'
   AND f.classification='PATIENT_PARTNER_SERVICE_PROOF'
   AND f.revoked_at IS NULL AND i.status='VALIDATED'))
 THEN
  RAISE EXCEPTION 'Original clinical/service invoice proof is unavailable'
   USING ERRCODE='P1735';
 END IF;
 IF NEW.payment_file_ref IS DISTINCT FROM source.payment_file_ref THEN
  RAISE EXCEPTION 'Original patient-submitted payment evidence changed'
   USING ERRCODE='P1736';
 END IF;
 IF NEW.payment_file_ref IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM cg19_patient_private_file f
  JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id AND i.id=f.intent_id
  WHERE f.realm_id=source.root_realm_id AND f.id=NEW.payment_file_ref
   AND f.patient_id=source.patient_ref AND f.scan_status='CLEAN_VERIFIED'
   AND f.classification='PATIENT_PARTNER_PAYMENT_PROOF'
   AND f.revoked_at IS NULL AND i.status='VALIDATED')
 THEN
  RAISE EXCEPTION 'Original scanned patient payment evidence is unavailable'
   USING ERRCODE='P1736';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_partner_claim_original_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_center record; v_policy record; v_support bigint; v_quote bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Original pending partner service evidence is immutable'
   USING ERRCODE='P1725';
 END IF;
 SELECT center.time_zone,center.status,center.access_state,
  provider.status AS provider_status
 INTO v_center FROM health_center center
 JOIN health_provider provider ON provider.root_realm_id=center.root_realm_id
  AND provider.id=center.provider_id
 WHERE center.root_realm_id=NEW.root_realm_id AND center.id=NEW.center_ref
 FOR SHARE OF center,provider;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Current verified healthcare service is required'
   USING ERRCODE='P1726';
 END IF;
 IF v_center.status<>'VERIFIED' OR
  v_center.access_state<>'ENABLED' OR v_center.provider_status<>'VERIFIED' OR
  NEW.service_local_date>(now() AT TIME ZONE v_center.time_zone)::date THEN
  RAISE EXCEPTION 'Current verified healthcare service is required'
   USING ERRCODE='P1726';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM health_center_capability cap
  WHERE cap.root_realm_id=NEW.root_realm_id AND cap.center_id=NEW.center_ref
   AND cap.capability_code=CASE NEW.service_kind
    WHEN 'OT' THEN 'SURGERY' WHEN 'LAB' THEN 'DIAGNOSTICS' ELSE NEW.service_kind END) THEN
  RAISE EXCEPTION 'Current verified center capability is required'
   USING ERRCODE='P1727';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM cg15_patient patient
  JOIN cg15_patient_account_link own ON own.root_realm_id=patient.root_realm_id
   AND own.patient_id=patient.id AND own.account_id=NEW.requested_by_account
   AND own.revoked_at IS NULL
  JOIN account active ON active.realm_id=own.root_realm_id
   AND active.id=own.account_id AND active.status='ACTIVE'
  WHERE patient.root_realm_id=NEW.root_realm_id AND patient.id=NEW.patient_ref
   AND patient.profile_status='VERIFIED'
   AND EXISTS(SELECT 1 FROM cg15_patient_identity_event identity
     WHERE identity.root_realm_id=patient.root_realm_id AND identity.patient_id=patient.id)
   AND (SELECT consent.granted FROM cg15_patient_consent consent
     WHERE consent.root_realm_id=patient.root_realm_id
      AND consent.patient_id=patient.id AND consent.purpose='PATIENT_CARE'
     ORDER BY consent.revision_no DESC LIMIT 1)=true
 ) THEN
  RAISE EXCEPTION 'Current verified patient consent is required'
   USING ERRCODE='P1728';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM cg19_patient_private_file f
  JOIN cg19_patient_file_intent intent ON intent.realm_id=f.realm_id
   AND intent.id=f.intent_id AND intent.status='VALIDATED'
  WHERE f.realm_id=NEW.root_realm_id AND f.patient_id=NEW.patient_ref
   AND f.id=NEW.invoice_file_ref
   AND f.classification='PATIENT_PARTNER_INVOICE'
   AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL) OR
  (NEW.completion_file_ref IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM cg19_patient_private_file f
   JOIN cg19_patient_file_intent intent ON intent.realm_id=f.realm_id
    AND intent.id=f.intent_id AND intent.status='VALIDATED'
   WHERE f.realm_id=NEW.root_realm_id AND f.patient_id=NEW.patient_ref
    AND f.id=NEW.completion_file_ref
    AND f.classification='PATIENT_PARTNER_SERVICE_PROOF'
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL)) THEN
  RAISE EXCEPTION 'Clean scanned source evidence is required'
   USING ERRCODE='P1729';
 END IF;
 SELECT policy.id,policy.mode,policy.percent_basis_points,policy.fixed_minor,
  policy.cap_minor,policy.valid_from,policy.valid_until
 INTO v_policy FROM healthcare_policy_revision policy
 WHERE policy.root_realm_id=NEW.root_realm_id
  AND policy.id=NEW.policy_revision_ref AND policy.center_ref=NEW.center_ref
  AND policy.service_kind=NEW.service_kind AND policy.doctor_ref IS NULL
  AND policy.approval_state='ACTIVE' AND policy.activated_at IS NOT NULL
  AND policy.activated_at<=now()
  AND policy.valid_from<=now() AND policy.valid_until>now()
 FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Original active service contribution is unavailable'
   USING ERRCODE='P1730';
 END IF;
 IF NEW.service_local_date <
  (v_policy.valid_from AT TIME ZONE v_center.time_zone)::date OR
  NEW.service_local_date >
  (v_policy.valid_until AT TIME ZONE v_center.time_zone)::date THEN
  RAISE EXCEPTION 'Original active service contribution is unavailable'
   USING ERRCODE='P1730';
 END IF;
 v_quote=CASE WHEN v_policy.mode='PERCENT'
  THEN (NEW.quoted_gross_minor*v_policy.percent_basis_points+5000)/10000
  ELSE v_policy.fixed_minor END;
 v_support=LEAST(v_quote,v_policy.cap_minor,NEW.quoted_gross_minor);
 IF NEW.estimated_support_minor<>v_support OR
  NEW.estimated_patient_due_minor<>NEW.quoted_gross_minor-v_support THEN
  RAISE EXCEPTION 'Original benefit estimate has changed'
   USING ERRCODE='P1731';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_partner_decision_validate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE claim cg17_partner_service_claim%ROWTYPE;
DECLARE attest cg17_partner_invoice_attestation%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Independent original Foundation decision is immutable'
   USING ERRCODE='P1737';
 END IF;
 SELECT * INTO claim FROM cg17_partner_service_claim
 WHERE root_realm_id=NEW.root_realm_id AND id=NEW.claim_ref
  AND center_ref=NEW.center_ref FOR SHARE;
 SELECT * INTO attest FROM cg17_partner_invoice_attestation
 WHERE root_realm_id=NEW.root_realm_id AND id=NEW.attestation_ref
  AND claim_ref=NEW.claim_ref FOR SHARE;
 IF claim.id IS NULL OR attest.id IS NULL OR
  claim.source_digest<>NEW.original_claim_digest OR
  attest.evidence_digest<>NEW.original_evidence_digest OR
  NEW.reviewed_by_account IN(attest.attested_by_account,claim.requested_by_account)
 THEN
  RAISE EXCEPTION 'Independent reviewed original proof is missing'
   USING ERRCODE='P1738';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM account reviewer
  JOIN account_role ar ON ar.realm_id=reviewer.realm_id AND
   ar.account_id=reviewer.id AND ar.revoked_at IS NULL
  JOIN role r ON r.realm_id=ar.realm_id AND r.id=ar.role_id
  WHERE reviewer.realm_id=NEW.root_realm_id AND reviewer.id=NEW.reviewed_by_account
   AND reviewer.status='ACTIVE' AND r.active AND r.is_protected)
 THEN
  RAISE EXCEPTION 'Current independent protected reviewer required'
   USING ERRCODE='P1739';
 END IF;
 IF NEW.accepted_gross_minor<>claim.quoted_gross_minor OR
    NEW.accepted_patient_paid_minor<>attest.collected_minor OR
    (NEW.outcome='APPROVED' AND NEW.approved_support_minor<>claim.estimated_support_minor) OR
    (NEW.outcome='REJECTED' AND NEW.approved_support_minor<>0)
 THEN
  RAISE EXCEPTION 'Reviewed accepted Foundation amounts changed'
   USING ERRCODE='P1740';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM health_center c JOIN health_provider p ON
   p.root_realm_id=c.root_realm_id AND p.id=c.provider_id
  JOIN health_center_capability cap ON cap.root_realm_id=c.root_realm_id
   AND cap.center_id=c.id
  WHERE c.root_realm_id=claim.root_realm_id AND c.id=claim.center_ref
   AND c.status='VERIFIED' AND c.access_state='ENABLED'
   AND p.status='VERIFIED' AND cap.capability_code=CASE claim.service_kind
    WHEN 'OT' THEN 'SURGERY' WHEN 'LAB' THEN 'DIAGNOSTICS' ELSE claim.service_kind END)
 THEN
  RAISE EXCEPTION 'Verified partner service is no longer available'
   USING ERRCODE='P1741';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM cg15_patient pat
  WHERE pat.root_realm_id=claim.root_realm_id AND pat.id=claim.patient_ref
   AND pat.profile_status='VERIFIED'
   AND (SELECT consent.granted FROM cg15_patient_consent consent
     WHERE consent.root_realm_id=pat.root_realm_id
      AND consent.patient_id=pat.id AND consent.purpose='PATIENT_CARE'
     ORDER BY consent.revision_no DESC LIMIT 1)=true)
 THEN
  RAISE EXCEPTION 'Original patient care consent is not current'
   USING ERRCODE='P1742';
 END IF;
 IF NEW.outcome='APPROVED' AND (
  NOT EXISTS(
   SELECT 1 FROM cg19_patient_file_event ev
   WHERE ev.realm_id=claim.root_realm_id AND ev.patient_id=claim.patient_ref
    AND ev.file_id=claim.invoice_file_ref
    AND ev.actor_account_id=NEW.reviewed_by_account
    AND ev.action='PARTNER_CLAIM_REVIEW_READ'
    AND ev.created_at>=attest.attested_at)
  OR (claim.service_kind IN('NURSING','OT','LAB') AND NOT EXISTS(
   SELECT 1 FROM cg19_patient_file_event ev
   WHERE ev.realm_id=claim.root_realm_id AND ev.patient_id=claim.patient_ref
    AND ev.file_id=claim.completion_file_ref
    AND ev.actor_account_id=NEW.reviewed_by_account
    AND ev.action='PARTNER_CLAIM_REVIEW_READ'
    AND ev.created_at>=attest.attested_at))
  OR (attest.payment_method='ELECTRONIC_EVIDENCE' AND NOT EXISTS(
   SELECT 1 FROM cg19_patient_file_event ev
   WHERE ev.realm_id=claim.root_realm_id AND ev.patient_id=claim.patient_ref
    AND ev.file_id=claim.payment_file_ref
    AND ev.actor_account_id=NEW.reviewed_by_account
    AND ev.action='PARTNER_CLAIM_REVIEW_READ'
    AND ev.created_at>=attest.attested_at))
 ) THEN
  RAISE EXCEPTION 'Financial reviewer must inspect original protected documents'
   USING ERRCODE='P1745';
 END IF;
 IF NEW.outcome='APPROVED' AND (
  NOT EXISTS(
   SELECT 1 FROM cg19_patient_private_file f
   JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id AND i.id=f.intent_id
   WHERE f.realm_id=claim.root_realm_id AND f.id=claim.invoice_file_ref
    AND f.patient_id=claim.patient_ref
    AND f.classification='PATIENT_PARTNER_INVOICE'
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND i.status='VALIDATED')
  OR (claim.service_kind IN('NURSING','OT','LAB') AND NOT EXISTS(
   SELECT 1 FROM cg19_patient_private_file f
   JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id AND i.id=f.intent_id
   WHERE f.realm_id=claim.root_realm_id AND f.id=claim.completion_file_ref
    AND f.patient_id=claim.patient_ref
    AND f.classification='PATIENT_PARTNER_SERVICE_PROOF'
    AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
    AND i.status='VALIDATED'))
  OR (attest.payment_method='ELECTRONIC_EVIDENCE' AND
    NOT EXISTS(
     SELECT 1 FROM cg19_patient_private_file f
     JOIN cg19_patient_file_intent i ON i.realm_id=f.realm_id AND i.id=f.intent_id
     WHERE f.realm_id=claim.root_realm_id
      AND f.id=claim.payment_file_ref AND f.patient_id=claim.patient_ref
      AND f.classification='PATIENT_PARTNER_PAYMENT_PROOF'
      AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
      AND i.status='VALIDATED'))
 ) THEN
  RAISE EXCEPTION 'Financial reviewer requires original current clean evidence'
   USING ERRCODE='P1745';
 END IF;
 IF NEW.outcome='APPROVED' AND
   (claim.estimated_support_minor=0 OR
   NOT EXISTS(SELECT 1 FROM healthcare_policy_revision pol
     WHERE pol.root_realm_id=claim.root_realm_id
      AND pol.id=claim.policy_revision_ref
      AND pol.center_ref=claim.center_ref
      AND pol.service_kind=claim.service_kind
      AND pol.approval_state='ACTIVE' AND pol.activated_at IS NOT NULL
      AND pol.valid_from<=now() AND pol.valid_until>now()))
 THEN
  RAISE EXCEPTION 'Original independently approved contribution is unavailable'
   USING ERRCODE='P1743';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_patient_charge_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Accepted CG17 patient charge must remain immutable';
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_payment_event_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Original provider payment evidence cannot be modified or deleted';
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_policy_full_coverage_fail_closed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.approval_state='ACTIVE' AND
    (NEW.service_kind<>'CONSULTATION' OR
     (NEW.mode='PERCENT' AND NEW.percent_basis_points=10000)) THEN
  IF NEW.approved_case_ref IS NULL OR NEW.approved_decision_ref IS NULL OR
    NOT EXISTS(
     SELECT 1 FROM cg03_case c
     JOIN cg03_case_decision d ON
      d.realm_id=c.realm_id AND d.case_id=c.id
     JOIN account reviewer ON reviewer.id=d.actor_id
      AND reviewer.realm_id=d.realm_id AND reviewer.status='ACTIVE'
     JOIN account_role ar ON ar.account_id=reviewer.id AND
      ar.realm_id=reviewer.realm_id AND ar.revoked_at IS NULL
     JOIN role cr ON cr.realm_id=ar.realm_id
      AND cr.id=ar.role_id
      AND cr.is_protected AND cr.active
     WHERE c.realm_id=NEW.root_realm_id AND c.id=NEW.approved_case_ref
      AND c.case_kind='CG17_POLICY_EXCEPTION'
      AND c.cg17_policy_revision_id=NEW.id
      AND c.cg17_policy_version=NEW.revision_no
      AND c.cg17_policy_digest=NEW.source_digest
      AND c.proposer_id=NEW.actor_ref AND c.status='PENDING_OWNER'
      AND d.id=NEW.approved_decision_ref AND d.action='APPROVE'
      AND d.actor_id<>c.proposer_id
      AND d.fresh_password_verified_at IS NOT NULL
      AND d.accepted_case_revision=c.revision
    )
  THEN
   RAISE EXCEPTION 'Protected healthcare support requires current original CG03 independent approval';
  END IF;
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_policy_immutable_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Historical healthcare assistance policy cannot be deleted';
 END IF;
 IF (to_jsonb(NEW)-'approval_state'-'changed_by'-'changed_at'
   -'approved_case_ref'-'approved_decision_ref'-'activated_at')
  IS DISTINCT FROM
    (to_jsonb(OLD)-'approval_state'-'changed_by'-'changed_at'
   -'approved_case_ref'-'approved_decision_ref'-'activated_at') THEN
  RAISE EXCEPTION 'Policy terms and original actor must be immutable';
 END IF;
 IF OLD.approval_state IN('WITHDRAWN','SUPERSEDED','REJECTED') OR
  NOT ((OLD.approval_state='ACTIVE' AND
       NEW.approval_state IN('WITHDRAWN','SUPERSEDED')) OR
       (OLD.approval_state='PENDING_APPROVAL' AND
       NEW.approval_state IN('ACTIVE','REJECTED'))) THEN
  RAISE EXCEPTION 'Healthcare support state transition denied';
 END IF;
 IF OLD.activated_at IS NOT NULL AND NEW.activated_at IS DISTINCT FROM OLD.activated_at THEN
  RAISE EXCEPTION 'Original policy activation time is immutable';
 END IF;
 IF OLD.approval_state='PENDING_APPROVAL' AND NEW.approval_state='ACTIVE' AND
    NEW.activated_at IS NULL THEN
  RAISE EXCEPTION 'Protected policy cannot become effective without activation time';
 END IF;
 IF NEW.changed_by IS NULL OR NEW.changed_at IS NULL OR
  (OLD.changed_at IS NOT NULL AND NEW.changed_at<=OLD.changed_at) THEN
  RAISE EXCEPTION 'Original policy transition requires an audited actor and time';
 END IF;
 IF OLD.approved_case_ref IS NOT NULL AND
    NEW.approved_case_ref IS DISTINCT FROM OLD.approved_case_ref OR
    OLD.approved_decision_ref IS NOT NULL AND
    NEW.approved_decision_ref IS DISTINCT FROM OLD.approved_decision_ref THEN
  RAISE EXCEPTION 'Protected approval reference cannot be replaced';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_settlement_claim_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_total numeric; v_lines integer; v_paid numeric;
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Approved Foundation settlement history cannot be deleted';
 END IF;
 IF (to_jsonb(NEW)-'state'-'revision'-'reviewed_by'-'reviewed_at'-
   'reviewed_request_key'-'paid_minor') IS DISTINCT FROM
   (to_jsonb(OLD)-'state'-'revision'-'reviewed_by'-'reviewed_at'-
   'reviewed_request_key'-'paid_minor') OR
   NEW.revision<>OLD.revision+1 THEN
  RAISE EXCEPTION 'Protected settlement identity and source cannot change';
 END IF;
 IF OLD.state='PROPOSED' AND NEW.state='APPROVED' THEN
  IF NEW.paid_minor<>0 OR NEW.reviewed_by IS NULL OR
   NEW.reviewed_by=OLD.proposed_by OR NEW.reviewed_at IS NULL OR
   NEW.reviewed_request_key IS NULL THEN
   RAISE EXCEPTION 'Original claim requires independent approval';
  END IF;
  SELECT count(*),coalesce(sum(line.amount_minor),0)
  INTO v_lines,v_total
  FROM provider_settlement_line line
  JOIN foundation_liability l ON l.root_realm_id=line.root_realm_id
   AND l.id=line.liability_ref
  JOIN cg17_financial_effect effect ON effect.root_realm_id=l.root_realm_id
   AND effect.id=line.original_effect_ref AND effect.liability_ref=l.id
   AND effect.effect_kind='LIABILITY_ACCRUAL'
   AND effect.posting_state='POSTED'
  JOIN journal j ON j.id=effect.original_cg09_ref
   AND j.root_realm_id=effect.root_realm_id
   AND j.status='POSTED' AND j.source_owner='CG-09'
   AND j.posting_kind='GENERAL' AND j.source_ref=effect.id
   AND j.immutable_source_event_key=effect.idempotency_key
   AND j.immutable_payload_digest=effect.source_digest
   AND j.posting_date=l.service_local_date
  WHERE line.root_realm_id=NEW.root_realm_id
   AND line.settlement_ref=NEW.id AND line.center_ref=NEW.center_ref
   AND line.amount_minor=l.amount_minor
   AND effect.amount_minor=l.amount_minor
   AND effect.source_digest=l.source_digest
   AND l.service_local_date>=NEW.period_start
   AND l.service_local_date<NEW.period_end;
  IF v_lines<1 OR v_total<>NEW.approved_total_minor OR
   v_lines<>(SELECT count(*) FROM provider_settlement_line
    WHERE root_realm_id=NEW.root_realm_id AND settlement_ref=NEW.id)
  THEN
   RAISE EXCEPTION 'Monthly claim must match exact original CG09 posted sources';
  END IF;
 ELSIF OLD.state IN('APPROVED','PARTIALLY_SETTLED') AND
       NEW.state IN('PARTIALLY_SETTLED','SETTLED') THEN
  IF NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by OR
   NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at OR
   NEW.reviewed_request_key IS DISTINCT FROM OLD.reviewed_request_key OR
   NEW.paid_minor<=OLD.paid_minor OR
   NEW.paid_minor>NEW.approved_total_minor THEN
   RAISE EXCEPTION 'Verified payout cannot change protected approval source';
  END IF;
  SELECT coalesce(sum(p.amount_minor),0) INTO v_paid
   FROM provider_settlement_payment p
   WHERE p.root_realm_id=NEW.root_realm_id AND p.settlement_ref=NEW.id;
  IF v_paid<>NEW.paid_minor OR
   (NEW.paid_minor=NEW.approved_total_minor AND NEW.state<>'SETTLED') OR
   (NEW.paid_minor<NEW.approved_total_minor AND NEW.state<>'PARTIALLY_SETTLED') THEN
   RAISE EXCEPTION 'Paid provider amount requires exact verified CG09 allocation';
  END IF;
 ELSE
  RAISE EXCEPTION 'Original settlement transition denied';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_settlement_line_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' OR TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original provider settlement lines are immutable';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM provider_settlement claim
  JOIN foundation_liability liability
   ON liability.root_realm_id=claim.root_realm_id
   AND liability.id=NEW.liability_ref AND liability.center_ref=claim.center_ref
  JOIN cg17_financial_effect effect
   ON effect.root_realm_id=liability.root_realm_id
   AND effect.id=NEW.original_effect_ref
   AND effect.liability_ref=liability.id
   AND effect.effect_kind='LIABILITY_ACCRUAL'
   AND effect.amount_minor=liability.amount_minor
   AND effect.source_digest=liability.source_digest
  JOIN journal j ON j.id=effect.original_cg09_ref
   AND j.root_realm_id=effect.root_realm_id
   AND j.source_owner='CG-09' AND j.posting_kind='GENERAL'
   AND j.source_ref=effect.id
   AND j.immutable_source_event_key=effect.idempotency_key
   AND j.immutable_payload_digest=effect.source_digest
   AND j.posting_date=liability.service_local_date AND j.status='POSTED'
  WHERE claim.root_realm_id=NEW.root_realm_id
   AND claim.id=NEW.settlement_ref AND claim.center_ref=NEW.center_ref
   AND claim.state='PROPOSED'
   AND liability.amount_minor=NEW.amount_minor
   AND liability.service_local_date>=claim.period_start
   AND liability.service_local_date<claim.period_end
   AND effect.posting_state='POSTED'
   AND effect.original_cg09_ref IS NOT NULL
 ) THEN
  RAISE EXCEPTION 'Settlement line requires original CG09 posted liability';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_verified_payout_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE rec record; count_lines integer; bank_count integer; liability_count integer;
 source_line_count integer; matched_line_count integer;
BEGIN
 IF TG_OP<>'INSERT' THEN
  RAISE EXCEPTION 'Verified original CG09 provider payout is immutable';
 END IF;
 -- Claimed amount is approved independently, never a prepared draft.
 SELECT claim.state,claim.approved_total_minor,claim.paid_minor,
  claim.proposed_by,claim.destination_file_ref,
  claim.destination_version,claim.provider_ref
 INTO rec FROM provider_settlement claim
 WHERE claim.root_realm_id=NEW.root_realm_id AND claim.id=NEW.settlement_ref
  AND claim.center_ref=NEW.center_ref FOR UPDATE;
 IF NOT FOUND OR rec.state NOT IN('APPROVED','PARTIALLY_SETTLED') OR
  NEW.verified_by_account=rec.proposed_by OR
  NEW.amount_minor>rec.approved_total_minor-rec.paid_minor THEN
  RAISE EXCEPTION 'Original provider settlement cannot exceed its approved payable';
 END IF;
 -- CG14 provider bank destination remains the same scanned original.
 IF NOT EXISTS(
  SELECT 1 FROM health_center center
  JOIN health_provider provider
   ON provider.id=center.provider_id AND provider.root_realm_id=center.root_realm_id
  JOIN health_provider_finance_ref ref
   ON ref.root_realm_id=provider.root_realm_id
   AND ref.provider_id=provider.id
  JOIN cg19_stored_file file ON file.id=ref.protected_file_ref
   AND file.realm_id=ref.root_realm_id
  JOIN cg19_upload_intent intent ON intent.id=file.upload_intent_id
   AND intent.realm_id=file.realm_id
  WHERE center.id=NEW.center_ref AND center.root_realm_id=NEW.root_realm_id
   AND center.status='VERIFIED' AND center.access_state='ENABLED'
   AND provider.status='VERIFIED' AND provider.id=rec.provider_ref
   AND ref.protected_file_ref=rec.destination_file_ref
   AND ref.version=rec.destination_version
   AND file.health_provider_id=provider.id
   AND file.owner_kind='CG14_DRAFT'
   AND file.scan_status='CLEAN_VERIFIED' AND file.revoked_at IS NULL
   AND intent.status='VALIDATED'
   AND intent.classification='HEALTH_BANK_PROOF'
 ) THEN
  RAISE EXCEPTION 'Current protected provider bank destination is not verified';
 END IF;
 -- CG09's independent bank reconciliation must match a real posted
 -- two-line liability-debit and Foundation-bank-credit journal exactly.
 IF NOT EXISTS(
  SELECT 1 FROM finance_bank_reconciliation bank
  JOIN journal j ON j.id=bank.journal_id AND j.root_realm_id=bank.root_realm_id
  JOIN finance_account cash ON cash.id=bank.bank_account_id
   AND cash.root_realm_id=bank.root_realm_id
  WHERE bank.id=NEW.bank_reconciliation_ref
   AND bank.root_realm_id=NEW.root_realm_id
   AND bank.status='VERIFIED' AND bank.variance_minor=0
   AND bank.statement_amount_minor=-NEW.amount_minor
   AND bank.posted_amount_minor=-NEW.amount_minor
   AND bank.journal_id=NEW.cg09_journal_ref
   AND bank.bank_account_id=NEW.bank_account_ref
   AND j.status='POSTED' AND j.source_owner='CG-09'
   AND j.posting_kind IN('GENERAL','VOUCHER')
   AND cash.account_kind='BANK' AND cash.scope_kind='FOUNDATION'
   AND cash.status='ACTIVE'
 ) THEN
  RAISE EXCEPTION 'Verified CG09 original bank disbursement is required';
 END IF;
 SELECT count(*),
  count(*) FILTER (WHERE line.account_id=NEW.bank_account_ref
   AND line.debit_minor=0 AND line.credit_minor=NEW.amount_minor
   AND line.branch_id IS NULL),
  count(*) FILTER (WHERE line.account_id=NEW.liability_account_ref
   AND line.credit_minor=0 AND line.debit_minor=NEW.amount_minor
   AND line.branch_id IS NULL)
 INTO count_lines,bank_count,liability_count FROM journal_line line
 WHERE line.root_realm_id=NEW.root_realm_id AND line.journal_id=NEW.cg09_journal_ref;
 IF count_lines<>2 OR bank_count<>1 OR liability_count<>1 OR
  NOT EXISTS(SELECT 1 FROM finance_account pay
   JOIN account_group g ON g.id=pay.group_id AND g.root_realm_id=pay.root_realm_id
   WHERE pay.id=NEW.liability_account_ref AND pay.root_realm_id=NEW.root_realm_id
    AND pay.scope_kind='FOUNDATION' AND pay.account_kind='GENERAL'
    AND pay.status='ACTIVE' AND g.category='LIABILITY') THEN
  RAISE EXCEPTION 'CG09 payout needs exact Foundation liability and bank lines';
 END IF;
 -- Every claim line must have been credited into THIS payable account
 -- by its exact immutable original CG09 accrual. A valid Foundation bank
 -- withdrawal for some other payable account is not this provider's claim.
 -- Keep this at the DB owner boundary so API bypass/replay cannot evade it.
 SELECT count(*) INTO source_line_count
 FROM provider_settlement_line line
 WHERE line.root_realm_id=NEW.root_realm_id
  AND line.settlement_ref=NEW.settlement_ref
  AND line.center_ref=NEW.center_ref;
 SELECT count(*) INTO matched_line_count
 FROM provider_settlement_line line
 JOIN foundation_liability obligation
  ON obligation.root_realm_id=line.root_realm_id
  AND obligation.id=line.liability_ref AND obligation.center_ref=line.center_ref
 JOIN cg17_financial_effect effect
  ON effect.root_realm_id=obligation.root_realm_id
  AND effect.id=line.original_effect_ref
  AND effect.liability_ref=obligation.id
  AND effect.effect_kind='LIABILITY_ACCRUAL'
  AND effect.posting_state='POSTED'
  AND effect.amount_minor=line.amount_minor
  AND effect.source_digest=obligation.source_digest
 JOIN journal accrual
  ON accrual.id=effect.original_cg09_ref
  AND accrual.root_realm_id=effect.root_realm_id
  AND accrual.source_owner='CG-09'
  AND accrual.posting_kind='GENERAL'
  AND accrual.status='POSTED'
  AND accrual.reversal_of_id IS NULL
  AND accrual.source_ref=effect.id
  AND accrual.immutable_source_event_key=effect.idempotency_key
  AND accrual.immutable_payload_digest=effect.source_digest
  AND accrual.posting_date=obligation.service_local_date
 JOIN journal_line credit
  ON credit.root_realm_id=accrual.root_realm_id
  AND credit.journal_id=accrual.id
  AND credit.account_id=NEW.liability_account_ref
  AND credit.branch_id IS NULL
  AND credit.debit_minor=0
  AND credit.credit_minor=line.amount_minor
 WHERE line.root_realm_id=NEW.root_realm_id
  AND line.settlement_ref=NEW.settlement_ref
  AND line.center_ref=NEW.center_ref
  AND (SELECT count(*) FROM journal_line exact
       WHERE exact.root_realm_id=accrual.root_realm_id
        AND exact.journal_id=accrual.id)=2;
 IF source_line_count<1 OR matched_line_count<>source_line_count THEN
  RAISE EXCEPTION 'Provider payout payable account differs from original accrued claim'
   USING ERRCODE='P1718';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg17_verify_unpaid_liability_reversal()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE original record; changed record; economic record; mismatch integer;
BEGIN
 SELECT l.id,l.amount_minor,e.id AS effect_ref,e.original_cg09_ref,
        e.posting_state,e.source_digest,e.source_ref
 INTO economic
 FROM foundation_liability l
 JOIN cg17_financial_effect e ON e.root_realm_id=l.root_realm_id
  AND e.liability_ref=l.id AND e.effect_kind='LIABILITY_ACCRUAL'
 WHERE l.root_realm_id=NEW.root_realm_id AND l.id=NEW.liability_ref
   AND l.center_ref=NEW.center_ref FOR SHARE OF l,e;
 IF NOT FOUND OR economic.effect_ref<>NEW.original_effect_ref
   OR economic.original_cg09_ref<>NEW.original_journal_ref
   OR economic.posting_state<>'POSTED'
   OR EXISTS(SELECT 1 FROM provider_settlement_line line
     WHERE line.root_realm_id=NEW.root_realm_id AND line.liability_ref=NEW.liability_ref)
 THEN
  RAISE EXCEPTION 'Original liability already claimed, changed or unavailable'
   USING ERRCODE='P1719';
 END IF;
 SELECT j.id AS id,j.posting_kind,j.source_owner,j.source_ref,j.created_by,
        j.immutable_payload_digest,j.status,j.reversal_of_id
 INTO original FROM journal j
 WHERE j.id=NEW.original_journal_ref AND j.root_realm_id=NEW.root_realm_id
 FOR SHARE;
 SELECT j.id AS id,j.posting_kind,j.source_owner,j.source_ref,j.created_by,
        j.immutable_payload_digest,j.status,j.reversal_of_id
 INTO changed FROM journal j
 WHERE j.id=NEW.reversal_journal_ref AND j.root_realm_id=NEW.root_realm_id
 FOR SHARE;
 IF original.id IS NULL OR changed.id IS NULL OR original.posting_kind<>'GENERAL' OR original.source_owner<>'CG-09'
   OR original.status<>'POSTED' OR original.reversal_of_id IS NOT NULL
   OR original.source_ref<>NEW.original_effect_ref
   OR original.immutable_payload_digest<>economic.source_digest
   OR original.created_by=NEW.reviewed_by_account
   OR changed.posting_kind<>'REVERSAL' OR changed.source_owner<>'CG-09'
   OR changed.status<>'POSTED' OR changed.reversal_of_id<>NEW.original_journal_ref
   OR changed.source_ref<>NEW.original_journal_ref
   OR changed.created_by<>NEW.reviewed_by_account
   OR changed.immutable_payload_digest<>NEW.request_digest
   OR EXISTS(SELECT 1 FROM journal j
      WHERE j.root_realm_id=NEW.root_realm_id
        AND j.reversal_of_id=NEW.original_journal_ref
        AND j.id<>NEW.reversal_journal_ref)
 THEN
  RAISE EXCEPTION 'Exact independent CG09 accrual reversal proof required'
   USING ERRCODE='P1719';
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM cg17_financial_effect e
  WHERE e.root_realm_id=NEW.root_realm_id
    AND e.id=NEW.reversal_effect_ref
    AND e.liability_ref=NEW.liability_ref
    AND e.effect_kind='LIABILITY_REVERSAL'
    AND e.source_ref=economic.source_ref
    AND e.amount_minor=economic.amount_minor
    AND e.source_digest=NEW.request_digest
    AND e.idempotency_key=NEW.request_key
    AND e.posting_state='POSTED'
    AND e.original_cg09_ref=NEW.reversal_journal_ref
 ) THEN
  RAISE EXCEPTION 'Original CG17 correction effect missing'
   USING ERRCODE='P1719';
 END IF;
 WITH prior AS (
  SELECT account_id,branch_id,count(*) AS n,
         sum(debit_minor) AS debits,sum(credit_minor) AS credits
  FROM journal_line WHERE root_realm_id=NEW.root_realm_id
   AND journal_id=NEW.original_journal_ref
  GROUP BY account_id,branch_id
 ), after AS (
  SELECT account_id,branch_id,count(*) AS n,
         sum(debit_minor) AS debits,sum(credit_minor) AS credits
  FROM journal_line WHERE root_realm_id=NEW.root_realm_id
   AND journal_id=NEW.reversal_journal_ref
  GROUP BY account_id,branch_id
 )
 SELECT count(*) INTO mismatch
 FROM prior p FULL OUTER JOIN after a
  ON a.account_id=p.account_id
  AND a.branch_id IS NOT DISTINCT FROM p.branch_id
 WHERE p.account_id IS NULL OR a.account_id IS NULL
   OR p.n<>a.n OR p.debits<>a.credits OR p.credits<>a.debits;
 IF mismatch<>0 OR
   (SELECT count(*) FROM journal_line
    WHERE root_realm_id=NEW.root_realm_id AND journal_id=NEW.original_journal_ref)<>2 OR
   (SELECT count(*) FROM journal_line
    WHERE root_realm_id=NEW.root_realm_id AND journal_id=NEW.reversal_journal_ref)<>2 THEN
  RAISE EXCEPTION 'The correction must exactly offset two original journal lines'
   USING ERRCODE='P1719';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg18_guard_navigation_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual record;
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT p.kind,v.content_digest INTO actual
   FROM cms_page_revision v JOIN cms_page p
    ON p.id=v.page_id AND p.foundation_root_id=v.foundation_root_id
   WHERE v.id=NEW.home_revision_id AND v.foundation_root_id=NEW.foundation_root_id
   FOR SHARE OF p,v;
  IF NOT FOUND OR actual.kind<>'HOME' OR
    actual.content_digest IS DISTINCT FROM NEW.source_digest OR
    NEW.status<>'DRAFT' OR NEW.cg03_decision_ref IS NOT NULL OR
    NEW.effective_at IS NOT NULL THEN
   RAISE EXCEPTION 'Navigation must start as original Home draft'
    USING ERRCODE='P1835';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' OR
    NEW.foundation_root_id IS DISTINCT FROM OLD.foundation_root_id OR
    NEW.home_revision_id IS DISTINCT FROM OLD.home_revision_id OR
    NEW.revision_no IS DISTINCT FROM OLD.revision_no OR
    NEW.created_by IS DISTINCT FROM OLD.created_by THEN
  RAISE EXCEPTION 'Approved navigation evidence cannot change'
   USING ERRCODE='P1835';
 END IF;
 IF OLD.status='DRAFT' THEN
  IF NEW.status NOT IN('DRAFT','SUBMITTED') OR
    (NEW.status='SUBMITTED' AND
      (NEW.cg03_decision_ref IS NOT NULL OR NEW.effective_at IS NOT NULL)) THEN
   RAISE EXCEPTION 'Navigation requires original submission'
    USING ERRCODE='P1835';
  END IF;
  SELECT v.content_digest INTO actual FROM cms_page_revision v
   WHERE v.id=NEW.home_revision_id AND v.foundation_root_id=NEW.foundation_root_id
   FOR SHARE;
  IF NOT FOUND OR actual.content_digest IS DISTINCT FROM NEW.source_digest THEN
   RAISE EXCEPTION 'Navigation and page must share one reviewed digest'
    USING ERRCODE='P1835';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='SUBMITTED' AND NEW.status='APPROVED' AND
    NEW.source_digest=OLD.source_digest AND
    NEW.login_desired=OLD.login_desired AND
    NEW.member_join_desired=OLD.member_join_desired AND
    NEW.volunteer_join_desired=OLD.volunteer_join_desired AND
    NEW.cg03_decision_ref IS NOT NULL AND NEW.effective_at IS NOT NULL THEN
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Submitted or approved navigation is immutable'
  USING ERRCODE='P1835';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg18_guard_revision_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target_rev uuid; target_root uuid;
BEGIN
 IF TG_TABLE_NAME='cms_page_revision' THEN
  IF TG_OP='DELETE' OR OLD.status IN('SUBMITTED','RETURNED') THEN
   RAISE EXCEPTION 'Submitted CMS revisions are immutable' USING ERRCODE='P1831';
  END IF;
  IF NEW.foundation_root_id IS DISTINCT FROM OLD.foundation_root_id OR
     NEW.page_id IS DISTINCT FROM OLD.page_id OR
     NEW.revision_no IS DISTINCT FROM OLD.revision_no OR
     NEW.created_by IS DISTINCT FROM OLD.created_by THEN
   RAISE EXCEPTION 'CMS revision identity cannot change' USING ERRCODE='P1831';
  END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='INSERT' THEN
  target_rev:=NEW.page_revision_id; target_root:=NEW.foundation_root_id;
 ELSE
  target_rev:=OLD.page_revision_id; target_root:=OLD.foundation_root_id;
 END IF;
 PERFORM 1 FROM cms_page_revision rev
  WHERE rev.id=target_rev AND
   rev.foundation_root_id=target_root AND rev.status='DRAFT' FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Submitted CMS content cannot be changed' USING ERRCODE='P1831';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND (NEW.foundation_root_id IS DISTINCT FROM OLD.foundation_root_id OR
    NEW.page_revision_id IS DISTINCT FROM OLD.page_revision_id) THEN
  RAISE EXCEPTION 'CMS revision source cannot be moved to another draft' USING ERRCODE='P1831';
 END IF;
 RETURN NEW;
END; $function$
;
