END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_donation_message_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Receipt delivery history cannot be deleted'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
   NEW.id IS DISTINCT FROM OLD.id OR
   NEW.donation_id IS DISTINCT FROM OLD.donation_id OR
   NEW.receipt_id IS DISTINCT FROM OLD.receipt_id OR
   NEW.channel IS DISTINCT FROM OLD.channel OR
   NEW.request_key IS DISTINCT FROM OLD.request_key OR
   NEW.requested_at IS DISTINCT FROM OLD.requested_at OR
   OLD.state NOT IN('MESSAGE_PENDING','SEND_RESERVED') OR
   (OLD.state='MESSAGE_PENDING' AND NEW.state NOT IN('SEND_RESERVED','MESSAGE_PENDING')) OR
   (OLD.state='SEND_RESERVED' AND NEW.state NOT IN
    ('PROVIDER_ACCEPTED','PROVIDER_UNKNOWN','DELIVERY_FAILED')) OR
   (OLD.attempt_key IS NOT NULL AND NEW.attempt_key IS DISTINCT FROM OLD.attempt_key)
  THEN RAISE EXCEPTION 'Original receipt message attempt is immutable or cannot be resent'; END IF;
 ELSE
  IF NEW.state<>'MESSAGE_PENDING' OR NEW.attempt_key IS NOT NULL
   THEN RAISE EXCEPTION 'New receipt notices must start pending'; END IF;
 END IF;
 IF NOT EXISTS(
  SELECT 1 FROM donation d
  JOIN donation_finance_effect e ON e.root_realm_id=d.root_realm_id AND e.donation_id=d.id
  JOIN journal j ON j.root_realm_id=e.root_realm_id AND j.id=e.journal_id
  JOIN cg19_donation_receipt_document r
   ON r.root_realm_id=d.root_realm_id AND r.donation_id=d.id
  WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.donation_id
   AND d.source_status='RECEIVED_POSTED' AND e.status='POSTED'
   AND j.status='POSTED' AND j.source_ref=d.id
   AND j.immutable_source_event_key=e.source_event_key
   AND j.immutable_payload_digest=e.immutable_digest
   AND r.id=NEW.receipt_id AND r.status='ISSUED'
   AND r.source_digest=e.immutable_digest
 ) THEN RAISE EXCEPTION 'Actual issued CG19 receipt and posted CG09 donation are required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_donation_proof_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Original donor proof cannot be deleted'; END IF;
 IF TG_OP='INSERT' AND NEW.state<>'RESERVED'
 THEN RAISE EXCEPTION 'New donor proof must await actual malware scan'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR
   NEW.id IS DISTINCT FROM OLD.id OR NEW.donation_id IS DISTINCT FROM OLD.donation_id OR
   NEW.requested_by IS DISTINCT FROM OLD.requested_by OR
   NEW.request_key IS DISTINCT FROM OLD.request_key OR
   NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
   NEW.mime IS DISTINCT FROM OLD.mime OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes OR
   NEW.expected_sha256 IS DISTINCT FROM OLD.expected_sha256 OR
   NEW.object_key IS DISTINCT FROM OLD.object_key OR
   NEW.reserved_until IS DISTINCT FROM OLD.reserved_until OR
   NEW.created_at IS DISTINCT FROM OLD.created_at OR
   OLD.state NOT IN('RESERVED','UNKNOWN') OR
   NEW.state NOT IN('UNKNOWN','VALIDATED','REJECTED') OR
   (OLD.object_version IS NOT NULL AND NEW.object_version IS DISTINCT FROM OLD.object_version)
  THEN RAISE EXCEPTION 'Donor attachment cannot be retargeted or rewritten'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_donation_receipt_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF OLD.status='ISSUED' THEN
  RAISE EXCEPTION 'Issued original donation receipt is immutable';
 END IF;
 IF NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id OR NEW.id IS DISTINCT FROM OLD.id OR
  NEW.donation_id IS DISTINCT FROM OLD.donation_id OR
  NEW.receipt_number IS DISTINCT FROM OLD.receipt_number OR
  NEW.source_digest IS DISTINCT FROM OLD.source_digest OR
  NEW.issue_key IS DISTINCT FROM OLD.issue_key OR
  NEW.issued_by IS DISTINCT FROM OLD.issued_by OR
  NEW.object_key IS DISTINCT FROM OLD.object_key OR NEW.created_at IS DISTINCT FROM OLD.created_at
 THEN RAISE EXCEPTION 'Original donation receipt identity is immutable'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_donation_receipt_issue_proof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.status<>'ISSUED' THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM donation d
  JOIN donation_finance_effect e ON e.root_realm_id=d.root_realm_id AND e.donation_id=d.id
  JOIN journal j ON j.root_realm_id=e.root_realm_id AND j.id=e.journal_id
  WHERE d.root_realm_id=NEW.root_realm_id AND d.id=NEW.donation_id
   AND d.source_status='RECEIVED_POSTED' AND e.status='POSTED' AND j.status='POSTED'
   AND j.source_ref=d.id AND j.immutable_source_event_key=e.source_event_key
   AND j.immutable_payload_digest=e.immutable_digest
   AND NEW.source_digest=e.immutable_digest)
 THEN RAISE EXCEPTION 'Donation receipt requires current original verified finance post'; END IF;
 RETURN NULL;
END; $function$
;
