 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.health_provider_id IS DISTINCT FROM OLD.health_provider_id OR
    NEW.health_center_id IS DISTINCT FROM OLD.health_center_id OR
    NEW.health_doctor_id IS DISTINCT FROM OLD.health_doctor_id OR
