CREATE OR REPLACE FUNCTION public.cg19_hr_asset_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.hr_template_asset AND NOT EXISTS(SELECT 1 FROM cg19_upload_intent i WHERE i.realm_id=NEW.realm_id AND i.id=NEW.intent_id
 AND i.owner_kind='CG19_HR_TEMPLATE_ASSET' AND i.requested_by=NEW.actor_id AND NEW.event_key IN('UPLOAD_INITIATED','UPLOAD_VERIFIED','UPLOAD_REJECTED','UPLOAD_UNKNOWN'))
 THEN RAISE EXCEPTION 'Original root template asset upload event required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_asset_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.owner_kind='CG19_HR_TEMPLATE_ASSET' OR EXISTS(SELECT 1 FROM cg19_upload_intent i WHERE i.id=NEW.upload_intent_id AND i.realm_id=NEW.realm_id AND i.owner_kind='CG19_HR_TEMPLATE_ASSET') THEN
  IF NOT EXISTS(SELECT 1 FROM cg19_upload_intent i WHERE i.id=NEW.upload_intent_id AND i.realm_id=NEW.realm_id AND i.owner_kind='CG19_HR_TEMPLATE_ASSET' AND NEW.owner_kind=i.owner_kind
   AND i.status='VALIDATED' AND i.requested_by=NEW.created_by AND i.object_key=NEW.object_key AND i.mime=NEW.original_mime AND i.size_bytes=NEW.verified_size_bytes
   AND i.expected_sha256=NEW.verified_sha256 AND NEW.scan_status='CLEAN_VERIFIED' AND NEW.case_id IS NULL AND NEW.proposal_revision=1)
  THEN RAISE EXCEPTION 'Exact verified root template asset required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;

-- Functions 361-405
CREATE OR REPLACE FUNCTION public.cg19_hr_card_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.hr_card_token_digest IS DISTINCT FROM OLD.hr_card_token_digest THEN RAISE EXCEPTION 'Original card verification identity is immutable'; END IF;
 IF TG_OP='INSERT' AND (NEW.hr_card_token_digest IS NOT NULL) IS DISTINCT FROM EXISTS(
  SELECT 1 FROM hr_document_request h WHERE h.root_realm_id=NEW.realm_id AND h.case_ref=NEW.case_id AND h.kind='EMPLOYEE_ID')
 THEN RAISE EXCEPTION 'Only an original employee card may have a card verifier'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_card_subject_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.hr_card_employee_ref IS DISTINCT FROM OLD.hr_card_employee_ref THEN RAISE EXCEPTION 'Original card subject cannot change'; END IF;
 IF NEW.hr_card_token_digest IS NOT NULL THEN
  IF NEW.hr_card_employee_ref IS NULL OR NOT EXISTS(SELECT 1 FROM hr_document_request h
   WHERE h.root_realm_id=NEW.realm_id AND h.case_ref=NEW.case_id AND h.kind='EMPLOYEE_ID' AND h.employee_id=NEW.hr_card_employee_ref)
   THEN RAISE EXCEPTION 'Original employee card subject required'; END IF;
 ELSIF NEW.hr_card_employee_ref IS NOT NULL THEN RAISE EXCEPTION 'Card subject is only valid for employee ID cards';
 END IF;
 IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM hr_document_request h WHERE h.root_realm_id=NEW.realm_id AND h.case_ref=NEW.case_id)
 AND NEW.state<>'PENDING' THEN RAISE EXCEPTION 'HR document must begin pending verified storage'; END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM hr_document_request h WHERE h.root_realm_id=NEW.realm_id AND h.case_ref=NEW.case_id)
 AND OLD.state='REVOKED' AND NEW.state IS DISTINCT FROM OLD.state THEN RAISE EXCEPTION 'Revoked HR documents cannot be reactivated'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_document_exact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM cg03_case c WHERE c.id=NEW.case_id AND c.realm_id=NEW.realm_id AND c.case_kind='HR_DOCUMENT_REVIEW') THEN
  IF NOT EXISTS(SELECT 1 FROM hr_document_request h JOIN cg03_case c
   ON c.id=h.case_ref AND c.realm_id=h.root_realm_id AND c.hr_document_request_id=h.id AND c.hr_document_source_digest=h.source_digest
   WHERE h.root_realm_id=NEW.realm_id AND h.case_ref=NEW.case_id AND h.revision=NEW.proposal_revision AND h.status='APPROVED'
    AND c.status='FINAL_APPROVED' AND h.template_id=NEW.template_id AND h.template_version=NEW.template_version
    AND h.source_digest=NEW.source_sha256 AND h.source_snapshot=NEW.source_snapshot)
  THEN RAISE EXCEPTION 'Original approved HR document snapshot required'; END IF;
 ELSIF EXISTS(SELECT 1 FROM cg19_document_template t WHERE t.id=NEW.template_id AND t.realm_id=NEW.realm_id AND t.template_kind LIKE 'HR_%')
 THEN RAISE EXCEPTION 'HR template is not allowed for another document source'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_document_notice_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.hr_document_ref,NEW.source_kind,NEW.source_key,NEW.recipient_id,NEW.realm_id,NEW.channel,NEW.template_id,NEW.template_version,NEW.subject_snapshot,NEW.body_snapshot)
  IS DISTINCT FROM (OLD.hr_document_ref,OLD.source_kind,OLD.source_key,OLD.recipient_id,OLD.realm_id,OLD.channel,OLD.template_id,OLD.template_version,OLD.subject_snapshot,OLD.body_snapshot)
  AND (OLD.source_kind='CG10_DOCUMENT_READY' OR NEW.source_kind='CG10_DOCUMENT_READY')
 THEN RAISE EXCEPTION 'Original HR dispatch identity is immutable'; END IF;
 IF TG_OP='INSERT' AND NEW.source_kind='CG10_DOCUMENT_READY' AND
  (NOT cg19_hr_document_notice_matches(NEW.realm_id,NEW.hr_document_ref,NEW.recipient_id)
   OR NOT EXISTS(SELECT 1 FROM cg19_message_template t WHERE t.realm_id=NEW.realm_id AND t.id=NEW.template_id AND t.version=NEW.template_version
    AND t.kind='CG10_DOCUMENT_READY' AND t.channel=NEW.channel AND t.status='APPROVED' AND t.subject=NEW.subject_snapshot AND t.body=NEW.body_snapshot))
 THEN RAISE EXCEPTION 'Original issued document recipient required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_document_notice_matches(root uuid, doc uuid, recipient uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(SELECT 1 FROM cg19_generated_document d JOIN hr_document_request h ON h.root_realm_id=d.realm_id AND h.case_ref=d.case_id AND h.source_digest=d.source_sha256
 JOIN hr_employee e ON e.root_realm_id=h.root_realm_id AND e.id=h.employee_id
 JOIN account a ON a.realm_id=e.root_realm_id AND a.id=e.account_ref AND a.status='ACTIVE'
 WHERE d.realm_id=root AND d.id=doc AND d.state='ISSUED' AND d.revoked_at IS NULL AND h.status='APPROVED'
  AND e.account_ref=recipient AND e.status IN('ACTIVE','PROBATION') AND EXISTS(SELECT 1 FROM hr_employment_assignment ea
   WHERE ea.root_realm_id=e.root_realm_id AND ea.employee_id=e.id AND ea.valid_from<=CURRENT_DATE AND ea.valid_to IS NULL))
$function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_document_receipt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.event_key='ACKNOWLEDGED' AND (NEW.document_id IS NULL OR NEW.file_id IS NOT NULL OR NEW.intent_id IS NOT NULL
  OR NOT cg19_hr_document_notice_matches(NEW.realm_id,NEW.document_id,NEW.actor_id)
  OR NOT EXISTS(SELECT 1 FROM cg19_generated_document d WHERE d.id=NEW.document_id AND d.realm_id=NEW.realm_id AND d.case_id=NEW.case_id))
 THEN RAISE EXCEPTION 'Actual recipient acknowledgement required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_document_staff_receipt_matches(root uuid, doc uuid, staff uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT EXISTS(
  SELECT 1 FROM cg19_generated_document d JOIN hr_document_request h
    ON h.root_realm_id=d.realm_id AND h.case_ref=d.case_id AND h.source_digest=d.source_sha256 AND h.revision=d.proposal_revision
   JOIN branch b ON b.root_realm_id=h.root_realm_id AND b.id=h.source_branch_ref
   JOIN access_realm rlm ON rlm.id=d.realm_id AND rlm.realm_key='FOUNDATION_ROOT'
   JOIN account ac ON ac.realm_id=d.realm_id AND ac.id=staff AND ac.status='ACTIVE'
   LEFT JOIN hr_employee e ON e.root_realm_id=h.root_realm_id AND e.id=h.employee_id
  WHERE d.realm_id=root AND d.id=doc AND d.state='ISSUED' AND d.revoked_at IS NULL AND h.status='APPROVED'
   AND NOT EXISTS(SELECT 1 FROM (VALUES ('hr.documents.manage'),('documents.letters.issue')) required(action)
    WHERE NOT EXISTS(SELECT 1 FROM account_role ar JOIN role r ON r.id=ar.role_id AND r.realm_id=ar.realm_id AND r.active
     WHERE ar.realm_id=root AND ar.account_id=staff AND ar.revoked_at IS NULL
     AND (r.is_protected OR EXISTS(SELECT 1 FROM role_grant g WHERE g.role_id=r.id AND g.capability_key=required.action))))
   AND (b.manager_account_ref=staff OR EXISTS(SELECT 1 FROM account_role ar JOIN role r ON r.id=ar.role_id AND r.realm_id=ar.realm_id AND r.active
    WHERE ar.realm_id=root AND ar.account_id=staff AND ar.revoked_at IS NULL AND
    (r.is_protected OR EXISTS(SELECT 1 FROM role_grant g WHERE g.role_id=r.id AND g.capability_key='foundation.branches.admin'))))
   AND ((h.employee_id IS NULL AND EXISTS(SELECT 1 FROM hr_employee_application ap WHERE ap.root_realm_id=h.root_realm_id AND ap.id=h.application_id AND ap.proposed_branch_ref=h.source_branch_ref))
    OR EXISTS(SELECT 1 FROM hr_employment_assignment a WHERE a.root_realm_id=h.root_realm_id AND a.employee_id=h.employee_id
     AND a.branch_ref=h.source_branch_ref AND a.valid_from<=CURRENT_DATE AND (a.valid_to IS NULL OR (e.status='EXITED' AND a.id=h.assignment_id)))
    OR EXISTS(SELECT 1 FROM account_role ar JOIN role ro ON ro.id=ar.role_id AND ro.realm_id=ar.realm_id AND ro.active AND ro.is_protected
     WHERE ar.realm_id=root AND ar.account_id=staff AND ar.revoked_at IS NULL))
 )
$function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_receipt_actor_matches(root uuid, doc uuid, actor uuid, mode text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT CASE mode WHEN 'STAFF' THEN cg19_hr_document_staff_receipt_matches(root,doc,actor)
 WHEN 'RECIPIENT' THEN cg19_hr_document_notice_matches(root,doc,actor) ELSE false END
$function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_receipt_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM cg19_upload_intent i WHERE i.realm_id=NEW.realm_id AND i.id=NEW.upload_intent_id AND i.classification='HR_RECEIVED_COPY') AND
  NOT EXISTS(SELECT 1 FROM cg19_upload_intent i WHERE i.realm_id=NEW.realm_id AND i.id=NEW.upload_intent_id
   AND i.classification='HR_RECEIVED_COPY' AND i.status='VALIDATED' AND i.case_id=NEW.case_id AND i.proposal_revision=NEW.proposal_revision
   AND i.requested_by=NEW.created_by AND i.mime=NEW.original_mime AND i.expected_sha256=NEW.verified_sha256
   AND i.size_bytes=NEW.verified_size_bytes AND i.object_key=NEW.object_key AND NEW.owner_kind='CG03_CASE'
   AND NEW.scan_status='CLEAN_VERIFIED' AND cg19_hr_receipt_actor_matches(i.realm_id,i.hr_receipt_document_ref,i.requested_by,i.hr_receipt_actor_kind))
 THEN RAISE EXCEPTION 'Exact scan-verified received copy and authorized uploader required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_receipt_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.hr_receipt_document_ref,NEW.hr_receipt_actor_kind) IS DISTINCT FROM (OLD.hr_receipt_document_ref,OLD.hr_receipt_actor_kind) THEN
  RAISE EXCEPTION 'Original receipt document and uploader mode are immutable';
 END IF;
 IF TG_OP='INSERT' AND NEW.classification='HR_RECEIVED_COPY' AND
  (NOT cg19_hr_receipt_actor_matches(NEW.realm_id,NEW.hr_receipt_document_ref,NEW.requested_by,NEW.hr_receipt_actor_kind)
   OR NOT EXISTS(SELECT 1 FROM cg19_generated_document d WHERE d.realm_id=NEW.realm_id AND d.id=NEW.hr_receipt_document_ref
    AND d.case_id=NEW.case_id AND d.proposal_revision=NEW.proposal_revision))
 THEN RAISE EXCEPTION 'Current original document and authorized receipt uploader required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_template_asset_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.hr_signatory_name,NEW.hr_signature_file_ref,NEW.hr_seal_file_ref) IS DISTINCT FROM (OLD.hr_signatory_name,OLD.hr_signature_file_ref,OLD.hr_seal_file_ref)
 THEN RAISE EXCEPTION 'Approved HR template asset metadata cannot change'; END IF;
 IF TG_OP='INSERT' AND NEW.template_kind LIKE 'HR_%' AND (NEW.hr_signatory_name IS NULL OR NOT cg19_hr_template_assets_ready(NEW.realm_id,NEW.hr_signature_file_ref,NEW.hr_seal_file_ref))
 THEN RAISE EXCEPTION 'Approved template requires authorized scan-verified signatory assets'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_hr_template_assets_ready(root uuid, signature uuid, seal uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
 SELECT signature IS NOT NULL AND seal IS NOT NULL AND signature<>seal AND EXISTS(
  SELECT 1 FROM cg19_stored_file f JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  WHERE f.realm_id=root AND f.id=signature AND f.owner_kind='CG19_HR_TEMPLATE_ASSET' AND i.owner_kind=f.owner_kind
   AND i.classification='HR_TEMPLATE_SIGNATURE' AND i.status='VALIDATED' AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
 ) AND EXISTS(
  SELECT 1 FROM cg19_stored_file f JOIN cg19_upload_intent i ON i.id=f.upload_intent_id AND i.realm_id=f.realm_id
  WHERE f.realm_id=root AND f.id=seal AND f.owner_kind='CG19_HR_TEMPLATE_ASSET' AND i.owner_kind=f.owner_kind
   AND i.classification='HR_TEMPLATE_SEAL' AND i.status='VALIDATED' AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
 )
$function$
;
CREATE OR REPLACE FUNCTION public.cg19_immutable_comm_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Notification evidence cannot be changed or removed'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_intent_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.realm_id IS DISTINCT FROM OLD.realm_id OR
     NEW.case_id IS DISTINCT FROM OLD.case_id OR
     NEW.proposal_revision IS DISTINCT FROM OLD.proposal_revision OR
     NEW.requested_by IS DISTINCT FROM OLD.requested_by OR
     NEW.request_key IS DISTINCT FROM OLD.request_key OR
     NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
     NEW.mime IS DISTINCT FROM OLD.mime OR
     NEW.size_bytes IS DISTINCT FROM OLD.size_bytes OR
     NEW.expected_sha256 IS DISTINCT FROM OLD.expected_sha256 OR
     NEW.classification IS DISTINCT FROM OLD.classification OR
     NEW.object_key IS DISTINCT FROM OLD.object_key OR
     NEW.reserved_until IS DISTINCT FROM OLD.reserved_until THEN
    RAISE EXCEPTION 'Private upload identity is immutable';
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_invoice_document_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original issued document cannot be deleted' USING ERRCODE='P0923';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'PENDING' THEN
   RAISE EXCEPTION 'Only an original pending document may be created' USING ERRCODE='P0923';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.invoice_id IS DISTINCT FROM OLD.invoice_id
  OR NEW.source_version<>OLD.source_version OR
  NEW.source_digest IS DISTINCT FROM OLD.source_digest OR
  NEW.issue_key IS DISTINCT FROM OLD.issue_key OR
  NEW.issued_by IS DISTINCT FROM OLD.issued_by OR
  NEW.object_key IS DISTINCT FROM OLD.object_key OR
  NEW.created_at IS DISTINCT FROM OLD.created_at THEN
   RAISE EXCEPTION 'Original invoice document identity cannot change' USING ERRCODE='P0923';
 END IF;
 IF OLD.status IN('PENDING','UNKNOWN') AND NEW.status IN('UNKNOWN','ISSUED')
   AND OLD.object_version IS NULL AND OLD.content_sha256 IS NULL
 THEN RETURN NEW;
 END IF;
 IF OLD.status='ISSUED' AND NEW.status='REVOKED'
   AND NEW.object_version IS NOT DISTINCT FROM OLD.object_version
   AND NEW.content_sha256 IS NOT DISTINCT FROM OLD.content_sha256
   AND NEW.content_length IS NOT DISTINCT FROM OLD.content_length
   AND NEW.issued_at IS NOT DISTINCT FROM OLD.issued_at AND NEW.revoked_at IS NOT NULL
 THEN RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Issued invoice bytes are immutable' USING ERRCODE='P0923';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_issued_identity_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.realm_id IS DISTINCT FROM OLD.realm_id OR
     NEW.case_id IS DISTINCT FROM OLD.case_id OR
     NEW.proposal_revision IS DISTINCT FROM OLD.proposal_revision OR
     NEW.template_id IS DISTINCT FROM OLD.template_id OR
     NEW.template_version IS DISTINCT FROM OLD.template_version OR
     NEW.issue_key IS DISTINCT FROM OLD.issue_key OR
     NEW.issue_revision IS DISTINCT FROM OLD.issue_revision OR
     NEW.source_snapshot IS DISTINCT FROM OLD.source_snapshot OR
     NEW.source_sha256 IS DISTINCT FROM OLD.source_sha256 OR
     NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
     NEW.issued_by IS DISTINCT FROM OLD.issued_by OR
     NEW.object_key IS DISTINCT FROM OLD.object_key AND OLD.object_key IS NOT NULL OR
     NEW.object_version IS DISTINCT FROM OLD.object_version AND OLD.object_version IS NOT NULL OR
     NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256 AND OLD.content_sha256 IS NOT NULL THEN
    RAISE EXCEPTION 'Private issued document identity is immutable';
  END IF;
  RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_quality_file_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR
  (to_jsonb(NEW)-'revoked_at') IS DISTINCT FROM
  (to_jsonb(OLD)-'revoked_at') OR
  (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
 THEN RAISE EXCEPTION 'Private quality file identity cannot be rewritten';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_quality_file_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM cg19_lab_quality_intent intent
  WHERE intent.root_realm_id=NEW.root_realm_id AND intent.id=NEW.intent_ref
   AND intent.status='VALIDATED' AND intent.center_ref=NEW.center_ref
   AND intent.equipment_ref=NEW.equipment_ref AND intent.mime=NEW.mime
   AND intent.size_bytes=NEW.size_bytes AND intent.sha256=NEW.sha256
   AND intent.object_key=NEW.object_key
 ) THEN
  RAISE EXCEPTION 'Quality file requires exact validated CG19 upload intent';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_quality_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original quality upload intent cannot be removed';
 END IF;
 IF (to_jsonb(NEW)-'status'-'reservation_ref'-'updated_at') IS DISTINCT FROM
    (to_jsonb(OLD)-'status'-'reservation_ref'-'updated_at') THEN
  RAISE EXCEPTION 'Original quality upload source is immutable';
 END IF;
 IF OLD.status IN('VALIDATED','REJECTED') THEN
  RAISE EXCEPTION 'Final quality scanner state cannot be revised';
 END IF;
 IF NOT ((OLD.status='INITIATED' AND
   NEW.status IN('INITIATED','UNKNOWN','VALIDATED','REJECTED')) OR
   (OLD.status='UNKNOWN' AND
   NEW.status IN('UNKNOWN','INITIATED','VALIDATED','REJECTED')))
 THEN
  RAISE EXCEPTION 'Original quality scanner transition is invalid';
 END IF;
 IF NEW.updated_at<OLD.updated_at THEN
  RAISE EXCEPTION 'Quality scanner event time cannot go backwards';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_release_wakeup()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 INSERT INTO cg19_lab_release_outbox(realm_id,release_ref)
 VALUES(NEW.root_realm_id,NEW.id) ON CONFLICT DO NOTHING;
 PERFORM pg_notify('cg19_lab_release_committed',NEW.root_realm_id::text);
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_result_event_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 RAISE EXCEPTION 'Original laboratory file event is immutable';
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_result_file_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM cg19_lab_result_intent intent
  WHERE intent.root_realm_id=NEW.root_realm_id
   AND intent.id=NEW.intent_ref AND intent.status='VALIDATED'
   AND intent.order_ref=NEW.order_ref AND intent.center_ref=NEW.center_ref
   AND intent.patient_ref=NEW.patient_ref
   AND intent.result_revision_ref=NEW.result_revision_ref
   AND intent.mime=NEW.mime AND intent.size_bytes=NEW.size_bytes
   AND intent.sha256=NEW.sha256 AND intent.object_key=NEW.object_key
 ) THEN
  RAISE EXCEPTION 'Verified laboratory file requires original matching upload';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_result_identity_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR
  (to_jsonb(NEW)-'revoked_at') IS DISTINCT FROM
  (to_jsonb(OLD)-'revoked_at') OR
  (OLD.revoked_at IS NOT NULL AND
   NEW.revoked_at IS DISTINCT FROM OLD.revoked_at) THEN
  RAISE EXCEPTION 'Original scanner verified lab report identity is immutable';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_lab_result_intent_identity_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR
  (to_jsonb(NEW)-'status'-'reservation_ref'-'updated_at') IS DISTINCT FROM
  (to_jsonb(OLD)-'status'-'reservation_ref'-'updated_at') OR
  (OLD.status IN('VALIDATED','REJECTED') AND
   (NEW.status IS DISTINCT FROM OLD.status OR
    NEW.reservation_ref IS DISTINCT FROM OLD.reservation_ref)) THEN
  RAISE EXCEPTION 'Original lab report upload intent cannot be rewritten';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_member_brand_asset_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND
  (NEW.root_realm_id,NEW.id,NEW.kind,NEW.requested_by,NEW.request_key,NEW.mime,NEW.size_bytes,NEW.expected_sha256,NEW.object_key,NEW.reserved_until)
   IS DISTINCT FROM
  (OLD.root_realm_id,OLD.id,OLD.kind,OLD.requested_by,OLD.request_key,OLD.mime,OLD.size_bytes,OLD.expected_sha256,OLD.object_key,OLD.reserved_until)
 THEN RAISE EXCEPTION 'Private brand asset identity cannot change'; END IF;
 IF TG_OP='UPDATE' AND OLD.status='VALIDATED' AND (NEW.status,NEW.object_version,NEW.scan_proof_ref,NEW.verified_at) IS DISTINCT FROM
  (OLD.status,OLD.object_version,OLD.scan_proof_ref,OLD.verified_at)
 THEN RAISE EXCEPTION 'Verified brand proof is immutable'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_member_brand_config_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND OLD.status='WITHDRAWN' AND NEW.status<>'WITHDRAWN' THEN
 RAISE EXCEPTION 'Withdrawn Foundation branding cannot be reapproved'; END IF;
 IF TG_OP='UPDATE' AND
  (NEW.root_realm_id,NEW.version,NEW.display_name,NEW.signatory_name,NEW.signature_asset_id,NEW.seal_asset_id,NEW.logo_asset_id,NEW.approved_by,NEW.request_key,NEW.request_digest,NEW.approved_at)
   IS DISTINCT FROM
  (OLD.root_realm_id,OLD.version,OLD.display_name,OLD.signatory_name,OLD.signature_asset_id,OLD.seal_asset_id,OLD.logo_asset_id,OLD.approved_by,OLD.request_key,OLD.request_digest,OLD.approved_at)
 THEN RAISE EXCEPTION 'Approved brand snapshot cannot change'; END IF;
 IF TG_OP='INSERT' AND NOT EXISTS(
  SELECT 1 FROM cg19_member_brand_asset a
  JOIN cg19_member_brand_asset b ON b.root_realm_id=a.root_realm_id AND b.id=NEW.seal_asset_id AND b.kind='SEAL' AND b.status='VALIDATED'
  JOIN cg19_member_brand_asset c ON c.root_realm_id=a.root_realm_id AND c.id=NEW.logo_asset_id AND c.kind='LOGO' AND c.status='VALIDATED'
  WHERE a.root_realm_id=NEW.root_realm_id AND a.id=NEW.signature_asset_id AND a.kind='SIGNATURE' AND a.status='VALIDATED'
 ) THEN RAISE EXCEPTION 'Original verified logo, signature and seal are required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_member_immutable_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'Issued member document history is immutable'; END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_member_pack_document_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND
 (NEW.root_realm_id,NEW.pack_id,NEW.kind,NEW.object_key) IS DISTINCT FROM (OLD.root_realm_id,OLD.pack_id,OLD.kind,OLD.object_key)
 THEN RAISE EXCEPTION 'Official document identity is immutable'; END IF;
 IF TG_OP='UPDATE' AND OLD.state='ISSUED' AND (NEW.state,NEW.object_version,NEW.content_sha256) IS DISTINCT FROM (OLD.state,OLD.object_version,OLD.content_sha256)
 THEN RAISE EXCEPTION 'Issued document proof is immutable'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_member_pack_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND
 (NEW.root_realm_id,NEW.id,NEW.member_id,NEW.term_id,NEW.brand_version,NEW.issue_revision,NEW.issue_key,NEW.issued_by,NEW.source_snapshot,NEW.source_digest,NEW.qr_token_digest)
 IS DISTINCT FROM
 (OLD.root_realm_id,OLD.id,OLD.member_id,OLD.term_id,OLD.brand_version,OLD.issue_revision,OLD.issue_key,OLD.issued_by,OLD.source_snapshot,OLD.source_digest,OLD.qr_token_digest)
 THEN RAISE EXCEPTION 'Original member document identity cannot change'; END IF;
 IF TG_OP='UPDATE' AND OLD.state='REVOKED' AND NEW.state<>'REVOKED' THEN
 RAISE EXCEPTION 'Revoked original member pack cannot be restored'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_membership_file_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Protected document history is retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.revision<>1 OR NEW.revoked_at IS NOT NULL OR NOT EXISTS(
   SELECT 1 FROM cg19_membership_file_intent i WHERE i.realm_id=NEW.realm_id AND i.id=NEW.intent_id
    AND i.application_id=NEW.application_id AND i.application_version=NEW.application_version AND i.status='VALIDATED'
    AND (i.classification,i.mime,i.size_bytes,i.sha256,i.object_key)=(NEW.classification,NEW.mime,NEW.size_bytes,NEW.sha256,NEW.object_key)
    AND i.reserved_until>now() FOR SHARE)
   THEN RAISE EXCEPTION 'Original verified upload does not match'; END IF;
 ELSE
  IF OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.revision<>OLD.revision+1
   OR (to_jsonb(NEW)-'revision'-'revoked_at') IS DISTINCT FROM (to_jsonb(OLD)-'revision'-'revoked_at')
   OR NOT EXISTS(SELECT 1 FROM membership_application a WHERE a.root_realm_id=NEW.realm_id AND a.id=NEW.application_id AND a.status IN('DRAFT','RETURNED') FOR SHARE)
   THEN RAISE EXCEPTION 'Submitted proof cannot be replaced'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_membership_intent_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Protected upload history is retained'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.status IN('VALIDATED','REJECTED') OR (to_jsonb(NEW)-'status'-'storage_reservation_ref'-'updated_at') IS DISTINCT FROM (to_jsonb(OLD)-'status'-'storage_reservation_ref'-'updated_at') THEN
   RAISE EXCEPTION 'Protected upload source is immutable'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM membership_application a WHERE a.root_realm_id=NEW.realm_id AND a.id=NEW.application_id
   AND a.applicant_account_ref=NEW.requested_by AND a.status IN('DRAFT','RETURNED') AND a.version=NEW.application_version FOR SHARE)
  THEN RAISE EXCEPTION 'The application changed. Refresh the current draft'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_message_template_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.realm_id IS DISTINCT FROM OLD.realm_id OR
   NEW.kind IS DISTINCT FROM OLD.kind OR
   NEW.channel IS DISTINCT FROM OLD.channel OR
   NEW.version IS DISTINCT FROM OLD.version OR
   NEW.subject IS DISTINCT FROM OLD.subject OR
   NEW.body IS DISTINCT FROM OLD.body OR
   NEW.origin IS DISTINCT FROM OLD.origin OR
   NEW.approved_by IS DISTINCT FROM OLD.approved_by THEN
