 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_notice_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.realm_id IS DISTINCT FROM OLD.realm_id OR
    NEW.author_id IS DISTINCT FROM OLD.author_id OR
    NEW.request_key IS DISTINCT FROM OLD.request_key OR
    NEW.request_digest IS DISTINCT FROM OLD.request_digest OR
    NEW.title IS DISTINCT FROM OLD.title OR NEW.body IS DISTINCT FROM OLD.body OR
    NEW.priority IS DISTINCT FROM OLD.priority OR
    NEW.purpose IS DISTINCT FROM OLD.purpose OR
    NEW.channels IS DISTINCT FROM OLD.channels OR
    NEW.target_href IS DISTINCT FROM OLD.target_href OR
    NEW.audience_kind IS DISTINCT FROM OLD.audience_kind OR
    NEW.audience_ref IS DISTINCT FROM OLD.audience_ref OR
    NEW.audience_digest IS DISTINCT FROM OLD.audience_digest OR
    NEW.audience_count IS DISTINCT FROM OLD.audience_count OR
    NEW.scheduled_at IS DISTINCT FROM OLD.scheduled_at OR
    NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
   RAISE EXCEPTION 'Frozen approved notice cannot be changed';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_original_recognition_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM redemption r
  JOIN reward_product_revision p ON p.root_realm_id=r.root_realm_id
   AND p.product_id=r.product_id AND p.revision=r.product_revision
  WHERE r.root_realm_id=NEW.realm_id AND r.id=NEW.redemption_id
   AND r.state='HELD' AND r.product_type='DIGITAL'
   AND r.recipient_account_ref=NEW.recipient_account_ref
   AND r.product_id=NEW.product_id AND r.product_revision=NEW.product_revision
   AND r.request_key=NEW.source_key
   AND p.digital_fulfillment_method='ON_PLATFORM_RECOGNITION'
   AND p.product_type='DIGITAL'
   AND p.name=NEW.title AND p.description=NEW.description
 ) THEN RAISE EXCEPTION 'Original on-platform recognition claim source required'; END IF;
 RETURN NEW;
END; $function$
;
