 IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN
  RAISE EXCEPTION 'Original project cover identity is immutable';
 END IF;
 RETURN NEW;
END $function$
;
CREATE OR REPLACE FUNCTION public.cg19_receipt_document_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  RAISE EXCEPTION 'Original issued document cannot be deleted' USING ERRCODE='P0923';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'PENDING' THEN
   RAISE EXCEPTION 'Only an original pending document may be created' USING ERRCODE='P0923';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.root_realm_id IS DISTINCT FROM OLD.root_realm_id
  OR NEW.receipt_id IS DISTINCT FROM OLD.receipt_id
  OR NEW.source_version<>OLD.source_version OR
  NEW.source_digest IS DISTINCT FROM OLD.source_digest OR
  NEW.issue_key IS DISTINCT FROM OLD.issue_key OR
  NEW.issued_by IS DISTINCT FROM OLD.issued_by OR
  NEW.object_key IS DISTINCT FROM OLD.object_key OR
  NEW.created_at IS DISTINCT FROM OLD.created_at THEN
   RAISE EXCEPTION 'Original receipt document identity cannot change' USING ERRCODE='P0923';
 END IF;
 IF OLD.status IN('PENDING','UNKNOWN') AND NEW.status IN('UNKNOWN','ISSUED')
   AND OLD.object_version IS NULL AND OLD.content_sha256 IS NULL
 THEN RETURN NEW;
 END IF;
 IF OLD.status='ISSUED' AND NEW.status='REVOKED'
   AND NEW.object_version IS NOT DISTINCT FROM OLD.object_version
   AND NEW.content_sha256 IS NOT DISTINCT FROM OLD.content_sha256
   AND NEW.content_length IS NOT DISTINCT FROM OLD.content_length
   AND NEW.issued_at IS NOT DISTINCT FROM OLD.issued_at AND NEW.revoked_at IS NOT NULL
 THEN RETURN NEW;
 END IF;
 RAISE EXCEPTION 'Issued receipt bytes are immutable' USING ERRCODE='P0923';
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_refuse_cancelled_invoice_issue()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 PERFORM 1 FROM finance_invoice
  WHERE id=NEW.invoice_id AND root_realm_id=NEW.root_realm_id FOR SHARE;
 PERFORM 1 FROM finance_invoice_posted_cancellation c
  WHERE c.root_realm_id=NEW.root_realm_id AND c.invoice_id=NEW.invoice_id FOR SHARE;
 IF FOUND THEN
  RAISE EXCEPTION 'This posted invoice was cancelled before private issue'
   USING ERRCODE='P0930';
 END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_reward_handover_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM redemption r
  JOIN stock_reward_hold h ON h.root_realm_id=r.root_realm_id
   AND h.redemption_id=r.id AND h.state='ISSUED'
  JOIN stock_reward_hold_event h_event
   ON h_event.root_realm_id=h.root_realm_id AND h_event.hold_id=h.id
   AND h_event.event_kind='ISSUED' AND h_event.source_key=h.issue_key
  JOIN stock_event issued ON issued.root_realm_id=h_event.root_realm_id
   AND issued.id=h_event.original_stock_event_id
  JOIN stock_operation_draft op ON op.root_realm_id=issued.root_realm_id
   AND op.id=issued.operation_id AND op.reward_hold_id=h.id
  JOIN inventory_location warehouse ON warehouse.root_realm_id=h.root_realm_id
   AND warehouse.id=h.location_id
  WHERE r.root_realm_id=NEW.realm_id AND r.id=NEW.redemption_id
   AND r.state='ISSUED_AWAITING_HANDOVER' AND r.product_type='PHYSICAL'
   AND r.recipient_account_ref=NEW.recipient_account_ref
   AND r.request_key=NEW.source_key
   AND issued.id=NEW.stock_issue_event_id AND issued.event_kind='ISSUE'
   AND issued.source_event_key=h.issue_key
   AND issued.actor_ref=op.actor_ref AND issued.recipient_id=op.actor_ref
   AND issued.actor_ref<>r.recipient_account_ref
   AND op.status='CONFIRMED'
   AND (NOT warehouse.delivery_proof_required OR EXISTS(
    SELECT 1 FROM cg19_stored_file f
    WHERE f.realm_id=issued.root_realm_id
     AND f.id=issued.movement_proof_ref
     AND f.revision=issued.movement_proof_revision
     AND f.scan_status='CLEAN_VERIFIED' AND f.revoked_at IS NULL
     AND f.owner_kind='CG12_MOVEMENT'
     AND f.inventory_operation_id=issued.operation_id))
 ) THEN RAISE EXCEPTION 'Actual staff ISSUE, CG19 evidence and recipient handover source required'; END IF;
 RETURN NEW;
END; $function$
;
CREATE OR REPLACE FUNCTION public.cg19_salary_notice_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE k text;doc uuid;line uuid;
BEGIN
 IF TG_OP='UPDATE' AND (OLD.source_kind='CG11_PAYROLL_EVENT' OR NEW.source_kind='CG11_PAYROLL_EVENT') AND
 (to_jsonb(NEW)-ARRAY['state','attempt_count','claim_token','claimed_until','due_at','provider_message_ref','provider_kind','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','attempt_count','claim_token','claimed_until','due_at','provider_message_ref','provider_kind','updated_at']) THEN RAISE EXCEPTION 'Original salary notice identity immutable'; END IF;
 IF TG_OP='INSERT' AND NEW.source_kind='CG11_PAYROLL_EVENT' THEN
 SELECT event_kind,doc_ref,line_ref INTO k,doc,line FROM cg19_payroll_event_outbox WHERE realm_id=NEW.realm_id AND id=NEW.payroll_event_ref AND state='CAPTURED';
 IF NOT FOUND OR NEW.purpose<>'TRANSACTIONAL' OR NOT cg19_payroll_event_matches(NEW.realm_id,NEW.payroll_event_ref,NEW.recipient_id) OR
 (k IN('GENERATED','RESEND') AND NOT EXISTS(SELECT 1 FROM cg19_payroll_payslip p WHERE p.root_realm_id=NEW.realm_id AND p.id=doc AND p.line_ref=line AND p.status='ISSUED')) OR
 NOT EXISTS(SELECT 1 FROM cg19_message_template t CROSS JOIN cg19_payroll_event_copy(k) fixed WHERE t.realm_id=NEW.realm_id AND t.id=NEW.template_id AND t.version=NEW.template_version AND t.kind=fixed.code AND t.channel=NEW.channel AND t.status='APPROVED' AND t.subject=fixed.subject AND t.body=fixed.body AND t.subject=NEW.subject_snapshot AND t.body=NEW.body_snapshot)
 THEN RAISE EXCEPTION 'Original salary notice source required'; END IF;
 END IF;
 RETURN NEW;
END; $function$
;
