-- Views
CREATE VIEW public.employee_compensation_effective (id, root_realm_id, employee_ref, branch_ref, assignment_ref, assignment_version, employee_status_version, source_hr_proposal_ref, source_hr_proposal_revision, source_hr_proposal_digest, policy_id, policy_revision, effective_from, effective_to, supersedes_ref, base_salary_minor, status, revision, created_by, request_key, request_digest, approval_case_ref, created_at, effective_until) AS  SELECT x.id,
    x.root_realm_id,
    x.employee_ref,
    x.branch_ref,
    x.assignment_ref,
    x.assignment_version,
    x.employee_status_version,
    x.source_hr_proposal_ref,
    x.source_hr_proposal_revision,
    x.source_hr_proposal_digest,
    x.policy_id,
    x.policy_revision,
    x.effective_from,
    x.effective_to,
    x.supersedes_ref,
    x.base_salary_minor,
    x.status,
    x.revision,
    x.created_by,
    x.request_key,
    x.request_digest,
    x.approval_case_ref,
    x.created_at,
    LEAST(x.effective_to, n.effective_from) AS effective_until
   FROM employee_compensation x
     LEFT JOIN employee_compensation n ON n.root_realm_id = x.root_realm_id AND n.supersedes_ref = x.id AND n.status = 'APPROVED'::text;
CREATE VIEW public.employee_payout_instruction_effective (id, root_realm_id, employee_ref, branch_ref, assignment_ref, assignment_version, employee_status_version, effective_from, effective_to, supersedes_ref, destination_ciphertext, destination_nonce, destination_tag, destination_fingerprint, masked_digits, masked_ifsc, status, revision, created_by, request_key, request_digest, approval_case_ref, created_at, effective_until) AS  SELECT x.id,
    x.root_realm_id,
    x.employee_ref,
    x.branch_ref,
    x.assignment_ref,
    x.assignment_version,
    x.employee_status_version,
    x.effective_from,
    x.effective_to,
    x.supersedes_ref,
    x.destination_ciphertext,
    x.destination_nonce,
    x.destination_tag,
    x.destination_fingerprint,
    x.masked_digits,
    x.masked_ifsc,
    x.status,
    x.revision,
    x.created_by,
    x.request_key,
    x.request_digest,
    x.approval_case_ref,
    x.created_at,
    LEAST(x.effective_to, n.effective_from) AS effective_until
   FROM employee_payout_instruction x
     LEFT JOIN employee_payout_instruction n ON n.root_realm_id = x.root_realm_id AND n.supersedes_ref = x.id AND n.status = 'APPROVED'::text;
CREATE VIEW public.finance_membership_verified_collection (root_realm_id, application_id, journal_id, amount_minor, reconciliation_id, statement_date) AS  SELECT m.root_realm_id,
    m.application_id,
    m.journal_id,
    m.amount_minor,
    r.id AS reconciliation_id,
    r.statement_date
   FROM finance_membership_collection m
     JOIN finance_bank_reconciliation r ON r.root_realm_id = m.root_realm_id AND r.journal_id = m.journal_id AND r.bank_account_id = m.bank_account_id
  WHERE r.status = 'VERIFIED'::text AND r.variance_minor = 0 AND r.statement_amount_minor = m.amount_minor AND r.posted_amount_minor = m.amount_minor AND (EXISTS ( SELECT 1
           FROM finance_reconciliation_decision d
             JOIN cg19_stored_file f ON f.id = d.statement_file_id AND f.realm_id = d.root_realm_id AND f.reconciliation_id = d.reconciliation_id AND f.revision = d.statement_file_version
             JOIN cg19_upload_intent i ON i.id = f.upload_intent_id AND i.realm_id = f.realm_id AND i.reconciliation_id = d.reconciliation_id
          WHERE d.root_realm_id = r.root_realm_id AND d.reconciliation_id = r.id AND d.action = 'VERIFY'::text AND f.owner_kind = 'CG09_BANK_STATEMENT'::text AND i.owner_kind = 'CG09_BANK_STATEMENT'::text AND i.status = 'VALIDATED'::text AND f.scan_status = 'CLEAN_VERIFIED'::text AND f.revoked_at IS NULL)) AND NOT (EXISTS ( SELECT 1
           FROM journal j
          WHERE j.root_realm_id = m.root_realm_id AND j.reversal_of_id = m.journal_id));
CREATE VIEW public.finance_membership_verified_refund (root_realm_id, application_id, journal_id, reconciliation_id, amount_minor, statement_date) AS  SELECT q.root_realm_id,
    q.application_id,
    q.journal_id,
    r.id AS reconciliation_id,
    rr.amount_minor,
    r.statement_date
   FROM finance_membership_refund_posting q
     JOIN finance_membership_refund_request rr ON rr.root_realm_id = q.root_realm_id AND rr.application_id = q.application_id
     JOIN finance_membership_collection m ON m.root_realm_id = q.root_realm_id AND m.application_id = q.application_id
     JOIN finance_bank_reconciliation r ON r.root_realm_id = q.root_realm_id AND r.journal_id = q.journal_id AND r.bank_account_id = m.bank_account_id
  WHERE r.status = 'VERIFIED'::text AND r.variance_minor = 0 AND r.statement_amount_minor = (- rr.amount_minor) AND r.posted_amount_minor = (- rr.amount_minor) AND (EXISTS ( SELECT 1
           FROM finance_reconciliation_decision d
             JOIN cg19_stored_file f ON f.id = d.statement_file_id AND f.realm_id = d.root_realm_id AND f.reconciliation_id = d.reconciliation_id AND f.revision = d.statement_file_version
             JOIN cg19_upload_intent i ON i.id = f.upload_intent_id AND i.realm_id = f.realm_id AND i.reconciliation_id = d.reconciliation_id
          WHERE d.root_realm_id = r.root_realm_id AND d.reconciliation_id = r.id AND d.action = 'VERIFY'::text AND f.owner_kind = 'CG09_BANK_STATEMENT'::text AND i.owner_kind = 'CG09_BANK_STATEMENT'::text AND i.status = 'VALIDATED'::text AND f.scan_status = 'CLEAN_VERIFIED'::text AND f.revoked_at IS NULL));
CREATE VIEW public.payroll_attempt_outcome (id, root_realm_id, item_ref, voucher_ref, amount_minor, request_key, created_by, created_at, voucher_status, voucher_number, voucher_version, paid_minor, reversed, attempt_status) AS  SELECT t.id,
    t.root_realm_id,
    t.item_ref,
    t.voucher_ref,
    t.amount_minor,
    t.request_key,
    t.created_by,
    t.created_at,
    v.status AS voucher_status,
    v.voucher_number,
    v.version AS voucher_version,
        CASE
            WHEN v.status = 'POSTED'::text AND (EXISTS ( SELECT 1
               FROM finance_voucher_payment_verification p
              WHERE p.root_realm_id = t.root_realm_id AND p.voucher_id = t.voucher_ref AND p.voucher_revision = v.version AND p.status = 'VERIFIED'::text AND p.amount_minor = t.amount_minor AND (b.method = 'CASH'::text AND p.method = 'CASH_RECEIPT'::text OR b.method = 'BANK'::text AND p.method = 'BANK_STATEMENT'::text AND p.payroll_destination_fingerprint = i.destination_fingerprint AND (EXISTS ( SELECT 1
                       FROM finance_voucher_posting fp
                         JOIN finance_bank_reconciliation br ON br.root_realm_id = fp.root_realm_id AND br.journal_id = fp.journal_id
                      WHERE fp.root_realm_id = t.root_realm_id AND fp.voucher_id = t.voucher_ref AND fp.voucher_revision = v.version AND br.bank_account_id = b.payment_account_ref AND br.status = 'VERIFIED'::text AND br.variance_minor = 0 AND br.statement_amount_minor = (- t.amount_minor) AND br.posted_amount_minor = (- t.amount_minor) AND upper(btrim(br.bank_item_ref)) = p.bank_reference))))) AND (EXISTS ( SELECT 1
               FROM finance_voucher_posting f
                 JOIN journal j ON j.root_realm_id = f.root_realm_id AND j.id = f.journal_id
              WHERE f.root_realm_id = t.root_realm_id AND f.voucher_id = t.voucher_ref AND f.voucher_revision = v.version AND j.source_ref = v.id AND j.status = 'POSTED'::text AND NOT (EXISTS ( SELECT 1
                       FROM journal reversal
                      WHERE reversal.root_realm_id = j.root_realm_id AND reversal.reversal_of_id = j.id)))) THEN t.amount_minor
            ELSE 0::bigint
        END AS paid_minor,
    (EXISTS ( SELECT 1
           FROM finance_voucher_posting f
             JOIN journal reversal ON reversal.root_realm_id = f.root_realm_id AND reversal.reversal_of_id = f.journal_id
          WHERE f.root_realm_id = t.root_realm_id AND f.voucher_id = t.voucher_ref)) AND NOT cg11_verified_bank_return(t.root_realm_id, t.id) AS reversed,
        CASE
            WHEN cg11_verified_bank_return(t.root_realm_id, t.id) THEN 'RETURNED_VERIFIED'::text
            WHEN (EXISTS ( SELECT 1
               FROM finance_voucher_payment_verification p
              WHERE p.root_realm_id = t.root_realm_id AND p.voucher_id = t.voucher_ref AND p.voucher_revision = v.version AND p.payroll_failure_verified AND p.payroll_destination_fingerprint = i.destination_fingerprint)) THEN 'FAILED_VERIFIED'::text
            ELSE v.status
        END AS attempt_status
   FROM payroll_payout_attempt t
     JOIN finance_voucher v ON v.root_realm_id = t.root_realm_id AND v.id = t.voucher_ref
     JOIN payroll_batch_item i ON i.root_realm_id = t.root_realm_id AND i.id = t.item_ref
     JOIN payroll_batch b ON b.root_realm_id = i.root_realm_id AND b.id = i.batch_ref;
CREATE VIEW public.payroll_policy_effective (id, root_realm_id, branch_ref, cycle, currency, period_timezone, attendance_rules, fiscal_year_start_month, label, effective_from, effective_to, supersedes_ref, status, revision, created_by, request_key, request_digest, approval_case_ref, created_at, effective_until) AS  SELECT x.id,
    x.root_realm_id,
    x.branch_ref,
    x.cycle,
    x.currency,
    x.period_timezone,
    x.attendance_rules,
    x.fiscal_year_start_month,
    x.label,
    x.effective_from,
    x.effective_to,
    x.supersedes_ref,
    x.status,
    x.revision,
    x.created_by,
    x.request_key,
    x.request_digest,
    x.approval_case_ref,
    x.created_at,
    LEAST(x.effective_to, n.effective_from) AS effective_until
   FROM payroll_policy x
     LEFT JOIN payroll_policy n ON n.root_realm_id = x.root_realm_id AND n.supersedes_ref = x.id AND n.status = 'APPROVED'::text;

